INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1c93c687-ac1c-53c3-a90e-79d7e079f8d5'::uuid,'085a0d5a-b650-5030-a423-8cf60a256f36'::uuid,'reading',1,'{"title":"ชื่ออักษรกับเสียงในคำ","body":"## ชื่ออักษรกับเสียงในคำ\n\nชื่ออักษรใช้เวลาสะกดชื่อ แต่เสียงในคำใช้เวลาอ่าน เช่นชื่อ B คือ /biː/ ส่วนเสียงต้นของ bag คือ /b/ ตัวอักษรหนึ่งตัวแทนเสียงได้หลายแบบ และบางกลุ่มอักษรแทนเสียงเดียว เริ่มจากชื่อของคุณและคำที่ใช้จริง ไม่ต้องท่องตาราง A–Z ให้จบก่อน ตัวใหญ่กับตัวเล็กเป็นอักษรเดียวกันแต่ใช้ต่างตำแหน่ง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| B / b — bag | ชื่ออักษร B ต่างจากเสียง /b/ ใน bag |\n| M / m — Mai | ชื่อเฉพาะ Mai เริ่มด้วยตัวใหญ่ |\n\n### จุดที่มักสับสน\n\nอย่าอ่านคำโดยเอาชื่ออักษรแต่ละตัวมาต่อกัน และอย่าใช้ตัวใหญ่ทุกคำในประโยค\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ชื่ออักษรกับเสียงในคำ: B → /biː/; bag → /b/; TEAcher · baNAna](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/88de95eecda14f2e-module-01-map.png)\n\n*สะกดด้วยชื่ออักษร อ่านด้วยเสียง และฟังคำเต็ม*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council TeachingEnglish — Stress](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/q-s/stress) · [British Council TeachingEnglish — Connected speech](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/connected-speech)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5be977a9-6ce3-5d1b-ac1a-c3329a7dcaba'::uuid,'085a0d5a-b650-5030-a423-8cf60a256f36'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/e7c60c490134f7f1-lesson-01-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The letter B. Bag. The letter M. Mai. My name is Ben. B. E. N."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f9a3ca49-47f7-52e2-a279-5bdcb2b8e4ac'::uuid,'085a0d5a-b650-5030-a423-8cf60a256f36'::uuid,'multiple_choice',1,'{"question":"เมื่อบอกเพื่อนให้เขียนชื่อ Ben คุณกำลังใช้สิ่งใด?","choices":[{"id":"choice_1","text":"ชื่ออักษร B–E–N"},{"id":"choice_2","text":"เสียง /b/ เพียงเสียงเดียว"},{"id":"choice_3","text":"ชื่ออักษรแปลความหมายชื่อ"}],"correctChoiceId":"choice_1","explanation":"การสะกดบอกชื่ออักษรทีละตัว ส่วนการอ่าน Ben ออกเป็นคำ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1678b5ae-edb2-5ac8-ac0e-0fe58fb7b181'::uuid,'085a0d5a-b650-5030-a423-8cf60a256f36'::uuid,'multiple_choice',1,'{"question":"คำใดใช้ตัวใหญ่เหมาะสม?","choices":[{"id":"choice_1","text":"my name is mai."},{"id":"choice_2","text":"My name is Mai."},{"id":"choice_3","text":"MY name IS mai."}],"correctChoiceId":"choice_2","explanation":"ต้นประโยค My และชื่อเฉพาะ Mai ใช้ตัวใหญ่"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7b56b649-baee-5fa5-a8cd-91cca978d8eb'::uuid,'085a0d5a-b650-5030-a423-8cf60a256f36'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nสะกดชื่อของคุณด้วยชื่ออักษร จากนั้นอ่านชื่อเป็นคำหนึ่งครั้ง แล้วเขียน My name is …\n\n### ตัวอย่างคำตอบ\n\nMy name is Ben. B–E–N.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ชื่ออักษรกับเสียงในคำ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e09e4cbf-ba5e-5122-af44-301b980a6dab'::uuid,'658211ac-434f-5bcc-aa59-46838417e2fe'::uuid,'reading',1,'{"title":"พยัญชนะและคู่เสียง","body":"## พยัญชนะและคู่เสียง\n\nใช้หูและตำแหน่งปากช่วยแยกเสียง /r/ กับ /l/ และ /v/ กับ /w/ สำหรับ /l/ ปลายลิ้นแตะบริเวณหลังฟันบน ส่วน /r/ ในสำเนียงอเมริกันไม่แตะตำแหน่งนั้น /v/ ใช้ฟันบนแตะริมฝีปากล่างและมีเสียงสั่น /w/ เริ่มจากริมฝีปากกลม th อาจเป็น /θ/ ใน think หรือ /ð/ ใน this; sh /ʃ/ ต่างจาก ch /tʃ/ ที่มีช่วงกักเสียงก่อนปล่อย\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| light / right | คู่เสียงต้นต่างกัน ความหมายจึงต่าง |\n| vest / west | เสื้อกั๊ก / ทิศตะวันตก |\n| ship / chip | sh กับ ch ไม่ใช่เสียงเดียวกัน |\n\n### จุดที่มักสับสน\n\nฝึกช้าแล้วเพิ่มความเร็วโดยไม่เพิ่มสระแทรก ไม่ต้องเลียนสำเนียงเดียวให้เหมือนทั้งหมด เป้าหมายคือให้ผู้ฟังแยกคำได้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council TeachingEnglish — Stress](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/q-s/stress) · [British Council TeachingEnglish — Connected speech](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/connected-speech)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('40733f0a-77fc-5719-a105-dcc11223d92c'::uuid,'658211ac-434f-5bcc-aa59-46838417e2fe'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/6bc7453c7fada9d9-lesson-01-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Light. Right. Light. Right. Vest. West. Vest. West. Think. This. Ship. Chip."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0d2154d7-5acf-58eb-a01b-bc0140a5e3d6'::uuid,'658211ac-434f-5bcc-aa59-46838417e2fe'::uuid,'multiple_choice',1,'{"question":"คู่ใดใช้เสียงเริ่ม /v/ กับ /w/?","choices":[{"id":"choice_1","text":"vest / west"},{"id":"choice_2","text":"light / right"},{"id":"choice_3","text":"ship / chip"}],"correctChoiceId":"choice_1","explanation":"vest เริ่ม /v/; west เริ่ม /w/"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('314053f8-e8f9-5067-a33e-e4df9422127e'::uuid,'658211ac-434f-5bcc-aa59-46838417e2fe'::uuid,'multiple_choice',1,'{"question":"คำว่า think กับ this มี th แบบใด?","choices":[{"id":"choice_1","text":"เสียงเดียวกันทุกตำแหน่ง"},{"id":"choice_2","text":"think ไม่มีเสียงสั่น ส่วน this มีเสียงสั่น"},{"id":"choice_3","text":"th อ่านเป็น t เสมอ"}],"correctChoiceId":"choice_2","explanation":"/θ/ ใน think ไม่ก้อง ส่วน /ð/ ใน this ก้อง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('113fd11b-55f5-5279-ad6d-61651ffc837f'::uuid,'658211ac-434f-5bcc-aa59-46838417e2fe'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nฟังเสียงจากพจนานุกรมของ light/right และ vest/west แล้วพูดแต่ละคู่สลับกันสามรอบ ให้ผู้ฟังชี้คำที่ได้ยิน\n\n### ตัวอย่างคำตอบ\n\nlight — right; vest — west. หากเพื่อนชี้ผิด ให้ลดความเร็วและตรวจตำแหน่งปากก่อนลองใหม่\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **พยัญชนะและคู่เสียง** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9074a2ab-f959-56a8-a02d-2f43c5b0fea1'::uuid,'61e3a677-5bd8-5be3-ad34-54cce5775c9c'::uuid,'reading',1,'{"title":"เสียงสระและการอ่านคำ","body":"## เสียงสระและการอ่านคำ\n\nเสียงสระเป็นส่วนสำคัญของคำ ship /ʃɪp/ กับ sheep /ʃiːp/ ต่างทั้งคุณภาพสระและความยาว ไม่ใช่เพียงยืดเสียงเดิม bed /bed/ ต่างจาก bad /bæd/ ตัวสะกดภาษาอังกฤษไม่จับคู่กับเสียงแบบหนึ่งต่อหนึ่ง เช่น ea ใน tea กับ bread ออกเสียงต่างกัน จึงตรวจเสียงของทั้งคำพร้อมฟังและอ่าน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| ship / sheep | เรือ / แกะ: เสียงสระต่างกัน |\n| bed / bad | เตียง / ไม่ดี |\n| tea / bread | ea เขียนเหมือนกัน แต่เสียงต่าง |\n\n### จุดที่มักสับสน\n\nการถอดเสียงด้วยอักษรไทยช่วยเริ่มได้ แต่ไม่แทนรายละเอียดของเสียงจริง ตรวจเสียงคำเต็มเสมอ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council TeachingEnglish — Stress](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/q-s/stress) · [British Council TeachingEnglish — Connected speech](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/connected-speech)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9e2d4448-6bf2-574a-a1c9-b30df96645ad'::uuid,'61e3a677-5bd8-5be3-ad34-54cce5775c9c'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/0f7d6d07adfaa6c8-lesson-01-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Ship. Sheep. Ship. Sheep. Bed. Bad. Bed. Bad. Tea. Bread. A sheep is on the ship."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('758c5cbb-be70-54e9-a0f0-097c9dbf0648'::uuid,'61e3a677-5bd8-5be3-ad34-54cce5775c9c'::uuid,'multiple_choice',1,'{"question":"คู่ใดต่างที่เสียงสระเป็นหลัก?","choices":[{"id":"choice_1","text":"ship / sheep"},{"id":"choice_2","text":"vest / west"},{"id":"choice_3","text":"light / right"}],"correctChoiceId":"choice_1","explanation":"ship /ʃɪp/ และ sheep /ʃiːp/ มีพยัญชนะต้นท้ายเหมือนกัน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('282ef81c-766d-59e4-af2d-bc8a53387881'::uuid,'61e3a677-5bd8-5be3-ad34-54cce5775c9c'::uuid,'multiple_choice',1,'{"question":"ea ใน tea และ bread บอกอะไร?","choices":[{"id":"choice_1","text":"อักษรกลุ่มเดียวกันมีได้หลายเสียง"},{"id":"choice_2","text":"ea ต้องอ่าน /iː/ เสมอ"},{"id":"choice_3","text":"ตัวสะกดไม่เกี่ยวกับเสียงเลย"}],"correctChoiceId":"choice_1","explanation":"tea ใช้ /iː/ แต่ bread ใช้ /e/ จึงดูคำเต็มประกอบ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5188b7db-da6c-520f-ad23-e654e3ea8618'::uuid,'61e3a677-5bd8-5be3-ad34-54cce5775c9c'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nฟัง ship/sheep และ bed/bad จดว่าคำใดออกเสียงยาก จากนั้นพูดประโยคสั้นพร้อมคำเป้าหมาย\n\n### ตัวอย่างคำตอบ\n\nA sheep is on the ship. This bed is bad.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เสียงสระและการอ่านคำ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3d2db5b9-2721-5f7f-ab05-aa05c512dc47'::uuid,'245f14ad-f282-558e-ac44-cd2071ef68b3'::uuid,'reading',1,'{"title":"เสียงท้ายคำและพยัญชนะควบ","body":"## เสียงท้ายคำและพยัญชนะควบ\n\nเสียงท้ายคำช่วยบอกทั้งคำศัพท์และไวยากรณ์ cap /kæp/ กับ cat /kæt/ ต่างเสียงท้าย ต้องคงตำแหน่งปากแม้บางสำเนียงไม่ปล่อยเสียง /t/ ชัดทุกครั้ง กลุ่มพยัญชนะเช่น /st/ ใน stop และ /ks/ ใน books ไม่ต้องเติมเสียงสระระหว่างกลาง ลองแยกเสียงช้าแล้วรวมเป็นพยางค์เดียว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| cap / cat | ต่างเสียงท้าย /p/ และ /t/ |\n| book / books | books มีเสียงท้าย /ks/ บอกหลายเล่ม |\n| stop | เริ่มด้วย /st/ โดยไม่มีสระแทรก |\n\n### จุดที่มักสับสน\n\nไม่อ่าน books เป็นสองพยางค์ และไม่ละเสียงท้ายทุกคำเพราะอาจเปลี่ยนความหมาย\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council TeachingEnglish — Stress](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/q-s/stress) · [British Council TeachingEnglish — Connected speech](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/connected-speech)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('78c6287b-54e4-5d4f-a775-27f3362fb6e8'::uuid,'245f14ad-f282-558e-ac44-cd2071ef68b3'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/648cc4af47d15954-lesson-01-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Cap. Cat. Cap. Cat. Book. Books. One book. Two books. Stop. Books."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b580a26d-a4fe-52a2-ae51-3101158bacde'::uuid,'245f14ad-f282-558e-ac44-cd2071ef68b3'::uuid,'multiple_choice',1,'{"question":"book กับ books ต่างกันอย่างไร?","choices":[{"id":"choice_1","text":"books มีเสียงท้ายและรูปพหูพจน์"},{"id":"choice_2","text":"books มีสระเพิ่มหนึ่งพยางค์เสมอ"},{"id":"choice_3","text":"ไม่มีความต่าง"}],"correctChoiceId":"choice_1","explanation":"เสียง /s/ ที่เพิ่มทำให้เป็น books หลายเล่ม"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0aceed7a-a26c-5e12-a812-0d254127d4e7'::uuid,'245f14ad-f282-558e-ac44-cd2071ef68b3'::uuid,'multiple_choice',1,'{"question":"คำว่า stop ควรเริ่มอย่างไร?","choices":[{"id":"choice_1","text":"/s/ ต่อ /t/ โดยไม่มีสระแทรก"},{"id":"choice_2","text":"เติมเสียงอะระหว่าง s กับ t"},{"id":"choice_3","text":"ละ t"}],"correctChoiceId":"choice_1","explanation":"กลุ่ม /st/ อยู่ในพยางค์เดียวกัน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('77f7ec21-96c7-527a-af98-44dc15ffd6c0'::uuid,'245f14ad-f282-558e-ac44-cd2071ef68b3'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nอ่าน cap/cat และ book/books แล้วบันทึกเสียง ตรวจว่ามีเสียงท้ายและไม่มีสระที่เพิ่มเอง\n\n### ตัวอย่างคำตอบ\n\ncap — cat; one book — two books; stop.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เสียงท้ายคำและพยัญชนะควบ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('72f9da03-11f5-55ba-af79-02ec9c14c22e'::uuid,'1717e0c0-8dca-580b-a773-ecd4073d65c4'::uuid,'reading',1,'{"title":"ตัวสะกดที่พบบ่อย","body":"## ตัวสะกดที่พบบ่อย\n\nกลุ่มตัวสะกดช่วยเดาเสียงเบื้องต้นได้ เช่น sh ใน shop, ch ใน chair, th ใน three; แต่ ch ใน school ไม่เป็น /tʃ/ เสมอ silent e อาจเปลี่ยนเสียงสระ เช่น cap/cape ส่วนตัวเงียบใน know และ walk ต้องเรียนเป็นคำ กลุ่มสระ ai ใน rain เป็นแนวทางที่ใช้บ่อย ไม่ใช่กฎที่รับรองทุกคำ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| cap / cape | e ท้ายไม่ออกเสียง แต่สัมพันธ์กับสระที่เปลี่ยน |\n| rain / train | ai มักออกเสียง /eɪ/ |\n| know / walk | k ใน know และ l ใน walk ไม่ออกเสียงในสำเนียงมาตรฐานทั่วไป |\n\n### จุดที่มักสับสน\n\nตัวสะกดให้ข้อสันนิษฐาน แล้วใช้เสียงพจนานุกรมตรวจ อย่าบอกว่า ch หรือ silent e ใช้กฎเดียวทุกคำ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council TeachingEnglish — Stress](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/q-s/stress) · [British Council TeachingEnglish — Connected speech](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/connected-speech)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('715d7c91-85ad-56df-aef2-58fd44fc5b84'::uuid,'1717e0c0-8dca-580b-a773-ecd4073d65c4'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/37b0e17b2750dd3e-lesson-01-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Cap. Cape. Cap. Cape. Rain. Train. Shop. Chair. Three. Know. Walk."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('49c81399-8c4d-5065-ad82-e4b323bf0ac5'::uuid,'1717e0c0-8dca-580b-a773-ecd4073d65c4'::uuid,'multiple_choice',1,'{"question":"เสียงต้นของ know ในสำเนียงทั่วไปคืออะไร?","choices":[{"id":"choice_1","text":"/n/"},{"id":"choice_2","text":"/k/"},{"id":"choice_3","text":"/kn/ มีสองเสียง"}],"correctChoiceId":"choice_1","explanation":"k เป็นตัวเงียบใน know"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('676f27dc-3d90-58ad-ab2a-38cf0824ba3a'::uuid,'1717e0c0-8dca-580b-a773-ecd4073d65c4'::uuid,'multiple_choice',1,'{"question":"คู่ใดแสดงรูป silent e ที่เปลี่ยนสระ?","choices":[{"id":"choice_1","text":"cap / cape"},{"id":"choice_2","text":"cat / cats"},{"id":"choice_3","text":"go / goes"}],"correctChoiceId":"choice_1","explanation":"cape มี e ท้ายเงียบและเสียงสระ /eɪ/ ต่างจาก cap"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('78d8274d-1360-5737-af48-a6ef4930430d'::uuid,'1717e0c0-8dca-580b-a773-ecd4073d65c4'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเลือกคำใหม่สามคำที่มี sh/ch/ai หรือ silent e ลองเดาแล้วฟังตรวจ เขียนจุดที่เดาถูกและต้องแก้\n\n### ตัวอย่างคำตอบ\n\nshop: sh /ʃ/; rain: ai /eɪ/; cape: a /eɪ/ และ e เงียบ\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ตัวสะกดที่พบบ่อย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('80b93108-84ec-5e74-aad8-338a2a533ddf'::uuid,'7601f278-d6be-5fd6-ae6a-ba48726d3f0d'::uuid,'reading',1,'{"title":"พยางค์และเสียงเน้น","body":"## พยางค์และเสียงเน้น\n\nพยางค์คือช่วงเสียงที่มีแกนสระ เช่น teacher มีสองพยางค์และเน้นพยางค์แรก ส่วน banana มีสามพยางค์และเน้นพยางค์ที่สอง พยางค์เน้นมักชัด ยาว หรือเด่นกว่าพยางค์อื่น สัญลักษณ์ ˈ อยู่ก่อนพยางค์เน้นในพจนานุกรม และ /ə/ เป็นเสียง schwa ที่พบบ่อยในพยางค์ไม่เน้น ตรวจชนิดสำเนียงและปุ่มเสียงควบคู่กัน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| TEA-cher | teacher เน้นพยางค์แรก |\n| ba-NA-na | banana เน้นพยางค์กลาง |\n| a-BOUT | about เน้นพยางค์ที่สอง ส่วน a มักเป็น /ə/ |\n\n### จุดที่มักสับสน\n\nอย่าเน้นทุกพยางค์เท่ากันหรือนับพยางค์จากจำนวนตัวสระที่เขียน\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council TeachingEnglish — Stress](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/q-s/stress) · [British Council TeachingEnglish — Connected speech](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/connected-speech)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('dccd3a07-8023-5902-a1ec-d04e9fbe0c82'::uuid,'7601f278-d6be-5fd6-ae6a-ba48726d3f0d'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/ddb599c8b30e8c51-lesson-01-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Teacher. Teacher. Banana. Banana. About. About. Student. Today."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e2537763-f975-5c40-aede-287237851fa3'::uuid,'7601f278-d6be-5fd6-ae6a-ba48726d3f0d'::uuid,'multiple_choice',1,'{"question":"banana โดยทั่วไปเน้นพยางค์ใด?","choices":[{"id":"choice_1","text":"แรก"},{"id":"choice_2","text":"กลาง"},{"id":"choice_3","text":"ท้าย"}],"correctChoiceId":"choice_2","explanation":"banana เน้น NA; ฟังทั้งคำเพื่อได้จังหวะ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('35a5ac38-3091-5c0f-a015-b5b6f2d7e3f8'::uuid,'7601f278-d6be-5fd6-ae6a-ba48726d3f0d'::uuid,'multiple_choice',1,'{"question":"สัญลักษณ์ ˈ ในรายการเสียงช่วยบอกอะไร?","choices":[{"id":"choice_1","text":"พยางค์ที่มี stress"},{"id":"choice_2","text":"คำพหูพจน์"},{"id":"choice_3","text":"คำที่ไม่ต้องอ่าน"}],"correctChoiceId":"choice_1","explanation":"เครื่องหมายอยู่หน้าพยางค์เน้น"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3069d948-25a1-5bef-a9c1-4ed4bef811a0'::uuid,'7601f278-d6be-5fd6-ae6a-ba48726d3f0d'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเปิดพจนานุกรมของ teacher, banana และ about ฟังแล้วเคาะจังหวะพยางค์เน้น บันทึกคำที่คุณใช้จริงเพิ่มสองคำ\n\n### ตัวอย่างคำตอบ\n\nTEAcher; baNAna; aBOUT. คำของฉัน: STUdent และ toDAY.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **พยางค์และเสียงเน้น** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1011eaad-78b3-5f1c-a87e-430999206061'::uuid,'49214b16-4c9c-5bc4-a420-8cc21e2aa7ee'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **ฟังแยกเสียงสำคัญ อ่านคำคุ้นเคย และรู้วิธีตรวจเสียงจากพจนานุกรม**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ชื่ออักษรกับเสียงในคำ: B → /biː/; bag → /b/; TEAcher · baNAna](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/88de95eecda14f2e-module-01-map.png)\n\n*สะกดด้วยชื่ออักษร อ่านด้วยเสียง และฟังคำเต็ม*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2d580cf8-6838-5e98-a498-e620c3ee4161'::uuid,'49214b16-4c9c-5bc4-a420-8cc21e2aa7ee'::uuid,'multiple_choice',1,'{"question":"คู่ใดต่างที่พยัญชนะต้น r/l?","choices":[{"id":"choice_1","text":"rice/light"},{"id":"choice_2","text":"ship/sheep"},{"id":"choice_3","text":"tea/tea"}],"correctChoiceId":"choice_1","explanation":"rice เริ่ม /r/ และ light เริ่ม /l/; ย้อน 01.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f0821503-0941-595d-ad30-a7a31a6d0b7f'::uuid,'49214b16-4c9c-5bc4-a420-8cc21e2aa7ee'::uuid,'multiple_choice',1,'{"question":"silent e ปรากฏในคำใด?","choices":[{"id":"choice_1","text":"bike"},{"id":"choice_2","text":"big"},{"id":"choice_3","text":"bus"}],"correctChoiceId":"choice_1","explanation":"e ท้าย bike ไม่ออกเสียงและสัมพันธ์กับเสียง i; ย้อน 01.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('91862da4-3c60-5c39-a7c4-8ccbffe8926a'::uuid,'49214b16-4c9c-5bc4-a420-8cc21e2aa7ee'::uuid,'multiple_choice',1,'{"question":"teacher โดยทั่วไปมี stress ที่ใด?","choices":[{"id":"choice_1","text":"พยางค์แรก"},{"id":"choice_2","text":"พยางค์ท้าย"},{"id":"choice_3","text":"ทุกพยางค์เท่ากัน"}],"correctChoiceId":"choice_1","explanation":"TEAcher; ฟังพจนานุกรมตรวจ ย้อน 01.06"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5790b162-9e1a-50ea-afec-9c1b8337bfa7'::uuid,'49214b16-4c9c-5bc4-a420-8cc21e2aa7ee'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nสะกดชื่อ อ่าน light/right, ship/sheep, book/books แล้วเลือกคำใหม่สองคำฟังตรวจเสียง บันทึกตนเองหนึ่งรอบ\n\n### ตัวอย่างผลงาน\n\nMy name is Mai. M–A–I. light/right; ship/sheep; book/books. คำใหม่ teacher และ about\n\n### ตรวจผลงาน\n\n- แยกชื่ออักษรกับเสียงคำ\n- คงเสียงท้ายและไม่เพิ่มสระแทรก\n- ตรวจ word stress ด้วยเสียงจริง\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('833269f2-78dd-5096-a5e9-2fbe95577fe9'::uuid,'bb47b533-f083-5dfd-a74c-6b1cb228a7d3'::uuid,'reading',1,'{"title":"หน้าที่ของคำ","body":"## หน้าที่ของคำ\n\nคำมีหน้าที่ต่างกัน noun เรียกคนหรือสิ่ง; pronoun แทน noun; verb บอกการกระทำหรือสภาพ; adjective บรรยาย noun; adverb ขยายการกระทำหรือระดับ; determiner ชี้หรือกำหนด noun; preposition เชื่อมความสัมพันธ์; conjunction เชื่อมความคิด ดูหน้าที่จากประโยค เพราะคำเดียวอาจทำหน้าที่ต่างกัน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The small cat sleeps quietly. | The กำหนด noun, small บรรยาย cat, sleeps เป็น verb, quietly เป็น adverb |\n| She reads in the room and smiles. | She แทนคน, in เชื่อมตำแหน่ง, and เชื่อมการกระทำ |\n\n### จุดที่มักสับสน\n\nชื่อชนิดคำเป็นเครื่องมือช่วยเรียงประโยค ไม่ต้องจำชื่อทั้งหมดก่อนเริ่มใช้ และอย่าตัดสินจากคำโดดอย่างเดียว\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('084e84dc-7f06-55f4-a399-c50ec53560d7'::uuid,'bb47b533-f083-5dfd-a74c-6b1cb228a7d3'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/76727603ec5e8807-lesson-02-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The small cat sleeps quietly.. She reads in the room and smiles."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('69dc76ec-01ed-52e8-a539-e28f3a53bbfc'::uuid,'bb47b533-f083-5dfd-a74c-6b1cb228a7d3'::uuid,'multiple_choice',1,'{"question":"ใน a red bag คำ red ทำหน้าที่อะไร?","choices":[{"id":"choice_1","text":"adjective"},{"id":"choice_2","text":"verb"},{"id":"choice_3","text":"preposition"}],"correctChoiceId":"choice_1","explanation":"red บรรยายสีของ bag"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('12079903-dfbb-542c-add6-308439107ba3'::uuid,'bb47b533-f083-5dfd-a74c-6b1cb228a7d3'::uuid,'multiple_choice',1,'{"question":"ใน They work here คำ They ทำหน้าที่อะไร?","choices":[{"id":"choice_1","text":"noun ชื่อสถานที่"},{"id":"choice_2","text":"pronoun แทนกลุ่มคน"},{"id":"choice_3","text":"adverb"}],"correctChoiceId":"choice_2","explanation":"They แทนกลุ่มคนที่เป็นประธาน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8014b73b-030a-516d-a55e-c9e31153f2aa'::uuid,'bb47b533-f083-5dfd-a74c-6b1cb228a7d3'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nแยกหน้าที่คำใน The blue bird flies แล้วแต่งอีกหนึ่งประโยค\n\n### ตัวอย่างคำตอบ\n\nThe: determiner; blue: adjective; bird: noun; flies: verb. My small dog runs.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **หน้าที่ของคำ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fbfbc4af-05f5-597d-a8bd-983a19eee0b9'::uuid,'a5a64ce0-f781-5f86-a956-30719742f771'::uuid,'reading',1,'{"title":"ใครทำอะไร","body":"## ใครทำอะไร\n\nประโยคบอกเล่าทั่วไปต้องมีประธานว่าใครหรืออะไร และกริยาว่าทำอะไรหรือมีสภาพอย่างไร ลำดับพื้นฐานคือ subject + verb ประธานอาจเป็นชื่อ กลุ่มคำนามหรือสรรพนาม แม้ภาษาไทยละประธานได้ในบางบริบท ประโยคอังกฤษทั่วไปยังต้องใส่ it/they/I ให้ชัด คำสั่งอย่าง Sit down. เป็นข้อยกเว้นที่เรียนภายหลัง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Birds fly. | Birds ประธาน; fly กริยา |\n| Mai works. | Mai ประธาน; works กริยา |\n\n### จุดที่มักสับสน\n\nRuns fast. ยังไม่มีประธานหากตั้งใจใช้เป็นประโยคบอกเล่าปกติ ให้เขียน She runs fast.\n\n\n\n### ดูภาพแล้วลองใช้\n\n![จากคำสู่ประโยค: Mai; reads; books](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/38035a43a72bfb52-module-02-map.png)\n\n*ใคร → ทำอะไร → กับสิ่งใด  •  บางกริยาไม่ต้องมีกรรม*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('82018a6a-f0e1-557c-aafd-09c7a166c440'::uuid,'a5a64ce0-f781-5f86-a956-30719742f771'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f9a4258148ad79ec-lesson-02-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Birds fly.. Mai works."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b79a8706-b06e-58a5-a6f3-e8f9577a2f13'::uuid,'a5a64ce0-f781-5f86-a956-30719742f771'::uuid,'multiple_choice',1,'{"question":"ประโยคใดมีทั้งประธานและกริยา?","choices":[{"id":"choice_1","text":"My friend."},{"id":"choice_2","text":"My friend runs."},{"id":"choice_3","text":"Runs in the park."}],"correctChoiceId":"choice_2","explanation":"My friend เป็นประธานและ runs เป็นกริยา"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a1850623-4318-5012-aa38-35afeec2da41'::uuid,'a5a64ce0-f781-5f86-a956-30719742f771'::uuid,'multiple_choice',1,'{"question":"ใน The children play คำใดเป็นประธาน?","choices":[{"id":"choice_1","text":"The children"},{"id":"choice_2","text":"play"},{"id":"choice_3","text":"children play"}],"correctChoiceId":"choice_1","explanation":"กลุ่มคำนาม The children บอกว่าใครทำ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('28a87951-2a82-5d46-ac53-37b3e469760a'::uuid,'a5a64ce0-f781-5f86-a956-30719742f771'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสามประโยคเกี่ยวกับคนหรือสัตว์ ขีดเส้นใต้ประธานและวงกริยา\n\n### ตัวอย่างคำตอบ\n\nI read. Ben walks. Birds sing.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ใครทำอะไร** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2456d34b-0189-557f-a1e2-eda40dd766af'::uuid,'2151855f-4d35-5898-a855-0e29ac00030a'::uuid,'reading',1,'{"title":"ทำอะไรกับใครหรือสิ่งใด","body":"## ทำอะไรกับใครหรือสิ่งใด\n\nบางกริยาต้องมีกรรมเพื่อบอกสิ่งหรือผู้รับการกระทำ เช่น I read books. มี books เป็นกรรม แต่ Birds fly. สมบูรณ์ได้โดยไม่ต้องมีกรรม กรรมมักอยู่หลังกริยาในประโยคพื้นฐาน อย่าสับสนกรรมกับข้อมูลสถานที่ เช่น in the park บอกที่ ไม่ใช่สิ่งที่ read อ่าน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I read books. | I ประธาน, read กริยา, books กรรม |\n| Birds fly in the sky. | fly ไม่ต้องมีกรรม; in the sky บอกที่ |\n\n### จุดที่มักสับสน\n\nไม่ใช่ทุกคำหลังกริยาเป็นกรรม และไม่ใช่ทุกประโยคต้องมีกรรม\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e0add626-52d4-5098-a758-0e936b97fa56'::uuid,'2151855f-4d35-5898-a855-0e29ac00030a'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/256e7e6a9b7cfdca-lesson-02-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I read books.. Birds fly in the sky."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('dd71b2cc-c9a1-55fe-a8b8-1058109956a2'::uuid,'2151855f-4d35-5898-a855-0e29ac00030a'::uuid,'multiple_choice',1,'{"question":"ใน Ben drinks water กรรมคือคำใด?","choices":[{"id":"choice_1","text":"Ben"},{"id":"choice_2","text":"drinks"},{"id":"choice_3","text":"water"}],"correctChoiceId":"choice_3","explanation":"water เป็นสิ่งที่ Ben ดื่ม"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('210b31f3-9abe-5af4-a8ea-a6687b93836d'::uuid,'2151855f-4d35-5898-a855-0e29ac00030a'::uuid,'multiple_choice',1,'{"question":"ประโยคใดสมบูรณ์โดยไม่ต้องมีกรรม?","choices":[{"id":"choice_1","text":"Birds fly."},{"id":"choice_2","text":"She puts."},{"id":"choice_3","text":"She gives."}],"correctChoiceId":"choice_1","explanation":"fly ใช้แบบไม่รับกรรมได้; puts/gives ต้องมีส่วนที่ตามในรูปตัวอย่างนี้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fa9184da-2f90-5de8-aebd-80a6216033f6'::uuid,'2151855f-4d35-5898-a855-0e29ac00030a'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nแต่งประโยคมีกับไม่มีกรรมอย่างละสองประโยค\n\n### ตัวอย่างคำตอบ\n\nI eat rice. She reads a book. Birds sing. We walk.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ทำอะไรกับใครหรือสิ่งใด** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('31c1fdf5-98b7-581c-acb7-f99ff69202d3'::uuid,'c0fc10c5-10bd-5e16-afca-73cd1da24701'::uuid,'reading',1,'{"title":"บอกว่าเป็นอะไรหรือเป็นอย่างไร","body":"## บอกว่าเป็นอะไรหรือเป็นอย่างไร\n\nถ้าบอกว่าใครเป็นอะไรหรือเป็นอย่างไร ใช้ subject + be + complement เช่น I am a student. และ She is happy. ส่วนเติมเต็มไม่ได้เป็นสิ่งที่ได้รับการกระทำ แต่บอกข้อมูลของประธาน be ในรูปปัจจุบันคือ am/is/are ต่างจากกริยาทั่วไปอย่าง work จึงไม่เติม be นำหน้ากริยาทั่วไปโดยอัตโนมัติ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Ben is a teacher. | a teacher บอกว่า Ben เป็นอะไร |\n| Ben teaches English. | teaches คือการกระทำ; English เป็นกรรม |\n\n### จุดที่มักสับสน\n\nI am happy. ถูก แต่ I am work. ไม่ใช่ Present Simple ที่ถูก ให้ใช้ I work.\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d23b0d42-eac7-58e8-ace8-b007cb5f5045'::uuid,'c0fc10c5-10bd-5e16-afca-73cd1da24701'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2a2564c5f7520960-lesson-02-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Ben is a teacher.. Ben teaches English."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fc970138-fe2f-58a5-ad1f-bec33cdb8495'::uuid,'c0fc10c5-10bd-5e16-afca-73cd1da24701'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคบอกสภาพที่ถูกต้อง","choices":[{"id":"choice_1","text":"She happy."},{"id":"choice_2","text":"She is happy."},{"id":"choice_3","text":"She is smiles."}],"correctChoiceId":"choice_2","explanation":"happy เป็น adjective จึงใช้ is เชื่อมประธานกับสภาพ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3353a7e7-7fb0-5b97-a4de-bd32f153bbc6'::uuid,'c0fc10c5-10bd-5e16-afca-73cd1da24701'::uuid,'multiple_choice',1,'{"question":"ข้อใดเป็นการกระทำด้วยกริยาทั่วไป?","choices":[{"id":"choice_1","text":"I am a cook."},{"id":"choice_2","text":"I cook rice."},{"id":"choice_3","text":"I am tired."}],"correctChoiceId":"choice_2","explanation":"cook เป็น verb และ rice เป็นกรรม"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bb1ea069-520e-550b-a929-501c6b5938c9'::uuid,'c0fc10c5-10bd-5e16-afca-73cd1da24701'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนข้อมูลตัวตนสองประโยคและการกระทำสองประโยค\n\n### ตัวอย่างคำตอบ\n\nI am a student. I am happy. I read books. I study English.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **บอกว่าเป็นอะไรหรือเป็นอย่างไร** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b153efde-f11b-59f2-a042-409f445dfe94'::uuid,'69485de7-81bf-5c8a-aa08-eb66a936bd0d'::uuid,'reading',1,'{"title":"เขียนประโยคให้อ่านรู้เรื่อง","body":"## เขียนประโยคให้อ่านรู้เรื่อง\n\nเริ่มประโยคด้วยตัวใหญ่ ใช้ I ตัวใหญ่เสมอและใช้ตัวใหญ่กับชื่อเฉพาะ เว้นช่องระหว่างคำและจบประโยคบอกเล่าด้วย full stop คำถามใช้ question mark ลำดับคำช่วยให้ผู้อ่านรู้ว่าใครทำอะไร คำคือหน่วยหนึ่ง; วลีเช่น a small bag ยังไม่ใช่ประโยคเต็ม; ประโยคอย่าง The bag is small. มีประธานและกริยา\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I live in Bangkok. | I และ Bangkok ตัวใหญ่ มีช่องและจุดท้าย |\n| Is the bag small? | คำถามใช้ ? |\n| a small bag | เป็นวลีคำนาม ยังไม่เป็นประโยคเต็ม |\n\n### จุดที่มักสับสน\n\nไม่ใช้ตัวใหญ่กลางคำทั่วไปเพียงเพื่อเน้น และไม่ต่อทุกประโยคโดยไม่มีเครื่องหมาย\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4fbe162c-aa4e-55cf-a44b-5d4f6f6277b8'::uuid,'69485de7-81bf-5c8a-aa08-eb66a936bd0d'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/6a6815ccd98f351d-lesson-02-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I live in Bangkok.. Is the bag small?. a small bag"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c1de63d2-952a-51bc-a171-2be83874c5c2'::uuid,'69485de7-81bf-5c8a-aa08-eb66a936bd0d'::uuid,'multiple_choice',1,'{"question":"ข้อใดเขียนถูกตามพื้นฐาน?","choices":[{"id":"choice_1","text":"i live in bangkok."},{"id":"choice_2","text":"I live in Bangkok."},{"id":"choice_3","text":"I Live In Bangkok"}],"correctChoiceId":"choice_2","explanation":"I ชื่อ Bangkok และต้นประโยคใช้ตัวใหญ่; มี full stop"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('24990943-6d8d-522f-a37f-66e7becc9308'::uuid,'69485de7-81bf-5c8a-aa08-eb66a936bd0d'::uuid,'multiple_choice',1,'{"question":"ข้อใดเป็นประโยคเต็ม?","choices":[{"id":"choice_1","text":"a red bag"},{"id":"choice_2","text":"the small room"},{"id":"choice_3","text":"The room is small."}],"correctChoiceId":"choice_3","explanation":"มีประธาน The room กับกริยา is"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('545f1f2c-9cc0-5950-a2bb-403e55caaa25'::uuid,'69485de7-81bf-5c8a-aa08-eb66a936bd0d'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nแก้ i am ben i live in thailand ให้เป็นสองประโยค แล้วเขียนคำถามหนึ่งประโยค\n\n### ตัวอย่างคำตอบ\n\nI am Ben. I live in Thailand. Are you a student?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เขียนประโยคให้อ่านรู้เรื่อง** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cbff3361-42d9-5dcc-a9d8-6124eee6a5bb'::uuid,'fb53d8f6-bf3e-5d5c-a2a4-0c13f9d92f6d'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **แยกหน้าที่ของคำและสร้างประโยคที่ไม่ตกประธานหรือกริยา**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![จากคำสู่ประโยค: Mai; reads; books](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/38035a43a72bfb52-module-02-map.png)\n\n*ใคร → ทำอะไร → กับสิ่งใด  •  บางกริยาไม่ต้องมีกรรม*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ef1b98aa-ef78-5105-ac6c-7aabb922e968'::uuid,'fb53d8f6-bf3e-5d5c-a2a4-0c13f9d92f6d'::uuid,'multiple_choice',1,'{"question":"ใน My dog eats rice ประธานคืออะไร?","choices":[{"id":"choice_1","text":"My dog"},{"id":"choice_2","text":"eats"},{"id":"choice_3","text":"rice"}],"correctChoiceId":"choice_1","explanation":"กลุ่ม My dog เป็นผู้ทำ ย้อน 02.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('33ed4f01-8274-51d7-a833-25d99183de3c'::uuid,'fb53d8f6-bf3e-5d5c-a2a4-0c13f9d92f6d'::uuid,'multiple_choice',1,'{"question":"ประโยคใดไม่ต้องมีกรรม?","choices":[{"id":"choice_1","text":"The baby sleeps."},{"id":"choice_2","text":"She puts."},{"id":"choice_3","text":"I put."}],"correctChoiceId":"choice_1","explanation":"sleeps ใช้โดยไม่มีกรรมได้ ย้อน 02.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d53abea0-aa2c-5c99-abf9-fcf0e7dcf58a'::uuid,'fb53d8f6-bf3e-5d5c-a2a4-0c13f9d92f6d'::uuid,'multiple_choice',1,'{"question":"แก้ประโยคใดเป็นข้อมูลสภาพถูก?","choices":[{"id":"choice_1","text":"He is cold."},{"id":"choice_2","text":"He cold."},{"id":"choice_3","text":"He is walks."}],"correctChoiceId":"choice_1","explanation":"cold เป็น adjective จึงใช้ is ย้อน 02.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('eb576a69-e6f2-5440-ac03-57e77d6a369c'::uuid,'fb53d8f6-bf3e-5d5c-a2a4-0c13f9d92f6d'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเขียนสองประโยคการกระทำและสองประโยคสภาพ พร้อมระบุ subject/verb/object หรือ complement\n\n### ตัวอย่างผลงาน\n\nI eat rice. Birds fly. Ben is happy. His room is small.\n\n### ตรวจผลงาน\n\n- ทุกประโยคบอกเล่ามีประธานกับกริยา\n- แยกกรรมจากคำบรรยายประธาน\n- ใช้ตัวใหญ่และเครื่องหมายท้าย\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c2b5b835-a48d-5830-aa9d-815c2b2369d3'::uuid,'65bea9fa-4019-55f2-ab8f-e87d9d7de9b1'::uuid,'reading',1,'{"title":"คน สิ่งของ สถานที่ และแนวคิด","body":"## คน สิ่งของ สถานที่ และแนวคิด\n\nคำนามเรียกคน สิ่งของ สถานที่และแนวคิด คำนามทั่วไปเช่น city ใช้กล่าวเป็นประเภท ส่วนชื่อเฉพาะเช่น Bangkok ระบุชื่อและขึ้นต้นตัวใหญ่ คำนามรูปธรรมอย่าง chair สัมผัสหรือสังเกตได้ ส่วน happiness เป็นแนวคิดหรือความรู้สึกที่นับเป็นชิ้นไม่ได้แบบเก้าอี้ อย่าเลือก article จากความเป็นรูปธรรมเพียงอย่างเดียว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| city / Bangkok | ประเภทเมือง / ชื่อเมืองเฉพาะ |\n| chair / happiness | สิ่งของ / แนวคิด |\n| teacher / Mai | ประเภทบุคคล / ชื่อบุคคล |\n\n### จุดที่มักสับสน\n\nภาษาและสัญชาติใช้ตัวใหญ่ เช่น English และ Thai แม้อยู่กลางประโยค\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5eca2f12-3f6b-550b-ab8e-66326a3da27c'::uuid,'65bea9fa-4019-55f2-ab8f-e87d9d7de9b1'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9f3f5d00e5d56105-lesson-03-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"city. Bangkok. chair. happiness. teacher. Mai"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0a1857b4-3a1e-581e-a2c6-0fe3a0d1d762'::uuid,'65bea9fa-4019-55f2-ab8f-e87d9d7de9b1'::uuid,'multiple_choice',1,'{"question":"ข้อใดเป็นชื่อเฉพาะ?","choices":[{"id":"choice_1","text":"school"},{"id":"choice_2","text":"Bangkok"},{"id":"choice_3","text":"happiness"}],"correctChoiceId":"choice_2","explanation":"Bangkok คือชื่อเมืองเฉพาะ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ddb22523-8ecc-5eec-a90b-eece3fc18c02'::uuid,'65bea9fa-4019-55f2-ab8f-e87d9d7de9b1'::uuid,'multiple_choice',1,'{"question":"คำใดเป็นคำนามแนวคิด?","choices":[{"id":"choice_1","text":"chair"},{"id":"choice_2","text":"bag"},{"id":"choice_3","text":"happiness"}],"correctChoiceId":"choice_3","explanation":"happiness บอกความสุข ไม่ใช่สิ่งที่นับเป็นชิ้นแบบ bag"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('86fead4f-237d-5811-a0f9-38834a4e87c0'::uuid,'65bea9fa-4019-55f2-ab8f-e87d9d7de9b1'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nจัดคำห้าคำรอบตัวเป็นชื่อทั่วไปหรือชื่อเฉพาะ แล้วเขียนหนึ่งประโยค\n\n### ตัวอย่างคำตอบ\n\ncity → Bangkok; person → Mai; language → English. Mai lives in Bangkok.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **คน สิ่งของ สถานที่ และแนวคิด** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c40b41b9-7710-55ce-a16b-b24ebb9b21ac'::uuid,'5ae7301c-833c-54f7-a381-7a1cb13536e6'::uuid,'reading',1,'{"title":"I, you, we, they, he, she, it","body":"## I, you, we, they, he, she, it\n\nใช้ I แทนผู้พูด; you แทนผู้ฟังหนึ่งหรือหลายคน; we รวมผู้พูดกับคนอื่น; they แทนกลุ่มหรือคนที่กล่าวถึง; he/she แทนบุคคลตามบริบท; it แทนสิ่งของ สัตว์หรือสภาพที่กำลังกล่าวถึง Subject pronouns ใช้เป็นประธาน ไม่เปลี่ยนตามจำนวนคำภาษาไทย และ they ใช้กับบุคคลหนึ่งคนได้เมื่อไม่ทราบหรือไม่ต้องระบุเพศ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Mai is here. She is happy. | She อ้างกลับ Mai |\n| Ben and I are friends. We study English. | We รวมผู้พูด |\n| You are welcome. | you อาจเป็นผู้ฟังหนึ่งคนหรือหลายคน |\n\n### จุดที่มักสับสน\n\nต้องทำให้ชัดว่า it/they อ้างถึงอะไร ถ้ามีหลายสิ่งให้ใช้ชื่อซ้ำเพื่อความชัดเจน\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e300c91f-aa2e-530f-a2ca-9d4596da8fe4'::uuid,'5ae7301c-833c-54f7-a381-7a1cb13536e6'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/0b65d48a7413eece-lesson-03-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Mai is here. She is happy.. Ben and I are friends. We study English.. You are welcome."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('28dfac4d-b751-556b-a300-1e0a0fee87e3'::uuid,'5ae7301c-833c-54f7-a381-7a1cb13536e6'::uuid,'multiple_choice',1,'{"question":"Ben and I ใช้ pronoun ใดแทนเป็นประธาน?","choices":[{"id":"choice_1","text":"we"},{"id":"choice_2","text":"they"},{"id":"choice_3","text":"he"}],"correctChoiceId":"choice_1","explanation":"รวมผู้พูด I จึงใช้ we"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f772d582-830e-5880-a423-e824170f6d45'::uuid,'5ae7301c-833c-54f7-a381-7a1cb13536e6'::uuid,'multiple_choice',1,'{"question":"you ใช้กับใครได้?","choices":[{"id":"choice_1","text":"ผู้ฟังหนึ่งคนเท่านั้น"},{"id":"choice_2","text":"ผู้ฟังหลายคนเท่านั้น"},{"id":"choice_3","text":"ผู้ฟังหนึ่งหรือหลายคน"}],"correctChoiceId":"choice_3","explanation":"รูป you ใช้ทั้งเอกพจน์และพหูพจน์"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2f7bddb2-fc72-5d1e-acc9-67fb86562100'::uuid,'5ae7301c-833c-54f7-a381-7a1cb13536e6'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนประโยคด้วย I, you, we, they, he, she, it โดยระบุว่าแต่ละคำแทนใคร\n\n### ตัวอย่างคำตอบ\n\nMai → She is a student. Ben and Mai → They are friends. Ben and I → We are friends.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **I, you, we, they, he, she, it** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('856d298f-3118-578a-a3ec-8a48ddcc463e'::uuid,'06b07b8c-f3d0-5537-a0d7-2bd4e3a90a52'::uuid,'reading',1,'{"title":"หนึ่งกับหลาย","body":"## หนึ่งกับหลาย\n\nคำนามนับได้มีเอกพจน์และพหูพจน์ ปกติเติม s เช่น books ถ้าท้ายเป็น s/sh/ch/x มักเติม es เช่น boxes ส่วนพยัญชนะ + y เปลี่ยน y เป็น ies เช่น city/cities แต่สระ + y เติม s เช่น toys เสียงท้ายพหูพจน์มี /s/ ใน books, /z/ ใน bags และ /ɪz/ ใน buses ดูทั้งเสียงและตัวสะกด\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| one book / two books | หนึ่งเล่ม / สองเล่ม |\n| one box / three boxes | เติม es |\n| one city / two cities | พยัญชนะ + y → ies |\n| one toy / four toys | สระ + y เติม s |\n\n### จุดที่มักสับสน\n\ns ของคำนามบอกหลายสิ่ง ส่วน s ของกริยาจะเรียนใน M08; อย่าเปลี่ยน y ทุกคำ\n\n\n\n### ดูภาพแล้วลองใช้\n\n![คำนามและจำนวน: a book; three books; child → children](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/5d5a5d2a7163d65c-module-03-map.png)\n\n*คำนามนับได้: ดูจำนวน แล้วเลือกรูปเอกพจน์หรือพหูพจน์*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n![โต๊ะที่มีหนังสือสีแดงหนึ่งเล่ม สีฟ้าหนึ่งเล่ม ดินสอสามแท่ง แอปเปิลหนึ่งผลและร่มหนึ่งคัน](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d4c92bf830daea5a-study-desk.png)\n\n*Two books, three pencils, an apple and an umbrella.*\n\nเลือกของสองชนิดในภาพ บอกจำนวน สีหรือคำชี้ให้ตรงหัวข้อบทนี้ แล้วแต่งประโยคใหม่ของคุณ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7e29c5cd-92fa-5800-a9e5-3a3179f0dba6'::uuid,'06b07b8c-f3d0-5537-a0d7-2bd4e3a90a52'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/53c3f07c00148b9e-lesson-03-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"one book. two books. one box. three boxes. one city. two cities. one toy. four toys"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ad599392-7286-5824-ac0d-7d226b171237'::uuid,'06b07b8c-f3d0-5537-a0d7-2bd4e3a90a52'::uuid,'multiple_choice',1,'{"question":"พหูพจน์ของ baby คืออะไร?","choices":[{"id":"choice_1","text":"babys"},{"id":"choice_2","text":"babies"},{"id":"choice_3","text":"babyes"}],"correctChoiceId":"choice_2","explanation":"พยัญชนะ b อยู่หน้า y จึงเปลี่ยน y เป็น ies"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d742a6b5-ef4c-55fe-aec1-660a8cff2f3b'::uuid,'06b07b8c-f3d0-5537-a0d7-2bd4e3a90a52'::uuid,'multiple_choice',1,'{"question":"พหูพจน์ของ key คืออะไร?","choices":[{"id":"choice_1","text":"keies"},{"id":"choice_2","text":"keys"},{"id":"choice_3","text":"keyes"}],"correctChoiceId":"choice_2","explanation":"e เป็นสระหน้า y จึงเติม s"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a5a418e8-3e53-5c13-a02a-20e6fa767be9'::uuid,'06b07b8c-f3d0-5537-a0d7-2bd4e3a90a52'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเลือกสิ่งของสามชนิด เขียนจำนวนหนึ่งและหลาย แล้วอ่านเสียงท้าย\n\n### ตัวอย่างคำตอบ\n\none cup / two cups; one bag / three bags; one bus / two buses.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **หนึ่งกับหลาย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ba47f5ab-7a97-5bb9-ab54-707742569abc'::uuid,'4cfdf91e-45cb-5656-aa23-8b2bbb5cf9a9'::uuid,'reading',1,'{"title":"พหูพจน์รูปพิเศษ","body":"## พหูพจน์รูปพิเศษ\n\nคำนามบางคำเปลี่ยนรูปเมื่อเป็นพหูพจน์ เช่น child/children, person/people, man/men, woman/women ไม่ใช้กฎเติม s ตามปกติ บางคำคงรูป เช่น one sheep/two sheep และ fish ในบริบททั่วไป รูป persons/fishes มีบริบทเฉพาะ แต่เริ่มจากรูปที่ใช้บ่อยและตรวจพจนานุกรมเมื่อจำเป็น\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| one child / two children | ไม่ใช่ childs |\n| one person / five people | people เป็นรูปที่ใช้ทั่วไป |\n| one sheep / three sheep | รูปคงเดิม |\n\n### จุดที่มักสับสน\n\npeople เป็นพหูพจน์ในความหมายคนหลายคน ใช้ are ไม่ใช่ is\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('158626d0-6ea7-56f4-a484-f8dece704e7b'::uuid,'4cfdf91e-45cb-5656-aa23-8b2bbb5cf9a9'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/dd8149f07fcd3b0a-lesson-03-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"one child. two children. one person. five people. one sheep. three sheep"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('99fdc9ad-5bda-56f9-a02d-50cbfb797a44'::uuid,'4cfdf91e-45cb-5656-aa23-8b2bbb5cf9a9'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มคำนามที่ถูก","choices":[{"id":"choice_1","text":"two childs"},{"id":"choice_2","text":"two children"},{"id":"choice_3","text":"two childrens"}],"correctChoiceId":"choice_2","explanation":"children เป็นรูปพหูพจน์อยู่แล้ว ไม่เติม s อีก"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e6abd6e0-6de4-5225-a65c-295212f9707e'::uuid,'4cfdf91e-45cb-5656-aa23-8b2bbb5cf9a9'::uuid,'multiple_choice',1,'{"question":"one woman → two …","choices":[{"id":"choice_1","text":"women"},{"id":"choice_2","text":"womans"},{"id":"choice_3","text":"womens"}],"correctChoiceId":"choice_1","explanation":"woman เปลี่ยนเป็น women"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('046f2b2d-0bc1-578c-a2bb-2eeab57e26a1'::uuid,'4cfdf91e-45cb-5656-aa23-8b2bbb5cf9a9'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนภาพสมมติที่มีเด็ก คนและแกะ พร้อมจำนวนอย่างละหนึ่งประโยค\n\n### ตัวอย่างคำตอบ\n\nThere are two children, three people and four sheep.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **พหูพจน์รูปพิเศษ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('13bf3dbb-0496-5274-a934-c1f3718f107d'::uuid,'4154d32a-246f-505d-a4e9-261cd3bbd2d3'::uuid,'reading',1,'{"title":"นับชิ้นกับนับปริมาณ","body":"## นับชิ้นกับนับปริมาณ\n\nคำนามนับได้แยกเป็นหน่วย เช่น a cup/two cups ส่วนคำนามนับไม่ได้เช่น water/rice ใช้เป็นปริมาณโดยไม่เติม s ในความหมายนั้น ถ้าต้องการนับให้มีหน่วย เช่น two cups of water ความเป็นนับได้ขึ้นอยู่กับความหมาย เช่น chicken คือเนื้อไก่อาจนับไม่ได้ แต่ a chicken หมายถึงไก่หนึ่งตัว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| a chair / two chairs | นับเป็นตัวได้ |\n| water / two glasses of water | นับปริมาณผ่านแก้ว |\n| chicken / a chicken | เนื้อไก่ / ไก่หนึ่งตัว |\n\n### จุดที่มักสับสน\n\nไม่ใช้ a water ในความหมายของน้ำทั่วไป รูป a water ในร้านอาจหมายถึงหนึ่งแก้วหรือขวดตามบริบท\n\n\n\n### ดูภาพแล้วลองใช้\n\n![แอปเปิลสามผล น้ำสองขวด ข้าวหนึ่งชาม ขนมปังหนึ่งก้อนกับสองแผ่นและนมหนึ่งแก้ว](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f82199a419ee302a-pantry-counting.png)\n\n*Three apples, two bottles of water, a bowl of rice, a loaf of bread, two slices of bread and a glass of milk.*\n\nแยกสิ่งที่นับโดยตรงจากปริมาณที่ต้องมีหน่วย แล้วเขียนรายการเตรียมอาหารสำหรับสองคน\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5da8789a-6c09-540c-a4ee-a476d7875e90'::uuid,'4154d32a-246f-505d-a4e9-261cd3bbd2d3'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/b9f5bad2c9b15d80-lesson-03-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"a chair. two chairs. water. two glasses of water. chicken. a chicken"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('37f77eeb-4083-55e1-a1b8-f7b56ba5f18a'::uuid,'4154d32a-246f-505d-a4e9-261cd3bbd2d3'::uuid,'multiple_choice',1,'{"question":"ข้อใดเหมาะกับน้ำทั่วไป?","choices":[{"id":"choice_1","text":"a water"},{"id":"choice_2","text":"some water"},{"id":"choice_3","text":"two waters ในทุกบริบท"}],"correctChoiceId":"choice_2","explanation":"water ในความหมายทั่วไปเป็น uncountable; ใช้ some water"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e0072730-a58a-5acf-a377-2882d0a56d04'::uuid,'4154d32a-246f-505d-a4e9-261cd3bbd2d3'::uuid,'multiple_choice',1,'{"question":"ข้อใดนับเป็นหน่วยได้โดยตรง?","choices":[{"id":"choice_1","text":"rice"},{"id":"choice_2","text":"furniture"},{"id":"choice_3","text":"chair"}],"correctChoiceId":"choice_3","explanation":"chair เป็น countable; rice และ furniture เป็น uncountable ในความหมายทั่วไป"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e0fc1667-7a64-5753-a1e8-a93eab334816'::uuid,'4154d32a-246f-505d-a4e9-261cd3bbd2d3'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nแยกของรอบตัวห้าชนิดว่าใช้หน่วยใดเมื่อนับ\n\n### ตัวอย่างคำตอบ\n\ntwo chairs; three books; two glasses of water; one bowl of rice; a piece of furniture.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **นับชิ้นกับนับปริมาณ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('209d3ae2-ed42-5cfc-a341-20098351dfc2'::uuid,'4183802e-fb30-50ff-abea-cc966bfc8b15'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เลือกประธานและรูปคำนามให้ตรงกับคนหรือสิ่งที่กล่าวถึง**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![คำนามและจำนวน: a book; three books; child → children](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/5d5a5d2a7163d65c-module-03-map.png)\n\n*คำนามนับได้: ดูจำนวน แล้วเลือกรูปเอกพจน์หรือพหูพจน์*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('98c5faa0-02fa-5f62-ac00-96f9421e7c94'::uuid,'4183802e-fb30-50ff-abea-cc966bfc8b15'::uuid,'multiple_choice',1,'{"question":"Anna and I แทนด้วยอะไร?","choices":[{"id":"choice_1","text":"we"},{"id":"choice_2","text":"they"},{"id":"choice_3","text":"she"}],"correctChoiceId":"choice_1","explanation":"รวมผู้พูดใช้ we ย้อน 03.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('69ed1c5b-0656-56f1-a123-bd22b9a1ca12'::uuid,'4183802e-fb30-50ff-abea-cc966bfc8b15'::uuid,'multiple_choice',1,'{"question":"one bus → two …","choices":[{"id":"choice_1","text":"buss"},{"id":"choice_2","text":"buses"},{"id":"choice_3","text":"busies"}],"correctChoiceId":"choice_2","explanation":"bus ลง s เติม es ย้อน 03.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e73535ca-bc7c-588a-a0f0-4645f60298e6'::uuid,'4183802e-fb30-50ff-abea-cc966bfc8b15'::uuid,'multiple_choice',1,'{"question":"ข้อใดเป็น plural ที่ถูก?","choices":[{"id":"choice_1","text":"three womans"},{"id":"choice_2","text":"three women"},{"id":"choice_3","text":"three womens"}],"correctChoiceId":"choice_2","explanation":"woman → women ย้อน 03.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('46d2c6be-58c8-5d26-a52c-9b6b6c97ae20'::uuid,'4183802e-fb30-50ff-abea-cc966bfc8b15'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nบรรยายรายการสิ่งของและคนที่มีหนึ่งกับหลาย แล้วใช้ pronouns อ้างกลับ\n\n### ตัวอย่างผลงาน\n\nThere is one child. There are two women and three books. They are here.\n\n### ตรวจผลงาน\n\n- เลือก plural ตรงจำนวน\n- ใช้รูปพิเศษไม่เติม s ซ้ำ\n- pronoun มีสิ่งที่อ้างกลับชัด\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6c3b6514-7b75-5a43-a565-fada35e86009'::uuid,'a71cb4a8-4876-5260-a368-0230d72a0665'::uuid,'reading',1,'{"title":"จับคู่ประธานกับ be","body":"## จับคู่ประธานกับ be\n\nเลือก be ตามประธาน: I am; he/she/it และคำนามเอกพจน์ is; you/we/they และคำนามพหูพจน์ are รูปนี้ใช้กับข้อมูลตัวตน สภาพหรือตำแหน่ง ดูหัวของกลุ่มคำนาม เช่น My friends เป็นหลายคนแม้เริ่มด้วย My\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I am ready. | I ใช้ am |\n| The teacher is here. | teacher หนึ่งคนใช้ is |\n| My friends are here. | friends หลายคนใช้ are |\n\n### จุดที่มักสับสน\n\nyou ใช้ are แม้พูดกับคนเดียว และชื่อ Mai ใช้ is เหมือน she\n\n\n\n### ดูภาพแล้วลองใช้\n\n![จับคู่ประธานกับ be: am; is; are](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/ef82309a25049c21-module-04-map.png)\n\n*บอกตัวตน สภาพและตำแหน่ง  •  คำถามย้าย be ขึ้นหน้า*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple: to be](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple-be)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('aa6c66f9-1930-5b39-adb7-5fcec31ef725'::uuid,'a71cb4a8-4876-5260-a368-0230d72a0665'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/6db313b4cc20eda5-lesson-04-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I am ready.. The teacher is here.. My friends are here."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('992f8a3a-b436-5e10-aa2c-5de35ae28a7d'::uuid,'a71cb4a8-4876-5260-a368-0230d72a0665'::uuid,'multiple_choice',1,'{"question":"My sister … a student.","choices":[{"id":"choice_1","text":"am"},{"id":"choice_2","text":"is"},{"id":"choice_3","text":"are"}],"correctChoiceId":"choice_2","explanation":"My sister เป็นประธานเอกพจน์ จึงใช้ is"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f66df4d2-2a30-5943-a686-91d87dc35e1c'::uuid,'a71cb4a8-4876-5260-a368-0230d72a0665'::uuid,'multiple_choice',1,'{"question":"You … welcome.","choices":[{"id":"choice_1","text":"is"},{"id":"choice_2","text":"am"},{"id":"choice_3","text":"are"}],"correctChoiceId":"choice_3","explanation":"you ใช้ are เสมอในรูปนี้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3c90ada0-2915-5e19-a60e-bc7a2ecc9978'::uuid,'a71cb4a8-4876-5260-a368-0230d72a0665'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนประโยคด้วยประธานชื่อคน คำนามเอกพจน์และพหูพจน์\n\n### ตัวอย่างคำตอบ\n\nMai is ready. The room is small. The books are new.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **จับคู่ประธานกับ be** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a4d79bd3-faec-5907-a2de-e1a065e4b467'::uuid,'96320221-c12c-5400-a806-79070c1dece3'::uuid,'reading',1,'{"title":"be บอกตัวตนและสภาพ","body":"## be บอกตัวตนและสภาพ\n\nใช้ be เชื่อมประธานกับชื่อ อาชีพ สัญชาติ ความรู้สึกและตำแหน่ง อาชีพที่เป็นคำนามนับได้เอกพจน์ใช้ a/an เช่น a nurse; nationality adjective เช่น Thai ไม่ต้องมี a; ความรู้สึก adjective เช่น tired ไม่เติม article; ตำแหน่งใช้กลุ่มคำเช่น at home\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| She is a nurse. | อาชีพใช้ a |\n| She is Thai. | สัญชาติ adjective |\n| She is tired. | บอกสภาพ |\n| She is at home. | บอกตำแหน่ง |\n\n### จุดที่มักสับสน\n\nไม่เขียน She is a tired. เมื่อ tired เป็น adjective เดี่ยว แต่ a tired nurse ได้เมื่อมี noun\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple: to be](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple-be)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a2f93b51-2fcb-5b48-a7ee-b75c39e07885'::uuid,'96320221-c12c-5400-a806-79070c1dece3'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/12e5717798a2c872-lesson-04-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"She is a nurse.. She is Thai.. She is tired.. She is at home."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('da321eac-7413-59a4-a6ee-759b5b436036'::uuid,'96320221-c12c-5400-a806-79070c1dece3'::uuid,'multiple_choice',1,'{"question":"ข้อใดบอกอาชีพถูก?","choices":[{"id":"choice_1","text":"He is teacher."},{"id":"choice_2","text":"He is a teacher."},{"id":"choice_3","text":"He a teacher."}],"correctChoiceId":"choice_2","explanation":"teacher เป็นคำนามนับได้เอกพจน์จึงใช้ a และมี is"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f0e5e723-ba60-5686-a18f-1aa58e00f8f0'::uuid,'96320221-c12c-5400-a806-79070c1dece3'::uuid,'multiple_choice',1,'{"question":"ข้อใดบอกความรู้สึกถูก?","choices":[{"id":"choice_1","text":"I am happy."},{"id":"choice_2","text":"I am a happy."},{"id":"choice_3","text":"I happy."}],"correctChoiceId":"choice_1","explanation":"happy เป็น adjective ใช้ am โดยไม่ต้องมี a"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6254b613-0d43-513b-a7b5-2801d5105708'::uuid,'96320221-c12c-5400-a806-79070c1dece3'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกอาชีพ สัญชาติ ความรู้สึกและที่อยู่ปัจจุบันอย่างละหนึ่งประโยค\n\n### ตัวอย่างคำตอบ\n\nI am a student. I am Thai. I am happy. I am at home.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **be บอกตัวตนและสภาพ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e4436b31-7041-51bd-a0d9-8fa2de89dc68'::uuid,'5e78963d-aaeb-50d6-ad76-4abc1c8de9ab'::uuid,'reading',1,'{"title":"รูปย่อและปฏิเสธ","body":"## รูปย่อและปฏิเสธ\n\nรูปย่อช่วยให้การพูดและเขียนไม่เป็นทางการเป็นธรรมชาติ I am → I’m; you are → you’re; he is → he’s ใช้ apostrophe แทนตัวที่ละ ปฏิเสธเติม not หลัง be: I am not; she is not/isn’t; they are not/aren’t รูป I’m not เป็นรูปพื้นฐาน ไม่ใช้ I amn’t ในอังกฤษมาตรฐานทั่วไป\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I’m ready. / I’m not ready. | บอกเล่า / ปฏิเสธ |\n| She’s here. / She isn’t here. | she is / she is not |\n| They’re busy. / They aren’t busy. | they are / they are not |\n\n### จุดที่มักสับสน\n\nits บอกเจ้าของ ต่างจาก it’s ที่ย่อ it is หรือ it has ตามโครงสร้าง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple: to be](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple-be)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f30f52a9-df63-5732-af74-e4a4502961cd'::uuid,'5e78963d-aaeb-50d6-ad76-4abc1c8de9ab'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/a05f000b1f5b3ecc-lesson-04-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I’m ready.. I’m not ready.. She’s here.. She isn’t here.. They’re busy.. They aren’t busy."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('88a0298e-bba4-52f0-a217-c9b904f24d0b'::uuid,'5e78963d-aaeb-50d6-ad76-4abc1c8de9ab'::uuid,'multiple_choice',1,'{"question":"รูปย่อของ they are คืออะไร?","choices":[{"id":"choice_1","text":"their"},{"id":"choice_2","text":"they’re"},{"id":"choice_3","text":"there"}],"correctChoiceId":"choice_2","explanation":"they’re = they are; their เป็นคำบอกเจ้าของ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bd219fc6-1585-5039-ac10-9398d1591130'::uuid,'5e78963d-aaeb-50d6-ad76-4abc1c8de9ab'::uuid,'multiple_choice',1,'{"question":"ข้อใดเป็นปฏิเสธที่ถูก?","choices":[{"id":"choice_1","text":"I amn’t late."},{"id":"choice_2","text":"I’m not late."},{"id":"choice_3","text":"I don’t late."}],"correctChoiceId":"choice_2","explanation":"I’m not = I am not"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('59468156-6699-522b-a823-155cf2c76c06'::uuid,'5e78963d-aaeb-50d6-ad76-4abc1c8de9ab'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเปลี่ยนประโยค I am tired / She is busy / We are ready เป็นรูปย่อและปฏิเสธ\n\n### ตัวอย่างคำตอบ\n\nI’m tired → I’m not tired. She’s busy → She isn’t busy. We’re ready → We aren’t ready.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **รูปย่อและปฏิเสธ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d4417658-9f59-5c1f-a051-c8470f8bb93e'::uuid,'6cdd9ed1-2677-5c75-a19c-c5a927dd29b4'::uuid,'reading',1,'{"title":"คำถามและคำตอบสั้น","body":"## คำถามและคำตอบสั้น\n\nคำถาม yes/no ด้วย be ย้าย be ไว้หน้าประธาน: You are ready → Are you ready? คำตอบสั้นใช้ pronoun + be ให้ตรงผู้ตอบ Yes, I am. / No, I’m not. ไม่ใช้ do/does ร่วมกับ be รูปนี้ และคำตอบบอกเล่าสั้นท้ายประโยคไม่ย่อเหลือ Yes, I’m\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Is she here? — Yes, she is. | ถามและตอบเกี่ยวกับเธอ |\n| Are they ready? — No, they aren’t. | ถามหลายคน |\n| Are you a student? — Yes, I am. | เปลี่ยน you เป็น I เมื่อตอบ |\n\n### จุดที่มักสับสน\n\nDo you are ready? ผิด เพราะ be เป็นกริยาที่สลับหน้าได้เอง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple: to be](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple-be)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('27bb7ade-52c4-5074-ac78-ed236e84daa6'::uuid,'6cdd9ed1-2677-5c75-a19c-c5a927dd29b4'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/aa39cbae891f7eb7-lesson-04-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Is she here?. Yes, she is.. Are they ready?. No, they aren’t.. Are you a student?. Yes, I am."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0ecdb086-19f0-5636-a407-e2e4c38780ee'::uuid,'6cdd9ed1-2677-5c75-a19c-c5a927dd29b4'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามที่ถูก","choices":[{"id":"choice_1","text":"Do she is here?"},{"id":"choice_2","text":"Is she here?"},{"id":"choice_3","text":"Is she are here?"}],"correctChoiceId":"choice_2","explanation":"คำถามใช้ Is + subject"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('878520a9-31e3-5a5c-a3e3-3775644ae9c5'::uuid,'6cdd9ed1-2677-5c75-a19c-c5a927dd29b4'::uuid,'multiple_choice',1,'{"question":"Are you ready? คำตอบสั้นบอกเล่าคืออะไร?","choices":[{"id":"choice_1","text":"Yes, I’m."},{"id":"choice_2","text":"Yes, I am."},{"id":"choice_3","text":"Yes, you is."}],"correctChoiceId":"choice_2","explanation":"คำตอบเปลี่ยน you เป็น I และไม่ย่อ am ท้ายประโยค"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5349e813-9418-5401-a905-a0c4791e49c5'::uuid,'6cdd9ed1-2677-5c75-a19c-c5a927dd29b4'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nถามเพื่อนสามคำถามด้วย be และตอบทั้ง yes/no\n\n### ตัวอย่างคำตอบ\n\nAre you tired? No, I’m not. Is Ben here? Yes, he is. Are the books new? Yes, they are.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **คำถามและคำตอบสั้น** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ad384666-b39c-5817-aba3-b65cf919d69d'::uuid,'bc20b703-a212-5060-a8db-1cb8307d69e6'::uuid,'reading',1,'{"title":"ถามข้อมูลด้วย be","body":"## ถามข้อมูลด้วย be\n\nวางคำถามหน้าประโยคก่อน be เช่น Where are you? What is your name? Who is she? How old are you? เลือกตามข้อมูลที่ต้องการ คำถามเกี่ยวกับสภาพใช้ How are you? ส่วน impersonal it ช่วยบอกเวลาและอากาศโดยไม่มีคนหรือสิ่งเฉพาะ เช่น It is cold. ไม่ละประธาน it\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Where is Mai? — She is at home. | ถามตำแหน่ง |\n| How old are you? — I am twenty. | ถามอายุ |\n| What time is it? — It is nine. | it สำหรับเวลา |\n\n### จุดที่มักสับสน\n\nอายุอังกฤษใช้ be: I am twenty. ไม่แปลตรงเป็น I have twenty years ในรูปพื้นฐาน\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple: to be](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple-be)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2ca296ec-5e77-5836-a0b8-45c38da90d37'::uuid,'bc20b703-a212-5060-a8db-1cb8307d69e6'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/46ead27fd26bd35e-lesson-04-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Where is Mai?. She is at home.. How old are you?. I am twenty.. What time is it?. It is nine."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c17156a3-b698-59b9-a096-dc73d1c266a0'::uuid,'bc20b703-a212-5060-a8db-1cb8307d69e6'::uuid,'multiple_choice',1,'{"question":"ต้องการถามตำแหน่งของกระเป๋า ใช้คำใด?","choices":[{"id":"choice_1","text":"Who is the bag?"},{"id":"choice_2","text":"Where is the bag?"},{"id":"choice_3","text":"How old is the bag?"}],"correctChoiceId":"choice_2","explanation":"Where ถามสถานที่"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e4544d37-7de1-51ac-a61f-b8f225d709d5'::uuid,'bc20b703-a212-5060-a8db-1cb8307d69e6'::uuid,'multiple_choice',1,'{"question":"ข้อใดบอกอายุถูก?","choices":[{"id":"choice_1","text":"I am eighteen."},{"id":"choice_2","text":"I have eighteen."},{"id":"choice_3","text":"I eighteen."}],"correctChoiceId":"choice_1","explanation":"ใช้ am เชื่อมกับอายุ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8bb09b11-8c62-5e80-a9d8-f07d25bc9cfe'::uuid,'bc20b703-a212-5060-a8db-1cb8307d69e6'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนคำถามเกี่ยวกับชื่อ อายุ ที่อยู่และอากาศ แล้วตอบจากข้อมูลของคุณ\n\n### ตัวอย่างคำตอบ\n\nWhat is your name? My name is Mai. How old are you? I am twenty. Where are you? I am at home. Is it hot? Yes, it is.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ถามข้อมูลด้วย be** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7c187719-51fd-577a-a2f9-59c3a0b4534c'::uuid,'dae797fe-e766-5da1-a70b-e0fe100af309'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **บอกเล่า ปฏิเสธ ถาม และตอบด้วย be ได้ครบทุกประธาน**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![จับคู่ประธานกับ be: am; is; are](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/ef82309a25049c21-module-04-map.png)\n\n*บอกตัวตน สภาพและตำแหน่ง  •  คำถามย้าย be ขึ้นหน้า*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a53000ca-2340-5d55-a765-6e636766a23d'::uuid,'dae797fe-e766-5da1-a70b-e0fe100af309'::uuid,'multiple_choice',1,'{"question":"The chairs … new.","choices":[{"id":"choice_1","text":"am"},{"id":"choice_2","text":"is"},{"id":"choice_3","text":"are"}],"correctChoiceId":"choice_3","explanation":"chairs หลายตัวใช้ are ย้อน 04.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a971cd52-c051-5375-a90d-3b5e673f4cda'::uuid,'dae797fe-e766-5da1-a70b-e0fe100af309'::uuid,'multiple_choice',1,'{"question":"Are your friends Thai? — Yes, …","choices":[{"id":"choice_1","text":"they are"},{"id":"choice_2","text":"they is"},{"id":"choice_3","text":"they’re"}],"correctChoiceId":"choice_1","explanation":"คำตอบสั้นบอกเล่าไม่ย่อ be ท้าย ย้อน 04.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4605b078-3223-5808-aa3e-cb9d8f383895'::uuid,'dae797fe-e766-5da1-a70b-e0fe100af309'::uuid,'multiple_choice',1,'{"question":"ถามอายุของ Ben ใช้รูปใด?","choices":[{"id":"choice_1","text":"How old is Ben?"},{"id":"choice_2","text":"How old does Ben?"},{"id":"choice_3","text":"How Ben old?"}],"correctChoiceId":"choice_1","explanation":"How old + is + Ben ย้อน 04.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('134f8b19-febd-5ab2-a571-98aa68928a40'::uuid,'dae797fe-e766-5da1-a70b-e0fe100af309'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nแนะนำตัวด้วยตัวตน สภาพและที่อยู่ จากนั้นถามเพื่อนสองคำถามและตอบ\n\n### ตัวอย่างผลงาน\n\nI am Mai. I am Thai. I am ready. I am at home. Are you ready? Yes, I am. Where is Ben? He is at school.\n\n### ตรวจผลงาน\n\n- จับคู่ am/is/are\n- คำถามสลับ be กับประธาน\n- คำตอบสั้นใช้ pronoun และ be ตรงคำถาม\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('50e7257e-7f4e-5396-a5c4-1d2627b42b19'::uuid,'cc4445e2-77ca-5883-a554-65e708d80905'::uuid,'reading',1,'{"title":"a/an กับคำนามเอกพจน์","body":"## a/an กับคำนามเอกพจน์\n\na/an ใช้กับคำนามนับได้เอกพจน์เมื่อกล่าวถึงหนึ่งหน่วยหรือสมาชิกหนึ่งประเภท เช่น a book, an apple คำนามนับได้เอกพจน์ทั่วไปไม่ยืนเดี่ยวในประโยคแบบ I have book ต้องมี determiner เช่น a/the/my/this ไม่ใช้ a/an หน้าพหูพจน์หรือคำนามนับไม่ได้ในความหมายทั่วไป\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I have a book. | หนึ่งเล่มที่ยังไม่ระบุเล่ม |\n| She is a doctor. | สมาชิกของอาชีพ doctor |\n| I have books. | หลายเล่ม ไม่ใช้ a |\n\n### จุดที่มักสับสน\n\na ไม่ได้แปลว่าเลขหนึ่งแบบเน้นจำนวนทุกครั้ง ใช้จัดสมาชิกหนึ่งประเภทได้\n\n\n\n### ดูภาพแล้วลองใช้\n\n![โต๊ะที่มีหนังสือสีแดงหนึ่งเล่ม สีฟ้าหนึ่งเล่ม ดินสอสามแท่ง แอปเปิลหนึ่งผลและร่มหนึ่งคัน](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d4c92bf830daea5a-study-desk.png)\n\n*Two books, three pencils, an apple and an umbrella.*\n\nเลือกของสองชนิดในภาพ บอกจำนวน สีหรือคำชี้ให้ตรงหัวข้อบทนี้ แล้วแต่งประโยคใหม่ของคุณ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Articles: a, an, the](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/articles-a-an-the) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6de1d9b7-44a8-5e82-a7d6-df9380c9c5af'::uuid,'cc4445e2-77ca-5883-a554-65e708d80905'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/fecabe0b89a1b9b9-lesson-05-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I have a book.. She is a doctor.. I have books."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0f195775-1813-5cbd-a99d-5fcb0fcb8c96'::uuid,'cc4445e2-77ca-5883-a554-65e708d80905'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มคำนามที่ถูก","choices":[{"id":"choice_1","text":"a books"},{"id":"choice_2","text":"a book"},{"id":"choice_3","text":"a rice ในความหมายข้าวทั่วไป"}],"correctChoiceId":"choice_2","explanation":"a ใช้กับ countable singular"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('958f9e55-8337-5b33-a2be-de095dba98ef'::uuid,'cc4445e2-77ca-5883-a554-65e708d80905'::uuid,'multiple_choice',1,'{"question":"ประโยคใดถูก?","choices":[{"id":"choice_1","text":"She is nurse."},{"id":"choice_2","text":"She is a nurse."},{"id":"choice_3","text":"She is a nurses."}],"correctChoiceId":"choice_2","explanation":"อาชีพ nurse เป็นคำนามนับได้เอกพจน์"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('527042a4-0e57-5db9-a606-ce3852040069'::uuid,'cc4445e2-77ca-5883-a554-65e708d80905'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนของในกระเป๋าสามชนิดด้วย a/an และของหลายชิ้นหนึ่งประโยค\n\n### ตัวอย่างคำตอบ\n\nI have a pen, a book and an umbrella. I have pencils.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **a/an กับคำนามเอกพจน์** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('23520ed8-c293-5e79-a34c-e02b407bce1e'::uuid,'391c232d-3171-595f-a7bf-22ded1c18156'::uuid,'reading',1,'{"title":"เลือก a หรือ an จากเสียง","body":"## เลือก a หรือ an จากเสียง\n\nเลือก a/an จากเสียงแรกของคำถัดไป ไม่ใช่ตัวอักษร an ใช้ก่อนเสียงสระ เช่น an apple, an hour เพราะ h ใน hour เงียบ a ใช้ก่อนเสียงพยัญชนะ เช่น a university เพราะเริ่ม /j/ เหมือน y และ a useful book ถ้ามี adjective ให้ฟังเสียงต้นของ adjective นั้น\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| an hour | h เงียบ เริ่มด้วยเสียงสระ |\n| a university | เริ่มเสียง /j/ |\n| an old bag | เสียงต้น old เป็นสระ |\n\n### จุดที่มักสับสน\n\nan university ผิดในเสียงมาตรฐานทั่วไป และ a hour ผิดแม้เห็น h เป็นพยัญชนะ\n\n\n\n### ดูภาพแล้วลองใช้\n\n![โต๊ะที่มีหนังสือสีแดงหนึ่งเล่ม สีฟ้าหนึ่งเล่ม ดินสอสามแท่ง แอปเปิลหนึ่งผลและร่มหนึ่งคัน](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d4c92bf830daea5a-study-desk.png)\n\n*Two books, three pencils, an apple and an umbrella.*\n\nเลือกของสองชนิดในภาพ บอกจำนวน สีหรือคำชี้ให้ตรงหัวข้อบทนี้ แล้วแต่งประโยคใหม่ของคุณ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Articles: a, an, the](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/articles-a-an-the) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('aa92762f-5903-5043-a75b-abc7d95096a5'::uuid,'391c232d-3171-595f-a7bf-22ded1c18156'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f68748042c4ee48e-lesson-05-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"an hour. a university. an old bag"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('67cce8f6-57fd-5786-a027-7dc7410632e4'::uuid,'391c232d-3171-595f-a7bf-22ded1c18156'::uuid,'multiple_choice',1,'{"question":"เลือก article: … honest person","choices":[{"id":"choice_1","text":"a"},{"id":"choice_2","text":"an"},{"id":"choice_3","text":"the เท่านั้น"}],"correctChoiceId":"choice_2","explanation":"honest เริ่มเสียงสระเพราะ h เงียบ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('097e46ad-53bd-5733-a377-88da944b090e'::uuid,'391c232d-3171-595f-a7bf-22ded1c18156'::uuid,'multiple_choice',1,'{"question":"เลือก article: … useful tool","choices":[{"id":"choice_1","text":"a"},{"id":"choice_2","text":"an"},{"id":"choice_3","text":"ไม่มี article เสมอ"}],"correctChoiceId":"choice_1","explanation":"useful เริ่ม /j/ ซึ่งเป็นเสียงพยัญชนะ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ef392b80-7802-5a82-a000-cbbb29627dc0'::uuid,'391c232d-3171-595f-a7bf-22ded1c18156'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nอ่านกลุ่มคำ hour, university, apple, useful book และเติม a/an โดยให้เหตุผลจากเสียง\n\n### ตัวอย่างคำตอบ\n\nan hour; a university; an apple; a useful book.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เลือก a หรือ an จากเสียง** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c4ec7cf7-ab53-5ba5-af68-583652864403'::uuid,'8f6c8961-721d-5c0c-a9d8-deb639ca8a4b'::uuid,'reading',1,'{"title":"the ระบุสิ่งที่เข้าใจตรงกัน","body":"## the ระบุสิ่งที่เข้าใจตรงกัน\n\nthe ใช้เมื่อผู้พูดและผู้ฟังระบุสิ่งเดียวกันได้ เช่นกล่าวถึงไปแล้ว มีคำขยายระบุชัด หรือมีเพียงสิ่งเดียวที่เกี่ยวข้องในบริบท I see a dog. The dog is black. ครั้งแรกยังไม่รู้ว่าตัวไหนจึงใช้ a; ครั้งต่อมาอ้างกลับตัวเดิมใช้ the ใช้ the ได้กับเอกพจน์ พหูพจน์และนับไม่ได้ถ้าเฉพาะเจาะจง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I bought a book. The book is good. | ครั้งแรก / อ้างเล่มเดิม |\n| Please close the door. | ประตูที่เข้าใจร่วมกัน |\n| The water in this bottle is cold. | น้ำเฉพาะขวดนี้ |\n\n### จุดที่มักสับสน\n\nthe ไม่ได้แปลว่าคำนามมีหนึ่งเดียวในโลกเสมอ แต่ต้องระบุได้ในบริบท\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ดูเสียงและสิ่งที่ระบุได้: a book; an hour; the book on this desk](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/6c28898ec1a31cba-module-05-map.png)\n\n*a/an ตามเสียง  •  the เมื่อระบุได้  •  books กล่าวทั่วไป*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n![โต๊ะที่มีหนังสือสีแดงหนึ่งเล่ม สีฟ้าหนึ่งเล่ม ดินสอสามแท่ง แอปเปิลหนึ่งผลและร่มหนึ่งคัน](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d4c92bf830daea5a-study-desk.png)\n\n*Two books, three pencils, an apple and an umbrella.*\n\nเลือกของสองชนิดในภาพ บอกจำนวน สีหรือคำชี้ให้ตรงหัวข้อบทนี้ แล้วแต่งประโยคใหม่ของคุณ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Articles: a, an, the](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/articles-a-an-the) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e0aae2f9-da05-5e07-a946-7a11c4c52f87'::uuid,'8f6c8961-721d-5c0c-a9d8-deb639ca8a4b'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/c4ce8c49e7b71e08-lesson-05-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I bought a book. The book is good.. Please close the door.. The water in this bottle is cold."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('18244041-03aa-5ea3-a122-01907494db9c'::uuid,'8f6c8961-721d-5c0c-a9d8-deb639ca8a4b'::uuid,'multiple_choice',1,'{"question":"I saw a cat. … cat was white.","choices":[{"id":"choice_1","text":"A"},{"id":"choice_2","text":"An"},{"id":"choice_3","text":"The"}],"correctChoiceId":"choice_3","explanation":"อ้างกลับแมวตัวที่เพิ่งกล่าวถึง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5f329dc6-d9dd-53d6-a828-ad8fa5f0a049'::uuid,'8f6c8961-721d-5c0c-a9d8-deb639ca8a4b'::uuid,'multiple_choice',1,'{"question":"เหตุใด the door จึงใช้ได้ในห้องหนึ่ง?","choices":[{"id":"choice_1","text":"ผู้พูดและผู้ฟังระบุประตูได้"},{"id":"choice_2","text":"door เป็นพหูพจน์"},{"id":"choice_3","text":"door ต้องใช้ the ทุกครั้ง"}],"correctChoiceId":"choice_1","explanation":"บริบททำให้รู้ว่าประตูไหน ไม่ใช่กฎว่า door ต้องมี the"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4b9e27a7-a9b2-51cb-afc7-aefd0783d064'::uuid,'8f6c8961-721d-5c0c-a9d8-deb639ca8a4b'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนเรื่องสองประโยคที่เริ่มด้วย a/an แล้วอ้างสิ่งเดิมด้วย the\n\n### ตัวอย่างคำตอบ\n\nI have an umbrella. The umbrella is blue.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **the ระบุสิ่งที่เข้าใจตรงกัน** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a6e1d1d7-fad5-516c-a057-2044e5670e1d'::uuid,'15bc9dfb-fdf1-5798-aebd-ef5f1faa1284'::uuid,'reading',1,'{"title":"เมื่อไม่ใช้ article","body":"## เมื่อไม่ใช้ article\n\nไม่ใช้ article เมื่อกล่าวทั่วไปด้วยพหูพจน์หรือนับไม่ได้ เช่น Dogs are friendly. Water is important. ชื่อคน เมือง ภาษา และประเทศส่วนใหญ่มักไม่มี article เช่น Mai, Bangkok, English, Thailand แต่ชื่อบางกลุ่มมี the เช่น the United States ตรวจเป็นชื่อเต็ม ถ้าเจาะจงกลุ่มหรือน้ำที่รู้ว่าหมายถึงไหนยังใช้ the ได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I like cats. | ชอบแมวทั่วไป |\n| The cats in this room are quiet. | แมวเฉพาะในห้อง |\n| She speaks English. | ชื่อภาษาไม่ใช้ the |\n\n### จุดที่มักสับสน\n\nไม่ใช้กฎว่า plural ห้ามมี the; ความเฉพาะเจาะจงเป็นตัวตัดสิน\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Articles: a, an, the](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/articles-a-an-the) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c61c628d-5330-5eab-a1b0-b0bcd77c791c'::uuid,'15bc9dfb-fdf1-5798-aebd-ef5f1faa1284'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d93e7e92b1f1fe65-lesson-05-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I like cats.. The cats in this room are quiet.. She speaks English."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('797be139-33cf-5da3-a568-517d12f3d02e'::uuid,'15bc9dfb-fdf1-5798-aebd-ef5f1faa1284'::uuid,'multiple_choice',1,'{"question":"กล่าวถึงกาแฟทั่วไป เลือกประโยค","choices":[{"id":"choice_1","text":"Coffee is popular."},{"id":"choice_2","text":"The coffee is popular. หมายถึงกาแฟทั่วไปเสมอ"},{"id":"choice_3","text":"A coffee is popular. หมายถึงกาแฟทั่วไปเสมอ"}],"correctChoiceId":"choice_1","explanation":"Coffee ไม่มี article เมื่อกล่าวทั่วไปในความหมาย uncountable"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('47eebc99-cd80-5405-a55d-8802899bebe5'::uuid,'15bc9dfb-fdf1-5798-aebd-ef5f1faa1284'::uuid,'multiple_choice',1,'{"question":"ชื่อใดใช้ the ในชื่อมาตรฐาน?","choices":[{"id":"choice_1","text":"Thailand"},{"id":"choice_2","text":"Bangkok"},{"id":"choice_3","text":"the United States"}],"correctChoiceId":"choice_3","explanation":"the United States เป็นชื่อประเทศที่ใช้ the"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ff450894-7345-5e42-af01-76c11767b7f3'::uuid,'15bc9dfb-fdf1-5798-aebd-ef5f1faa1284'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนความชอบทั่วไปสองประโยคและข้อมูลเมืองหรือภาษาอีกสองประโยค\n\n### ตัวอย่างคำตอบ\n\nI like books. Music is important to me. I live in Bangkok. I study English.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เมื่อไม่ใช้ article** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2abebd96-78e8-5cc7-aab0-e73de116f816'::uuid,'88c066f9-2fe2-5b5e-a56a-889631872983'::uuid,'reading',1,'{"title":"ประกอบกลุ่มคำนาม","body":"## ประกอบกลุ่มคำนาม\n\nกลุ่มคำนามพื้นฐานเรียง determiner + adjective + noun เช่น my blue bag หรือ a small room adjective อยู่หน้าคำนามในกลุ่มนี้ ไม่วาง article ซ้อนกับ my/this ที่ทำหน้าที่ determiner อยู่แล้ว เขียน my bag ไม่ใช่ the my bag ถ้าคำนามหลายชิ้นเปลี่ยน noun เป็น plural แต่ adjective ไม่เติม s\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| a small room | a + adjective + noun |\n| my blue bags | my + adjective + plural noun |\n| these new books | ชี้หลายเล่ม |\n\n### จุดที่มักสับสน\n\na my book และ the this room ผิด; เลือก determiner ที่ตรงความหมายเพียงแบบหนึ่งในรูปพื้นฐานนี้\n\n\n\n### ดูภาพแล้วลองใช้\n\n![โต๊ะที่มีหนังสือสีแดงหนึ่งเล่ม สีฟ้าหนึ่งเล่ม ดินสอสามแท่ง แอปเปิลหนึ่งผลและร่มหนึ่งคัน](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d4c92bf830daea5a-study-desk.png)\n\n*Two books, three pencils, an apple and an umbrella.*\n\nเลือกของสองชนิดในภาพ บอกจำนวน สีหรือคำชี้ให้ตรงหัวข้อบทนี้ แล้วแต่งประโยคใหม่ของคุณ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Articles: a, an, the](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/articles-a-an-the) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a0d87d8b-4709-5d6b-a3b7-bc2a9b18b42b'::uuid,'88c066f9-2fe2-5b5e-a56a-889631872983'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/982f39ae0f3e1ec3-lesson-05-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"a small room. my blue bags. these new books"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a7e76594-9ebf-5efa-ad68-498388da1a15'::uuid,'88c066f9-2fe2-5b5e-a56a-889631872983'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มคำนามที่ถูก","choices":[{"id":"choice_1","text":"the my red bag"},{"id":"choice_2","text":"my red bag"},{"id":"choice_3","text":"red my bag"}],"correctChoiceId":"choice_2","explanation":"my ทำหน้าที่ determiner แล้วตามด้วย adjective และ noun"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('96d6dfab-497c-51cf-afa7-940a2d518266'::uuid,'88c066f9-2fe2-5b5e-a56a-889631872983'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มของหลายเล่ม","choices":[{"id":"choice_1","text":"these new books"},{"id":"choice_2","text":"these news books"},{"id":"choice_3","text":"new these books"}],"correctChoiceId":"choice_1","explanation":"adjective new ไม่เติม s"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7d17c34d-9ec8-59e1-a63a-115aa2b95ae9'::uuid,'88c066f9-2fe2-5b5e-a56a-889631872983'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบรรยายสิ่งของสี่กลุ่มโดยสลับใช้ a, my, this, these\n\n### ตัวอย่างคำตอบ\n\na small cup; my blue bag; this old book; these new shoes.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ประกอบกลุ่มคำนาม** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a735d8bb-2e53-5008-a59b-1bffd80caae5'::uuid,'f7a22e6a-7ce8-51b6-a7e0-cde42c602fae'::uuid,'reading',1,'{"title":"article เปลี่ยนความหมายอย่างไร","body":"## article เปลี่ยนความหมายอย่างไร\n\narticle เปลี่ยนจุดเน้น a book หมายถึงหนึ่งเล่มที่ยังไม่ระบุ; the book คือเล่มที่ระบุได้; books อาจกล่าวทั่วไป บางวลีใช้ตามกิจกรรมหรือจุดประสงค์ เช่น go to school คือไปเรียน ส่วน go to the school คือไปอาคารโรงเรียนที่ระบุได้ go home ไม่ใช้ to/the; in bed หมายถึงอยู่บนเตียงพักหรือนอนตามบริบท\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I go to school. | ไปเรียน |\n| I go to the school to meet a teacher. | ไปโรงเรียนแห่งที่ระบุเพื่อพบครู |\n| I go home. | กลับบ้าน ไม่ใช้ to home |\n\n### จุดที่มักสับสน\n\nจำวลีพร้อมความหมาย อย่าเติมหรือถอด the ทุกครั้งจากชนิดสถานที่เพียงอย่างเดียว\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Articles: a, an, the](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/articles-a-an-the) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('64eab59b-80a7-522e-a813-09a125ff7852'::uuid,'f7a22e6a-7ce8-51b6-a7e0-cde42c602fae'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/44d4b9b639f6ff32-lesson-05-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I go to school.. I go to the school to meet a teacher.. I go home."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('56deb3ab-4e86-5542-a980-2b1fe73388b7'::uuid,'f7a22e6a-7ce8-51b6-a7e0-cde42c602fae'::uuid,'multiple_choice',1,'{"question":"ประโยคใดเป็นวลีกลับบ้านพื้นฐาน?","choices":[{"id":"choice_1","text":"I go to home."},{"id":"choice_2","text":"I go home."},{"id":"choice_3","text":"I go to the home. เสมอ"}],"correctChoiceId":"choice_2","explanation":"home เป็นคำบอกทิศทางในวลี go home"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9ed8e227-64dd-56b7-a926-13e315f977ef'::uuid,'f7a22e6a-7ce8-51b6-a7e0-cde42c602fae'::uuid,'multiple_choice',1,'{"question":"go to school ต่างจาก go to the school อย่างไร?","choices":[{"id":"choice_1","text":"อย่างแรกเน้นไปเรียน อย่างหลังระบุอาคารหรือสถานที่"},{"id":"choice_2","text":"ไม่ต่างกันได้เลย"},{"id":"choice_3","text":"อย่างแรกเป็นอดีต"}],"correctChoiceId":"choice_1","explanation":"article สะท้อนการกล่าวถึงกิจกรรมกับสถานที่เฉพาะ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9f770cbd-2dde-5561-ab54-d0b04b8cb357'::uuid,'f7a22e6a-7ce8-51b6-a7e0-cde42c602fae'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสองประโยคแยกการไปเรียนกับการไปอาคารโรงเรียน และหนึ่งประโยคกลับบ้าน\n\n### ตัวอย่างคำตอบ\n\nI go to school every day. My father goes to the school to meet my teacher. I go home after class.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **article เปลี่ยนความหมายอย่างไร** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f4eebd53-6c01-57a1-ae55-8b6a2ace380d'::uuid,'dd755c73-11eb-5ee4-a301-7725f4254405'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เลือกคำหน้าคำนามและประกอบ noun phrase ง่าย ๆ ได้**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ดูเสียงและสิ่งที่ระบุได้: a book; an hour; the book on this desk](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/6c28898ec1a31cba-module-05-map.png)\n\n*a/an ตามเสียง  •  the เมื่อระบุได้  •  books กล่าวทั่วไป*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('84c9f3f6-7feb-5c2a-a039-3268ffc0da21'::uuid,'dd755c73-11eb-5ee4-a301-7725f4254405'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มคำนามที่ถูก","choices":[{"id":"choice_1","text":"an university"},{"id":"choice_2","text":"a university"},{"id":"choice_3","text":"a universities"}],"correctChoiceId":"choice_2","explanation":"university เริ่มเสียง /j/ ย้อน 05.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f60e0c24-68cf-5ca1-a472-989c1a16a1f6'::uuid,'dd755c73-11eb-5ee4-a301-7725f4254405'::uuid,'multiple_choice',1,'{"question":"I found a key. … key is small.","choices":[{"id":"choice_1","text":"A"},{"id":"choice_2","text":"An"},{"id":"choice_3","text":"The"}],"correctChoiceId":"choice_3","explanation":"อ้างกุญแจที่กล่าวแล้ว ย้อน 05.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5137b519-1677-5ecd-acf4-9db40b085e4a'::uuid,'dd755c73-11eb-5ee4-a301-7725f4254405'::uuid,'multiple_choice',1,'{"question":"ข้อใดกล่าวชอบสุนัขทั่วไป?","choices":[{"id":"choice_1","text":"I like dogs."},{"id":"choice_2","text":"I like the dogs. ทุกบริบท"},{"id":"choice_3","text":"I like a dogs."}],"correctChoiceId":"choice_1","explanation":"plural ทั่วไปไม่ใช้ article ย้อน 05.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fc4e6820-d9dd-56fa-a21a-c34c0d2b1056'::uuid,'dd755c73-11eb-5ee4-a301-7725f4254405'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเล่าเรื่องสิ่งของหนึ่งชิ้นสามประโยค ใช้ a/an แล้ว the และบอกความชอบทั่วไปหนึ่งประโยค\n\n### ตัวอย่างผลงาน\n\nI have an old bag. The bag is blue. My blue bag is small. I like bags.\n\n### ตรวจผลงาน\n\n- เลือก a/an ตามเสียง\n- อ้างสิ่งเดิมด้วย the\n- ไม่ซ้อน my กับ article\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4d9eb8e9-be3c-5108-ac30-8ac87bf27e1d'::uuid,'eaf9f26f-87cf-577b-a1a3-ac61da1daaa6'::uuid,'reading',1,'{"title":"this/that/these/those","body":"## this/that/these/those\n\nthis/that ใช้กับสิ่งเดียว ส่วน these/those ใช้กับหลายสิ่ง this/these มักชี้ใกล้ผู้พูด; that/those มักชี้ไกลหรือสิ่งที่กำลังกล่าวถึง จับคู่ this/that กับ is และ these/those กับ are ใช้หน้าคำนามได้ เช่น this bag หรือแทนคำนามได้ เช่น This is mine.\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| This bag is blue. | ใกล้ หนึ่งใบ |\n| Those bags are red. | ไกล หลายใบ |\n| These are books. | ใช้แทนคำนามในตำแหน่งประธาน |\n\n### จุดที่มักสับสน\n\nไม่ใช้ these bag หรือ this bags ในความหมายทั่วไป ต้องให้คำชี้และจำนวนตรงกัน\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ชี้สิ่งของและบอกเจ้าของ: this book; those books; my bag → mine](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2bded285e27a293d-module-06-map.png)\n\n*this/that + is  •  these/those + are  •  mine ไม่มี noun ตาม*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n![โต๊ะที่มีหนังสือสีแดงหนึ่งเล่ม สีฟ้าหนึ่งเล่ม ดินสอสามแท่ง แอปเปิลหนึ่งผลและร่มหนึ่งคัน](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d4c92bf830daea5a-study-desk.png)\n\n*Two books, three pencils, an apple and an umbrella.*\n\nเลือกของสองชนิดในภาพ บอกจำนวน สีหรือคำชี้ให้ตรงหัวข้อบทนี้ แล้วแต่งประโยคใหม่ของคุณ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('40922d33-38d7-5208-a308-72e2b078d7e3'::uuid,'eaf9f26f-87cf-577b-a1a3-ac61da1daaa6'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f19db6e3b35aba9c-lesson-06-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"This bag is blue.. Those bags are red.. These are books."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('164d3e3e-31a1-5423-adb4-2d2df7551ad1'::uuid,'eaf9f26f-87cf-577b-a1a3-ac61da1daaa6'::uuid,'multiple_choice',1,'{"question":"ของหลายชิ้นอยู่ใกล้ผู้พูด ใช้คำใด?","choices":[{"id":"choice_1","text":"this"},{"id":"choice_2","text":"these"},{"id":"choice_3","text":"that"}],"correctChoiceId":"choice_2","explanation":"these ชี้หลายสิ่งใกล้ผู้พูด"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fc22c323-30fc-5e18-af8a-adb80841a74f'::uuid,'eaf9f26f-87cf-577b-a1a3-ac61da1daaa6'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคที่ถูก","choices":[{"id":"choice_1","text":"Those books is new."},{"id":"choice_2","text":"Those book are new."},{"id":"choice_3","text":"Those books are new."}],"correctChoiceId":"choice_3","explanation":"those กับ books เป็นพหูพจน์จึงใช้ are"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('caac3851-bce0-530c-ada0-e6e344a50f54'::uuid,'eaf9f26f-87cf-577b-a1a3-ac61da1daaa6'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nชี้สิ่งใกล้และไกลอย่างละหนึ่งกับหลาย แล้วเขียนสี่ประโยค\n\n### ตัวอย่างคำตอบ\n\nThis pen is blue. These pens are blue. That bag is red. Those bags are red.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **this/that/these/those** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('106288b6-d073-522f-a89b-fb16de63bad0'::uuid,'6d575ff5-ec0e-55b0-aa7e-ca694f335c2e'::uuid,'reading',1,'{"title":"my/your/his/her/its/our/their","body":"## my/your/his/her/its/our/their\n\nmy/your/his/her/its/our/their อยู่หน้าคำนามเพื่อบอกเจ้าของ จับคู่ I→my, you→your, he→his, she→her, it→its, we→our, they→their รูปไม่เปลี่ยนตามจำนวนสิ่งของ เช่น my book/my books its ไม่มี apostrophe ส่วน it’s ย่อ it is หรือ it has ตามโครงสร้าง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I have a bag. My bag is blue. | I ประธาน; my หน้าคำนาม |\n| They have a room. Their room is small. | their บอกเจ้าของ |\n| The dog moves its tail. | its บอกส่วนของสัตว์ |\n\n### จุดที่มักสับสน\n\nไม่ใช้ I bag แทน my bag; her + noun เป็นคำบอกเจ้าของ ต่างจาก her ที่เป็นกรรม\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e856e087-0e0f-509b-abf9-09b068426e2b'::uuid,'6d575ff5-ec0e-55b0-aa7e-ca694f335c2e'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/48d76e689b5ad31b-lesson-06-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I have a bag. My bag is blue.. They have a room. Their room is small.. The dog moves its tail."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c046ce56-7507-56d7-a3a5-94156b2e70a3'::uuid,'6d575ff5-ec0e-55b0-aa7e-ca694f335c2e'::uuid,'multiple_choice',1,'{"question":"We have a house. … house is small.","choices":[{"id":"choice_1","text":"Our"},{"id":"choice_2","text":"Us"},{"id":"choice_3","text":"We"}],"correctChoiceId":"choice_1","explanation":"our ใช้หน้าคำนามบอกเจ้าของของ we"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('35133d9d-52dd-5fb2-af67-e0e9b2a697d0'::uuid,'6d575ff5-ec0e-55b0-aa7e-ca694f335c2e'::uuid,'multiple_choice',1,'{"question":"ข้อใดบอกเจ้าของถูก?","choices":[{"id":"choice_1","text":"It’s tail"},{"id":"choice_2","text":"Its tail"},{"id":"choice_3","text":"It tail"}],"correctChoiceId":"choice_2","explanation":"its เป็นคำบอกเจ้าของ ไม่มี apostrophe"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cbf57664-0d8e-5388-a47b-6a8f85e7587a'::uuid,'6d575ff5-ec0e-55b0-aa7e-ca694f335c2e'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนประธานแล้วเปลี่ยนเป็นคำบอกเจ้าของสามคู่\n\n### ตัวอย่างคำตอบ\n\nI → my phone; she → her book; they → their car.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **my/your/his/her/its/our/their** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1ae7fbf1-33ff-5ff5-af19-49e765e61bb5'::uuid,'caa18f4f-dc57-5c3c-aca1-2386786c6f26'::uuid,'reading',1,'{"title":"mine/yours/his/hers/ours/theirs","body":"## mine/yours/his/hers/ours/theirs\n\nmine/yours/his/hers/ours/theirs แทนทั้งกลุ่มคำนามที่บอกเจ้าของ จึงไม่เติมคำนามตามหลัง my bag = mine ในบริบทที่รู้ว่าหมายถึงกระเป๋า his รูปเหมือนกันทั้งหน้าคำนามและแทนคำนาม แต่ her ต้องเปลี่ยนเป็น hers เมื่อใช้เดี่ยว ๆ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| This is my bag. This bag is mine. | mine แทน my bag |\n| That is her book. That book is hers. | hers ไม่มี noun ตาม |\n| These seats are ours. | ours แทนที่นั่งของเรา |\n\n### จุดที่มักสับสน\n\nmine bag และ her’s ผิดในรูปนี้; possessive pronouns ไม่มี apostrophe\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5c7856ef-139a-580d-ad04-ec968a46f821'::uuid,'caa18f4f-dc57-5c3c-aca1-2386786c6f26'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/17376bb7a7f08ba2-lesson-06-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"This is my bag. This bag is mine.. That is her book. That book is hers.. These seats are ours."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4e9ead33-3a20-5e96-a50e-6882b540880a'::uuid,'caa18f4f-dc57-5c3c-aca1-2386786c6f26'::uuid,'multiple_choice',1,'{"question":"This is their room. This room is …","choices":[{"id":"choice_1","text":"their"},{"id":"choice_2","text":"theirs"},{"id":"choice_3","text":"them"}],"correctChoiceId":"choice_2","explanation":"theirs แทน their room"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d4684fbf-35b9-5083-ac5d-22763388047d'::uuid,'caa18f4f-dc57-5c3c-aca1-2386786c6f26'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคที่ถูก","choices":[{"id":"choice_1","text":"The pen is hers."},{"id":"choice_2","text":"The pen is her’s."},{"id":"choice_3","text":"The pen is her."}],"correctChoiceId":"choice_1","explanation":"hers เป็น possessive pronoun ไม่มี apostrophe"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d772d810-4273-5d64-a9fc-1cda9ff0b223'::uuid,'caa18f4f-dc57-5c3c-aca1-2386786c6f26'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสามคู่ my/mine, her/hers, our/ours โดยไม่พูดคำนามซ้ำ\n\n### ตัวอย่างคำตอบ\n\nThis is my cup. It is mine. That is her bag. It is hers. This is our room. It is ours.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **mine/yours/his/hers/ours/theirs** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fe48787f-49ea-5e90-ae1d-f1c27629beb0'::uuid,'cc77e862-aba2-555c-a629-2f4ecf5fe073'::uuid,'reading',1,'{"title":"ชื่อเจ้าของกับ apostrophe","body":"## ชื่อเจ้าของกับ apostrophe\n\nใช้ชื่อเจ้าของ + ’s เช่น Anna’s bag ถ้าเจ้าของพหูพจน์ลง s ใช้ apostrophe หลัง s เช่น my parents’ room แต่ plural ที่ไม่ลง s ใช้ ’s เช่น children’s books รูป s มีสามหน้าที่ที่ต้องดูบริบท: books หลายเล่ม; Anna’s book ของ Anna; Anna’s happy ย่อ Anna is happy\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Anna’s bag | กระเป๋าของ Anna |\n| my parents’ room | ห้องของพ่อแม่หลายคน |\n| children’s books | หนังสือของเด็กหลายคน |\n\n### จุดที่มักสับสน\n\nอย่าใช้ apostrophe เพื่อทำพหูพจน์ธรรมดา เช่น two book’s ผิด\n\n\n\n### ดูภาพแล้วลองใช้\n\n![โต๊ะที่มีหนังสือสีแดงหนึ่งเล่ม สีฟ้าหนึ่งเล่ม ดินสอสามแท่ง แอปเปิลหนึ่งผลและร่มหนึ่งคัน](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d4c92bf830daea5a-study-desk.png)\n\n*Two books, three pencils, an apple and an umbrella.*\n\nเลือกของสองชนิดในภาพ บอกจำนวน สีหรือคำชี้ให้ตรงหัวข้อบทนี้ แล้วแต่งประโยคใหม่ของคุณ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cb97a6bb-bd53-52e0-abbc-313b0004b934'::uuid,'cc77e862-aba2-555c-a629-2f4ecf5fe073'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2330f5da043986e3-lesson-06-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Anna’s bag. my parents’ room. children’s books"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e1e87a55-6fba-5f82-a662-01012d6f19e8'::uuid,'cc77e862-aba2-555c-a629-2f4ecf5fe073'::uuid,'multiple_choice',1,'{"question":"ห้องของพ่อแม่ทั้งสองคน ใช้รูปใด?","choices":[{"id":"choice_1","text":"my parents’ room"},{"id":"choice_2","text":"my parent’s room"},{"id":"choice_3","text":"my parents room"}],"correctChoiceId":"choice_1","explanation":"parents เป็น plural ลง s จึงใส่ apostrophe หลัง s"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ed0e2763-8d45-52bc-a6ab-5aabae8b18b8'::uuid,'cc77e862-aba2-555c-a629-2f4ecf5fe073'::uuid,'multiple_choice',1,'{"question":"หนังสือของเด็กหลายคน ใช้รูปใด?","choices":[{"id":"choice_1","text":"childrens’ books"},{"id":"choice_2","text":"children’s books"},{"id":"choice_3","text":"children books"}],"correctChoiceId":"choice_2","explanation":"children เป็น plural ที่ไม่ลง s เติม ’s"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d99331b0-18bc-5b12-a775-d985093afe06'::uuid,'cc77e862-aba2-555c-a629-2f4ecf5fe073'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nแยก s ใน Ben’s here, Ben’s books และ two books แล้วเขียนรูปเจ้าของหนึ่งตัวอย่าง\n\n### ตัวอย่างคำตอบ\n\nBen’s here = Ben is here; Ben’s books = หนังสือของ Ben; books = หลายเล่ม. My sister’s phone is new.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ชื่อเจ้าของกับ apostrophe** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('245f805f-ac7d-58cb-a9bd-b3a934d60390'::uuid,'8792427e-0fef-53d7-a43e-344f33dbac52'::uuid,'reading',1,'{"title":"ถาม Whose และพูดถึงสมาชิกของกลุ่ม","body":"## ถาม Whose และพูดถึงสมาชิกของกลุ่ม\n\nWhose ถามเจ้าของและใช้หน้าคำนามหรือใช้เดี่ยวตามบริบท เช่น Whose bag is this? ตอบ It is Mai’s. / It is hers. วลี a friend of mine หมายถึงเพื่อนคนหนึ่งของฉัน ต่างจาก my friend ที่อาจชี้เพื่อนเฉพาะ ใช้ of + possessive pronoun เช่น of theirs ไม่ใช้ of they\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Whose book is this? — It is Ben’s. | ถามเจ้าของ |\n| She is a friend of mine. | เพื่อนคนหนึ่งของฉัน |\n| He is a friend of theirs. | เพื่อนคนหนึ่งของพวกเขา |\n\n### จุดที่มักสับสน\n\nWho’s = who is/who has ต่างจาก Whose ที่ถามเจ้าของ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a4d7b37b-14f3-5946-a421-f0fc3d898490'::uuid,'8792427e-0fef-53d7-a43e-344f33dbac52'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4162d48932d2e8f0-lesson-06-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Whose book is this?. It is Ben’s.. She is a friend of mine.. He is a friend of theirs."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2425d371-52c4-5888-a383-23565b7783f5'::uuid,'8792427e-0fef-53d7-a43e-344f33dbac52'::uuid,'multiple_choice',1,'{"question":"คำใดถามเจ้าของ?","choices":[{"id":"choice_1","text":"Who’s"},{"id":"choice_2","text":"Whose"},{"id":"choice_3","text":"Where"}],"correctChoiceId":"choice_2","explanation":"Whose ถามว่าเป็นของใคร"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bb11672d-2807-57df-a700-8854a6ebb408'::uuid,'8792427e-0fef-53d7-a43e-344f33dbac52'::uuid,'multiple_choice',1,'{"question":"เลือกวลีที่ถูก","choices":[{"id":"choice_1","text":"a friend of my"},{"id":"choice_2","text":"a friend of I"},{"id":"choice_3","text":"a friend of mine"}],"correctChoiceId":"choice_3","explanation":"หลัง of ในโครงนี้ใช้ possessive pronoun mine"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8182f5b7-99cc-5c72-a1aa-42c6d6264398'::uuid,'8792427e-0fef-53d7-a43e-344f33dbac52'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nถามเจ้าของสิ่งของสองชิ้นและแนะนำเพื่อนคนหนึ่งของคุณ\n\n### ตัวอย่างคำตอบ\n\nWhose pen is this? It is Mai’s. Whose bag is that? It is his. Ben is a friend of mine.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ถาม Whose และพูดถึงสมาชิกของกลุ่ม** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8bac561b-0451-57bf-a6dc-f7e62dd19ece'::uuid,'bf850454-37f5-5e4a-aba8-4bdfe7a20d4b'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **ระบุสิ่งของใกล้ไกลและบอกหรือถามว่าเป็นของใคร**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ชี้สิ่งของและบอกเจ้าของ: this book; those books; my bag → mine](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2bded285e27a293d-module-06-map.png)\n\n*this/that + is  •  these/those + are  •  mine ไม่มี noun ตาม*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e1e1a063-935a-5465-a508-524cc47eae70'::uuid,'bf850454-37f5-5e4a-aba8-4bdfe7a20d4b'::uuid,'multiple_choice',1,'{"question":"หลายสิ่งไกลผู้พูดใช้คำใด?","choices":[{"id":"choice_1","text":"these"},{"id":"choice_2","text":"those"},{"id":"choice_3","text":"this"}],"correctChoiceId":"choice_2","explanation":"those = plural ไกล ย้อน 06.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d8cf7b9c-8803-576f-a125-1ab3bc7117d5'::uuid,'bf850454-37f5-5e4a-aba8-4bdfe7a20d4b'::uuid,'multiple_choice',1,'{"question":"This is our classroom. It is …","choices":[{"id":"choice_1","text":"our"},{"id":"choice_2","text":"ours"},{"id":"choice_3","text":"us"}],"correctChoiceId":"choice_2","explanation":"ours แทนกลุ่มคำนาม ย้อน 06.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8537a264-847e-5198-a34e-562551d8c46e'::uuid,'bf850454-37f5-5e4a-aba8-4bdfe7a20d4b'::uuid,'multiple_choice',1,'{"question":"ข้อใดถามเจ้าของ?","choices":[{"id":"choice_1","text":"Whose shoes are these?"},{"id":"choice_2","text":"Who’s shoes are these?"},{"id":"choice_3","text":"Who shoes these?"}],"correctChoiceId":"choice_1","explanation":"Whose ถามเจ้าของ ย้อน 06.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2663ffac-c34f-57a3-a6c0-396c6207c395'::uuid,'bf850454-37f5-5e4a-aba8-4bdfe7a20d4b'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nบรรยายสิ่งใกล้ไกลและเจ้าของสี่ประโยค ตั้งคำถาม Whose หนึ่งข้อ\n\n### ตัวอย่างผลงาน\n\nThis cup is mine. Those books are Ben’s. These pens are ours. That bag is hers. Whose phone is this?\n\n### ตรวจผลงาน\n\n- จำนวนตรง this/these\n- my/mine ใช้ตำแหน่งถูก\n- apostrophe ใช้บอกเจ้าของตามจำนวน\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b4ffbe14-4892-5120-a83a-67248e78aeed'::uuid,'fc8afe1d-982e-5170-a6c5-b472563732b6'::uuid,'reading',1,'{"title":"adjective ก่อนคำนามและหลัง be","body":"## adjective ก่อนคำนามและหลัง be\n\nadjective บรรยาย noun ได้สองตำแหน่งพื้นฐาน: ก่อน noun เช่น a small room หรือหลัง be เช่น The room is small. รูป adjective ไม่เปลี่ยนตามจำนวนคำนาม small rooms ไม่ใช่ smalls rooms ถ้า adjective เป็นสภาพของประธานต้องมี be ไม่ใช้ The room small. เป็นประโยคเต็ม\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| a blue bag / blue bags | blue ไม่เติม s |\n| The bag is blue. / The bags are blue. | be เปลี่ยนตามจำนวน แต่ blue คงเดิม |\n\n### จุดที่มักสับสน\n\nadjective ไม่ใช่กริยาการกระทำ จึงต้องเลือกโครงสร้างให้เหมาะ\n\n\n\n### ดูภาพแล้วลองใช้\n\n![คำบรรยายไม่เติม s ตามจำนวน: a small blue bag; The bags are small.; bored / boring](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/7aeba79b5cb2cfaa-module-07-map.png)\n\n*adjective บรรยาย noun  •  สภาพใช้ be เชื่อม*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adjectives ending in -ed and -ing](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-ending-ed-ing) · [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c8161876-e0bb-5d6d-af99-68d4deaeee6d'::uuid,'fc8afe1d-982e-5170-a6c5-b472563732b6'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/6a71a606d9587eed-lesson-07-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"a blue bag. blue bags. The bag is blue.. The bags are blue."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('01b3c7c7-cd83-53fb-af6f-0a589308c29d'::uuid,'fc8afe1d-982e-5170-a6c5-b472563732b6'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มคำนามที่ถูก","choices":[{"id":"choice_1","text":"reds bags"},{"id":"choice_2","text":"red bags"},{"id":"choice_3","text":"bags red ใน noun phrase พื้นฐาน"}],"correctChoiceId":"choice_2","explanation":"red อยู่ก่อน bags และไม่เติม s"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9dc77081-3c6b-57cd-a638-84377f2378af'::uuid,'fc8afe1d-982e-5170-a6c5-b472563732b6'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคเต็ม","choices":[{"id":"choice_1","text":"The rooms small."},{"id":"choice_2","text":"The rooms are small."},{"id":"choice_3","text":"The rooms is smalls."}],"correctChoiceId":"choice_2","explanation":"rooms หลายห้องใช้ are; small คงรูป"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('80dd5eb0-c750-5fc9-aa5d-303355de926a'::uuid,'fc8afe1d-982e-5170-a6c5-b472563732b6'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบรรยายสิ่งของสามอย่างทั้งรูปกลุ่มคำนามและประโยค\n\n### ตัวอย่างคำตอบ\n\na red cup → The cup is red. new shoes → The shoes are new. a small desk → The desk is small.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **adjective ก่อนคำนามและหลัง be** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b2689f4c-d860-51fc-a628-0c3b9652e12e'::uuid,'314493ff-20a7-5935-a136-539b9f5b0db1'::uuid,'reading',1,'{"title":"คุณลักษณะที่พบบ่อย","body":"## คุณลักษณะที่พบบ่อย\n\nเลือก adjective ให้ตรงคุณลักษณะที่สังเกต สี red/blue; ขนาด big/small; รูปร่าง round/square; อายุ new/old; สัญชาติ Thai/Japanese; บุคลิก kind/friendly; สภาพ clean/dirty คำหนึ่งอาจมีความหมายตามบริบท เช่น old ใช้กับอายุคนหรือสิ่งของเก่า และ new หมายถึงใหม่ต่อผู้พูดได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| a round table | โต๊ะทรงกลม |\n| a friendly teacher | ครูที่เป็นมิตร |\n| The room is clean. | ห้องสะอาด |\n\n### จุดที่มักสับสน\n\nสัญชาติขึ้นต้นตัวใหญ่ แต่สีทั่วไปไม่ต้องขึ้นต้นใหญ่กลางประโยค\n\n\n\n### ดูภาพแล้วลองใช้\n\n![โต๊ะที่มีหนังสือสีแดงหนึ่งเล่ม สีฟ้าหนึ่งเล่ม ดินสอสามแท่ง แอปเปิลหนึ่งผลและร่มหนึ่งคัน](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d4c92bf830daea5a-study-desk.png)\n\n*Two books, three pencils, an apple and an umbrella.*\n\nเลือกของสองชนิดในภาพ บอกจำนวน สีหรือคำชี้ให้ตรงหัวข้อบทนี้ แล้วแต่งประโยคใหม่ของคุณ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adjectives ending in -ed and -ing](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-ending-ed-ing) · [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a228c08c-1405-5c54-a3f4-f9f5eb65abae'::uuid,'314493ff-20a7-5935-a136-539b9f5b0db1'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/231bbaa0486c4556-lesson-07-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"a round table. a friendly teacher. The room is clean."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('efefd26b-4af8-5822-a3ec-4e5d55958905'::uuid,'314493ff-20a7-5935-a136-539b9f5b0db1'::uuid,'multiple_choice',1,'{"question":"ต้องการบอกโต๊ะทรงกลม เลือกคำใด?","choices":[{"id":"choice_1","text":"round"},{"id":"choice_2","text":"friendly"},{"id":"choice_3","text":"Thai"}],"correctChoiceId":"choice_1","explanation":"round บอก shape"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('473d1e93-e844-5ace-abb9-71c228c37614'::uuid,'314493ff-20a7-5935-a136-539b9f5b0db1'::uuid,'multiple_choice',1,'{"question":"ข้อใดบอกบุคลิก?","choices":[{"id":"choice_1","text":"a blue teacher"},{"id":"choice_2","text":"a friendly teacher"},{"id":"choice_3","text":"a square teacher"}],"correctChoiceId":"choice_2","explanation":"friendly เป็นคำบอกบุคลิกในบริบทคน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b83b98e1-1ada-54cb-a305-3f76cb3ccdb3'::uuid,'314493ff-20a7-5935-a136-539b9f5b0db1'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเลือกสิ่งของหนึ่งชิ้นและคนหนึ่งคน บรรยายอย่างละสองคุณลักษณะ\n\n### ตัวอย่างคำตอบ\n\nMy table is small and round. My teacher is kind and friendly.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **คุณลักษณะที่พบบ่อย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('11d728fd-f825-5a0e-a7da-6a096d93107c'::uuid,'b9ac9276-21c0-5fe8-affd-d2ea3240665f'::uuid,'reading',1,'{"title":"คำบรรยายมากกว่าหนึ่งคำ","body":"## คำบรรยายมากกว่าหนึ่งคำ\n\nเมื่อมีหลาย adjective ให้เริ่มจากชุดที่ใช้บ่อย เช่น size + colour + noun: a small blue bag ลำดับมักให้ความคิดเห็นมาก่อนขนาดและคุณสมบัติเฉพาะ เช่น a lovely small red bag ไม่ต้องท่องตารางยาวก่อนใช้ แต่สังเกตกลุ่มคำและตรวจตัวอย่างจริงเมื่อมีหลายคำมาก\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| a small blue bag | ขนาดก่อนสี |\n| a big round table | ขนาดก่อนรูปร่าง |\n| a lovely red dress | ความเห็นก่อนสี |\n\n### จุดที่มักสับสน\n\nไม่ย้าย noun ไปกลางชุด adjective และไม่เติม article แยกทุกคำเมื่อพูดถึงสิ่งเดียว\n\n\n\n### ดูภาพแล้วลองใช้\n\n![โต๊ะที่มีหนังสือสีแดงหนึ่งเล่ม สีฟ้าหนึ่งเล่ม ดินสอสามแท่ง แอปเปิลหนึ่งผลและร่มหนึ่งคัน](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d4c92bf830daea5a-study-desk.png)\n\n*Two books, three pencils, an apple and an umbrella.*\n\nเลือกของสองชนิดในภาพ บอกจำนวน สีหรือคำชี้ให้ตรงหัวข้อบทนี้ แล้วแต่งประโยคใหม่ของคุณ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adjectives ending in -ed and -ing](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-ending-ed-ing) · [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c3733197-bc31-52ec-adcb-5311a0fab2bf'::uuid,'b9ac9276-21c0-5fe8-affd-d2ea3240665f'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/a8c4804a8a1cb9c0-lesson-07-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"a small blue bag. a big round table. a lovely red dress"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5782b622-453c-5d96-ad76-f53601c40fb7'::uuid,'b9ac9276-21c0-5fe8-affd-d2ea3240665f'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มคำนามธรรมชาติในบทนี้","choices":[{"id":"choice_1","text":"a blue small bag"},{"id":"choice_2","text":"a small blue bag"},{"id":"choice_3","text":"a small bag blue"}],"correctChoiceId":"choice_2","explanation":"ขนาด small ก่อนสี blue แล้วจบด้วย noun"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a88c7a65-8863-5a63-a199-dfbe515589e7'::uuid,'b9ac9276-21c0-5fe8-affd-d2ea3240665f'::uuid,'multiple_choice',1,'{"question":"a big round … ควรตามด้วยอะไร?","choices":[{"id":"choice_1","text":"table"},{"id":"choice_2","text":"a"},{"id":"choice_3","text":"big"}],"correctChoiceId":"choice_1","explanation":"table เป็น noun ที่ถูกบรรยาย"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('76afcaeb-2694-5fde-a916-ff1346baa00c'::uuid,'b9ac9276-21c0-5fe8-affd-d2ea3240665f'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบรรยายสามสิ่งโดยใช้ adjective สองคำต่อ noun\n\n### ตัวอย่างคำตอบ\n\na small black phone; a big round table; a lovely blue shirt.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **คำบรรยายมากกว่าหนึ่งคำ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f1158886-9d04-5910-a7cc-b0c5c3804a07'::uuid,'7a061731-eb2f-5cd1-aa0f-04ee9951ab4f'::uuid,'reading',1,'{"title":"ความรู้สึกกับสิ่งที่ทำให้รู้สึก","body":"## ความรู้สึกกับสิ่งที่ทำให้รู้สึก\n\nadjective ลง -ed มักบอกความรู้สึกผู้ได้รับผล เช่น I am bored. ส่วน -ing บอกสิ่งหรือคนที่ทำให้เกิดความรู้สึก เช่น The lesson is boring. ใช้คู่ interested/interesting, excited/exciting ตามความหมาย รูปเหล่านี้เป็น adjective ได้ จึงอย่าคิดว่า -ing ทุกคำคือ Present Continuous\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I am interested in music. | ฉันสนใจดนตรี |\n| Music is interesting. | ดนตรีน่าสนใจ |\n| She is bored. The film is boring. | เธอเบื่อ / หนังทำให้เบื่อ |\n\n### จุดที่มักสับสน\n\nI am boring. หมายถึงฉันทำให้คนอื่นเบื่อ ซึ่งต่างจาก I am bored.\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adjectives ending in -ed and -ing](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-ending-ed-ing) · [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9041d998-92d6-5bd8-a43b-0eb07bf15bb3'::uuid,'7a061731-eb2f-5cd1-aa0f-04ee9951ab4f'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/17e48ee253769383-lesson-07-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I am interested in music.. Music is interesting.. She is bored. The film is boring."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('674e379e-eb62-55e0-a0fd-b3ad4bd6be47'::uuid,'7a061731-eb2f-5cd1-aa0f-04ee9951ab4f'::uuid,'multiple_choice',1,'{"question":"คุณรู้สึกตื่นเต้นก่อนเดินทาง: I am …","choices":[{"id":"choice_1","text":"excited"},{"id":"choice_2","text":"exciting"},{"id":"choice_3","text":"excite"}],"correctChoiceId":"choice_1","explanation":"excited บอกความรู้สึกของผู้พูด"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c617ccaf-3ad5-5ef7-a5f2-7f8f4c6dfc62'::uuid,'7a061731-eb2f-5cd1-aa0f-04ee9951ab4f'::uuid,'multiple_choice',1,'{"question":"หนังทำให้คนดูสนใจ: The film is …","choices":[{"id":"choice_1","text":"interested"},{"id":"choice_2","text":"interesting"},{"id":"choice_3","text":"interest"}],"correctChoiceId":"choice_2","explanation":"interesting บอกคุณสมบัติที่ทำให้สนใจ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('eca48c5e-abe0-5c10-a7f1-138e13edfa34'::uuid,'7a061731-eb2f-5cd1-aa0f-04ee9951ab4f'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสองคู่เกี่ยวกับความรู้สึกของคุณกับสิ่งที่ทำให้รู้สึก\n\n### ตัวอย่างคำตอบ\n\nI am excited. The trip is exciting. I am interested in art. Art is interesting.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ความรู้สึกกับสิ่งที่ทำให้รู้สึก** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('74b239aa-0dc0-5c52-a2b6-fb452bec97ef'::uuid,'ff2ce744-05ce-52e1-a86f-9b53d91cdd83'::uuid,'reading',1,'{"title":"บรรยายให้เฉพาะเจาะจง","body":"## บรรยายให้เฉพาะเจาะจง\n\nรวม adjective กับ noun phrase เพื่อบรรยายให้เฉพาะเจาะจง I am happy. บอกสภาพตอนนี้ ส่วน I am a happy person. บรรยายลักษณะบุคคลโดยรวม คำถาม What is Ben like? ขอคำบรรยายบุคลิกหรือคุณลักษณะ ต่างจาก What does Ben like? ที่ถามความชอบ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| What is Mai like? — She is kind. | ถามบุคลิก |\n| What is the room like? — It is small and bright. | ถามลักษณะ |\n| I am happy. / I am a happy person. | สภาพ / ลักษณะบุคคล |\n\n### จุดที่มักสับสน\n\nlike ใน What is … like? ไม่ได้เป็นกริยาชอบในโครงสร้างนี้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adjectives ending in -ed and -ing](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-ending-ed-ing) · [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('da8f18ff-528a-54f9-aff8-cf7650d2ca5b'::uuid,'ff2ce744-05ce-52e1-a86f-9b53d91cdd83'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/797a9367c9cd2049-lesson-07-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"What is Mai like?. She is kind.. What is the room like?. It is small and bright.. I am happy.. I am a happy person."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9bcff562-cfa2-5af9-a13d-3dfdf823aa51'::uuid,'ff2ce744-05ce-52e1-a86f-9b53d91cdd83'::uuid,'multiple_choice',1,'{"question":"What is your teacher like? คำตอบใดตรงคำถาม?","choices":[{"id":"choice_1","text":"She is friendly."},{"id":"choice_2","text":"She likes tea."},{"id":"choice_3","text":"She is at school."}],"correctChoiceId":"choice_1","explanation":"คำถามขอคำบรรยายลักษณะหรือบุคลิก"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('295a88c9-1acf-52c2-a554-04d2123bf529'::uuid,'ff2ce744-05ce-52e1-a86f-9b53d91cdd83'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคที่มีกลุ่มคำนามบรรยายบุคคล","choices":[{"id":"choice_1","text":"I am a kind person."},{"id":"choice_2","text":"I am a kind."},{"id":"choice_3","text":"I am person kind."}],"correctChoiceId":"choice_1","explanation":"a + adjective + noun จัดเป็น noun phrase"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('97a2eac5-d324-595f-a4f8-5091866d0db0'::uuid,'ff2ce744-05ce-52e1-a86f-9b53d91cdd83'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบรรยายคนหนึ่งคนและห้องหนึ่งห้อง แล้วตั้งคำถาม What is … like?\n\n### ตัวอย่างคำตอบ\n\nWhat is Ben like? He is a friendly person. What is his room like? It is small and clean.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **บรรยายให้เฉพาะเจาะจง** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8e05d811-5230-5e2a-a3a0-fbd241687b51'::uuid,'13b8eebd-a1f4-5c5d-aa37-1c812e58b2ee'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **บรรยายด้วย adjective โดยไม่ใช้แทนกริยาหรือเติม s ตามจำนวน**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![คำบรรยายไม่เติม s ตามจำนวน: a small blue bag; The bags are small.; bored / boring](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/7aeba79b5cb2cfaa-module-07-map.png)\n\n*adjective บรรยาย noun  •  สภาพใช้ be เชื่อม*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('944b2a10-77cb-5d0b-a13c-78afdc4fc9eb'::uuid,'13b8eebd-a1f4-5c5d-aa37-1c812e58b2ee'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มคำบรรยายถูก","choices":[{"id":"choice_1","text":"two smalls rooms"},{"id":"choice_2","text":"two small rooms"},{"id":"choice_3","text":"two rooms small"}],"correctChoiceId":"choice_2","explanation":"adjective ไม่เติม s ย้อน 07.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2b47092b-9f73-5d78-a4d6-1f644cfd2ed3'::uuid,'13b8eebd-a1f4-5c5d-aa37-1c812e58b2ee'::uuid,'multiple_choice',1,'{"question":"I feel … because the game is exciting.","choices":[{"id":"choice_1","text":"excited"},{"id":"choice_2","text":"exciting"},{"id":"choice_3","text":"excite"}],"correctChoiceId":"choice_1","explanation":"excited บอกความรู้สึก ย้อน 07.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4b8da355-b8e9-5575-a1fb-d2ea956e6ab4'::uuid,'13b8eebd-a1f4-5c5d-aa37-1c812e58b2ee'::uuid,'multiple_choice',1,'{"question":"What is your room like? คำตอบใดตรง?","choices":[{"id":"choice_1","text":"It is big and clean."},{"id":"choice_2","text":"I like coffee."},{"id":"choice_3","text":"It likes me."}],"correctChoiceId":"choice_1","explanation":"ถามลักษณะของห้อง ย้อน 07.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cedfd217-a1d2-5823-afea-af56869e0088'::uuid,'13b8eebd-a1f4-5c5d-aa37-1c812e58b2ee'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nบรรยายคนกับสิ่งของอย่างละสองประโยคและแยกความรู้สึกจากสิ่งที่ทำให้รู้สึก\n\n### ตัวอย่างผลงาน\n\nMai is a kind person. Her room is small and bright. She is interested in art. Art is interesting.\n\n### ตรวจผลงาน\n\n- adjective อยู่ก่อน noun หรือหลัง be\n- ไม่เติม s ให้ adjective\n- เลือก ed/ing ตามผู้รู้สึกกับสิ่งที่ทำให้รู้สึก\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('52239dc4-5236-50af-aa02-5e1318808ffe'::uuid,'a7fb3e60-4e0e-5df6-ad18-7605b52f6c71'::uuid,'reading',1,'{"title":"กริยาที่ใช้บ่อย","body":"## กริยาที่ใช้บ่อย\n\nเรียนกริยาพร้อมสิ่งที่ใช้ร่วมกัน go to school, come home, live in Bangkok, work in a shop, study English, eat rice, drink water, like music, want a book กลุ่มคำช่วยให้ใช้ถูกมากกว่าท่องคำแปลเดี่ยว ๆ ใน Present Simple I/you/we/they ใช้รูปพื้นฐาน; he/she/it จะเปลี่ยนรูปในบทถัดไป\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I live in Bangkok. | live in + สถานที่ |\n| We study English. | study + วิชาหรือภาษา |\n| I drink water. | drink + สิ่งที่ดื่ม |\n\n### จุดที่มักสับสน\n\nไม่เติม to หลังกริยาทุกคำ เช่น study English ไม่ใช่ study to English\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9564d4ac-d623-5eb4-ad52-206b3ac39074'::uuid,'a7fb3e60-4e0e-5df6-ad18-7605b52f6c71'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d02ac1c285574377-lesson-08-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I live in Bangkok.. We study English.. I drink water."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('64c2f5d9-f9cd-5dd4-a844-bddb7c17b24a'::uuid,'a7fb3e60-4e0e-5df6-ad18-7605b52f6c71'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มคำที่ถูก","choices":[{"id":"choice_1","text":"study to English"},{"id":"choice_2","text":"study English"},{"id":"choice_3","text":"study at English"}],"correctChoiceId":"choice_2","explanation":"study รับกรรมชื่อวิชาโดยตรง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('94cc405d-fdf1-5611-ac36-c9ee5c1de3f9'::uuid,'a7fb3e60-4e0e-5df6-ad18-7605b52f6c71'::uuid,'multiple_choice',1,'{"question":"ต้องการบอกที่อยู่อาศัย เลือก","choices":[{"id":"choice_1","text":"I live in Chiang Mai."},{"id":"choice_2","text":"I eat Chiang Mai."},{"id":"choice_3","text":"I drink Chiang Mai."}],"correctChoiceId":"choice_1","explanation":"live in ใช้กับสถานที่อาศัย"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d5d4ba04-09bd-5665-afb0-7e1b3c6b9b57'::uuid,'a7fb3e60-4e0e-5df6-ad18-7605b52f6c71'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนกิจกรรมของคุณห้าประโยคด้วยกริยาต่างกัน\n\n### ตัวอย่างคำตอบ\n\nI live in Bangkok. I study English. I eat rice. I drink water. I like music.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **กริยาที่ใช้บ่อย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('01e4f73b-b9de-5b8f-a781-67f8493c39ab'::uuid,'58946c87-c848-57e6-aade-ea995d45c06f'::uuid,'reading',1,'{"title":"รูปกริยาและเวลา","body":"## รูปกริยาและเวลา\n\nกริยาหนึ่งคำมีหลายรูป เช่น work/works/working/worked/worked และ go/goes/going/went/gone รูปพื้นฐาน V1 ใช้หลัง I ใน Present Simple; s-form ใช้กับ he/she/it; -ing ใช้ใน continuous พร้อม be; V2 ใช้เล่าอดีต; V3 ใช้หลัง have หรือใน passive ภายหลัง เวลาในความหมายกับ tense ไม่ใช่สิ่งเดียวกัน เช่น Present Simple ใช้กับตารางอนาคตได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| go — goes — going — went — gone | รูปต่างกันตามโครงสร้าง |\n| work — works — working — worked — worked | V2 และ V3 เหมือนกัน |\n\n### จุดที่มักสับสน\n\nตอนนี้รู้หน้าที่คร่าว ๆ ไม่ต้องเอาทุกรูปมาต่อกัน และอย่าคิดว่าคำเวลาอนาคตบังคับ will เสมอ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('60e5b181-bec4-5d9c-a5e0-38850760cc36'::uuid,'58946c87-c848-57e6-aade-ea995d45c06f'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/c1ce759f023830c3-lesson-08-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"go. goes. going. went. gone. work. works. working. worked. worked"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b4e1664b-7423-5e7f-a9ad-1fa0e9a64170'::uuid,'58946c87-c848-57e6-aade-ea995d45c06f'::uuid,'multiple_choice',1,'{"question":"รูปไหนเป็น base form ของ eat?","choices":[{"id":"choice_1","text":"eats"},{"id":"choice_2","text":"eat"},{"id":"choice_3","text":"eaten"}],"correctChoiceId":"choice_2","explanation":"eat เป็นรูปพื้นฐาน; eats เป็น s-form; eaten เป็น V3"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('17556599-a9b3-5522-adf2-8f3e4c8b711e'::uuid,'58946c87-c848-57e6-aade-ea995d45c06f'::uuid,'multiple_choice',1,'{"question":"V2 และ V3 ของ work เป็นอย่างไร?","choices":[{"id":"choice_1","text":"เหมือนกัน: worked"},{"id":"choice_2","text":"ต่างกันทุกครั้ง"},{"id":"choice_3","text":"ไม่มีรูป V3"}],"correctChoiceId":"choice_1","explanation":"regular verbs มักมี V2/V3 ลง ed เหมือนกัน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c0b12c4d-5e30-5b7b-a79a-e776cbb3e8a3'::uuid,'58946c87-c848-57e6-aade-ea995d45c06f'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nทำบัตรรูปกริยา go และ work พร้อมจดว่าจะกลับมาใช้ V2/V3 ในบทใด\n\n### ตัวอย่างคำตอบ\n\ngo/goes/going/went/gone; work/works/working/worked/worked. V2 ใช้ใน M20 และ V3 ใช้ใน M25/M31.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **รูปกริยาและเวลา** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7da854f0-f122-5447-a204-554119a01f94'::uuid,'59c0f8be-db21-55ab-a74e-29b9c7a1766b'::uuid,'reading',1,'{"title":"Present Simple ใช้เมื่อไร","body":"## Present Simple ใช้เมื่อไร\n\nPresent Simple ใช้กับกิจวัตร ข้อเท็จจริงทั่วไปและสภาพที่คงอยู่ในความหมายที่พูด เช่น I work in a shop. ไม่ได้แปลว่ากำลังทำงาน ณ วินาทีนี้เสมอ ข้อมูลอย่าง Water boils at 100°C ใช้ข้อเท็จจริงทั่วไปภายใต้ความดันบรรยากาศปกติ คำบอกกิจวัตรช่วยบริบท แต่การเลือก tense ต้องดูความหมายของทั้งข้อความ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I study English every day. | กิจวัตร |\n| She lives in Chiang Mai. | สภาพที่เป็นจริงในช่วงนี้ |\n| Birds have wings. | ข้อเท็จจริงทั่วไป |\n\n### จุดที่มักสับสน\n\nสิ่งกำลังเกิด ณ ตอนนี้จะใช้ Present Continuous ใน M17; ไม่เลือก tense จากคำใบ้หนึ่งคำโดยไม่ดูความหมาย\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ผู้หญิงเสื้อฟ้าอ่านหนังสือ ผู้ชายเสื้อแดงวิ่ง คนสองคนเดินและสุนัขนอนใต้ต้นไม้](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/dd683d7c6dc8b68a-park-activities.png)\n\n*Four people are in the park. A woman is reading, a man is running, and two people are walking.*\n\nชี้คนที่หมายถึงก่อนบรรยาย แยกสิ่งที่เห็นตอนนี้จากกิจวัตรที่คุณต้องการสมมติ แล้วใช้รูปประโยคตามบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a01a39b3-1c3a-533b-a2d0-16f949f0215d'::uuid,'59c0f8be-db21-55ab-a74e-29b9c7a1766b'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2a3d942e19a91f15-lesson-08-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I study English every day.. She lives in Chiang Mai.. Birds have wings."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('40dfc196-a7bd-5142-a080-18d0eefd69d7'::uuid,'59c0f8be-db21-55ab-a74e-29b9c7a1766b'::uuid,'multiple_choice',1,'{"question":"I walk to school every day สื่ออะไรเป็นหลัก?","choices":[{"id":"choice_1","text":"กิจวัตร"},{"id":"choice_2","text":"เหตุการณ์ที่จบเมื่อวาน"},{"id":"choice_3","text":"คำสั่ง"}],"correctChoiceId":"choice_1","explanation":"every day บอกการทำเป็นปกติ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5dfeacaf-c7c6-5a61-a26a-11efa87ff8f0'::uuid,'59c0f8be-db21-55ab-a74e-29b9c7a1766b'::uuid,'multiple_choice',1,'{"question":"ข้อใดเป็นข้อเท็จจริงทั่วไป?","choices":[{"id":"choice_1","text":"Cats are animals."},{"id":"choice_2","text":"I went home yesterday."},{"id":"choice_3","text":"I am running now."}],"correctChoiceId":"choice_1","explanation":"Cats are animals ใช้ปัจจุบันบอกประเภททั่วไป"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('45067a30-7f8a-57cd-aaf5-2ed8aac25757'::uuid,'59c0f8be-db21-55ab-a74e-29b9c7a1766b'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนกิจวัตรสองข้อและข้อเท็จจริงหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nI eat breakfast every day. I study English. Dogs are animals.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Present Simple ใช้เมื่อไร** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('46102472-ab33-5c68-aeed-fe97b9f011f4'::uuid,'3edc8312-10ed-58d2-ab33-c81bbafb01d8'::uuid,'reading',1,'{"title":"I/you/we/they + V1","body":"## I/you/we/they + V1\n\nI/you/we/they กับ Present Simple บอกเล่าใช้ base verb เช่น I work. We study. ไม่ต้องมี am/are นำหน้า เพราะ work/study เป็นกริยาอยู่แล้ว เปรียบเทียบ I am happy. ที่ happy เป็น adjective ต้องมี be ประธานหลายคนเช่น My friends ใช้รูปพื้นฐานเช่นเดียวกับ they\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I work in a shop. | กริยาทั่วไปไม่เติม am |\n| We study English. | we + base verb |\n| I am happy. | adjective ใช้ be |\n\n### จุดที่มักสับสน\n\nI am work และ We are study ผิดใน Present Simple; หากกำลังทำจะต้องเป็น am working/are studying ตามบท M17\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ebb80967-9e08-56ab-aaad-82e42513bbe6'::uuid,'3edc8312-10ed-58d2-ab33-c81bbafb01d8'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/404a85912e8d4254-lesson-08-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I work in a shop.. We study English.. I am happy."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8e91e9ea-807a-5e2a-a1e6-202fea3bd1e1'::uuid,'3edc8312-10ed-58d2-ab33-c81bbafb01d8'::uuid,'multiple_choice',1,'{"question":"เลือก Present Simple ที่ถูก","choices":[{"id":"choice_1","text":"They are play football."},{"id":"choice_2","text":"They play football."},{"id":"choice_3","text":"They plays football."}],"correctChoiceId":"choice_2","explanation":"they ใช้ base verb play"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('99749590-c668-5027-ab52-4d20dea10413'::uuid,'3edc8312-10ed-58d2-ab33-c81bbafb01d8'::uuid,'multiple_choice',1,'{"question":"ประโยคใดต้องมี am?","choices":[{"id":"choice_1","text":"I … happy."},{"id":"choice_2","text":"I … drink water."},{"id":"choice_3","text":"I … read books."}],"correctChoiceId":"choice_1","explanation":"happy เป็น adjective; drink/read เป็น verb"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f613a027-230d-5041-a95f-940389828af5'::uuid,'3edc8312-10ed-58d2-ab33-c81bbafb01d8'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสี่ประโยคด้วย I, you, we, they และเปรียบเทียบหนึ่งประโยคด้วย be\n\n### ตัวอย่างคำตอบ\n\nI read. You work. We study. They walk. I am ready.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **I/you/we/they + V1** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('58a9d2b0-cd92-5480-af19-47dcecd5563c'::uuid,'aeb5004c-a89b-53f6-aabc-e72d5859e2d7'::uuid,'reading',1,'{"title":"he/she/it + s/es","body":"## he/she/it + s/es\n\nhe/she/it และประธานเอกพจน์ใน Present Simple บอกเล่าเติม s/es ให้กริยา ส่วนใหญ่เติม s; ลง sh/ch/s/x/o บางคำเติม es เช่น watches/goes/does; พยัญชนะ + y เปลี่ยนเป็น ies เช่น studies แต่ plays เติม s เสียงท้ายมี /s,z,ɪz/ เหมือนพหูพจน์ noun แต่หน้าที่ต่างกัน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Mai works. / My friends work. | ประธานหนึ่ง / หลาย |\n| She studies. / He plays. | study → studies; play → plays |\n| He watches TV. | เติม es |\n\n### จุดที่มักสับสน\n\nใน She likes books, likes เป็น verb agreement ส่วน books เป็น plural noun; อย่าเติม s ให้กริยาตามจำนวนกรรม\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ดูประธาน ไม่ใช่จำนวนกรรม: read books; reads books; reads ≠ books](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/ed206aa70dc41243-module-08-map.png)\n\n*s ของกริยาตามประธาน  •  s ของคำนามบอกจำนวน*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n![ผู้หญิงเสื้อฟ้าอ่านหนังสือ ผู้ชายเสื้อแดงวิ่ง คนสองคนเดินและสุนัขนอนใต้ต้นไม้](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/dd683d7c6dc8b68a-park-activities.png)\n\n*Four people are in the park. A woman is reading, a man is running, and two people are walking.*\n\nชี้คนที่หมายถึงก่อนบรรยาย แยกสิ่งที่เห็นตอนนี้จากกิจวัตรที่คุณต้องการสมมติ แล้วใช้รูปประโยคตามบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5d6cdd70-f6b0-577f-a44c-dae6afddf49a'::uuid,'aeb5004c-a89b-53f6-aabc-e72d5859e2d7'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/00ba4184249d103b-lesson-08-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"She works. He plays. She watches. Mai studies English. Her friends study English."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c1e733f4-c97d-55ea-a220-4999c2fbfe56'::uuid,'aeb5004c-a89b-53f6-aabc-e72d5859e2d7'::uuid,'multiple_choice',1,'{"question":"My brother … English.","choices":[{"id":"choice_1","text":"study"},{"id":"choice_2","text":"studies"},{"id":"choice_3","text":"studys"}],"correctChoiceId":"choice_2","explanation":"brother เอกพจน์ และ study มีพยัญชนะหน้า y จึง studies"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d66e651e-7a58-51db-a933-6c64496cebd9'::uuid,'aeb5004c-a89b-53f6-aabc-e72d5859e2d7'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคที่ถูก","choices":[{"id":"choice_1","text":"She like books."},{"id":"choice_2","text":"She likes books."},{"id":"choice_3","text":"She liking books."}],"correctChoiceId":"choice_2","explanation":"She ใช้ likes; books หลายเล่มเป็นกรรม"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('971c31ef-cc92-5b10-a735-a5c0c3b936b7'::uuid,'aeb5004c-a89b-53f6-aabc-e72d5859e2d7'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเปลี่ยน I go / I study / I play / I watch เป็นประโยคเกี่ยวกับ Mai\n\n### ตัวอย่างคำตอบ\n\nMai goes to school. Mai studies English. Mai plays football. Mai watches TV.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **he/she/it + s/es** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c7dc2de1-6ec4-5e65-a256-dcdc334af1be'::uuid,'0cde18d4-8098-5b1b-a686-4513d3d6ece1'::uuid,'reading',1,'{"title":"have/has และ have got","body":"## have/has และ have got\n\nhave/has เป็นกริยาทั่วไปเมื่อบอกการมี: I have a bike; she has a bike ใช้ have ในกิจกรรมบางกลุ่มเช่น have breakfast จึงไม่ได้แปลว่าครอบครองทุกครั้ง have got เป็นรูปบอกการมีที่พบบ่อยใน British English: I have got / she has got ใช้คำถาม Have you got…? ต่างจาก Do you have…? รูปปฏิเสธคือ I haven’t got / she hasn’t got อย่าปนสองระบบในประโยคเดียว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I have a bike. / She has a bike. | have/has ตามประธาน |\n| I have breakfast at seven. | have เป็นกิจกรรมกิน |\n| Have you got a pen? — Yes, I have. | have got แบบบอกการมี |\n\n### จุดที่มักสับสน\n\nไม่เขียน Does she has…? หลัง does ใช้ have; Have you got…? ไม่เติม do อีก\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('906579f7-9bd3-5c23-aad3-acf534006d5b'::uuid,'0cde18d4-8098-5b1b-a686-4513d3d6ece1'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/1a4580db7d3ff878-lesson-08-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I have a bike.. She has a bike.. I have breakfast at seven.. Have you got a pen?. Yes, I have."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d0c494b1-b143-5ac1-aa2e-dc514934043b'::uuid,'0cde18d4-8098-5b1b-a686-4513d3d6ece1'::uuid,'multiple_choice',1,'{"question":"Ben … two sisters.","choices":[{"id":"choice_1","text":"have"},{"id":"choice_2","text":"has"},{"id":"choice_3","text":"haves"}],"correctChoiceId":"choice_2","explanation":"Ben เอกพจน์ใช้ has"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b6d00b84-d3df-56be-a364-e1d1d2e2a17c'::uuid,'0cde18d4-8098-5b1b-a686-4513d3d6ece1'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามถูกเกี่ยวกับการมี","choices":[{"id":"choice_1","text":"Do you have a pen?"},{"id":"choice_2","text":"Do you have got a pen?"},{"id":"choice_3","text":"Does you has a pen?"}],"correctChoiceId":"choice_1","explanation":"Do you have…? ใช้ระบบกริยาทั่วไป; Have you got…? เป็นอีกระบบ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('59e52ff5-b792-5e1c-aee4-122e0a55f56c'::uuid,'0cde18d4-8098-5b1b-a686-4513d3d6ece1'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกสิ่งที่คุณมีสองประโยคและกิจกรรมหนึ่งประโยคด้วย have แล้วเขียน have got อีกแบบ\n\n### ตัวอย่างคำตอบ\n\nI have a phone. I have two books. I have breakfast at home. I have got a phone.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **have/has และ have got** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f7799911-451d-522e-a9d1-559671432f5d'::uuid,'91c408b8-6eeb-5d04-af83-14c41e526854'::uuid,'reading',1,'{"title":"ขยายประโยคกริยา","body":"## ขยายประโยคกริยา\n\nขยายประโยคโดยเพิ่มกรรม เวลาและสถานที่ตามข้อมูลที่ต้องการ เช่น My sister reads books at home. ดูจำนวนประธานจากกลุ่มคำนาม My sister หนึ่งคนจึง reads ไม่เปลี่ยนตามจำนวนกรรม books ลำดับพื้นฐาน subject + verb + object + place/time ช่วยเริ่มได้ แต่ข้อมูลเวลาอาจอยู่ต้นประโยคตามจุดเน้น\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| My sister reads books at home. | ประธานหนึ่ง กรรมหลาย |\n| My sisters read books at home. | ประธานหลาย |\n| Every day, Ben walks to school. | เวลาอยู่ต้นได้ |\n\n### จุดที่มักสับสน\n\nเติม s ตาม subject ไม่ใช่คำที่อยู่ชิด verb โดยไม่ดูหน้าที่\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8da6f274-dcf3-5709-acd3-044eee3e0459'::uuid,'91c408b8-6eeb-5d04-af83-14c41e526854'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/061fb07a58003db8-lesson-08-07.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"My sister reads books at home.. My sisters read books at home.. Every day, Ben walks to school."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('87552c12-fa09-5ee5-aa59-552b523d6786'::uuid,'91c408b8-6eeb-5d04-af83-14c41e526854'::uuid,'multiple_choice',1,'{"question":"The students … English at school.","choices":[{"id":"choice_1","text":"studies"},{"id":"choice_2","text":"study"},{"id":"choice_3","text":"studys"}],"correctChoiceId":"choice_2","explanation":"students เป็น plural จึง study"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ae72d498-215d-5a6f-a977-acd85ec8ad12'::uuid,'91c408b8-6eeb-5d04-af83-14c41e526854'::uuid,'multiple_choice',1,'{"question":"ใน She reads books at home จำนวน books กำหนด reads หรือไม่?","choices":[{"id":"choice_1","text":"ไม่กำหนด ประธาน She กำหนด"},{"id":"choice_2","text":"กำหนดเพราะอยู่หลังกริยา"},{"id":"choice_3","text":"ทำให้ต้องใช้ read"}],"correctChoiceId":"choice_1","explanation":"agreement ดูประธาน She"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('226ea627-4a48-569e-a6c8-49e5917ed66b'::uuid,'91c408b8-6eeb-5d04-af83-14c41e526854'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nขยาย I read ให้มีสิ่งที่อ่าน สถานที่และเวลา แล้วเปลี่ยนประธานเป็นเพื่อนคนหนึ่ง\n\n### ตัวอย่างคำตอบ\n\nI read books at home every day. Ben reads books at home every day.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ขยายประโยคกริยา** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6af75437-876a-5d47-a595-0e63cf8d1c70'::uuid,'7b66e249-d72a-5be5-a6a5-68b3fd8f3e68'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **สร้างประโยคปัจจุบันทั่วไปและเลือกกริยาตามประธานได้**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ดูประธาน ไม่ใช่จำนวนกรรม: read books; reads books; reads ≠ books](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/ed206aa70dc41243-module-08-map.png)\n\n*s ของกริยาตามประธาน  •  s ของคำนามบอกจำนวน*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('eda15a0c-2d52-5b4e-ada3-2ce1978eaffe'::uuid,'7b66e249-d72a-5be5-a6a5-68b3fd8f3e68'::uuid,'multiple_choice',1,'{"question":"My friend … to school.","choices":[{"id":"choice_1","text":"go"},{"id":"choice_2","text":"goes"},{"id":"choice_3","text":"going"}],"correctChoiceId":"choice_2","explanation":"friend หนึ่งคนใช้ goes ย้อน 08.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('794a9361-db33-50f5-afc2-7360f149cd2d'::uuid,'7b66e249-d72a-5be5-a6a5-68b3fd8f3e68'::uuid,'multiple_choice',1,'{"question":"เลือก Present Simple ที่ถูก","choices":[{"id":"choice_1","text":"We are eat rice."},{"id":"choice_2","text":"We eat rice."},{"id":"choice_3","text":"We eats rice."}],"correctChoiceId":"choice_2","explanation":"we + base eat ไม่ใส่ be ย้อน 08.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('74aa2bbe-cc63-5148-a942-1c9f4e765a39'::uuid,'7b66e249-d72a-5be5-a6a5-68b3fd8f3e68'::uuid,'multiple_choice',1,'{"question":"He … breakfast at home.","choices":[{"id":"choice_1","text":"has"},{"id":"choice_2","text":"have"},{"id":"choice_3","text":"haves"}],"correctChoiceId":"choice_1","explanation":"he ใช้ has; have breakfast เป็นกิจกรรม ย้อน 08.06"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('039cd2c2-fdfe-5bec-aa28-e13420b200a8'::uuid,'7b66e249-d72a-5be5-a6a5-68b3fd8f3e68'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเขียนกิจวัตรของคุณและคนใกล้ตัวรวมสี่ประโยค พร้อมชี้ s ของ verb และ plural noun\n\n### ตัวอย่างผลงาน\n\nI read books at home. Mai reads books at school. I have breakfast at seven. She has breakfast at eight.\n\n### ตรวจผลงาน\n\n- กริยาตรงประธาน\n- แยก be จากกริยาการกระทำ\n- ใช้กรรม เวลาและสถานที่ให้เข้าใจ\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f4c5e680-7b1a-5eff-a941-2bc0d2dd16af'::uuid,'3a482264-9c25-5568-affc-83ff931a2a92'::uuid,'reading',1,'{"title":"me/you/him/her/it/us/them","body":"## me/you/him/her/it/us/them\n\nกรรมใช้ me/you/him/her/it/us/them แทนกลุ่มคำนามหลัง verb เปรียบเทียบ I like him. กับ He likes me. รูปขึ้นกับหน้าที่ ไม่ใช่เพศหรือความหมายภาษาไทยอย่างเดียว I/he/she/we/they เป็น subject; me/him/her/us/them เป็น object ส่วน you/it รูปเหมือนกัน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| She helps me. | She ประธาน; me กรรม |\n| I help her. | I ประธาน; her กรรม |\n| We know them. | them แทนคนหลายคน |\n\n### จุดที่มักสับสน\n\nHim likes I ผิดทั้งสองตำแหน่ง ให้ใช้ He likes me.\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ประธานกับกรรมใช้คนละรูป: I · he · they; me · him · them; with me · for her](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/00554ad0e619de52-module-09-map.png)\n\n*She helps me.  ↔  I help her.*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3189a676-5d2c-5562-a0a1-c170f7486a8d'::uuid,'3a482264-9c25-5568-affc-83ff931a2a92'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/5e19b8b544885699-lesson-09-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"She helps me.. I help her.. We know them."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f6fcff84-7298-5106-a251-d9c9258c3672'::uuid,'3a482264-9c25-5568-affc-83ff931a2a92'::uuid,'multiple_choice',1,'{"question":"Ben helps … (ฉัน)","choices":[{"id":"choice_1","text":"I"},{"id":"choice_2","text":"my"},{"id":"choice_3","text":"me"}],"correctChoiceId":"choice_3","explanation":"ตำแหน่งหลัง helps เป็นกรรม ใช้ me"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('85bfba6c-a293-5df8-a87f-ba796dce6dc1'::uuid,'3a482264-9c25-5568-affc-83ff931a2a92'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคที่ถูก","choices":[{"id":"choice_1","text":"They know us."},{"id":"choice_2","text":"Them know we."},{"id":"choice_3","text":"Their know our."}],"correctChoiceId":"choice_1","explanation":"They ประธาน; us กรรม"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bc133f87-9e08-5bed-a1ea-60512debf73d'::uuid,'3a482264-9c25-5568-affc-83ff931a2a92'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nแต่งประโยคสามคู่โดยสลับผู้ทำกับผู้รับ\n\n### ตัวอย่างคำตอบ\n\nI help her. She helps me. We know them. They know us.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **me/you/him/her/it/us/them** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0b67000a-bba3-5572-ae7a-026ee5dc52e4'::uuid,'6f28d542-52b6-51b1-a8b0-de7e1baa8150'::uuid,'reading',1,'{"title":"กรรมหลังคำบุพบท","body":"## กรรมหลังคำบุพบท\n\nหลัง preposition เช่น with/for/to ใช้ object pronouns: with me, for her, to them รูป I/she/they ไม่ใช้ในตำแหน่งนี้ คำบุพบทบอกความสัมพันธ์ เช่นไปด้วยกัน with, ทำให้ for, ส่งถึง to ต้องเรียนคำที่ใช้ร่วมกริยาด้วย\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Come with me. | with + me |\n| This gift is for her. | for + her |\n| I talk to them. | to + them |\n\n### จุดที่มักสับสน\n\nwith I และ for she ผิด แม้ภาษาไทยไม่เปลี่ยนรูปสรรพนาม\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('58f7682b-341e-584d-a9bb-ad039ad4e373'::uuid,'6f28d542-52b6-51b1-a8b0-de7e1baa8150'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/a973fe1669523fda-lesson-09-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Come with me.. This gift is for her.. I talk to them."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('325882f6-51c8-53a3-a2a2-3badeca8e5a0'::uuid,'6f28d542-52b6-51b1-a8b0-de7e1baa8150'::uuid,'multiple_choice',1,'{"question":"This letter is for … (เขาผู้ชาย)","choices":[{"id":"choice_1","text":"he"},{"id":"choice_2","text":"him"},{"id":"choice_3","text":"his"}],"correctChoiceId":"choice_2","explanation":"หลัง for ใช้ object pronoun him"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('32427c7f-96fd-5afc-ac02-8356fab01032'::uuid,'6f28d542-52b6-51b1-a8b0-de7e1baa8150'::uuid,'multiple_choice',1,'{"question":"เลือกวลีที่ถูก","choices":[{"id":"choice_1","text":"with they"},{"id":"choice_2","text":"with their"},{"id":"choice_3","text":"with them"}],"correctChoiceId":"choice_3","explanation":"them เป็น object pronoun หลัง preposition"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('64bd792b-933e-5ae2-a600-9623261d995b'::uuid,'6f28d542-52b6-51b1-a8b0-de7e1baa8150'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนคำชวนด้วย with, ของให้ใครด้วย for และคำพูดถึงใครด้วย to\n\n### ตัวอย่างคำตอบ\n\nCome with us. This book is for you. I talk to her.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **กรรมหลังคำบุพบท** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0d83ff03-9bfb-5937-ab90-3cc11d22d75a'::uuid,'94606932-29c5-518b-a581-c98420adb30e'::uuid,'reading',1,'{"title":"ให้ใครและให้อะไร","body":"## ให้ใครและให้อะไร\n\nกริยา give/show/send ใช้สองกรรมได้: give me a book คือผู้รับ me แล้วสิ่งที่ให้ a book หรือ give a book to me คือสิ่งก่อนแล้วใช้ to บอกผู้รับ ส่วน buy/make ใช้ for ในรูปที่พบบ่อย เช่น buy a gift for her รูปเลือกตามกริยา ไม่เปลี่ยน to/for แบบอิสระทุกคำ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| She gives me a book. | ผู้รับ + สิ่งของ |\n| She gives a book to me. | สิ่งของ + to ผู้รับ |\n| He buys a gift for her. | for ผู้ได้รับประโยชน์ |\n\n### จุดที่มักสับสน\n\nไม่ใช้ give me to a book; ถ้าเปลี่ยนรูปต้องรักษาผู้รับและสิ่งของให้ตรง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f541a23c-8a13-5a7f-a1cc-21d5c7237671'::uuid,'94606932-29c5-518b-a581-c98420adb30e'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/8d446377015ad5ef-lesson-09-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"She gives me a book.. She gives a book to me.. He buys a gift for her."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('70b64b24-b2c9-5a2e-a33d-a2703ae49ff9'::uuid,'94606932-29c5-518b-a581-c98420adb30e'::uuid,'multiple_choice',1,'{"question":"รูปใดเท่ากับ He sends me a letter?","choices":[{"id":"choice_1","text":"He sends a letter to me."},{"id":"choice_2","text":"He sends to a letter me."},{"id":"choice_3","text":"He sends me to a letter."}],"correctChoiceId":"choice_1","explanation":"ย้ายสิ่งของ letter มาก่อนแล้วใช้ to me"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f4c78e3c-e615-5b3f-aebf-1e02f204be10'::uuid,'94606932-29c5-518b-a581-c98420adb30e'::uuid,'multiple_choice',1,'{"question":"He buys a cake … us.","choices":[{"id":"choice_1","text":"to"},{"id":"choice_2","text":"for"},{"id":"choice_3","text":"of"}],"correctChoiceId":"choice_2","explanation":"buy something for someone ใช้ for ผู้ได้รับประโยชน์"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a5e54b15-6efe-5fe8-a398-3058674cc642'::uuid,'94606932-29c5-518b-a581-c98420adb30e'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียน give และ show อย่างละสองรูป แล้วเขียน buy … for …\n\n### ตัวอย่างคำตอบ\n\nI give Ben a pen. I give a pen to Ben. I show her a picture. I show a picture to her. I buy a book for him.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ให้ใครและให้อะไร** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c8b53f97-25c0-5bf2-a3ab-b5242228a708'::uuid,'218e2d72-4adc-5fd1-a49d-65b074465540'::uuid,'reading',1,'{"title":"อ้างกลับโดยไม่พูดชื่อซ้ำ","body":"## อ้างกลับโดยไม่พูดชื่อซ้ำ\n\npronouns ช่วยอ้างกลับโดยไม่พูดชื่อซ้ำ แต่ต้องมีบริบทชัด Mai has a bag. She likes it. She อ้าง Mai; it อ้าง bag ถ้าคำนามหลายชิ้นใช้ they เป็นประธานและ them เป็นกรรม เช่น The books are new. I like them. her อาจเป็นกรรมใน I help her หรือคำเจ้าของใน her bag ให้ดูว่ามี noun ตามหรือไม่\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Ben has two dogs. They are small. He likes them. | They/them อ้าง dogs; He อ้าง Ben |\n| I help her. / Her bag is blue. | her กรรม / her หน้าคำนาม |\n\n### จุดที่มักสับสน\n\nถ้ามีคนหรือสิ่งหลายตัวที่อาจตรง pronoun ใช้ชื่อซ้ำเพื่อไม่ให้คนอ่านเดา\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Personal pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/personal-pronouns) · [Cambridge Dictionary — Verb patterns with and without objects](https://dictionary.cambridge.org/uk/grammar/british-grammar/intransitive-and-transitive-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d785194e-de17-5c1f-a3a7-c2325961caa4'::uuid,'218e2d72-4adc-5fd1-a49d-65b074465540'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/3b4f0c9ff83b2073-lesson-09-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Ben has two dogs. They are small. He likes them.. I help her.. Her bag is blue."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('252a84d3-030e-594f-a58f-9aac12f6081a'::uuid,'218e2d72-4adc-5fd1-a49d-65b074465540'::uuid,'multiple_choice',1,'{"question":"The shoes are new. I like …","choices":[{"id":"choice_1","text":"it"},{"id":"choice_2","text":"they"},{"id":"choice_3","text":"them"}],"correctChoiceId":"choice_3","explanation":"shoes เป็น plural และอยู่ตำแหน่งกรรม ใช้ them"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e7ca148a-1e07-5138-aae6-ce3ab65bda42'::uuid,'218e2d72-4adc-5fd1-a49d-65b074465540'::uuid,'multiple_choice',1,'{"question":"ใน Her phone is new คำ Her ทำหน้าที่ใด?","choices":[{"id":"choice_1","text":"คำบอกเจ้าของหน้าคำนาม"},{"id":"choice_2","text":"ประธานเดี่ยว"},{"id":"choice_3","text":"กริยา"}],"correctChoiceId":"choice_1","explanation":"มี noun phone ตามจึงเป็น possessive determiner"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5ed89043-42fd-58db-a791-b825239259f9'::uuid,'218e2d72-4adc-5fd1-a49d-65b074465540'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนเรื่องสามประโยคที่อ้างคนและสิ่งของให้ชัด\n\n### ตัวอย่างคำตอบ\n\nMai has a book. She reads it every day. Ben has two books. He likes them.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **อ้างกลับโดยไม่พูดชื่อซ้ำ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b80d8855-bf06-5979-a14f-02ab9e51911d'::uuid,'50f1d1fc-36b3-5eb8-adc9-67499954076c'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เลือก I/me และวางผู้รับหรือสิ่งที่ได้รับในประโยคได้**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ประธานกับกรรมใช้คนละรูป: I · he · they; me · him · them; with me · for her](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/00554ad0e619de52-module-09-map.png)\n\n*She helps me.  ↔  I help her.*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('78b5e932-4c0c-5f5d-ad48-242a28c9e8ab'::uuid,'50f1d1fc-36b3-5eb8-adc9-67499954076c'::uuid,'multiple_choice',1,'{"question":"My parents help … (พวกเรา)","choices":[{"id":"choice_1","text":"we"},{"id":"choice_2","text":"us"},{"id":"choice_3","text":"our"}],"correctChoiceId":"choice_2","explanation":"us เป็นกรรม ย้อน 09.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bdea4fab-78d9-5104-aaa0-967d3065d02d'::uuid,'50f1d1fc-36b3-5eb8-adc9-67499954076c'::uuid,'multiple_choice',1,'{"question":"Come with … (พวกเขา)","choices":[{"id":"choice_1","text":"they"},{"id":"choice_2","text":"their"},{"id":"choice_3","text":"them"}],"correctChoiceId":"choice_3","explanation":"หลัง with ใช้ them ย้อน 09.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3605be1f-9417-536f-a215-3ac790e794de'::uuid,'50f1d1fc-36b3-5eb8-adc9-67499954076c'::uuid,'multiple_choice',1,'{"question":"She gives Tom a cup เท่ากับรูปใด?","choices":[{"id":"choice_1","text":"She gives a cup to Tom."},{"id":"choice_2","text":"She gives Tom to a cup."},{"id":"choice_3","text":"She gives for Tom a cup."}],"correctChoiceId":"choice_1","explanation":"สิ่งของ + to + ผู้รับ ย้อน 09.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('69093a87-a97d-5d37-a53b-435ca912c7ee'::uuid,'50f1d1fc-36b3-5eb8-adc9-67499954076c'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเขียนเรื่องคนสองคนและสิ่งของหนึ่งชิ้น โดยใช้ subject/object pronouns และ give สองรูป\n\n### ตัวอย่างผลงาน\n\nMai has a pen. She gives it to Ben. Ben likes it. He gives her a book.\n\n### ตรวจผลงาน\n\n- pronoun อ้างกลับชัด\n- กรรมหลัง verb/preposition ใช้รูป object\n- ลำดับผู้รับและสิ่งของถูก\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e9d862fa-9914-5ef8-a3bb-27b451ae9abe'::uuid,'527d0417-5f62-5edc-a618-13d5557688d9'::uuid,'reading',1,'{"title":"don''t/doesn''t","body":"## don''t/doesn''t\n\nPresent Simple ปฏิเสธกริยาทั่วไปใช้ I/you/we/they + do not/don’t + base verb และ he/she/it + does not/doesn’t + base verb does รับรูปตามประธานแล้วกริยาหลักจึงไม่เติม s ไม่ใช้รูปนี้กับ be: She is not tired.\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I don’t drink coffee. | don’t + base |\n| She doesn’t drink coffee. | doesn’t + base |\n| She isn’t tired. | be ใช้ not ตรงหลัง be |\n\n### จุดที่มักสับสน\n\nShe doesn’t drinks ผิด; ต้องถอด s จากกริยาหลักเมื่อมี does\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ab1b213e-f298-5d13-a744-a274e556a1f5'::uuid,'527d0417-5f62-5edc-a618-13d5557688d9'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/230977b0d36198df-lesson-10-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I don’t drink coffee.. She doesn’t drink coffee.. She isn’t tired."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4bcbf52c-8337-5763-a16f-4fa99bd22f44'::uuid,'527d0417-5f62-5edc-a618-13d5557688d9'::uuid,'multiple_choice',1,'{"question":"Ben … live here.","choices":[{"id":"choice_1","text":"don’t"},{"id":"choice_2","text":"doesn’t"},{"id":"choice_3","text":"isn’t"}],"correctChoiceId":"choice_2","explanation":"live เป็นกริยาทั่วไป; Ben เอกพจน์ใช้ doesn’t"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('72038c42-1533-5e5c-ad9a-0f63472f032e'::uuid,'527d0417-5f62-5edc-a618-13d5557688d9'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคที่ถูก","choices":[{"id":"choice_1","text":"She doesn’t works."},{"id":"choice_2","text":"She doesn’t work."},{"id":"choice_3","text":"She don’t work."}],"correctChoiceId":"choice_2","explanation":"doesn’t + base work"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7eaddfbb-0557-5e57-a869-b0ca323addb3'::uuid,'527d0417-5f62-5edc-a618-13d5557688d9'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสิ่งที่คุณไม่ทำสองข้อ แล้วเขียนเกี่ยวกับเพื่อนสองข้อ\n\n### ตัวอย่างคำตอบ\n\nI don’t drink coffee. I don’t play tennis. Mai doesn’t eat meat. Ben doesn’t live here.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **don''t/doesn''t** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a3c29926-7181-5f8e-af05-7408730d5fc7'::uuid,'c334a8bb-1695-5d61-a5f4-4d3b7fff39fe'::uuid,'reading',1,'{"title":"Do/Does…? และคำตอบสั้น","body":"## Do/Does…? และคำตอบสั้น\n\nถาม yes/no กริยาทั่วไปใช้ Do/Does + subject + base verb? I/you/we/they ใช้ Do; he/she/it ใช้ Does คำตอบสั้นใช้ auxiliary เดิม: Yes, she does. / No, they don’t. คำถาม be ใช้ Is/Are โดยไม่เติม Do: Is she tired?\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Do you like tea? — Yes, I do. | ผู้ตอบใช้ I |\n| Does Ben work here? — No, he doesn’t. | does + work |\n| Is Ben tired? — Yes, he is. | be แยกระบบ |\n\n### จุดที่มักสับสน\n\nDoes he likes? ผิด และคำตอบ Yes, he is ไม่ตรง Does he like…?\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ถามและปฏิเสธกริยาทั่วไป: Does she work?; She doesn’t work.; Yes, she does.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/fa9a79d8915ef635-module-10-map.png)\n\n*หลัง do/does ใช้ base verb  •  be ใช้ Is/Are แยกกัน*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('124502df-38c6-5fc6-a440-555d10530d52'::uuid,'c334a8bb-1695-5d61-a5f4-4d3b7fff39fe'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/19a6c6e357a168a2-lesson-10-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Do you like tea?. Yes, I do.. Does Ben work here?. No, he doesn’t.. Is Ben tired?. Yes, he is."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0d246f8e-c2cc-5ff0-af8a-f2fc5a011192'::uuid,'c334a8bb-1695-5d61-a5f4-4d3b7fff39fe'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามที่ถูก","choices":[{"id":"choice_1","text":"Does Mai study English?"},{"id":"choice_2","text":"Does Mai studies English?"},{"id":"choice_3","text":"Do Mai study English?"}],"correctChoiceId":"choice_1","explanation":"Mai ใช้ Does ตามด้วย base study"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6065d2f4-8f0a-5b45-afdb-53030e8f7201'::uuid,'c334a8bb-1695-5d61-a5f4-4d3b7fff39fe'::uuid,'multiple_choice',1,'{"question":"Do they live here? คำตอบสั้นปฏิเสธคืออะไร?","choices":[{"id":"choice_1","text":"No, they aren’t."},{"id":"choice_2","text":"No, they don’t."},{"id":"choice_3","text":"No, they doesn’t."}],"correctChoiceId":"choice_2","explanation":"คำถาม Do ตอบด้วย don’t"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('976f30cb-ba10-5a25-abbb-2394cc5ad114'::uuid,'c334a8bb-1695-5d61-a5f4-4d3b7fff39fe'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nถามกิจวัตรสามคำถามและตอบทั้งบอกเล่ากับปฏิเสธ\n\n### ตัวอย่างคำตอบ\n\nDo you drink tea? Yes, I do. Does Mai play tennis? No, she doesn’t. Do your friends study here? Yes, they do.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Do/Does…? และคำตอบสั้น** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c226fcf4-2f73-5429-a516-c10268ba32cc'::uuid,'ce6b45e3-3e9d-586e-ac87-1b4cddfd9205'::uuid,'reading',1,'{"title":"Wh-questions","body":"## Wh-questions\n\nWh-question กริยาทั่วไปใช้คำถาม + do/does + subject + base verb เช่น Where do you live? When does Ben work? what ถามสิ่ง; who คน; where ที่; when เวลา; why เหตุผล; how วิธี คำผสม What time ถามเวลาเฉพาะ What kind of ถามชนิด Why ตอบด้วย because ตามเหตุผล\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Where do you live? — In Bangkok. | ถามที่ |\n| What time does she start? — At nine. | เวลาเฉพาะ |\n| Why do you study English? — Because I like it. | เหตุผล |\n\n### จุดที่มักสับสน\n\nอย่าใช้ Where you live? ในรูปคำถามพื้นฐานที่กำลังฝึก ต้องมี do\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('26568965-bd82-56eb-a9f4-8ea1a5547db6'::uuid,'ce6b45e3-3e9d-586e-ac87-1b4cddfd9205'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9b6f9f96a6d07d21-lesson-10-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Where do you live?. In Bangkok.. What time does she start?. At nine.. Why do you study English?. Because I like it."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c0d322c1-2dcf-56b1-ad4e-3d000e6842c9'::uuid,'ce6b45e3-3e9d-586e-ac87-1b4cddfd9205'::uuid,'multiple_choice',1,'{"question":"ถามเหตุผลที่เขาเรียนภาษาอังกฤษ เลือก","choices":[{"id":"choice_1","text":"Why does he study English?"},{"id":"choice_2","text":"Where does he study English?"},{"id":"choice_3","text":"Who studies English?"}],"correctChoiceId":"choice_1","explanation":"Why ถามเหตุผล และ he ใช้ does + study"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('42386b89-9014-53b9-a6dc-2b6c6a4b708d'::uuid,'ce6b45e3-3e9d-586e-ac87-1b4cddfd9205'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามเวลาเริ่มงาน","choices":[{"id":"choice_1","text":"What time do you start work?"},{"id":"choice_2","text":"What kind of do you work?"},{"id":"choice_3","text":"What you time start?"}],"correctChoiceId":"choice_1","explanation":"What time + do + subject + base verb"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4ce84499-8da7-5159-a26a-7bf690362e21'::uuid,'ce6b45e3-3e9d-586e-ac87-1b4cddfd9205'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nถามและตอบสถานที่ เวลาและเหตุผลจากชีวิตของคุณ\n\n### ตัวอย่างคำตอบ\n\nWhere do you live? In Chiang Mai. What time do you study? At eight. Why do you study? Because I like English.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Wh-questions** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('71baf3c0-f025-59fc-a7ec-74e060eee0a3'::uuid,'2a101aac-8cd8-54f0-ac8c-492b1475412c'::uuid,'reading',1,'{"title":"what/which/whose","body":"## what/which/whose\n\nwhat ถามสิ่งหรือข้อมูลทั่วไป; which ถามตัวเลือกจากชุดที่มีอยู่; whose ถามเจ้าของ เช่น What book do you like? อาจถามกว้าง ส่วน Which book do you want, this one or that one? มีตัวเลือกชัด Whose book is this? ถามเจ้าของและใช้ be ตามโครงประโยค ไม่เติม do โดยอัตโนมัติ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| What music do you like? | ถามชนิดหรือสิ่งทั่วไป |\n| Which cup do you want, red or blue? | ถามเลือกจากชุด |\n| Whose cup is this? | ถามเจ้าของ |\n\n### จุดที่มักสับสน\n\nเลือกคำถามจากข้อมูลที่ต้องการ ไม่แปล which เป็นคำว่าที่ทุกกรณี\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ac48a0b1-bfc3-5697-aa60-a3260a44a99f'::uuid,'2a101aac-8cd8-54f0-ac8c-492b1475412c'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/796e5f7c011d02a9-lesson-10-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"What music do you like?. Which cup do you want, red or blue?. Whose cup is this?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e974c302-e23d-5f02-a108-aacd06950a44'::uuid,'2a101aac-8cd8-54f0-ac8c-492b1475412c'::uuid,'multiple_choice',1,'{"question":"มีเสื้อสองตัวให้เลือก คำถามเหมาะที่สุดคืออะไร?","choices":[{"id":"choice_1","text":"Which shirt do you want?"},{"id":"choice_2","text":"Whose shirt do you want?"},{"id":"choice_3","text":"Where shirt do you want?"}],"correctChoiceId":"choice_1","explanation":"which เลือกจากตัวเลือกที่ระบุ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('191f904d-5f6b-5d68-a704-96f0d982bed1'::uuid,'2a101aac-8cd8-54f0-ac8c-492b1475412c'::uuid,'multiple_choice',1,'{"question":"ต้องการรู้เจ้าของโทรศัพท์ ใช้คำใด?","choices":[{"id":"choice_1","text":"What colour"},{"id":"choice_2","text":"Whose"},{"id":"choice_3","text":"When"}],"correctChoiceId":"choice_2","explanation":"Whose ถามเป็นของใคร"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('78c98565-18e1-5a46-a15a-fce7dad84eee'::uuid,'2a101aac-8cd8-54f0-ac8c-492b1475412c'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนคำถาม what/which/whose อย่างละหนึ่ง พร้อมตอบ\n\n### ตัวอย่างคำตอบ\n\nWhat food do you like? Rice. Which bag do you want, this one or that one? This one. Whose phone is this? It is Ben’s.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **what/which/whose** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bb3c20df-907a-5277-aa92-b4f38812a361'::uuid,'6ad04929-4427-5bcd-acf0-09c357d300f2'::uuid,'reading',1,'{"title":"ถามประธานกับถามกรรม","body":"## ถามประธานกับถามกรรม\n\nถ้าถามว่าใครเป็นผู้ทำ ใช้ Who + verb โดยไม่เติม do ในรูปบอกเล่าพื้นฐาน: Who works here? เพราะ Who เป็นประธาน แต่ถ้าถามว่าคุณช่วยใคร Who เป็นกรรม จึงใช้ Who do you help? คำตอบช่วยตรวจหน้าที่: Mai works here. / I help Mai.\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Who helps Ben? — Mai helps Ben. | Who เป็นประธาน |\n| Who do you help? — I help Ben. | Who เป็นกรรม |\n| What happens? | What เป็นประธาน |\n\n### จุดที่มักสับสน\n\nไม่ใช้ Who does works here? และไม่ตัด do จากคำถามกรรมโดยอัตโนมัติ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('316bea4e-31d6-5a4b-a8f3-1eead55d4e19'::uuid,'6ad04929-4427-5bcd-acf0-09c357d300f2'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/c532f02f1eb9e670-lesson-10-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Who helps Ben?. Mai helps Ben.. Who do you help?. I help Ben.. What happens?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1430b0cd-582f-5c78-ab03-266578bf6775'::uuid,'6ad04929-4427-5bcd-acf0-09c357d300f2'::uuid,'multiple_choice',1,'{"question":"คำถามที่ตอบว่า Mai lives here คืออะไร?","choices":[{"id":"choice_1","text":"Who lives here?"},{"id":"choice_2","text":"Who does lives here?"},{"id":"choice_3","text":"Who do live here?"}],"correctChoiceId":"choice_1","explanation":"Who แทนผู้ทำ lives จึงเป็น subject question"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0f41781a-3dc7-52c9-a77e-7b5d2d92ee33'::uuid,'6ad04929-4427-5bcd-acf0-09c357d300f2'::uuid,'multiple_choice',1,'{"question":"คำถามที่ตอบว่า I know Ben คืออะไร?","choices":[{"id":"choice_1","text":"Who knows you?"},{"id":"choice_2","text":"Who do you know?"},{"id":"choice_3","text":"Who know?"}],"correctChoiceId":"choice_2","explanation":"ถามกรรม Ben; ประธาน you ยังอยู่ จึงใช้ do"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0e3fb758-33e9-5433-aa16-1cebcbfd5a01'::uuid,'6ad04929-4427-5bcd-acf0-09c357d300f2'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนคำถามประธานและกรรมเกี่ยวกับ help อย่างละหนึ่ง แล้วตอบ\n\n### ตัวอย่างคำตอบ\n\nWho helps Mai? Ben helps Mai. Who does Mai help? Mai helps her brother.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ถามประธานกับถามกรรม** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('efa1fb36-3410-5cb2-ac45-78f55022dfdc'::uuid,'df18597d-fd9c-5d6d-af07-5322a91c81ed'::uuid,'reading',1,'{"title":"ถามต่อและตรวจความเข้าใจ","body":"## ถามต่อและตรวจความเข้าใจ\n\nHow…? ขอวิธีหรือสภาพ ส่วน What is … like? ขอคำบรรยาย ใช้คำถามต่อให้บทสนทนาไปได้ เช่น Who do you work with? preposition with อยู่ท้ายในภาษาทั่วไป คำถามสะท้อน Do you? / Does she? แสดงสนใจหรือขอให้เล่าต่อ ใช้ auxiliary ให้ตรงกริยาของประโยคที่ได้ยิน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| How do you go to work? — By bus. | วิธีเดินทาง |\n| Who do you study with? — With Ben. | with ท้ายคำถาม |\n| I work in a shop. — Do you? | ถามต่อด้วย do |\n\n### จุดที่มักสับสน\n\nWhat is she like? ถามลักษณะ; What does she like? ถามความชอบ เป็นคนละข้อมูล\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f24a6414-609d-5458-a7ac-86b6ab2ad60e'::uuid,'df18597d-fd9c-5d6d-af07-5322a91c81ed'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/14426ffc10858364-lesson-10-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"How do you go to work?. By bus.. Who do you study with?. With Ben.. I work in a shop.. Do you?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1067da0b-a8ec-5b9a-ac21-99d78ddcee3b'::uuid,'df18597d-fd9c-5d6d-af07-5322a91c81ed'::uuid,'multiple_choice',1,'{"question":"I like jazz. คำถามสะท้อนที่ตรง auxiliary คืออะไร?","choices":[{"id":"choice_1","text":"Do you?"},{"id":"choice_2","text":"Are you?"},{"id":"choice_3","text":"Does you?"}],"correctChoiceId":"choice_1","explanation":"like เป็นกริยาทั่วไปกับ I ใช้คำถามต่อ Do you?"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('102a827a-6b38-5b8c-a91f-8c993b7ff891'::uuid,'df18597d-fd9c-5d6d-af07-5322a91c81ed'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามที่ถูก","choices":[{"id":"choice_1","text":"Who do you work with?"},{"id":"choice_2","text":"Who with you work?"},{"id":"choice_3","text":"Who does you work with?"}],"correctChoiceId":"choice_1","explanation":"Who + do + you + work + with"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('39496b02-377b-53ce-af89-96302785b072'::uuid,'df18597d-fd9c-5d6d-af07-5322a91c81ed'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nสร้างบทสนทนาสี่บรรทัดที่ตอบแล้วถามต่อด้วย How หรือ Who … with\n\n### ตัวอย่างคำตอบ\n\nI study English. — Do you? Who do you study with? — With Mai. — How do you study? — We read books.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ถามต่อและตรวจความเข้าใจ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ac4b09b2-8cb7-56c5-ade9-adf24593563a'::uuid,'b838c4d7-e559-51be-abf5-6cabd404ff98'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เปลี่ยนประโยคกริยาทั่วไปเป็นปฏิเสธและคำถามได้**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ถามและปฏิเสธกริยาทั่วไป: Does she work?; She doesn’t work.; Yes, she does.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/fa9a79d8915ef635-module-10-map.png)\n\n*หลัง do/does ใช้ base verb  •  be ใช้ Is/Are แยกกัน*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4a53b026-98e3-5079-ab50-f704666103ac'::uuid,'b838c4d7-e559-51be-abf5-6cabd404ff98'::uuid,'multiple_choice',1,'{"question":"The nurse … work on Sundays.","choices":[{"id":"choice_1","text":"don’t"},{"id":"choice_2","text":"doesn’t"},{"id":"choice_3","text":"isn’t"}],"correctChoiceId":"choice_2","explanation":"nurse หนึ่งคนกับ verb work ใช้ doesn’t ย้อน 10.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d6add352-6c33-597f-a80b-223dde722726'::uuid,'b838c4d7-e559-51be-abf5-6cabd404ff98'::uuid,'multiple_choice',1,'{"question":"ถามผู้ทำใน People work here ใช้รูปใด?","choices":[{"id":"choice_1","text":"Who works here?"},{"id":"choice_2","text":"Who does works here?"},{"id":"choice_3","text":"Who do works here?"}],"correctChoiceId":"choice_1","explanation":"Who เป็น subject ไม่เติม do ย้อน 10.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('044b5504-8e7a-5501-a464-f229d2bab243'::uuid,'b838c4d7-e559-51be-abf5-6cabd404ff98'::uuid,'multiple_choice',1,'{"question":"Where … your friends live?","choices":[{"id":"choice_1","text":"do"},{"id":"choice_2","text":"does"},{"id":"choice_3","text":"are"}],"correctChoiceId":"choice_1","explanation":"friends หลายคนกับ live ใช้ do ย้อน 10.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f4638656-0719-51f7-aebb-97ddb2e6e4b0'::uuid,'b838c4d7-e559-51be-abf5-6cabd404ff98'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nสัมภาษณ์เพื่อนด้วย yes/no สองข้อและ Wh สองข้อ จากนั้นสรุปข้อมูลเป็นสามประโยค\n\n### ตัวอย่างผลงาน\n\nDo you like tea? Yes, I do. Do you play tennis? No, I don’t. Where do you live? In Bangkok. What do you study? English. Ben likes tea. He doesn’t play tennis. He studies English.\n\n### ตรวจผลงาน\n\n- เลือก do/does ตรงประธาน\n- หลัง do/does ใช้ base\n- เลือกคำถามตรงข้อมูลและสรุปด้วย s-form ถูก\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('da940dab-e036-56d9-a41f-09abf1f363a9'::uuid,'a76a15f7-7522-5c49-aa64-6f4444f34ea7'::uuid,'reading',1,'{"title":"แสดงสิ่งที่ทำได้","body":"## งานปิดคอร์ส 1\n\n**สร้างประโยคบอกเล่า ปฏิเสธ และคำถามเกี่ยวกับตัวเองหรือกิจวัตรได้**\n\nทำข้อทดสอบใหม่ต่อไปนี้ แล้วทำงานอ่าน/พูด/เขียนตามโจทย์ ใช้ feedback เพื่อเลือกทบทวน ไม่ใช้จำนวน block ที่อ่านเป็นหลักฐานว่าคุณใช้ภาษาได้แล้ว","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('77e6cea6-3c4a-5c3c-a3a7-5bb402fe5242'::uuid,'a76a15f7-7522-5c49-aa64-6f4444f34ea7'::uuid,'multiple_choice',1,'{"question":"A new student says: I … from Thailand.","choices":[{"id":"choice_1","text":"am"},{"id":"choice_2","text":"is"},{"id":"choice_3","text":"are"}],"correctChoiceId":"choice_1","explanation":"I ใช้ am: M04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('12b86005-65f2-51aa-a78b-c8366f95c3d3'::uuid,'a76a15f7-7522-5c49-aa64-6f4444f34ea7'::uuid,'multiple_choice',1,'{"question":"You see one apple for the first time: I have … apple.","choices":[{"id":"choice_1","text":"a"},{"id":"choice_2","text":"an"},{"id":"choice_3","text":"the เท่านั้น"}],"correctChoiceId":"choice_2","explanation":"apple เสียงสระและกล่าวครั้งแรก: M05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('96ee3388-43cb-5b99-a715-0e2382b99b9a'::uuid,'a76a15f7-7522-5c49-aa64-6f4444f34ea7'::uuid,'multiple_choice',1,'{"question":"The two … are teachers.","choices":[{"id":"choice_1","text":"man"},{"id":"choice_2","text":"men"},{"id":"choice_3","text":"mans"}],"correctChoiceId":"choice_2","explanation":"man → men: M03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('645e22b8-a377-5056-a669-c8a3f8fbc5bd'::uuid,'a76a15f7-7522-5c49-aa64-6f4444f34ea7'::uuid,'multiple_choice',1,'{"question":"Sara … English every day.","choices":[{"id":"choice_1","text":"study"},{"id":"choice_2","text":"studies"},{"id":"choice_3","text":"is study"}],"correctChoiceId":"choice_2","explanation":"Sara เอกพจน์ใช้ studies: M08"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('90cfe9ba-198a-5d46-a16f-7247d1f3369f'::uuid,'a76a15f7-7522-5c49-aa64-6f4444f34ea7'::uuid,'multiple_choice',1,'{"question":"Does your brother like music? — No, …","choices":[{"id":"choice_1","text":"he isn’t"},{"id":"choice_2","text":"he don’t"},{"id":"choice_3","text":"he doesn’t"}],"correctChoiceId":"choice_3","explanation":"ตอบ Does ด้วย doesn’t: M10"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,6) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6d31f6e4-bf68-513f-a918-5f0fad66bf69'::uuid,'a76a15f7-7522-5c49-aa64-6f4444f34ea7'::uuid,'multiple_choice',1,'{"question":"I work with Anna. I work with …","choices":[{"id":"choice_1","text":"she"},{"id":"choice_2","text":"her"},{"id":"choice_3","text":"hers"}],"correctChoiceId":"choice_2","explanation":"หลัง with ใช้กรรม her: M09"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,7) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cd37bfbf-4539-5f6e-a8d3-0e619a33d203'::uuid,'a76a15f7-7522-5c49-aa64-6f4444f34ea7'::uuid,'reading',1,'{"title":"ผลงานปิดคอร์ส","body":"แนะนำตัว 5–6 ประโยค บอกคนใกล้ตัวกับสิ่งของและกิจวัตร จากนั้นตั้งคำถามให้คนอื่นตอบ 4 ข้อ โดยมี be และ do/does ทั้งสองแบบ\n\n### ตัวอย่างผลงาน\n\nI am Mai. I am Thai. I am a student. My sister is a teacher. She reads books. I study English. Are you a student? Where are you from? Do you like books? What do you study?\n\n### เกณฑ์ตรวจ\n\n- ข้อมูลครบและคนอ่านเข้าใจว่าใครเป็นใคร\n- เลือก pronouns, be, articles และ plural ถูก\n- เลือก verb s-form ตาม subject\n- ถามและปฏิเสธด้วย be/do/does ไม่ปนกัน\n- อ่านออกเสียงแล้วแก้คำที่ทำให้ผู้ฟังไม่เข้าใจ\n\nให้ตนเองหรือครูตรวจงาน ระบบตรวจอัตโนมัติเฉพาะข้อเลือกตอบ แล้วทบทวนจุดที่ยังไม่มั่นใจเป็นระยะ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,8) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('38a083c3-e710-58f3-a1eb-5b21d625aacb'::uuid,'e58d1cb9-71dc-5ad8-a596-9ccf0fb82214'::uuid,'reading',1,'{"title":"จำนวนและตัวเลขหลายหลัก","body":"## จำนวนและตัวเลขหลายหลัก\n\nตัวเลข cardinal บอกจำนวน one/two/three หลักสิบ twenty/thirty ตามด้วยหลักหน่วย เช่น twenty-one หลักร้อยใช้ hundred และหลักพัน thousand รูป one hundred/two hundred ไม่เติม s เมื่อมีเลขกำหนด แยกจำนวน 203 ที่อ่านเป็น two hundred and three จากหมายเลขห้องหรือโทรศัพท์ที่อาจอ่านทีละหลัก ฟัง stress ของ thirteen กับ thirty ด้วย\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| 13 / 30 | thirteen / thirty |\n| 203 | two hundred and three แบบ British English |\n| Room 203 | room two oh three ตามบริบทหมายเลข |\n\n### จุดที่มักสับสน\n\nzero อ่าน oh ได้ในหมายเลขบางบริบท ไม่ใช้ oh แทนจำนวนศูนย์ทุกบริบท\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('534b9daa-34b6-5453-afa6-a89bef283424'::uuid,'e58d1cb9-71dc-5ad8-a596-9ccf0fb82214'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/ad39567d3f2bd608-lesson-11-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"13. 30. 203. Room 203"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2c677c10-0aa3-5a77-a45b-3a3b47b66831'::uuid,'e58d1cb9-71dc-5ad8-a596-9ccf0fb82214'::uuid,'multiple_choice',1,'{"question":" forty-two คือจำนวนใด?","choices":[{"id":"choice_1","text":"24"},{"id":"choice_2","text":"42"},{"id":"choice_3","text":"40"}],"correctChoiceId":"choice_2","explanation":"forty คือ 40 และ two คือ 2"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a9f9d53b-2cc1-547c-a69b-cae18c88561f'::uuid,'e58d1cb9-71dc-5ad8-a596-9ccf0fb82214'::uuid,'multiple_choice',1,'{"question":"เลือกรูปจำนวนที่ถูก","choices":[{"id":"choice_1","text":"two hundreds people"},{"id":"choice_2","text":"two hundred people"},{"id":"choice_3","text":"two hundred of people"}],"correctChoiceId":"choice_2","explanation":"hundred ไม่เติม s เมื่อมีเลขกำหนด"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0173fe0a-c52e-5b44-a6f3-85b5e9db4f90'::uuid,'e58d1cb9-71dc-5ad8-a596-9ccf0fb82214'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนอายุ ราคาและหมายเลขสมมติอย่างละหนึ่ง แยกการอ่านจำนวนกับหมายเลข\n\n### ตัวอย่างคำตอบ\n\nAge: twenty-one. Price: two hundred baht. Room: two oh five.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **จำนวนและตัวเลขหลายหลัก** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8e0f9f25-cd9a-51ea-a188-f98bd8432745'::uuid,'8f718736-5377-5398-a5df-90b290f5eb69'::uuid,'reading',1,'{"title":"ลำดับและวันที่","body":"## ลำดับและวันที่\n\nordinal บอกลำดับ first/second/third แล้วรูปทั่วไปลง th เช่น fourth; ยี่สิบเอ็ดใช้ twenty-first วันที่เขียนได้ 4 October หรือ October 4 อ่าน the fourth of October / October fourth วันและเดือนใช้ตัวใหญ่ วันที่ตัวเลข 04/10 อาจหมายถึง 4 October หรือ April 10 ตามประเทศ จึงเขียนชื่อเดือนเมื่อต้องการความชัดเจน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| 1st / 2nd / 3rd | first / second / third |\n| 21st | twenty-first |\n| 4 October 2026 | วันที่ 4 ตุลาคม 2026 |\n\n### จุดที่มักสับสน\n\nลำดับ 21st ไม่ใช่ 21th และวันที่ตัวเลขต้องถาม format ถ้าไม่ชัด\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3cc144c4-e644-5711-a402-d91b7741e319'::uuid,'8f718736-5377-5398-a5df-90b290f5eb69'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/fb0d211ad8b3c792-lesson-11-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"1st. 2nd. 3rd. 21st. 4 October 2026"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0364d063-d548-5b81-a15d-199ba5adcacd'::uuid,'8f718736-5377-5398-a5df-90b290f5eb69'::uuid,'multiple_choice',1,'{"question":"ลำดับที่สามใช้คำใด?","choices":[{"id":"choice_1","text":"three"},{"id":"choice_2","text":"third"},{"id":"choice_3","text":"threeth"}],"correctChoiceId":"choice_2","explanation":"third เป็น ordinal ของ three"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('050fe07d-b60e-56c5-a542-f4d3b5bda874'::uuid,'8f718736-5377-5398-a5df-90b290f5eb69'::uuid,'multiple_choice',1,'{"question":"วันที่แบบใดลดความกำกวมมากที่สุด?","choices":[{"id":"choice_1","text":"04/10"},{"id":"choice_2","text":"10/04"},{"id":"choice_3","text":"4 October"}],"correctChoiceId":"choice_3","explanation":"ชื่อเดือนชัดเจน ต่างจากการเรียงตัวเลขที่ต่างประเทศต่างกัน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ebc7958a-b099-5a95-a8f8-d3dd2807e5a6'::uuid,'8f718736-5377-5398-a5df-90b290f5eb69'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนวันเกิดสมมติและลำดับของคุณในแถว พร้อมอ่านออกเสียง\n\n### ตัวอย่างคำตอบ\n\nMy birthday is on 12 May. I am the twenty-first person in the line.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ลำดับและวันที่** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('eedb360d-ce68-5580-a7a9-74d9d1476365'::uuid,'e1fba245-591e-5acd-ac23-e3fbd8ec7ac1'::uuid,'reading',1,'{"title":"เวลาในนาฬิกา","body":"## เวลาในนาฬิกา\n\nบอกเวลาได้แบบชั่วโมง–นาที เช่น six thirty หรือ half past six; quarter past คือผ่านชั่วโมงมา 15 นาที และ quarter to คืออีก 15 นาทีถึงชั่วโมงถัดไป o’clock ใช้ชั่วโมงเต็ม a.m. ก่อนเที่ยงและ p.m. หลังเที่ยง ระวัง 12 a.m. คือเที่ยงคืนและ 12 p.m. คือเที่ยงวัน ใช้ noon/midnight ช่วยลดความสับสน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| 6:30 | six thirty / half past six |\n| 6:45 | six forty-five / quarter to seven |\n| 9:00 | nine o’clock |\n\n### จุดที่มักสับสน\n\nquarter to seven คือ 6:45 ไม่ใช่ 7:15 และไม่ต้องเติม o’clock หลังเวลาแสดงนาที\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9a15a724-e654-55ae-a87e-32c6040f9165'::uuid,'e1fba245-591e-5acd-ac23-e3fbd8ec7ac1'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9d4e4e7f9fe473c9-lesson-11-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"6:30. 6:45. 9:00"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('49329ddc-eb2f-5ef3-ad15-39941ee0e355'::uuid,'e1fba245-591e-5acd-ac23-e3fbd8ec7ac1'::uuid,'multiple_choice',1,'{"question":"half past eight คือเวลาใด?","choices":[{"id":"choice_1","text":"8:30"},{"id":"choice_2","text":"8:15"},{"id":"choice_3","text":"7:30"}],"correctChoiceId":"choice_1","explanation":"half past ผ่านชั่วโมงนั้นครึ่งชั่วโมง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4eb57eaa-d6d4-56bd-a70d-15a5f26cd675'::uuid,'e1fba245-591e-5acd-ac23-e3fbd8ec7ac1'::uuid,'multiple_choice',1,'{"question":"quarter to ten คือเวลาใด?","choices":[{"id":"choice_1","text":"10:15"},{"id":"choice_2","text":"9:45"},{"id":"choice_3","text":"10:45"}],"correctChoiceId":"choice_2","explanation":"อีก 15 นาทีถึงสิบโมง คือ 9:45"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6b6b714b-27ac-57c4-acfb-74373ad3b072'::uuid,'e1fba245-591e-5acd-ac23-e3fbd8ec7ac1'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกเวลาตื่น เริ่มเรียนและกลับบ้านคนละสองรูป แล้วระบุ a.m./p.m.\n\n### ตัวอย่างคำตอบ\n\nI get up at six thirty a.m., or half past six. Class starts at nine o’clock a.m. I go home at quarter to five p.m.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เวลาในนาฬิกา** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('12262b67-3703-5298-ad5c-604fb839707d'::uuid,'07e43c3d-77db-5d9c-ab80-e4f965b99f1a'::uuid,'reading',1,'{"title":"ราคา เงิน และการคำนวณง่าย","body":"## ราคา เงิน และการคำนวณง่าย\n\nราคาใช้จำนวนตามด้วยหน่วยเงิน เช่น forty baht หรือ two dollars and fifty cents ส่วน number decimal อ่าน point และเลขหลังจุดทีละหลัก เช่น 2.5 two point five ราคาในบริบทอาจย่อเป็น two fifty จึงต้องรู้หน่วย คำถาม How much does it cost? ใช้ does + cost รูปพื้นฐาน เงินทอนคำนวณจากเงินจ่ายลบราคา\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| 40 baht | สี่สิบบาท |\n| $2.50 | two dollars and fifty cents |\n| 50 − 35 = 15 | จ่าย 50 ราคา 35 ทอน 15 |\n\n### จุดที่มักสับสน\n\nไม่เติม s ให้ baht ในรูปจำนวนภาษาอังกฤษที่ใช้ทั่วไป แต่ dollars มี plural\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('eddd359b-30d3-525b-a463-0295758aa0ff'::uuid,'07e43c3d-77db-5d9c-ab80-e4f965b99f1a'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/a0df498a7e47f6c5-lesson-11-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"40 baht. $2.50. 50 − 35 = 15"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3967a1d6-5d15-56f6-a79d-c2d776debb1d'::uuid,'07e43c3d-77db-5d9c-ab80-e4f965b99f1a'::uuid,'multiple_choice',1,'{"question":"ซื้อของ 35 baht จ่าย 50 baht เงินทอนเท่าไร?","choices":[{"id":"choice_1","text":"15 baht"},{"id":"choice_2","text":"25 baht"},{"id":"choice_3","text":"85 baht"}],"correctChoiceId":"choice_1","explanation":"50−35=15"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b620f246-b93c-50ff-a793-aea692ac82b7'::uuid,'07e43c3d-77db-5d9c-ab80-e4f965b99f1a'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามราคาที่ถูก","choices":[{"id":"choice_1","text":"How much does it costs?"},{"id":"choice_2","text":"How much does it cost?"},{"id":"choice_3","text":"How many does it cost?"}],"correctChoiceId":"choice_2","explanation":"much ถามราคาและหลัง does ใช้ cost"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d7b04daa-1d22-5d0d-ace2-5187b0393505'::uuid,'07e43c3d-77db-5d9c-ab80-e4f965b99f1a'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nทำรายการสินค้าสามชิ้นพร้อมราคาและเงินทอนหนึ่งรายการ\n\n### ตัวอย่างคำตอบ\n\nA pen costs 20 baht. A book costs 80 baht. A cup costs 50 baht. I pay 100 baht for the book and get 20 baht change.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ราคา เงิน และการคำนวณง่าย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4803a028-0bd4-5c1c-ab69-16bd17afcc30'::uuid,'eeaadf7a-d478-50a0-ad97-b108387bf0dc'::uuid,'reading',1,'{"title":"หน่วยวัดและส่วนของจำนวน","body":"## หน่วยวัดและส่วนของจำนวน\n\nหน่วยวัดช่วยให้ตัวเลขมีความหมาย เช่น two metres, three kilograms, twenty degrees Celsius รูปทั่วไปเติม plural เมื่อจำนวนเกินหนึ่ง สัญลักษณ์ m/kg/°C คงรูป half หมายถึงครึ่ง a quarter หมายถึงหนึ่งในสี่ และ percent หมายถึงต่อร้อย fifty percent คือครึ่งหนึ่ง ระบุสิ่งที่วัดและหน่วยให้ชัด\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| 2 kg | two kilograms |\n| 1/2 / 1/4 | a half / a quarter |\n| 25% | twenty-five percent |\n\n### จุดที่มักสับสน\n\nไม่ใช้ตัวเลขโดดโดยไม่บอกหน่วยเมื่อผู้ฟังยังไม่รู้ เช่นน้ำหนัก 2 ต้องบอก kilograms หรือหน่วยอื่น\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e6dcbbc2-8ede-50a7-a7f9-500f95e38512'::uuid,'eeaadf7a-d478-50a0-ad97-b108387bf0dc'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/8132002aef7df85d-lesson-11-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"2 kg. 1/2. 1/4. 25%"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('25dbda63-525a-58ae-aefc-7e0e6a1861ff'::uuid,'eeaadf7a-d478-50a0-ad97-b108387bf0dc'::uuid,'multiple_choice',1,'{"question":"a quarter เท่ากับส่วนใด?","choices":[{"id":"choice_1","text":"1/2"},{"id":"choice_2","text":"1/4"},{"id":"choice_3","text":"3/4"}],"correctChoiceId":"choice_2","explanation":"quarter คือหนึ่งในสี่"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c0af44fa-34a0-5a5c-aa0c-24d01cdbc10d'::uuid,'eeaadf7a-d478-50a0-ad97-b108387bf0dc'::uuid,'multiple_choice',1,'{"question":"50 percent เทียบกับส่วนใด?","choices":[{"id":"choice_1","text":"ครึ่งหนึ่ง"},{"id":"choice_2","text":"ทั้งหมด"},{"id":"choice_3","text":"หนึ่งในสิบ"}],"correctChoiceId":"choice_1","explanation":"50 ต่อ100เท่ากับครึ่งหนึ่ง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bb6c3cf3-6f49-5454-ac3a-e34e570b4af7'::uuid,'eeaadf7a-d478-50a0-ad97-b108387bf0dc'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกน้ำหนัก ความยาวและอุณหภูมิสมมติ แล้วอธิบาย half และ quarter\n\n### ตัวอย่างคำตอบ\n\nThe bag weighs two kilograms. The table is one metre long. It is thirty degrees Celsius. Half a litre is 0.5 litres; a quarter is 0.25.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **หน่วยวัดและส่วนของจำนวน** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3dd22dfd-b6c5-5cc5-ae56-88ff8277d3cd'::uuid,'011447a1-ff71-5090-a471-97aec7c43f8a'::uuid,'reading',1,'{"title":"in/on/at กับเวลา","body":"## in/on/at กับเวลา\n\nใช้ in กับเดือน ปีและช่วงวัน เช่น in May/in 2026/in the morning; on กับวันหรือวันที่ เช่น on Monday/on 4 October; at กับเวลาเฉพาะ เช่น at nine/at night มีวลีที่ต้องเรียนตามการใช้ ไม่เติม preposition หน้า every/next/last เช่น every day, next week, last year\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| in the morning / at night | วลีช่วงวันต่างกัน |\n| on Friday / on 12 May | วันและวันที่ |\n| at 8:30 | เวลานาฬิกา |\n\n### จุดที่มักสับสน\n\nin Monday และ on eight o’clock ผิดในรูปนี้; next Monday ไม่ใช้ on ข้างหน้าในรูปทั่วไป\n\n\n\n### ดูภาพแล้วลองใช้\n\n![เลือกบุพบทตามชนิดเวลา: in October; on Monday; at 7:30](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d68b85cf74783387-module-11-map.png)\n\n*every day / next week / last year ไม่เติม preposition ในรูปทั่วไป*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ff1bd3b8-78af-532e-a7bd-4250147a051d'::uuid,'011447a1-ff71-5090-a471-97aec7c43f8a'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/ae2906300dc4fec8-lesson-11-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"in the morning. at night. on Friday. on 12 May. at 8:30"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ce350536-03c6-5e2e-a125-b4b708f5f826'::uuid,'011447a1-ff71-5090-a471-97aec7c43f8a'::uuid,'multiple_choice',1,'{"question":"The class starts … ten o’clock.","choices":[{"id":"choice_1","text":"in"},{"id":"choice_2","text":"on"},{"id":"choice_3","text":"at"}],"correctChoiceId":"choice_3","explanation":"เวลาเฉพาะใช้ at"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e59902a3-568f-55f0-a9e7-95ab430b3a49'::uuid,'011447a1-ff71-5090-a471-97aec7c43f8a'::uuid,'multiple_choice',1,'{"question":"เลือกวลีที่ถูก","choices":[{"id":"choice_1","text":"on next week"},{"id":"choice_2","text":"in every day"},{"id":"choice_3","text":"next week"}],"correctChoiceId":"choice_3","explanation":"next/every/last ไม่ต้องมี preposition ในวลีเวลาเหล่านี้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a13e6c4c-d04d-5276-afe3-c0ee41457b48'::uuid,'011447a1-ff71-5090-a471-97aec7c43f8a'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนตารางของคุณสามประโยค ใช้ in/on/at และหนึ่งประโยค every/next\n\n### ตัวอย่างคำตอบ\n\nI study in the evening. I work on Monday. I eat at seven. I study every day.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **in/on/at กับเวลา** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6648386c-ce19-5ff6-a7c9-4ec7142e175d'::uuid,'d6a6bcbc-2865-5844-a0a9-b80ca9c6326b'::uuid,'reading',1,'{"title":"ก่อน หลัง และช่วงเวลา","body":"## ก่อน หลัง และช่วงเวลา\n\nbefore/after บอกก่อนหรือหลังจุดเวลา from…to บอกต้นกับปลาย until เน้นทำต่อถึงจุดจบ during + noun บอกว่ากิจกรรมเกิดในช่วงนั้น ไม่ได้บอกความยาวเอง this/last/next ชี้ช่วงเทียบปัจจุบัน แยก Monday ซึ่งเป็นวันออกจาก two hours ซึ่งเป็นระยะเวลา\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I work from nine to five. | เริ่มถึงจบ |\n| I study until ten. | ต่อเนื่องถึงสิบโมง |\n| I read during lunch. | อ่านในช่วงอาหารกลางวัน |\n\n### จุดที่มักสับสน\n\nduring two hours ไม่ใช่รูปบอกระยะเวลาในบทนี้ ให้ใช้ for two hours; until ไม่ได้หมายถึงจุดเริ่ม\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f5eb594a-dc6f-5982-ad48-8717d583394b'::uuid,'d6a6bcbc-2865-5844-a0a9-b80ca9c6326b'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/a9ffea6e672d63fd-lesson-11-07.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I work from nine to five.. I study until ten.. I read during lunch."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d6d8844b-90d4-5305-a5ff-fffd404cdcc7'::uuid,'d6a6bcbc-2865-5844-a0a9-b80ca9c6326b'::uuid,'multiple_choice',1,'{"question":"ร้านเปิดตั้งแต่ 8 ถึง 6 เลือกรูปใด?","choices":[{"id":"choice_1","text":"from eight to six"},{"id":"choice_2","text":"until eight to six"},{"id":"choice_3","text":"during eight to six"}],"correctChoiceId":"choice_1","explanation":"from…to บอกช่วงต้นปลาย"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('453e806d-2f71-5ef6-af13-76ff68ea0696'::uuid,'d6a6bcbc-2865-5844-a0a9-b80ca9c6326b'::uuid,'multiple_choice',1,'{"question":"I stay here until Friday หมายถึงอะไร?","choices":[{"id":"choice_1","text":"เริ่มอยู่วันศุกร์"},{"id":"choice_2","text":"อยู่ต่อถึงวันศุกร์"},{"id":"choice_3","text":"อยู่ทุกศุกร์"}],"correctChoiceId":"choice_2","explanation":"until แสดงจุดจบของช่วง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('51be137f-4cab-51dd-a10f-e151321deba2'::uuid,'d6a6bcbc-2865-5844-a0a9-b80ca9c6326b'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนกิจกรรมก่อน หลัง และช่วงเวลา รวมสามประโยค\n\n### ตัวอย่างคำตอบ\n\nI eat before class. I rest after work. I study from seven to eight.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ก่อน หลัง และช่วงเวลา** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ce2621fa-4cee-56e2-ab33-db6692245a8f'::uuid,'399f863c-a1cb-568d-ac8f-823fc1ae98f8'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **ฟังและบอกจำนวน ราคา เวลา วันที่ และค่าที่วัดได้**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![เลือกบุพบทตามชนิดเวลา: in October; on Monday; at 7:30](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d68b85cf74783387-module-11-map.png)\n\n*every day / next week / last year ไม่เติม preposition ในรูปทั่วไป*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2f929f08-1b7b-5ffa-a610-d14a7825671c'::uuid,'399f863c-a1cb-568d-ac8f-823fc1ae98f8'::uuid,'multiple_choice',1,'{"question":"quarter past three คือเวลาใด?","choices":[{"id":"choice_1","text":"3:15"},{"id":"choice_2","text":"2:45"},{"id":"choice_3","text":"3:45"}],"correctChoiceId":"choice_1","explanation":"past ผ่านสามโมงมา 15 นาที ย้อน 11.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bb346d88-046a-5bc6-a7e2-41752d210e3e'::uuid,'399f863c-a1cb-568d-ac8f-823fc1ae98f8'::uuid,'multiple_choice',1,'{"question":"The meeting is … Tuesday.","choices":[{"id":"choice_1","text":"in"},{"id":"choice_2","text":"on"},{"id":"choice_3","text":"at"}],"correctChoiceId":"choice_2","explanation":"วันใช้ on ย้อน 11.06"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2f086df4-4c16-5b64-aed2-fd6c584569bd'::uuid,'399f863c-a1cb-568d-ac8f-823fc1ae98f8'::uuid,'multiple_choice',1,'{"question":"ซื้อของราคา 65 จ่าย 100 เงินทอนคืออะไร?","choices":[{"id":"choice_1","text":"35 baht"},{"id":"choice_2","text":"45 baht"},{"id":"choice_3","text":"165 baht"}],"correctChoiceId":"choice_1","explanation":"100−65=35 ย้อน 11.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9451e1a3-df3a-5b98-acd6-c640a3a359ff'::uuid,'399f863c-a1cb-568d-ac8f-823fc1ae98f8'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเขียนตารางวันหนึ่งพร้อมเวลา วันที่ ค่าใช้จ่ายและช่วง from…to แล้วอ่านให้ผู้อื่นจด\n\n### ตัวอย่างผลงาน\n\nOn 10 May, I study from nine to ten. Lunch costs 65 baht. I pay 100 baht and get 35 baht change.\n\n### ตรวจผลงาน\n\n- อ่านจำนวนกับเวลาได้ตรง\n- in/on/at ตรงชนิดเวลา\n- ใช้หน่วยและวันเดือนชัด\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3cebd27c-09e7-5a93-a5d3-09fc41d1f6c3'::uuid,'f522f3c2-21cf-5174-a09e-73790de6d52e'::uuid,'reading',1,'{"title":"ระดับความถี่","body":"## ระดับความถี่\n\nalways/usually/often/sometimes/rarely/hardly ever/never บอกความถี่โดยประมาณ always ทุกครั้ง; usually เป็นปกติ; often บ่อย; sometimes บางครั้ง; rarely/hardly ever แทบไม่; never ไม่เคยเกิดในบริบทที่พูด คำเหล่านี้ไม่มีเปอร์เซ็นต์ตายตัว เพราะขึ้นกับกิจกรรมและผู้พูด\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I usually walk to work. | ปกติเดินไปทำงาน |\n| I sometimes take a bus. | บางครั้งขึ้นรถ |\n| I never drive. | ไม่ขับในกิจวัตรนี้ |\n\n### จุดที่มักสับสน\n\nnever มีความหมายปฏิเสธอยู่แล้ว ไม่ใช้ I don’t never drive ในภาษาอังกฤษมาตรฐานที่ฝึก\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ผู้หญิงเสื้อฟ้าอ่านหนังสือ ผู้ชายเสื้อแดงวิ่ง คนสองคนเดินและสุนัขนอนใต้ต้นไม้](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/dd683d7c6dc8b68a-park-activities.png)\n\n*Four people are in the park. A woman is reading, a man is running, and two people are walking.*\n\nชี้คนที่หมายถึงก่อนบรรยาย แยกสิ่งที่เห็นตอนนี้จากกิจวัตรที่คุณต้องการสมมติ แล้วใช้รูปประโยคตามบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adverbs of frequency](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/adverbs-frequency) · [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('20d8a65a-324c-53bb-aa8c-ce566fc720ea'::uuid,'f522f3c2-21cf-5174-a09e-73790de6d52e'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/ade710a2490d966d-lesson-12-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I usually walk to work.. I sometimes take a bus.. I never drive."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('12abd65d-1513-5b33-ae32-bd4eaa4a7f14'::uuid,'f522f3c2-21cf-5174-a09e-73790de6d52e'::uuid,'multiple_choice',1,'{"question":"คำใดหมายถึงแทบไม่ทำ?","choices":[{"id":"choice_1","text":"always"},{"id":"choice_2","text":"hardly ever"},{"id":"choice_3","text":"usually"}],"correctChoiceId":"choice_2","explanation":"hardly ever หมายถึงน้อยมากจนแทบไม่"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('10c6bfce-1d97-58f6-aeaf-42162fb99853'::uuid,'f522f3c2-21cf-5174-a09e-73790de6d52e'::uuid,'multiple_choice',1,'{"question":"usually มีเปอร์เซ็นต์มาตรฐานตายตัวหรือไม่?","choices":[{"id":"choice_1","text":"ไม่มี ต้องดูบริบท"},{"id":"choice_2","text":"มี 80% เสมอ"},{"id":"choice_3","text":"มี 50% เสมอ"}],"correctChoiceId":"choice_1","explanation":"เป็นระดับความถี่โดยประมาณ ไม่ใช่สูตรเปอร์เซ็นต์"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bcd68189-2a10-5cd9-a66c-66932b8d7a6f'::uuid,'f522f3c2-21cf-5174-a09e-73790de6d52e'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nจัดกิจกรรมของคุณสามอย่างตามความถี่ แล้วเขียนประโยคโดยไม่กำหนดเปอร์เซ็นต์ให้คำ\n\n### ตัวอย่างคำตอบ\n\nI always eat breakfast. I sometimes drink tea. I hardly ever play tennis.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ระดับความถี่** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('73600db6-77a8-502e-a379-d96bb050cd43'::uuid,'b52a10f2-c46a-50d7-a1b3-7c7f1608003f'::uuid,'reading',1,'{"title":"ตำแหน่งคำบอกความถี่","body":"## ตำแหน่งคำบอกความถี่\n\nตำแหน่งทั่วไปคือ frequency adverb ก่อน main verb: She often reads. แต่หลัง be: She is often tired. ถ้ามีกริยาช่วยในรูปที่จะเรียนต่อ มักอยู่ระหว่าง auxiliary กับ main verb เช่น I have never seen it. sometimes วางต้นหรือท้ายได้ในบางบริบท เริ่มฝึกตำแหน่งกลางที่ใช้บ่อยก่อน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I usually work at home. | ก่อน work |\n| I am usually at home. | หลัง am |\n| She can always help. | ระหว่าง can กับ help |\n\n### จุดที่มักสับสน\n\nI always am tired ใช้ได้ในจุดเน้นบางบริบท แต่รูปพื้นฐานเป็น I am always tired.; ไม่ใช้ don’t never\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adverbs of frequency](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/adverbs-frequency) · [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bf1aff9e-fbf6-5ba3-a7df-e39338e4ce53'::uuid,'b52a10f2-c46a-50d7-a1b3-7c7f1608003f'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f2b1eab4427d4859-lesson-12-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I usually work at home.. I am usually at home.. She can always help."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ecdb7a6e-850d-530d-ac42-0a3bc2e4efd0'::uuid,'b52a10f2-c46a-50d7-a1b3-7c7f1608003f'::uuid,'multiple_choice',1,'{"question":"เลือกลำดับพื้นฐาน","choices":[{"id":"choice_1","text":"Ben often reads books."},{"id":"choice_2","text":"Ben reads often books."},{"id":"choice_3","text":"Ben reads books oftenly."}],"correctChoiceId":"choice_1","explanation":"often ก่อน main verb reads"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2e63516e-7c6c-5752-a7ad-ee242dbaee9c'::uuid,'b52a10f2-c46a-50d7-a1b3-7c7f1608003f'::uuid,'multiple_choice',1,'{"question":"เลือกลำดับพื้นฐานกับ be","choices":[{"id":"choice_1","text":"She always is late. เป็นรูปเริ่มต้นในบทนี้"},{"id":"choice_2","text":"She is always late."},{"id":"choice_3","text":"She is late alwaysly."}],"correctChoiceId":"choice_2","explanation":"frequency adverb หลัง be"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('377e0559-6598-541a-aac8-4cf661c60be1'::uuid,'b52a10f2-c46a-50d7-a1b3-7c7f1608003f'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนกิจวัตรสองประโยคและสภาพด้วย be สองประโยค พร้อมชี้ตำแหน่ง adverb\n\n### ตัวอย่างคำตอบ\n\nI often read. She usually walks. I am sometimes tired. Ben is never late.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ตำแหน่งคำบอกความถี่** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d3bc1baf-33fc-595a-ac96-831967125c02'::uuid,'4ac3736d-f94f-5871-a287-128a7034e130'::uuid,'reading',1,'{"title":"บอกจำนวนครั้ง","body":"## บอกจำนวนครั้ง\n\nonce หมายถึงหนึ่งครั้ง twice สองครั้ง และ three/four times หลายครั้งตามเลข เติม a day/week/month เพื่อบอกหน่วยความถี่ every day คือทุกวัน ส่วน everyday เป็น adjective แปลว่าทั่วไปในชีวิตประจำวัน เช่น everyday English on Mondays หมายถึงทุกวันจันทร์ในบริบทกิจวัตร\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I exercise twice a week. | สองครั้งต่อสัปดาห์ |\n| I read every day. | อ่านทุกวัน |\n| I study everyday English. | English ที่ใช้ในชีวิตประจำวัน |\n\n### จุดที่มักสับสน\n\nไม่ใช้ two times ผิดเสมอ แต่ twice เป็นรูปที่ใช้บ่อย; everyday ไม่แทน every day ในคำบอกเวลา\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adverbs of frequency](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/adverbs-frequency) · [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d0163d71-bd49-58a4-a15a-6ee7614cd9bb'::uuid,'4ac3736d-f94f-5871-a287-128a7034e130'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/141901b1ccc23f5c-lesson-12-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I exercise twice a week.. I read every day.. I study everyday English."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f3c12a09-d839-51ff-a900-0d4dc4a36e40'::uuid,'4ac3736d-f94f-5871-a287-128a7034e130'::uuid,'multiple_choice',1,'{"question":"once a month หมายถึงอะไร?","choices":[{"id":"choice_1","text":"เดือนละครั้ง"},{"id":"choice_2","text":"วันละครั้ง"},{"id":"choice_3","text":"สองครั้งต่อเดือน"}],"correctChoiceId":"choice_1","explanation":"once หนึ่งครั้ง; month เดือน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('df9e4e99-89da-51a6-a1de-c7bfe78de5ca'::uuid,'4ac3736d-f94f-5871-a287-128a7034e130'::uuid,'multiple_choice',1,'{"question":"เลือกคำบอกเวลาถูก","choices":[{"id":"choice_1","text":"I study English everyday."},{"id":"choice_2","text":"I study English every day."},{"id":"choice_3","text":"I study everydays English."}],"correctChoiceId":"choice_2","explanation":"every day เป็นกลุ่มคำบอกเวลา"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cbf862d2-1a8e-5e37-abe3-5d7038f83b50'::uuid,'4ac3736d-f94f-5871-a287-128a7034e130'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกกิจกรรมหนึ่งครั้ง สองครั้งและสามครั้งต่อช่วงเวลา แล้วใช้ every day\n\n### ตัวอย่างคำตอบ\n\nI call my friend once a week. I exercise twice a week. I study three times a week. I read every day.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **บอกจำนวนครั้ง** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('46ec2aea-e0ab-519d-a63a-aa4880480c6a'::uuid,'d35e8b1e-f80a-5f59-a75e-d65ea1e025c5'::uuid,'reading',1,'{"title":"ถาม How often…?","body":"## ถาม How often…?\n\nHow often + do/does + subject + base verb? ถามความถี่ ตอบได้ด้วย adverb หรือจำนวนครั้ง เช่น Usually. / Twice a week. เปรียบเทียบข้อมูลคนสองคนโดยไม่สรุปเกินตาราง ถ้า A ทำสามครั้งต่อสัปดาห์และ B หนึ่งครั้ง บอก A does it more often. ได้ แต่ยังไม่รู้ระยะเวลาต่อครั้ง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| How often do you swim? — Twice a week. | ถามจำนวนครั้ง |\n| How often does she walk? — Every day. | does + base |\n| How often are you late? — Never. | be ใช้สลับหน้า |\n\n### จุดที่มักสับสน\n\nHow often ไม่ถามว่านานเท่าไรหรือเกิดเมื่อไร\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ถามคนละชนิดข้อมูล: twice a week; for an hour; at seven](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2ad6990d78dc68de-module-12-map.png)\n\n*I usually read.  •  I am usually at home.  •  ไม่มีเปอร์เซ็นต์ตายตัว*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adverbs of frequency](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/adverbs-frequency) · [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5c206611-2ac1-5fc3-a3e8-6518d854161c'::uuid,'d35e8b1e-f80a-5f59-a75e-d65ea1e025c5'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/fd1b1e8ca787bd13-lesson-12-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"How often do you swim?. Twice a week.. How often does she walk?. Every day.. How often are you late?. Never."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('db3db6e9-0087-5137-a8e2-3d4d3c6418c1'::uuid,'d35e8b1e-f80a-5f59-a75e-d65ea1e025c5'::uuid,'multiple_choice',1,'{"question":"ต้องการรู้จำนวนครั้งที่ Mai อ่านหนังสือ ใช้คำถามใด?","choices":[{"id":"choice_1","text":"How long does Mai read?"},{"id":"choice_2","text":"How often does Mai read?"},{"id":"choice_3","text":"Where does Mai read?"}],"correctChoiceId":"choice_2","explanation":"How often ถามความถี่"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('97db3662-2cc1-59bf-a209-09a01738e0ca'::uuid,'d35e8b1e-f80a-5f59-a75e-d65ea1e025c5'::uuid,'multiple_choice',1,'{"question":"คำตอบใดตรง How often do you exercise?","choices":[{"id":"choice_1","text":"For one hour."},{"id":"choice_2","text":"At six."},{"id":"choice_3","text":"Three times a week."}],"correctChoiceId":"choice_3","explanation":"บอกจำนวนครั้งต่อสัปดาห์ ไม่ใช่ระยะเวลาหรือเวลาเริ่ม"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a87321e1-9e5a-5aeb-a6d8-040a38100d1a'::uuid,'d35e8b1e-f80a-5f59-a75e-d65ea1e025c5'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nถามเพื่อนสามกิจกรรมเรื่องความถี่ แล้วสรุปหนึ่งประโยคต่อกิจกรรม\n\n### ตัวอย่างคำตอบ\n\nHow often do you read? Every day. Ben reads every day. He plays tennis twice a week. He never drives.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ถาม How often…?** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7ef1e41e-ba02-530c-a512-e03141212987'::uuid,'e7822179-9955-5bf3-af5a-557f028c0622'::uuid,'reading',1,'{"title":"How long…? และระยะเวลา","body":"## How long…? และระยะเวลา\n\nHow long ถามระยะเวลา ใช้ for + ช่วงเวลา เช่น for twenty minutes ต่างจาก How often ที่ถามความถี่ และ When ที่ถามเวลาเกิดกิจกรรม รูป How long do you study each day? ใช้ถามความยาวกิจวัตรได้ for/since กับ Present Perfect จะขยายใน M25 โดย since บอกจุดเริ่ม ไม่ใช่ระยะยาว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| How long do you study? — For an hour. | ระยะเวลา |\n| How often do you study? — Every day. | ความถี่ |\n| When do you study? — At seven. | เวลา |\n\n### จุดที่มักสับสน\n\none hour, every day และ at seven เป็นข้อมูลคนละชนิด เลือกคำถามให้ตรง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adverbs of frequency](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/adverbs-frequency) · [British Council — Prepositions of time](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/prepositions-time)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d61b7ade-ecc3-5be5-a874-4c776c513059'::uuid,'e7822179-9955-5bf3-af5a-557f028c0622'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4386ff5f763ab2c7-lesson-12-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"How long do you study?. For an hour.. How often do you study?. Every day.. When do you study?. At seven."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e5a86d1a-fea9-5fe9-aa99-3f12676d88d9'::uuid,'e7822179-9955-5bf3-af5a-557f028c0622'::uuid,'multiple_choice',1,'{"question":"คำตอบ For thirty minutes ตรงคำถามใด?","choices":[{"id":"choice_1","text":"How long…?"},{"id":"choice_2","text":"How often…?"},{"id":"choice_3","text":"Where…?"}],"correctChoiceId":"choice_1","explanation":"for + duration ตอบ How long"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('63fe0c5c-f50f-53c9-aa22-18590b99e5f1'::uuid,'e7822179-9955-5bf3-af5a-557f028c0622'::uuid,'multiple_choice',1,'{"question":"How often do you run? คำตอบที่ตรงคืออะไร?","choices":[{"id":"choice_1","text":"For ten minutes."},{"id":"choice_2","text":"Twice a week."},{"id":"choice_3","text":"At home."}],"correctChoiceId":"choice_2","explanation":"twice a week บอกความถี่"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a1bdb4b6-7e3f-5b92-a852-31ca61b6a6f6'::uuid,'e7822179-9955-5bf3-af5a-557f028c0622'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกกิจกรรมเดียวกันให้ครบความถี่ ระยะเวลาและเวลาเริ่ม\n\n### ตัวอย่างคำตอบ\n\nI study English every day, for thirty minutes, at seven in the evening.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **How long…? และระยะเวลา** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4f642d1d-33fe-54f0-a2c6-04fae3c9c86a'::uuid,'8541f558-f767-5aca-afa2-e4af3b4d6e24'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **ถามและตอบความถี่กับระยะเวลาโดยวางคำถูกตำแหน่ง**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ถามคนละชนิดข้อมูล: twice a week; for an hour; at seven](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2ad6990d78dc68de-module-12-map.png)\n\n*I usually read.  •  I am usually at home.  •  ไม่มีเปอร์เซ็นต์ตายตัว*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e40fc6f1-ada6-5368-a19b-5c05c984a25f'::uuid,'8541f558-f767-5aca-afa2-e4af3b4d6e24'::uuid,'multiple_choice',1,'{"question":"She … tired after work.","choices":[{"id":"choice_1","text":"is usually"},{"id":"choice_2","text":"usually is always ในรูปพื้นฐาน"},{"id":"choice_3","text":"is usuallyly"}],"correctChoiceId":"choice_1","explanation":"usually หลัง be ย้อน 12.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6d525c85-dff0-5c73-a52f-505a570e90ec'::uuid,'8541f558-f767-5aca-afa2-e4af3b4d6e24'::uuid,'multiple_choice',1,'{"question":"How often do you call home? คำตอบใดตรง?","choices":[{"id":"choice_1","text":"Once a week."},{"id":"choice_2","text":"For one hour."},{"id":"choice_3","text":"At eight."}],"correctChoiceId":"choice_1","explanation":"once a week ความถี่ ย้อน 12.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('81b55f42-b4af-5ddf-aa47-1c1e5108cf5a'::uuid,'8541f558-f767-5aca-afa2-e4af3b4d6e24'::uuid,'multiple_choice',1,'{"question":"ถามความยาวกิจกรรมใช้คำใด?","choices":[{"id":"choice_1","text":"How long"},{"id":"choice_2","text":"How often"},{"id":"choice_3","text":"Which"}],"correctChoiceId":"choice_1","explanation":"How long ถาม duration ย้อน 12.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ecdeb29d-997d-5012-a119-8daa8c282cd9'::uuid,'8541f558-f767-5aca-afa2-e4af3b4d6e24'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nบอกกิจกรรมสามอย่างทั้งความถี่และระยะเวลา แล้วถามข้อมูลเดียวกันจากเพื่อน\n\n### ตัวอย่างผลงาน\n\nI read every day for twenty minutes. I swim twice a week for an hour. I never drive. How often do you read? How long do you swim?\n\n### ตรวจผลงาน\n\n- วาง adverb ก่อน main verb หรือหลัง be\n- แยก once/twice จากระยะเวลา\n- เลือก How often/How long ตามคำตอบ\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c93d88c7-4fba-5bc6-ae40-718a77ecaf97'::uuid,'cff4eb56-96af-57f8-a004-813c59b1cb11'::uuid,'reading',1,'{"title":"in/on/at กับตำแหน่ง","body":"## in/on/at กับตำแหน่ง\n\nin บอกอยู่ในพื้นที่หรือภาชนะ on บอกอยู่บนผิวหรือเส้น at บอกตำแหน่งหรือจุดที่เกี่ยวข้องกับกิจกรรม เช่น in a room/on a table/at a station ไม่สามารถแปลแต่ละคำเป็นไทยคำเดียวแล้วใช้ได้ทุกบริบท at school อาจเน้นสถานที่ทำกิจกรรม ส่วน in the school ระบุภายในอาคาร\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The book is in the bag. | ในกระเป๋า |\n| The book is on the table. | บนผิวโต๊ะ |\n| Mai is at the station. | จุดสถานีตามบริบท |\n\n### จุดที่มักสับสน\n\nใช้คำร่วมที่พบบ่อยและดูสิ่งที่ต้องการเน้น ไม่ยึดว่าพื้นที่ใหญ่ต้อง in ทุกครั้ง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — There is / there are and it](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/there/there-are-it) · [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c310a693-d321-5177-aca5-f05719bc28b2'::uuid,'cff4eb56-96af-57f8-a004-813c59b1cb11'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2c8414b3f3a48bba-lesson-13-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The book is in the bag.. The book is on the table.. Mai is at the station."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f4a7690e-75fd-5505-a62f-7ad96c1a3ed4'::uuid,'cff4eb56-96af-57f8-a004-813c59b1cb11'::uuid,'multiple_choice',1,'{"question":"ลูกบอลอยู่ภายในกล่อง: It is … the box.","choices":[{"id":"choice_1","text":"on"},{"id":"choice_2","text":"in"},{"id":"choice_3","text":"at"}],"correctChoiceId":"choice_2","explanation":"ภายในภาชนะใช้ in"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('38ae08bc-5334-529e-ae92-f00af6117f92'::uuid,'cff4eb56-96af-57f8-a004-813c59b1cb11'::uuid,'multiple_choice',1,'{"question":"แก้ววางบนผิวโต๊ะ: It is … the table.","choices":[{"id":"choice_1","text":"on"},{"id":"choice_2","text":"in"},{"id":"choice_3","text":"into"}],"correctChoiceId":"choice_1","explanation":"บนผิวใช้ on"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6ee1fa98-b5f5-5999-a923-38580789d720'::uuid,'cff4eb56-96af-57f8-a004-813c59b1cb11'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nจัดสิ่งของสามชิ้นแล้วบอกตำแหน่งด้วย in/on/at\n\n### ตัวอย่างคำตอบ\n\nThe pen is in the bag. The cup is on the desk. Ben is at school.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **in/on/at กับตำแหน่ง** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6da89de9-7dba-5dfa-a85a-53e57b7c1305'::uuid,'2160108b-1b88-5abd-a15b-dce3cf36a4f0'::uuid,'reading',1,'{"title":"ตำแหน่งสัมพันธ์","body":"## ตำแหน่งสัมพันธ์\n\nตำแหน่งสัมพันธ์ต้องมีสิ่งอ้างอิง under ใต้; above สูงกว่าไม่จำเป็นต้องสัมผัส; below ต่ำกว่า; behind หลัง; in front of หน้า; next to ติดข้าง; between ระหว่าง; opposite ตรงข้าม; near ใกล้ over ใช้ได้ทั้งเหนือหรือคร่อมตามบริบท ระบุจุดอ้างอิงให้ผู้ฟังเข้าใจ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The bag is under the table. | ใต้โต๊ะ |\n| The chair is between the desk and the door. | ระหว่างสองจุด |\n| The shop is opposite the bank. | ตรงข้ามธนาคาร |\n\n### จุดที่มักสับสน\n\nbetween มักตามด้วย A and B ในตัวอย่างพื้นฐาน ไม่ต้องติดกันเหมือน next to\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ผู้หญิงเสื้อฟ้าอ่านหนังสือ ผู้ชายเสื้อแดงวิ่ง คนสองคนเดินและสุนัขนอนใต้ต้นไม้](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/dd683d7c6dc8b68a-park-activities.png)\n\n*Four people are in the park. A woman is reading, a man is running, and two people are walking.*\n\nชี้คนที่หมายถึงก่อนบรรยาย แยกสิ่งที่เห็นตอนนี้จากกิจวัตรที่คุณต้องการสมมติ แล้วใช้รูปประโยคตามบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — There is / there are and it](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/there/there-are-it) · [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6d66e1bd-6c4f-5adb-a0eb-1b0081288f73'::uuid,'2160108b-1b88-5abd-a15b-dce3cf36a4f0'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/5bf8f5a509b3a117-lesson-13-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The bag is under the table.. The chair is between the desk and the door.. The shop is opposite the bank."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e90dd14a-75b7-5823-a8ca-387c46fb0699'::uuid,'2160108b-1b88-5abd-a15b-dce3cf36a4f0'::uuid,'multiple_choice',1,'{"question":"แมวอยู่ใต้เก้าอี้ ใช้คำใด?","choices":[{"id":"choice_1","text":"under"},{"id":"choice_2","text":"above"},{"id":"choice_3","text":"behind"}],"correctChoiceId":"choice_1","explanation":"under บอกตำแหน่งใต้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('35534ca4-8edb-5160-a4b1-16b000d9d26e'::uuid,'2160108b-1b88-5abd-a15b-dce3cf36a4f0'::uuid,'multiple_choice',1,'{"question":"ตรงข้ามธนาคารใช้วลีใด?","choices":[{"id":"choice_1","text":"opposite the bank"},{"id":"choice_2","text":"between the bank"},{"id":"choice_3","text":"into the bank"}],"correctChoiceId":"choice_1","explanation":"opposite หมายถึงอยู่ฝั่งตรงข้าม"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a84fcde7-3699-581c-a6c3-4e787a4fe4fc'::uuid,'2160108b-1b88-5abd-a15b-dce3cf36a4f0'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบรรยายห้องสามประโยคโดยมี behind/next to/between\n\n### ตัวอย่างคำตอบ\n\nThe chair is next to the desk. The bag is behind the chair. The lamp is between the books and the cup.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ตำแหน่งสัมพันธ์** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b81dba0d-4859-5a3c-a7c5-9f046f2b68a1'::uuid,'54952b47-b025-588b-abbd-ef30a44c168d'::uuid,'reading',1,'{"title":"ทิศทางและการเคลื่อนที่","body":"## ทิศทางและการเคลื่อนที่\n\nmovement prepositions บอกเส้นทาง to จุดหมาย from ต้นทาง into เข้าไปภายใน out of ออกจากภายใน through ผ่านด้านใน across ข้ามจากด้านหนึ่งไปอีกด้าน up/down ขึ้นลง left/right/straight ใช้ให้ทิศทาง Where are you going? ถามจุดหมายและพูด Where are you going to? ได้ในบริบททั่วไป\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Go into the room. | เคลื่อนเข้าไปในห้อง |\n| Walk across the street. | ข้ามถนน |\n| Walk through the park. | ผ่านพื้นที่สวน |\n\n### จุดที่มักสับสน\n\nin บอกตำแหน่ง ต่างจาก into ที่เน้นเคลื่อนเข้า; across กับ through ต้องดูเส้นทาง\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ตำแหน่งกับเส้นทาง: in the room; into the room; There are two chairs.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/3290420b950b456b-module-13-map.png)\n\n*in: อยู่ภายใน  •  into: เคลื่อนเข้า  •  there: แนะนำว่ามี*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — There is / there are and it](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/there/there-are-it) · [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('07f9d6c8-f405-59c6-a3c2-1dfdb87617eb'::uuid,'54952b47-b025-588b-abbd-ef30a44c168d'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/c8d6c3f67d8a8e48-lesson-13-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Go into the room.. Walk across the street.. Walk through the park."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e0d84b5b-9372-5697-ab2e-c667ad6f5f85'::uuid,'54952b47-b025-588b-abbd-ef30a44c168d'::uuid,'multiple_choice',1,'{"question":"เคลื่อนออกจากห้อง ใช้คำใด?","choices":[{"id":"choice_1","text":"out of"},{"id":"choice_2","text":"into"},{"id":"choice_3","text":"under"}],"correctChoiceId":"choice_1","explanation":"out of เคลื่อนจากภายในสู่ภายนอก"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6c2883f8-7306-55bd-af37-ce977823062c'::uuid,'54952b47-b025-588b-abbd-ef30a44c168d'::uuid,'multiple_choice',1,'{"question":"ข้ามถนนจากฝั่งหนึ่งไปอีกฝั่งใช้คำใด?","choices":[{"id":"choice_1","text":"through"},{"id":"choice_2","text":"across"},{"id":"choice_3","text":"in"}],"correctChoiceId":"choice_2","explanation":"across เน้นข้ามพื้นที่"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f092717a-dac1-5e6b-abcc-504f69c9fd7c'::uuid,'54952b47-b025-588b-abbd-ef30a44c168d'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนเส้นทางสั้นจากจุดหนึ่งไปอีกจุด ใช้ to/from และ across/into\n\n### ตัวอย่างคำตอบ\n\nWalk from the station to the bank. Go straight. Turn left. Walk across the street and go into the shop.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ทิศทางและการเคลื่อนที่** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2c8deeff-ea32-54a0-a90b-63b5391a3956'::uuid,'53cddf7d-2cbd-545b-a407-3987c66eabd2'::uuid,'reading',1,'{"title":"There is / There are","body":"## There is / There are\n\nThere is + singular/uncountable และ There are + plural ใช้แนะนำว่ามีสิ่งใด ไม่ได้บอกเจ้าของแบบ have ปฏิเสธ there isn’t/aren’t คำถาม Is there…?/Are there…? คำตอบ Yes, there is./No, there aren’t. เลือก be ตาม noun ที่ตามมา\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| There is a book on the desk. | มีหนึ่งเล่ม |\n| There are three books on the desk. | มีหลายเล่ม |\n| Is there a bank near here? | ถามว่ามีไหม |\n\n### จุดที่มักสับสน\n\nThere have a book ไม่ใช่รูปนี้ และคำตอบบอกเล่าสั้น Yes, there’s. ไม่ใช้ย่อท้าย\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — There is / there are and it](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/there/there-are-it) · [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('046cffa2-5f1a-56da-a713-576496c4a7a4'::uuid,'53cddf7d-2cbd-545b-a407-3987c66eabd2'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/db0ad12648e0f18a-lesson-13-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"There is a book on the desk.. There are three books on the desk.. Is there a bank near here?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1a426472-d5ed-551c-a487-9716dd9459b9'::uuid,'53cddf7d-2cbd-545b-a407-3987c66eabd2'::uuid,'multiple_choice',1,'{"question":"… two chairs in the room.","choices":[{"id":"choice_1","text":"There is"},{"id":"choice_2","text":"There are"},{"id":"choice_3","text":"There am"}],"correctChoiceId":"choice_2","explanation":"two chairs plural ใช้ are"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9cb0af6c-e549-5364-ac44-2d8e6f4a4898'::uuid,'53cddf7d-2cbd-545b-a407-3987c66eabd2'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามที่ถูก","choices":[{"id":"choice_1","text":"Are there a book?"},{"id":"choice_2","text":"Is there a book?"},{"id":"choice_3","text":"Do there is a book?"}],"correctChoiceId":"choice_2","explanation":"book หนึ่งเล่ม ใช้ Is there"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('13cd53e8-0e57-561f-adec-e8980dd06e5c'::uuid,'53cddf7d-2cbd-545b-a407-3987c66eabd2'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกสิ่งที่มีในห้องสองประโยค สิ่งที่ไม่มีหนึ่งประโยค และถามหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nThere is a desk. There are two chairs. There isn’t a TV. Are there any books?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **There is / There are** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('38bca15b-9e88-5780-aef6-88fa0263ea0f'::uuid,'68ce93aa-5f04-5bee-acac-75bd9ebe78b5'::uuid,'reading',1,'{"title":"there กับ it","body":"## there กับ it\n\nthere ใน There is a bus. ใช้แนะนำการมีอยู่ ส่วน it ใน It is red. อ้าง bus ที่เพิ่งกล่าวแล้ว it ยังเป็น dummy subject สำหรับเวลา อากาศและระยะทาง เช่น It is raining. It is five kilometres to the station. there อีกการใช้แปลว่าที่นั่น เช่น The bus is there. ต้องดูตำแหน่งและความหมาย\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| There is a bus. It is red. | มีรถ แล้วบรรยายรถ |\n| It is cold today. | it สำหรับอากาศ |\n| The bus is there. | there หมายถึงที่นั่น |\n\n### จุดที่มักสับสน\n\nไม่ใช้ It is a bus near here. แทนการบอกว่ามีรถหนึ่งคันใกล้ ๆ โดยไม่มีสิ่งให้อ้าง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — There is / there are and it](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/there/there-are-it) · [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3ea617ab-edfd-5dbd-abf3-049ebd0f5b5c'::uuid,'68ce93aa-5f04-5bee-acac-75bd9ebe78b5'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/274e3ec4cf9a2172-lesson-13-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"There is a bus. It is red.. It is cold today.. The bus is there."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1f4abf92-f2a1-5df7-add0-3389ca5a7d8e'::uuid,'68ce93aa-5f04-5bee-acac-75bd9ebe78b5'::uuid,'multiple_choice',1,'{"question":"There is a cat. … is black.","choices":[{"id":"choice_1","text":"It"},{"id":"choice_2","text":"There"},{"id":"choice_3","text":"They"}],"correctChoiceId":"choice_1","explanation":"It อ้าง cat หนึ่งตัว"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cba4d81e-dd05-5241-a5be-155b132d219b'::uuid,'68ce93aa-5f04-5bee-acac-75bd9ebe78b5'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคบอกอากาศถูก","choices":[{"id":"choice_1","text":"Is hot today."},{"id":"choice_2","text":"There is hot today."},{"id":"choice_3","text":"It is hot today."}],"correctChoiceId":"choice_3","explanation":"it เป็น dummy subject สำหรับสภาพอากาศ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ea6c5186-cb20-51ac-a445-3c7b2e9e690d'::uuid,'68ce93aa-5f04-5bee-acac-75bd9ebe78b5'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสองประโยคแนะนำสิ่งหนึ่งด้วย there แล้วอ้าง it จากนั้นบอกเวลาและอากาศ\n\n### ตัวอย่างคำตอบ\n\nThere is a bike. It is blue. It is nine o’clock. It is sunny.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **there กับ it** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('574e58d8-e9e2-5c00-aa2d-00dc37b16b45'::uuid,'53690570-9dfb-57fd-aebf-a4288a913424'::uuid,'reading',1,'{"title":"เดินทางและเครื่องมือ","body":"## เดินทางและเครื่องมือ\n\nเรียน prepositions เป็นกลุ่มความหมาย: by bus/train บอกวิธีเดินทาง แต่ on foot คือเดิน with a pen บอกเครื่องมือ by email บอกช่องทาง about บอกเรื่อง for บอกจุดประสงค์หรือผู้รับประโยชน์ like + noun เปรียบลักษณะ วลี at the end of/for sale/on holiday ใช้ตามรูปที่พบบ่อย home/here/there หลัง go ไม่เติม to\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I go by bus. / I go on foot. | วิธีเดินทาง |\n| I write with a pen. / I send it by email. | เครื่องมือ / ช่องทาง |\n| Go home. Come here. | ไม่เติม to |\n\n### จุดที่มักสับสน\n\nby foot และ go to home ไม่ใช่รูปทั่วไปที่ฝึก; home เป็น noun ได้ในโครงอื่น แต่ไม่ยึดกฎนี้ทุกการใช้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — There is / there are and it](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/there/there-are-it) · [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('053c9bc4-a397-58d9-a8b5-e8c349a54618'::uuid,'53690570-9dfb-57fd-aebf-a4288a913424'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/e33f0fa79e631a26-lesson-13-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I go by bus.. I go on foot.. I write with a pen.. I send it by email.. Go home. Come here."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2ea5ffa1-1e47-5f72-a71a-7edb3145d270'::uuid,'53690570-9dfb-57fd-aebf-a4288a913424'::uuid,'multiple_choice',1,'{"question":"เดินเท้าใช้วลีใด?","choices":[{"id":"choice_1","text":"by foot"},{"id":"choice_2","text":"on foot"},{"id":"choice_3","text":"with foot"}],"correctChoiceId":"choice_2","explanation":"on foot เป็นวลีมาตรฐาน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c885dc3e-ee5a-5465-af54-0a5036814d2b'::uuid,'53690570-9dfb-57fd-aebf-a4288a913424'::uuid,'multiple_choice',1,'{"question":"เขียนด้วยปากกา ใช้คำใด?","choices":[{"id":"choice_1","text":"with a pen"},{"id":"choice_2","text":"by a pen"},{"id":"choice_3","text":"to a pen"}],"correctChoiceId":"choice_1","explanation":"with ใช้บอกเครื่องมือ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8a731451-526b-55f1-a27f-c3dcd89f3c77'::uuid,'53690570-9dfb-57fd-aebf-a4288a913424'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกการเดินทาง เครื่องมือและช่องทางติดต่ออย่างละหนึ่ง พร้อมใช้วลีสถานที่อีกหนึ่ง\n\n### ตัวอย่างคำตอบ\n\nI go to school by bus. I write with a pen. I send messages by email. I go home at five.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เดินทางและเครื่องมือ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8c4b37fa-b013-53a3-a62f-be6ae5124288'::uuid,'610af072-d1af-5679-a16b-9fea829395d6'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **บอกว่าสิ่งใดอยู่ไหนและแยกการมีอยู่จากการระบุสิ่งนั้น**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ตำแหน่งกับเส้นทาง: in the room; into the room; There are two chairs.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/3290420b950b456b-module-13-map.png)\n\n*in: อยู่ภายใน  •  into: เคลื่อนเข้า  •  there: แนะนำว่ามี*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1c8df68c-bb51-5ed7-a564-9d672dddb60a'::uuid,'610af072-d1af-5679-a16b-9fea829395d6'::uuid,'multiple_choice',1,'{"question":"The keys are … the box (อยู่ภายใน).","choices":[{"id":"choice_1","text":"in"},{"id":"choice_2","text":"on"},{"id":"choice_3","text":"across"}],"correctChoiceId":"choice_1","explanation":"in บอกภายใน ย้อน 13.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9be7291b-5560-5a93-a7a4-bfc4771c11cb'::uuid,'610af072-d1af-5679-a16b-9fea829395d6'::uuid,'multiple_choice',1,'{"question":"… a cafe near the station?","choices":[{"id":"choice_1","text":"Is there"},{"id":"choice_2","text":"Are there"},{"id":"choice_3","text":"Does there"}],"correctChoiceId":"choice_1","explanation":"a cafe singular ใช้ Is there ย้อน 13.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('605f614c-7aa2-53d2-acaf-ad0ca95de8d7'::uuid,'610af072-d1af-5679-a16b-9fea829395d6'::uuid,'multiple_choice',1,'{"question":"เดินเท้าใช้วลีใด?","choices":[{"id":"choice_1","text":"on foot"},{"id":"choice_2","text":"by foot"},{"id":"choice_3","text":"in foot"}],"correctChoiceId":"choice_1","explanation":"on foot เป็นกลุ่มคำ ย้อน 13.06"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8ee3e441-331c-546a-ae0f-9f5c3fe302cb'::uuid,'610af072-d1af-5679-a16b-9fea829395d6'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nวาดแผนห้องหรือถนนง่าย ๆ แล้วบอกสิ่งที่มี ตำแหน่งและเส้นทางสามขั้นตอน\n\n### ตัวอย่างผลงาน\n\nThere is a shop next to the bank. The station is opposite the shop. Walk across the street. Turn right. Go into the shop.\n\n### ตรวจผลงาน\n\n- there is/are ตรงจำนวน\n- จุดอ้างอิงตำแหน่งชัด\n- แยกตำแหน่งจากทิศทางเคลื่อน\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c3c87092-0874-514f-a4d7-762373199166'::uuid,'9850c3ee-998f-5a7f-af1a-80db9e535aec'::uuid,'reading',1,'{"title":"นับได้–นับไม่ได้ตามความหมาย","body":"## นับได้–นับไม่ได้ตามความหมาย\n\ncountability ขึ้นกับความหมายและหน่วย water/rice/information/furniture เป็น uncountable ในความหมายทั่วไป ไม่มี a และไม่เติม s เมื่อต้องการนับใช้หน่วยหรือคำนามอื่น เช่น a piece of information/two chairs coffee/chicken เปลี่ยนได้ตามบริบท a coffee อาจหมายถึงหนึ่งถ้วย a chicken ไก่หนึ่งตัว แต่ chicken ที่เป็นเนื้อใช้เป็นปริมาณ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| some information | ข้อมูล ไม่ใช้ informations |\n| two pieces of furniture | นับชิ้นผ่าน pieces |\n| a coffee / some coffee | หนึ่งถ้วยในร้าน / กาแฟเป็นปริมาณ |\n\n### จุดที่มักสับสน\n\nการมีหลายข้อมูลในความหมายไม่ได้ทำให้ information เติม s; ตรวจชนิด noun จากความหมายที่ใช้\n\n\n\n### ดูภาพแล้วลองใช้\n\n![แอปเปิลสามผล น้ำสองขวด ข้าวหนึ่งชาม ขนมปังหนึ่งก้อนกับสองแผ่นและนมหนึ่งแก้ว](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f82199a419ee302a-pantry-counting.png)\n\n*Three apples, two bottles of water, a bowl of rice, a loaf of bread, two slices of bread and a glass of milk.*\n\nแยกสิ่งที่นับโดยตรงจากปริมาณที่ต้องมีหน่วย แล้วเขียนรายการเตรียมอาหารสำหรับสองคน\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns) · [British Council — Few, a few, little, a bit of](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/quantifiers-few-a-few-little-a-bit)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e54dda47-62f5-54be-ae36-950331105fb3'::uuid,'9850c3ee-998f-5a7f-af1a-80db9e535aec'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/112d489a0d28b192-lesson-14-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"some information. two pieces of furniture. a coffee. some coffee"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('460e64f1-b4aa-58c2-a8c2-b26ae2af03a2'::uuid,'9850c3ee-998f-5a7f-af1a-80db9e535aec'::uuid,'multiple_choice',1,'{"question":"เลือกวลีที่ถูกในความหมายทั่วไป","choices":[{"id":"choice_1","text":"three informations"},{"id":"choice_2","text":"some information"},{"id":"choice_3","text":"an information"}],"correctChoiceId":"choice_2","explanation":"information เป็น uncountable"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('75bb0380-59fc-5511-aaca-f454e57f4c20'::uuid,'9850c3ee-998f-5a7f-af1a-80db9e535aec'::uuid,'multiple_choice',1,'{"question":"a chicken ต่างจาก some chicken อย่างไร?","choices":[{"id":"choice_1","text":"ไก่หนึ่งตัว / เนื้อไก่เป็นปริมาณ"},{"id":"choice_2","text":"เหมือนกันทุกบริบท"},{"id":"choice_3","text":"อย่างแรกเป็นกริยา"}],"correctChoiceId":"choice_1","explanation":"ความหมายกำหนดวิธีนับ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2ed713b7-42cc-5337-a8b7-0ee1a94b84a6'::uuid,'9850c3ee-998f-5a7f-af1a-80db9e535aec'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nทำรายการอาหาร สิ่งของและข้อมูลอย่างละสองรายการ โดยเลือกหน่วยให้เหมาะ\n\n### ตัวอย่างคำตอบ\n\nsome rice; a chicken; two chairs; some furniture; a piece of information; some advice.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **นับได้–นับไม่ได้ตามความหมาย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ba8a8ceb-7061-5116-ad4a-d57cd5d35a07'::uuid,'0dc07a7d-9a00-5363-a015-e14f0a31c9a3'::uuid,'reading',1,'{"title":"หน่วยนับและภาชนะ","body":"## หน่วยนับและภาชนะ\n\nนับปริมาณด้วย unit + of + uncountable noun เช่น a bottle of water/two bottles of water การเติม plural อยู่ที่หน่วย bottles ไม่ใช่ water ใช้ glass/cup สำหรับภาชนะ piece สำหรับชิ้น slice สำหรับแผ่น loaf สำหรับขนมปังทั้งก้อน ชนิดหน่วยเปลี่ยนปริมาณและความหมายจึงเลือกให้ตรง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| two glasses of water | แก้วสองใบใส่น้ำ |\n| a slice of bread | ขนมปังหนึ่งแผ่น |\n| a piece of advice | คำแนะนำหนึ่งข้อ |\n\n### จุดที่มักสับสน\n\none bread ไม่ใช่รูปที่ใช้ทั่วไปเมื่อนับก้อนหรือแผ่น ต้องระบุ loaf/slice\n\n\n\n### ดูภาพแล้วลองใช้\n\n![แอปเปิลสามผล น้ำสองขวด ข้าวหนึ่งชาม ขนมปังหนึ่งก้อนกับสองแผ่นและนมหนึ่งแก้ว](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f82199a419ee302a-pantry-counting.png)\n\n*Three apples, two bottles of water, a bowl of rice, a loaf of bread, two slices of bread and a glass of milk.*\n\nแยกสิ่งที่นับโดยตรงจากปริมาณที่ต้องมีหน่วย แล้วเขียนรายการเตรียมอาหารสำหรับสองคน\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns) · [British Council — Few, a few, little, a bit of](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/quantifiers-few-a-few-little-a-bit)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5113b4cc-f763-5b99-a4e6-9ee8090b863a'::uuid,'0dc07a7d-9a00-5363-a015-e14f0a31c9a3'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/c8fdab4bab52b9ee-lesson-14-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"two glasses of water. a slice of bread. a piece of advice"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8513e1c5-2bc0-5960-a4e2-3e135fe3f53f'::uuid,'0dc07a7d-9a00-5363-a015-e14f0a31c9a3'::uuid,'multiple_choice',1,'{"question":"น้ำสามขวดใช้รูปใด?","choices":[{"id":"choice_1","text":"three bottle of waters"},{"id":"choice_2","text":"three bottles of water"},{"id":"choice_3","text":"three waters bottle"}],"correctChoiceId":"choice_2","explanation":"plural ที่ bottles; water คงรูป"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2d5329ae-b034-515c-a8dd-fac6c6258886'::uuid,'0dc07a7d-9a00-5363-a015-e14f0a31c9a3'::uuid,'multiple_choice',1,'{"question":"ขนมปังหนึ่งแผ่นใช้วลีใด?","choices":[{"id":"choice_1","text":"a slice of bread"},{"id":"choice_2","text":"a bread slice of"},{"id":"choice_3","text":"a slice of breads"}],"correctChoiceId":"choice_1","explanation":"slice + of + bread"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('57fddef9-5686-57bf-a4ca-14a878ceda6b'::uuid,'0dc07a7d-9a00-5363-a015-e14f0a31c9a3'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนรายการซื้อของห้ารายการพร้อมหน่วยและจำนวน\n\n### ตัวอย่างคำตอบ\n\ntwo bottles of water; a loaf of bread; three slices of cheese; a cup of coffee; a piece of fruit.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **หน่วยนับและภาชนะ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7da7772f-d5b2-53bf-aecc-8844e3da6233'::uuid,'63c28a9e-8d96-5fb6-ad9a-6e1586ceb718'::uuid,'reading',1,'{"title":"some/any/no","body":"## some/any/no\n\nsome มักใช้บอกว่ามีปริมาณหนึ่งในบอกเล่า any มักใช้คำถามและปฏิเสธ no + noun มีความหมายเท่ากับ not any ในรูปนี้ เช่น I have no money./I don’t have any money. some ใช้คำถามเมื่อเสนอหรือขอสิ่งและคาดว่าจะมีให้ เช่น Would you like some tea? ไม่ใช่กฎว่า some ห้ามอยู่ในคำถาม\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I have some rice. | บอกว่ามี |\n| Do you have any rice? | ถามว่ามีไหม |\n| I don’t have any rice. / I have no rice. | ปฏิเสธ |\n\n### จุดที่มักสับสน\n\nไม่ใช้ I don’t have no rice ในอังกฤษมาตรฐานนี้ เพราะปฏิเสธซ้อน\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns) · [British Council — Few, a few, little, a bit of](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/quantifiers-few-a-few-little-a-bit)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fc2fbdb1-075d-58b0-a51a-94dee578a5b7'::uuid,'63c28a9e-8d96-5fb6-ad9a-6e1586ceb718'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/7785b67f6969e2d5-lesson-14-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I have some rice.. Do you have any rice?. I don’t have any rice.. I have no rice."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fa8e52f0-c39f-5ebb-a017-54e540ce2ddd'::uuid,'63c28a9e-8d96-5fb6-ad9a-6e1586ceb718'::uuid,'multiple_choice',1,'{"question":"Do you have … milk? เป็นคำถามทั่วไป","choices":[{"id":"choice_1","text":"any"},{"id":"choice_2","text":"no เท่านั้น"},{"id":"choice_3","text":"many"}],"correctChoiceId":"choice_1","explanation":"any ใช้คำถามปริมาณทั่วไป"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('06c86873-e9aa-5137-a36c-22c4db9db3b8'::uuid,'63c28a9e-8d96-5fb6-ad9a-6e1586ceb718'::uuid,'multiple_choice',1,'{"question":"เสนอชาให้แขก รูปใดเหมาะ?","choices":[{"id":"choice_1","text":"Would you like some tea?"},{"id":"choice_2","text":"Would you like no tea?"},{"id":"choice_3","text":"Would you like a teas?"}],"correctChoiceId":"choice_1","explanation":"some ใช้คำถามเสนอได้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('93108697-0fc0-5cbe-a551-7c639747a93a'::uuid,'63c28a9e-8d96-5fb6-ad9a-6e1586ceb718'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสิ่งที่มี สิ่งที่ไม่มี และคำเสนออาหารอย่างละหนึ่ง\n\n### ตัวอย่างคำตอบ\n\nI have some bread. I don’t have any milk. Would you like some water?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **some/any/no** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6c887974-82aa-56d8-aaee-fba7c515c13d'::uuid,'c65a9162-8a5c-5702-a6b2-d869b5a78a48'::uuid,'reading',1,'{"title":"many/much/a lot of","body":"## many/much/a lot of\n\nmany ใช้กับ countable plural เช่น many books ส่วน much ใช้กับ uncountable เช่น much water ถาม How many books…? แต่ How much water…? a lot of ใช้ได้ทั้งสองชนิดและพบบ่อยในบอกเล่าทั่วไป much ในบอกเล่าล้วนบางรูปฟังเป็นทางการ จึงเริ่ม I have a lot of time. ปฏิเสธและคำถามใช้ much ได้ธรรมชาติ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| many apples / much rice | countable plural / uncountable |\n| a lot of apples / a lot of rice | ใช้ได้ทั้งสอง |\n| How much does it cost? | much ถามราคา |\n\n### จุดที่มักสับสน\n\nmuch books และ many water ผิดถ้าไม่มีการเปลี่ยนความหมายเป็นหน่วย\n\n\n\n### ดูภาพแล้วลองใช้\n\n![นับหน่วยหรือบอกปริมาณ: many apples; much water; two bottles of water](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2bff1ab62e3ed0e1-module-14-map.png)\n\n*a few apples  •  a little rice  •  enough + noun*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n![แอปเปิลสามผล น้ำสองขวด ข้าวหนึ่งชาม ขนมปังหนึ่งก้อนกับสองแผ่นและนมหนึ่งแก้ว](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f82199a419ee302a-pantry-counting.png)\n\n*Three apples, two bottles of water, a bowl of rice, a loaf of bread, two slices of bread and a glass of milk.*\n\nแยกสิ่งที่นับโดยตรงจากปริมาณที่ต้องมีหน่วย แล้วเขียนรายการเตรียมอาหารสำหรับสองคน\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns) · [British Council — Few, a few, little, a bit of](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/quantifiers-few-a-few-little-a-bit)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('65e69ff5-9d3f-5612-acc1-ad2147971392'::uuid,'c65a9162-8a5c-5702-a6b2-d869b5a78a48'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/117fc7f239f7039d-lesson-14-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"many apples. much rice. a lot of apples. a lot of rice. How much does it cost?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a95c0ac4-7cd0-5a8c-aa0f-1aefabc19758'::uuid,'c65a9162-8a5c-5702-a6b2-d869b5a78a48'::uuid,'multiple_choice',1,'{"question":"How … chairs are there?","choices":[{"id":"choice_1","text":"much"},{"id":"choice_2","text":"many"},{"id":"choice_3","text":"a lot"}],"correctChoiceId":"choice_2","explanation":"chairs countable plural ใช้ many"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('76103b61-e152-530e-a291-07fe8ad7e679'::uuid,'c65a9162-8a5c-5702-a6b2-d869b5a78a48'::uuid,'multiple_choice',1,'{"question":"I don’t have … time.","choices":[{"id":"choice_1","text":"many"},{"id":"choice_2","text":"much"},{"id":"choice_3","text":"a many"}],"correctChoiceId":"choice_2","explanation":"time ในความหมายระยะเวลาเป็น uncountable"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f2303fd4-00b2-517f-a679-101c0c253b47'::uuid,'c65a9162-8a5c-5702-a6b2-d869b5a78a48'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nถามจำนวนของและปริมาณสองข้อ แล้วบอกปริมาณด้วย a lot of\n\n### ตัวอย่างคำตอบ\n\nHow many books do you have? How much water do you drink? I have a lot of books. I drink a lot of water.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **many/much/a lot of** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('29657126-4173-5d15-aa1d-cc781718d2ad'::uuid,'4931c7f6-0850-518b-a509-b4899a11fd45'::uuid,'reading',1,'{"title":"few/a few/little/a little","body":"## few/a few/little/a little\n\na few + countable plural และ a little + uncountable หมายถึงมีบ้าง ส่วน few/little โดยไม่มี a เน้นว่าน้อยจนไม่พอหรือแทบไม่มีตามมุมมองผู้พูด a bit of + uncountable หมายถึงเล็กน้อย ข้อมูลปริมาณใกล้กันแต่ทัศนคติต่างกัน จึงอ่านบริบทว่าผู้พูดพอใจหรือขาดสิ่งจำเป็น\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I have a few friends. | มีเพื่อนอยู่บ้าง |\n| I have few friends. | เน้นว่ามีเพื่อนน้อย |\n| We have a little time. | พอมีเวลาอยู่บ้าง |\n| We have little time. | เน้นเวลาแทบไม่พอ |\n\n### จุดที่มักสับสน\n\nอย่าใช้ little กับ plural countable เช่น little books เมื่อหมายถึงจำนวน; little books อีกความหมายคือหนังสือเล่มเล็ก\n\n\n\n### ดูภาพแล้วลองใช้\n\n![แอปเปิลสามผล น้ำสองขวด ข้าวหนึ่งชาม ขนมปังหนึ่งก้อนกับสองแผ่นและนมหนึ่งแก้ว](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f82199a419ee302a-pantry-counting.png)\n\n*Three apples, two bottles of water, a bowl of rice, a loaf of bread, two slices of bread and a glass of milk.*\n\nแยกสิ่งที่นับโดยตรงจากปริมาณที่ต้องมีหน่วย แล้วเขียนรายการเตรียมอาหารสำหรับสองคน\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns) · [British Council — Few, a few, little, a bit of](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/quantifiers-few-a-few-little-a-bit)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a11d4116-2899-584b-a110-d5de29c09912'::uuid,'4931c7f6-0850-518b-a509-b4899a11fd45'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/7ee3fa5b8287ab02-lesson-14-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I have a few friends.. I have few friends.. We have a little time.. We have little time."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('415dffac-5728-55ad-ab07-02454930800a'::uuid,'4931c7f6-0850-518b-a509-b4899a11fd45'::uuid,'multiple_choice',1,'{"question":"มีแอปเปิลอยู่บ้างเพียงพอเล็กน้อย ใช้คำใด?","choices":[{"id":"choice_1","text":"a few apples"},{"id":"choice_2","text":"a little apples"},{"id":"choice_3","text":"a few rice"}],"correctChoiceId":"choice_1","explanation":"apples เป็น countable plural ใช้ a few"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2f2e645d-6a39-528a-ae9f-46b1655aaf13'::uuid,'4931c7f6-0850-518b-a509-b4899a11fd45'::uuid,'multiple_choice',1,'{"question":"We have little water. สื่อมุมมองใด?","choices":[{"id":"choice_1","text":"เน้นว่าน้ำน้อย"},{"id":"choice_2","text":"น้ำมาก"},{"id":"choice_3","text":"น้ำทั้งหมด"}],"correctChoiceId":"choice_1","explanation":"little ไม่มี a เน้นน้อยจนเป็นข้อจำกัด"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('099ca18f-6a44-5d33-af7a-579bfc6540c4'::uuid,'4931c7f6-0850-518b-a509-b4899a11fd45'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสองคู่ few/a few และ little/a little พร้อมบอกมุมมองต่างกัน\n\n### ตัวอย่างคำตอบ\n\nI have a few books, so I can read. I have few books, so I need more. We have a little water. We have little water, so we need to buy some.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **few/a few/little/a little** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3ad72a4f-22f8-5eb3-a43e-32a19aaba5ab'::uuid,'573ae342-69ba-5f65-af6d-64451ac6fcc6'::uuid,'reading',1,'{"title":"all/most/both/each/every","body":"## all/most/both/each/every\n\nall ทุกคนหรือทั้งหมด most ส่วนใหญ่ both ทั้งสอง each/every มองสมาชิกทีละคนและตามด้วย singular noun/verb เช่น Every student has a book. both ตามด้วย plural เช่น Both students have books. either เลือกอย่างใดอย่างหนึ่งในสอง; neither ไม่เลือกทั้งสอง ใช้ either/neither + singular noun ในรูปพื้นฐาน some of/all of ตามด้วยกลุ่มที่กำหนด เช่น some of the students/all of them\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Every student has a pen. | singular หลัง every |\n| Both students have pens. | ทั้งสอง plural |\n| Some of the books are new. | ส่วนหนึ่งของกลุ่มเฉพาะ |\n\n### จุดที่มักสับสน\n\nไม่ใช้ every students; แต่ all the students ถูก ต้องดู determiner และจำนวน\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns) · [British Council — Few, a few, little, a bit of](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/quantifiers-few-a-few-little-a-bit)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bc4eb94f-a453-5e0b-ab58-b0b2657557cf'::uuid,'573ae342-69ba-5f65-af6d-64451ac6fcc6'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/0685fa18c6a1c08a-lesson-14-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Every student has a pen.. Both students have pens.. Some of the books are new."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f65db4a3-572f-5cd8-a5e2-c54fb09024d2'::uuid,'573ae342-69ba-5f65-af6d-64451ac6fcc6'::uuid,'multiple_choice',1,'{"question":"Every student … a book.","choices":[{"id":"choice_1","text":"have"},{"id":"choice_2","text":"has"},{"id":"choice_3","text":"are"}],"correctChoiceId":"choice_2","explanation":"every + singular student ใช้ has"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8e22bab7-b4e4-536d-a9f6-c3bbfc41fd41'::uuid,'573ae342-69ba-5f65-af6d-64451ac6fcc6'::uuid,'multiple_choice',1,'{"question":"both หมายถึงจำนวนใด?","choices":[{"id":"choice_1","text":"หนึ่งจากสอง"},{"id":"choice_2","text":"ทั้งสอง"},{"id":"choice_3","text":"ไม่มีทั้งสอง"}],"correctChoiceId":"choice_2","explanation":"both รวมสมาชิกสองสิ่ง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('80d0de15-eb27-539e-a95a-8f072f5c2523'::uuid,'573ae342-69ba-5f65-af6d-64451ac6fcc6'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบรรยายกลุ่มเพื่อนสมมติ ใช้ all/most/both/every และตัวเลือก either/neither\n\n### ตัวอย่างคำตอบ\n\nAll my friends study English. Most of them like music. Both my sisters have phones. Every student has a book. Neither answer is correct.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **all/most/both/each/every** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6087e644-dba6-52f2-a4fe-36a0883f014c'::uuid,'0079bd6e-64cb-5942-afe9-2a0ac6c86f55'::uuid,'reading',1,'{"title":"ปริมาณที่มากเกินหรือเพียงพอ","body":"## ปริมาณที่มากเกินหรือเพียงพอ\n\ntoo many + countable plural และ too much + uncountable หมายถึงมากเกินที่เหมาะ ไม่ใช่เพียงมาก enough + noun บอกเพียงพอ เช่น enough chairs/not enough water จำนวนเพียงพอขึ้นกับความต้องการ ต้องเทียบข้อมูล เช่นมีสี่เก้าอี้แต่ห้าคน คือ not enough chairs\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| too many bags | กระเป๋ามากเกิน |\n| too much sugar | น้ำตาลมากเกิน |\n| enough chairs | เก้าอี้เพียงพอ |\n\n### จุดที่มักสับสน\n\nenough + noun ต่างจาก adjective + enough ที่เรียน M16; many กับ too many มีจุดประเมินต่างกัน\n\n\n\n### ดูภาพแล้วลองใช้\n\n![แอปเปิลสามผล น้ำสองขวด ข้าวหนึ่งชาม ขนมปังหนึ่งก้อนกับสองแผ่นและนมหนึ่งแก้ว](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f82199a419ee302a-pantry-counting.png)\n\n*Three apples, two bottles of water, a bowl of rice, a loaf of bread, two slices of bread and a glass of milk.*\n\nแยกสิ่งที่นับโดยตรงจากปริมาณที่ต้องมีหน่วย แล้วเขียนรายการเตรียมอาหารสำหรับสองคน\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Countable and uncountable nouns](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/countable-uncountable-nouns) · [British Council — Few, a few, little, a bit of](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2-grammar/quantifiers-few-a-few-little-a-bit)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2655863a-6d3a-508b-a5de-3632ce2a6be9'::uuid,'0079bd6e-64cb-5942-afe9-2a0ac6c86f55'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/40a916248f18afc9-lesson-14-07.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"too many bags. too much sugar. enough chairs"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4fc2036c-6f67-50ec-a297-810d9bac2564'::uuid,'0079bd6e-64cb-5942-afe9-2a0ac6c86f55'::uuid,'multiple_choice',1,'{"question":"มีหกคนแต่เก้าอี้สี่ตัว คำใดตรง?","choices":[{"id":"choice_1","text":"enough chairs"},{"id":"choice_2","text":"not enough chairs"},{"id":"choice_3","text":"too much chairs"}],"correctChoiceId":"choice_2","explanation":"จำนวนเก้าอี้ไม่พอต่อคน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c33c7353-fe22-53fb-a592-e00f3ef75c99'::uuid,'0079bd6e-64cb-5942-afe9-2a0ac6c86f55'::uuid,'multiple_choice',1,'{"question":"ชามีน้ำตาลมากเกิน ใช้รูปใด?","choices":[{"id":"choice_1","text":"too many sugar"},{"id":"choice_2","text":"too much sugar"},{"id":"choice_3","text":"sugar enough too"}],"correctChoiceId":"choice_2","explanation":"sugar uncountable ใช้ too much"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('45a7ab04-349b-5a8b-a712-a41c7350da3d'::uuid,'0079bd6e-64cb-5942-afe9-2a0ac6c86f55'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nจัดของสำหรับสามคนแล้วบอกสิ่งพอ ไม่พอและมากเกิน\n\n### ตัวอย่างคำตอบ\n\nWe have enough cups for three people. We don’t have enough water. We have too many spoons.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ปริมาณที่มากเกินหรือเพียงพอ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1dcee838-4a3d-5c06-ae40-c46a7db92b00'::uuid,'b396853a-9e80-5db0-ab0a-b918301f9423'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เลือกคำนาม หน่วยนับ และ quantifier ให้ตรงปริมาณที่สื่อ**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![นับหน่วยหรือบอกปริมาณ: many apples; much water; two bottles of water](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2bff1ab62e3ed0e1-module-14-map.png)\n\n*a few apples  •  a little rice  •  enough + noun*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('91eea593-7351-58d6-a151-8e55cf5ce340'::uuid,'b396853a-9e80-5db0-ab0a-b918301f9423'::uuid,'multiple_choice',1,'{"question":"How … milk do we need?","choices":[{"id":"choice_1","text":"many"},{"id":"choice_2","text":"much"},{"id":"choice_3","text":"few"}],"correctChoiceId":"choice_2","explanation":"milk uncountable ใช้ much ย้อน 14.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f41ef361-8f3c-5a7b-a8e7-f1c035a656ec'::uuid,'b396853a-9e80-5db0-ab0a-b918301f9423'::uuid,'multiple_choice',1,'{"question":"มีเวลาอยู่บ้าง คำใดตรง?","choices":[{"id":"choice_1","text":"a little time"},{"id":"choice_2","text":"a few time"},{"id":"choice_3","text":"many time"}],"correctChoiceId":"choice_1","explanation":"a little ใช้ uncountable ย้อน 14.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('90a3b2f1-1b69-5e6c-a29b-eb09286f6032'::uuid,'b396853a-9e80-5db0-ab0a-b918301f9423'::uuid,'multiple_choice',1,'{"question":"มีสามคนแต่สองแก้ว สื่อว่าอะไร?","choices":[{"id":"choice_1","text":"not enough cups"},{"id":"choice_2","text":"too much cups"},{"id":"choice_3","text":"enough cups"}],"correctChoiceId":"choice_1","explanation":"จำนวนแก้วไม่พอ ย้อน 14.07"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('909cf5b3-2bb6-550f-aa01-88f219333ba3'::uuid,'b396853a-9e80-5db0-ab0a-b918301f9423'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nวางรายการอาหารสำหรับสามคน ใช้หน่วยนับ some/any และคำพอหรือไม่พอ\n\n### ตัวอย่างผลงาน\n\nWe need three bottles of water and some rice. We have a few apples, but we don’t have enough cups. Every person needs a cup.\n\n### ตรวจผลงาน\n\n- countability และหน่วยถูก\n- many/much/few/little ตรง noun\n- ประเมิน enough เทียบจำนวนคนจริง\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f534b7b4-a71a-5a97-a343-63e240a40885'::uuid,'8e7ea35f-1e79-55be-ae2a-7fc1f3f84059'::uuid,'reading',1,'{"title":"someone/anyone/everyone/no one","body":"## someone/anyone/everyone/no one\n\nsomeone/somebody หมายถึงคนหนึ่งที่ไม่ระบุ anyone/anybody ใช้คำถามหรือปฏิเสธทั่วไป และอาจหมายถึงใครก็ได้ตามบริบท everyone/everybody คือทุกคน no one/nobody คือไม่มีใคร กลุ่มคำเหล่านี้ใช้กริยาเอกพจน์ เช่น Everyone is here. ใช้ they อ้างกลับแบบไม่ระบุเพศได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Someone is at the door. | คนหนึ่ง |\n| Is anyone here? | มีใครไหม |\n| Everyone has a book. | ทุกคน แต่ verb เอกพจน์ |\n\n### จุดที่มักสับสน\n\neveryone ไม่ใช่ every people และไม่ใช้ Everyone are ในอังกฤษมาตรฐาน\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Indefinite pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/indefinite-pronouns) · [British Council — Reflexive pronouns, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/reflexive-pronouns) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ea01837b-8970-59e2-a812-fbdb45b1fa17'::uuid,'8e7ea35f-1e79-55be-ae2a-7fc1f3f84059'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/60b6656329b5f2c5-lesson-15-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Someone is at the door.. Is anyone here?. Everyone has a book."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e353ac69-d031-5c36-a868-e5622c957b0f'::uuid,'8e7ea35f-1e79-55be-ae2a-7fc1f3f84059'::uuid,'multiple_choice',1,'{"question":"Everyone … ready.","choices":[{"id":"choice_1","text":"are"},{"id":"choice_2","text":"is"},{"id":"choice_3","text":"am"}],"correctChoiceId":"choice_2","explanation":"everyone ใช้ singular verb is"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('40b8dbff-f626-54f7-abe9-a9295a5b4ccb'::uuid,'8e7ea35f-1e79-55be-ae2a-7fc1f3f84059'::uuid,'multiple_choice',1,'{"question":"ไม่มีใครอยู่ในห้อง ใช้คำใด?","choices":[{"id":"choice_1","text":"Someone is in the room."},{"id":"choice_2","text":"No one is in the room."},{"id":"choice_3","text":"Everyone is in the room."}],"correctChoiceId":"choice_2","explanation":"No one หมายถึงไม่มีใคร"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ce121995-7aa5-5e4d-ad3a-f8c29915e7ba'::uuid,'8e7ea35f-1e79-55be-ae2a-7fc1f3f84059'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบรรยายห้องสมมติด้วย someone, everyone และ no one สามประโยค\n\n### ตัวอย่างคำตอบ\n\nSomeone is near the door. Everyone has a pen. No one is late.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **someone/anyone/everyone/no one** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b7d8cc8d-bd68-5fac-ad87-f3e4d98203d4'::uuid,'f070ef3e-aaf2-5891-a2e8-ad3cf58107a6'::uuid,'reading',1,'{"title":"something/anything/nothing และสถานที่","body":"## something/anything/nothing และสถานที่\n\nsomething/anything/nothing แทนสิ่งที่ไม่ระบุ ส่วน somewhere/anywhere/everywhere/nowhere แทนสถานที่ รูป some/any อาจแทน noun ที่รู้จากบริบท เช่น Do you have rice? Yes, I have some. nothing/nowhere มีปฏิเสธในตัว ไม่ใช้ not ซ้ำในรูปมาตรฐานที่ฝึก\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I want something to eat. | สิ่งหนึ่ง |\n| I don’t know anything. | ไม่รู้อะไร |\n| I know nothing. | ความหมายปฏิเสธโดย nothing |\n| Let’s go somewhere quiet. | ที่หนึ่งที่เงียบ |\n\n### จุดที่มักสับสน\n\nI don’t know nothing ไม่ใช่รูปที่สอนในหลักสูตรนี้; adjective มักอยู่หลัง something เช่น something new\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Indefinite pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/indefinite-pronouns) · [British Council — Reflexive pronouns, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/reflexive-pronouns) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a2458b22-6fe2-5c1c-af50-bb37a86d1a6c'::uuid,'f070ef3e-aaf2-5891-a2e8-ad3cf58107a6'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/6870c84e7890fc86-lesson-15-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I want something to eat.. I don’t know anything.. I know nothing.. Let’s go somewhere quiet."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d2fc36f3-1924-54aa-a90e-f39c7321762e'::uuid,'f070ef3e-aaf2-5891-a2e8-ad3cf58107a6'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคปฏิเสธมาตรฐาน","choices":[{"id":"choice_1","text":"I don’t see nothing."},{"id":"choice_2","text":"I don’t see anything."},{"id":"choice_3","text":"I not see anything."}],"correctChoiceId":"choice_2","explanation":"don’t กับ anything ไม่ซ้อนปฏิเสธ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bce856d5-cc4c-5e3d-ac33-7080b30a9d33'::uuid,'f070ef3e-aaf2-5891-a2e8-ad3cf58107a6'::uuid,'multiple_choice',1,'{"question":"ข้อใดหมายถึงสถานที่?","choices":[{"id":"choice_1","text":"something"},{"id":"choice_2","text":"somewhere"},{"id":"choice_3","text":"someone"}],"correctChoiceId":"choice_2","explanation":"somewhere แทนสถานที่"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('14ce3584-bcbb-5091-ac13-958fb4c355fe'::uuid,'f070ef3e-aaf2-5891-a2e8-ad3cf58107a6'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสิ่งที่ต้องการ สถานที่ที่อยากไป และสิ่งที่ไม่เห็นโดยใช้ indefinite pronouns\n\n### ตัวอย่างคำตอบ\n\nI want something cold. I want to go somewhere quiet. I don’t see anything on the table.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **something/anything/nothing และสถานที่** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e39f8d12-e90e-51dd-a3f1-d4b2242c2e0a'::uuid,'726e9f69-f65d-5eac-a75a-fb5c441ba27a'::uuid,'reading',1,'{"title":"one/ones","body":"## one/ones\n\none แทนคำนามนับได้เอกพจน์และ ones แทนพหูพจน์ที่กล่าวถึงแล้ว เช่น Which bag? The blue one. หรือ Which shoes? The black ones. ใช้เพื่อไม่พูด noun ซ้ำ แต่ไม่ใช้ one แทน uncountable quantity ทั่วไป เช่น rice ต้องใช้ some หรือหน่วยที่นับได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I want the blue one. | one แทน bag หนึ่งใบ |\n| I like the small ones. | ones แทนสิ่งหลายชิ้น |\n| This cup is big. That one is small. | อ้าง cup อีกใบ |\n\n### จุดที่มักสับสน\n\none/ones ต้องมี noun ที่อ้างกลับได้ ไม่ใช้ water one ในความหมายปริมาณน้ำทั่วไป\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Indefinite pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/indefinite-pronouns) · [British Council — Reflexive pronouns, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/reflexive-pronouns) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0c09d414-9c7a-5790-ad3c-58bfb7dd4682'::uuid,'726e9f69-f65d-5eac-a75a-fb5c441ba27a'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/772206586931a830-lesson-15-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I want the blue one.. I like the small ones.. This cup is big. That one is small."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9e5a813f-d9d7-5ddf-a4c3-4b8bf85508e0'::uuid,'726e9f69-f65d-5eac-a75a-fb5c441ba27a'::uuid,'multiple_choice',1,'{"question":"พูดถึงเสื้อหนึ่งตัว: I like the red …","choices":[{"id":"choice_1","text":"one"},{"id":"choice_2","text":"ones"},{"id":"choice_3","text":"some"}],"correctChoiceId":"choice_1","explanation":"one แทน singular shirt"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('668a785a-29c5-5935-a2b8-eddddfb5ceac'::uuid,'726e9f69-f65d-5eac-a75a-fb5c441ba27a'::uuid,'multiple_choice',1,'{"question":"พูดถึงรองเท้าหลายคู่: The new … are nice.","choices":[{"id":"choice_1","text":"one"},{"id":"choice_2","text":"ones"},{"id":"choice_3","text":"it"}],"correctChoiceId":"choice_2","explanation":"ones แทน plural shoes"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('225f6702-86e2-5034-a7f0-815717195533'::uuid,'726e9f69-f65d-5eac-a75a-fb5c441ba27a'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนบทเลือกสิ่งของหนึ่งกับหลายโดยไม่พูด noun ซ้ำ\n\n### ตัวอย่างคำตอบ\n\nWhich cup do you want? The blue one. Which books do you like? The small ones.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **one/ones** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d2f0498e-8c31-5395-a165-a87685a71b12'::uuid,'b6270c04-8f70-56f7-ab7a-71bd16139a78'::uuid,'reading',1,'{"title":"another/other/the other","body":"## another/other/the other\n\nanother + singular countable หมายถึงอีกหนึ่งหรือเพิ่มหนึ่ง other + plural/uncountable หมายถึงอื่น ๆ the other ชี้อีกสิ่งที่เหลือในชุดที่รู้ เช่นมีสองใบใบนี้กับอีกใบ others แทนคำนามหลายสิ่งโดยไม่ตาม noun และ the others ชี้กลุ่มที่เหลือที่ระบุได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I need another cup. | เพิ่มอีกหนึ่ง |\n| I have other books. | หนังสืออื่น ๆ |\n| I have two bags. One is blue; the other is red. | อีกใบที่เหลือ |\n\n### จุดที่มักสับสน\n\nไม่ใช้ another cups ในรูปพื้นฐาน; other books มี noun แต่ others ไม่มี noun ตาม\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Indefinite pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/indefinite-pronouns) · [British Council — Reflexive pronouns, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/reflexive-pronouns) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('51ba414c-0bd4-5839-a88f-173c0aae2891'::uuid,'b6270c04-8f70-56f7-ab7a-71bd16139a78'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9deadf23725e86ff-lesson-15-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I need another cup.. I have other books.. I have two bags. One is blue; the other is red."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('902d7dca-3f4c-5ed4-aa2b-44fabc2d0ef7'::uuid,'b6270c04-8f70-56f7-ab7a-71bd16139a78'::uuid,'multiple_choice',1,'{"question":"ต้องการแก้วเพิ่มอีกหนึ่งใบ ใช้รูปใด?","choices":[{"id":"choice_1","text":"another cup"},{"id":"choice_2","text":"other cup"},{"id":"choice_3","text":"others cup"}],"correctChoiceId":"choice_1","explanation":"another + singular countable"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9b6601a9-88ae-558e-a003-4ed2eb1b00ed'::uuid,'b6270c04-8f70-56f7-ab7a-71bd16139a78'::uuid,'multiple_choice',1,'{"question":"มีรองเท้าสองคู่ อ้างอีกคู่ที่เหลือใช้คำใด?","choices":[{"id":"choice_1","text":"the other pair"},{"id":"choice_2","text":"another pairs"},{"id":"choice_3","text":"others pair"}],"correctChoiceId":"choice_1","explanation":"the other ระบุสมาชิกที่เหลือจากชุดสอง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6243e3d1-2aea-5790-a3b6-692db97987a4'::uuid,'b6270c04-8f70-56f7-ab7a-71bd16139a78'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนหนึ่งสถานการณ์เพิ่มของกับหนึ่งสถานการณ์เลือกสองสิ่ง\n\n### ตัวอย่างคำตอบ\n\nI need another pen. I have two cups. One is white; the other is blue. Some books are new; the others are old.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **another/other/the other** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2425e593-2de9-56a7-af7e-c9ec3f19495a'::uuid,'bb2e6b0a-f3e7-5a4e-ad1e-3ea450f45bb3'::uuid,'reading',1,'{"title":"myself/yourself และ each other","body":"## myself/yourself และ each other\n\nmyself/yourself/himself/herself/itself/ourselves/yourselves/themselves ใช้เมื่อผู้ทำกับผู้รับเป็นคนเดียวกัน เช่น I cut myself. วลี by myself หมายถึงคนเดียวหรือทำเอง ไม่เหมือน with me ที่มีคนไปด้วย each other หมายถึงต่างคนทำต่อกัน เช่น They help each other. ต่างจาก They help themselves. ที่ช่วยตนเอง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I wash myself. | ผู้ทำกับผู้รับคนเดียว |\n| I go by myself. | ไปคนเดียว |\n| We help each other. | ช่วยกัน |\n| We help ourselves. | แต่ละคนช่วยตัวเอง |\n\n### จุดที่มักสับสน\n\nไม่ใช้ myself แทน me ทุกตำแหน่ง เช่น Ben helps me. ไม่ใช่ Ben helps myself.\n\n\n\n### ดูภาพแล้วลองใช้\n\n![อ้างกลับให้ชัดเจน: Everyone is ready.; the blue one; help yourself / help each other](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/34ef77dff8595e3a-module-15-map.png)\n\n*ดูจำนวน หน้าที่และสิ่งที่อ้างกลับ ไม่แปลคำโดดอย่างเดียว*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Indefinite pronouns](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/indefinite-pronouns) · [British Council — Reflexive pronouns, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/reflexive-pronouns) · [Cambridge Dictionary — Determiners](https://dictionary.cambridge.org/grammar/british-grammar/determiners-the-my-some-this)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c24c8885-00d6-509e-a8e8-bed585c8b9d9'::uuid,'bb2e6b0a-f3e7-5a4e-ad1e-3ea450f45bb3'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9d6abbac079bb4f3-lesson-15-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I wash myself.. I go by myself.. We help each other.. We help ourselves."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bd0477eb-a60b-57ff-a361-329a022f8645'::uuid,'bb2e6b0a-f3e7-5a4e-ad1e-3ea450f45bb3'::uuid,'multiple_choice',1,'{"question":"สองคนช่วยกัน ใช้คำใด?","choices":[{"id":"choice_1","text":"They help each other."},{"id":"choice_2","text":"They help themselves. เท่านั้น"},{"id":"choice_3","text":"They help myself."}],"correctChoiceId":"choice_1","explanation":"each other เป็นการทำต่อกัน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ae582291-57ef-55d9-a521-6f9e4c5b8f06'::uuid,'bb2e6b0a-f3e7-5a4e-ad1e-3ea450f45bb3'::uuid,'multiple_choice',1,'{"question":"I go by myself หมายถึงอะไร?","choices":[{"id":"choice_1","text":"ไปกับเพื่อน"},{"id":"choice_2","text":"ไปคนเดียว"},{"id":"choice_3","text":"เพื่อนพาฉันไป"}],"correctChoiceId":"choice_2","explanation":"by myself คือไปลำพัง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('86f207f9-a178-58b9-aa0f-5fe4fa5a6456'::uuid,'bb2e6b0a-f3e7-5a4e-ad1e-3ea450f45bb3'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนประโยคทำเอง ไปคนเดียวและช่วยกัน รวมสามข้อ\n\n### ตัวอย่างคำตอบ\n\nI teach myself. I study by myself. My friends help each other.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **myself/yourself และ each other** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('599867fc-3788-5412-ab47-6883e9f0d683'::uuid,'64b66412-766d-5a39-a6aa-cedf7691cbc5'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **อ้างถึงคน สิ่งของ และตัวเองได้โดยไม่สับสนจำนวนหรือกรรม**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![อ้างกลับให้ชัดเจน: Everyone is ready.; the blue one; help yourself / help each other](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/34ef77dff8595e3a-module-15-map.png)\n\n*ดูจำนวน หน้าที่และสิ่งที่อ้างกลับ ไม่แปลคำโดดอย่างเดียว*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('da601114-191c-5423-a97e-bbec0d99f605'::uuid,'64b66412-766d-5a39-a6aa-cedf7691cbc5'::uuid,'multiple_choice',1,'{"question":"Nobody … here.","choices":[{"id":"choice_1","text":"is"},{"id":"choice_2","text":"are"},{"id":"choice_3","text":"am"}],"correctChoiceId":"choice_1","explanation":"nobody singular ย้อน 15.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('494bf3cb-e98d-5717-ae78-0b076226c87a'::uuid,'64b66412-766d-5a39-a6aa-cedf7691cbc5'::uuid,'multiple_choice',1,'{"question":"มีสองกระเป๋า อีกใบที่เหลือใช้รูปใด?","choices":[{"id":"choice_1","text":"the other bag"},{"id":"choice_2","text":"another bags"},{"id":"choice_3","text":"others bag"}],"correctChoiceId":"choice_1","explanation":"the other ระบุสิ่งที่เหลือ ย้อน 15.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e142b367-c581-5bf8-a475-1878ba295386'::uuid,'64b66412-766d-5a39-a6aa-cedf7691cbc5'::uuid,'multiple_choice',1,'{"question":"We teach ourselves หมายถึงอะไร?","choices":[{"id":"choice_1","text":"สอนตนเอง"},{"id":"choice_2","text":"สอนกันคนละคน"},{"id":"choice_3","text":"ครูสอนเรา"}],"correctChoiceId":"choice_1","explanation":"ourselves ผู้ทำกับผู้รับกลุ่มเดียว ย้อน 15.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9609b6da-5519-5afb-ad53-8a0853dbb621'::uuid,'64b66412-766d-5a39-a6aa-cedf7691cbc5'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเล่าเรื่องเลือกสิ่งของและคนในกลุ่มโดยมี one/ones, another/the other และ each other\n\n### ตัวอย่างผลงาน\n\nEveryone is ready. I want the blue one. I need another cup. Ben has two bags; the other one is red. We help each other.\n\n### ตรวจผลงาน\n\n- indefinite pronoun ใช้ verb ถูก\n- one/ones อ้าง noun ชัด\n- แยก reflexive กับ reciprocal\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a2c9675f-4b09-513a-ae2c-f31dbeaf3b50'::uuid,'283063a4-4416-5385-acdd-cf8eef08ce2d'::uuid,'reading',1,'{"title":"adjective กับ adverb","body":"## adjective กับ adverb\n\nadjective บรรยายคนหรือสิ่ง ส่วน adverb บรรยายการกระทำหรือระดับ หลายคำสร้างด้วย -ly: slow→slowly แต่ good→well เป็นรูปพิเศษ fast/hard ใช้รูปเดียวได้ทั้ง adjective/adverb friendly เป็น adjective แม้ลง -ly จึงต้องดูหน้าที่ ไม่ใช่ดูท้ายคำอย่างเดียว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| He is a careful driver. | careful บรรยาย driver |\n| He drives carefully. | carefully บรรยาย drives |\n| She is a good singer. She sings well. | good / well |\n\n### จุดที่มักสับสน\n\nHe is well. ใช้บอกสุขภาพได้อีกความหมาย ส่วนในงานร้องเพลงใช้ sings well ไม่ใช่ sings good ในอังกฤษมาตรฐานที่ฝึก\n\n\n\n### ดูภาพแล้วลองใช้\n\n![คุณลักษณะกับวิธีทำ: a careful driver; drives carefully; big enough / enough space](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/48b653e09fe9853c-module-16-map.png)\n\n*very = มาก  •  too = มากเกินเกณฑ์*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adverbials of manner](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/adverbials-manner) · [British Council — Adverbs of frequency](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/adverbs-frequency) · [British Council — Adjectives ending in -ed and -ing](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-ending-ed-ing)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('57227963-ac1f-5329-acb3-bbe52f51832d'::uuid,'283063a4-4416-5385-acdd-cf8eef08ce2d'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/c4dd92b1263e1d24-lesson-16-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"He is a careful driver.. He drives carefully.. She is a good singer. She sings well."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('030aad38-d639-54f2-a143-a04bec7babc0'::uuid,'283063a4-4416-5385-acdd-cf8eef08ce2d'::uuid,'multiple_choice',1,'{"question":"She speaks English …","choices":[{"id":"choice_1","text":"good"},{"id":"choice_2","text":"well"},{"id":"choice_3","text":"friendly"}],"correctChoiceId":"choice_2","explanation":"well ขยาย speaks"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c1bc6aac-aa16-5f3e-aed6-a7fc25ee0e17'::uuid,'283063a4-4416-5385-acdd-cf8eef08ce2d'::uuid,'multiple_choice',1,'{"question":"คำ friendly โดยทั่วไปเป็นอะไร?","choices":[{"id":"choice_1","text":"adjective"},{"id":"choice_2","text":"adverb เพราะลง ly เสมอ"},{"id":"choice_3","text":"verb"}],"correctChoiceId":"choice_1","explanation":"friendly บรรยายคน; -ly ไม่รับรอง adverb"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('88ba7e83-6fe1-5c69-a81b-5bd5fa5afbed'::uuid,'283063a4-4416-5385-acdd-cf8eef08ce2d'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนคู่ adjective/adverb ด้วย careful และ good\n\n### ตัวอย่างคำตอบ\n\nHe is careful. He works carefully. She is a good singer. She sings well.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **adjective กับ adverb** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9fbdc852-1840-56be-ac6f-1480a2d27019'::uuid,'bb4e9cb9-324a-596b-af4e-c1ad42c469f7'::uuid,'reading',1,'{"title":"บอกวิธีทำ","body":"## บอกวิธีทำ\n\nmanner adverbs เช่น carefully/quickly/badly บอกทำอย่างไร ตำแหน่งพื้นฐานหลัง verb หรือหลัง object เช่น She walks slowly. / She reads the letter carefully. ไม่แทรก adverb ระหว่างกริยากับกรรมในรูปธรรมดาที่กำลังฝึก บางตำแหน่งหน้ากริยาใช้ได้ตามจุดเน้น แต่เริ่มจากรูปที่ชัด\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| He opens the door carefully. | หลังกรรม |\n| She speaks slowly. | หลัง verb |\n| They did the work badly. | วิธีทำที่ไม่ดี |\n\n### จุดที่มักสับสน\n\nHe opens carefully the door ไม่เป็นลำดับเริ่มต้นธรรมชาติในรูปนี้ ใช้ opens the door carefully\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adverbials of manner](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/adverbials-manner) · [British Council — Adverbs of frequency](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/adverbs-frequency) · [British Council — Adjectives ending in -ed and -ing](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-ending-ed-ing)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4eaa7be3-8c1d-5749-a534-bd582b19632a'::uuid,'bb4e9cb9-324a-596b-af4e-c1ad42c469f7'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/fd710ecd2f0a7c58-lesson-16-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"He opens the door carefully.. She speaks slowly.. They did the work badly."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a2ee37f6-0f79-5df5-af6b-6e5fbbb54b5b'::uuid,'bb4e9cb9-324a-596b-af4e-c1ad42c469f7'::uuid,'multiple_choice',1,'{"question":"เลือกลำดับที่เป็นธรรมชาติในบทนี้","choices":[{"id":"choice_1","text":"She reads carefully the book."},{"id":"choice_2","text":"She reads the book carefully."},{"id":"choice_3","text":"She carefully the book reads."}],"correctChoiceId":"choice_2","explanation":"adverb หลัง object"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ddb19da2-0e36-5c4c-aeda-cf1fdea092f6'::uuid,'bb4e9cb9-324a-596b-af4e-c1ad42c469f7'::uuid,'multiple_choice',1,'{"question":"คำใดถาม manner?","choices":[{"id":"choice_1","text":"How does she drive?"},{"id":"choice_2","text":"When does she drive?"},{"id":"choice_3","text":"Whose car?"}],"correctChoiceId":"choice_1","explanation":"How ถามวิธีทำ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('73a2f7a6-396d-56c1-a68d-f94b294e8a8b'::uuid,'bb4e9cb9-324a-596b-af4e-c1ad42c469f7'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nอธิบายสามกิจกรรมโดยมีกรรมกับ adverb แล้วตอบ How…?\n\n### ตัวอย่างคำตอบ\n\nI wash the cups carefully. Ben finishes his work quickly. Mai speaks slowly.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **บอกวิธีทำ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f00b3cee-e994-50d6-ab94-2ee9dda58c3a'::uuid,'05df6b62-0d33-568a-a9ef-d8a3fb4c68c3'::uuid,'reading',1,'{"title":"ระดับความเข้ม","body":"## ระดับความเข้ม\n\nvery/really/quite/so/a bit/rather ขยายระดับของ adjective/adverb เช่น very tired/really slowly คำเหล่านี้มีน้ำหนักตามบริบท very คือมาก แต่ too คือมากเกินที่เหมาะหรือทำให้เป็นปัญหา เช่น very hot อาจเพียงร้อนมาก ส่วน too hot to drink ร้อนเกินจะดื่ม quite มีการใช้ต่างตามสำเนียงและ adjective จึงดูประโยคเต็ม\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The tea is very hot. | ร้อนมาก |\n| The tea is too hot to drink. | ร้อนเกินดื่ม |\n| I am a bit tired. | เหนื่อยเล็กน้อย |\n\n### จุดที่มักสับสน\n\nอย่าใช้ too แทน very ทุกครั้ง เพราะเพิ่มความหมายเกินเกณฑ์\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adverbials of manner](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/adverbials-manner) · [British Council — Adverbs of frequency](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/adverbs-frequency) · [British Council — Adjectives ending in -ed and -ing](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-ending-ed-ing)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('67e7c871-5114-5848-a408-f19bdace1cfd'::uuid,'05df6b62-0d33-568a-a9ef-d8a3fb4c68c3'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f5909e5898d6140b-lesson-16-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The tea is very hot.. The tea is too hot to drink.. I am a bit tired."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e3f544a1-dcd8-5fdc-a782-d027ae742936'::uuid,'05df6b62-0d33-568a-a9ef-d8a3fb4c68c3'::uuid,'multiple_choice',1,'{"question":"น้ำร้อนมากแต่ยังดื่มได้ ต้องการบอกระดับอย่างเดียวใช้คำใด?","choices":[{"id":"choice_1","text":"very hot"},{"id":"choice_2","text":"too hot to drink"},{"id":"choice_3","text":"not hot"}],"correctChoiceId":"choice_1","explanation":"very เน้นระดับไม่ยืนยันว่าเกินดื่ม"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f2309c7f-170c-577e-aaf8-55347c4c3342'::uuid,'05df6b62-0d33-568a-a9ef-d8a3fb4c68c3'::uuid,'multiple_choice',1,'{"question":"too heavy สื่ออะไร?","choices":[{"id":"choice_1","text":"หนักเกินเกณฑ์บางอย่าง"},{"id":"choice_2","text":"หนักนิดหน่อย"},{"id":"choice_3","text":"เบามาก"}],"correctChoiceId":"choice_1","explanation":"too มีความหมายเกินที่เหมาะในบริบท"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0e505b52-f4b1-5be3-a3c3-d68205b53a23'::uuid,'05df6b62-0d33-568a-a9ef-d8a3fb4c68c3'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบรรยายอาหารหรือสภาพสามอย่างด้วย very, a bit และ too พร้อมเหตุผลหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nThe room is very bright. I am a bit tired. The bag is too heavy to carry.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ระดับความเข้ม** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e13c377f-1f3c-599e-a6dd-72bd64b0c7d0'::uuid,'0f83e99b-7544-5b29-a286-b72f3fe00d66'::uuid,'reading',1,'{"title":"enough และ too + adjective","body":"## enough และ too + adjective\n\nenough อยู่หลัง adjective/adverb: old enough/quickly enough แต่หน้าคำนาม: enough time/ enough chairs too อยู่หน้า adjective เช่น too young และอาจตามด้วย to + verb เพื่อบอกผล เช่น too young to drive คำว่า enough ประเมินเทียบสิ่งที่ต้องทำ ไม่ได้หมายถึงมากที่สุด\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The room is big enough. | adjective + enough |\n| We have enough space. | enough + noun |\n| The box is too heavy to lift. | too + adjective |\n\n### จุดที่มักสับสน\n\nenough big ผิดในโครง adjective; ไม่ใช้ time enough เป็นรูปเริ่มต้นในบทนี้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adverbials of manner](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/adverbials-manner) · [British Council — Adverbs of frequency](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/adverbs-frequency) · [British Council — Adjectives ending in -ed and -ing](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-ending-ed-ing)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('25a03c29-bf32-5b96-af92-a5a2ea2c63d4'::uuid,'0f83e99b-7544-5b29-a286-b72f3fe00d66'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/c31e46404f274b55-lesson-16-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The room is big enough.. We have enough space.. The box is too heavy to lift."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4a543572-18f5-58fa-a942-90129bbb0eee'::uuid,'0f83e99b-7544-5b29-a286-b72f3fe00d66'::uuid,'multiple_choice',1,'{"question":"เลือกวลี adjective ที่ถูก","choices":[{"id":"choice_1","text":"enough tall"},{"id":"choice_2","text":"tall enough"},{"id":"choice_3","text":"tall many"}],"correctChoiceId":"choice_2","explanation":"enough หลัง adjective"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fa5896c4-e3bd-5eaa-a50c-1c2f31fdf180'::uuid,'0f83e99b-7544-5b29-a286-b72f3fe00d66'::uuid,'multiple_choice',1,'{"question":"We have … chairs for everyone.","choices":[{"id":"choice_1","text":"enough"},{"id":"choice_2","text":"chairs enough"},{"id":"choice_3","text":"too much"}],"correctChoiceId":"choice_1","explanation":"enough หน้าคำนาม plural chairs"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cdbb368b-451a-5116-a1a3-12e7abec9a1b'::uuid,'0f83e99b-7544-5b29-a286-b72f3fe00d66'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกสิ่งที่พอหรือไม่พอและสิ่งที่เกินไป โดยใช้ adjective และ noun\n\n### ตัวอย่างคำตอบ\n\nThe room is large enough. We have enough chairs. We don’t have enough time. The music is too loud.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **enough และ too + adjective** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bf598d09-3f01-59d0-a109-13ac29b79389'::uuid,'95de2cb7-6f7c-5533-a1a2-dcf111dfb267'::uuid,'reading',1,'{"title":"ตำแหน่งและการเพิ่มข้อมูล","body":"## ตำแหน่งและการเพิ่มข้อมูล\n\nคำบอก place/time/manner เพิ่มข้อมูลหลายชนิด เช่น He reads quietly at home every evening. ลำดับนี้เป็นรูปที่เริ่มใช้ได้แต่เปลี่ยนได้ตามจุดเน้น also มักอยู่ก่อนกริยาหลักหรือหลัง be; too มักท้ายบอกเล่า; either มักท้ายปฏิเสธ เช่น I don’t like it either. ตรวจว่าผู้ฟังเข้าใจข้อมูลแทนท่องลำดับเดียวใช้ทุกประโยค\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I also study English. | also ก่อน verb |\n| I am also a teacher. | also หลัง be |\n| I like tea too. / I don’t like coffee either. | ท้ายบอกเล่า / ปฏิเสธ |\n\n### จุดที่มักสับสน\n\ntoo ที่แปลว่าด้วยไม่ใช่ too + adjective ที่แปลว่าเกิน\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Adverbials of manner](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/adverbials-manner) · [British Council — Adverbs of frequency](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/adverbs-frequency) · [British Council — Adjectives ending in -ed and -ing](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-ending-ed-ing)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f484c642-cac2-5434-a41b-7ebd86ce13c3'::uuid,'95de2cb7-6f7c-5533-a1a2-dcf111dfb267'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/62f0c6246756d70d-lesson-16-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I also study English.. I am also a teacher.. I like tea too.. I don’t like coffee either."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b3b0f76e-1add-53f2-ab44-6a2b0b1e238f'::uuid,'95de2cb7-6f7c-5533-a1a2-dcf111dfb267'::uuid,'multiple_choice',1,'{"question":"I don’t drive. Ben doesn’t drive …","choices":[{"id":"choice_1","text":"too"},{"id":"choice_2","text":"either"},{"id":"choice_3","text":"alsoly"}],"correctChoiceId":"choice_2","explanation":"either ท้ายประโยคปฏิเสธ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1f6a3e75-56ae-5578-a461-0e2cbec76611'::uuid,'95de2cb7-6f7c-5533-a1a2-dcf111dfb267'::uuid,'multiple_choice',1,'{"question":"เลือกรูปที่เป็นธรรมชาติ","choices":[{"id":"choice_1","text":"She also reads books."},{"id":"choice_2","text":"She reads also books."},{"id":"choice_3","text":"She also books reads."}],"correctChoiceId":"choice_1","explanation":"also ก่อน main verb ในรูปนี้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('34436849-cd11-5890-a4d4-3408bdd9730e'::uuid,'95de2cb7-6f7c-5533-a1a2-dcf111dfb267'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nขยายกิจกรรมด้วยวิธีทำ สถานที่เวลา แล้วเพิ่มข้อมูลด้วย also/too/either\n\n### ตัวอย่างคำตอบ\n\nI read quietly at home every night. I also study English. Ben studies English too. We don’t study French either.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ตำแหน่งและการเพิ่มข้อมูล** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b8e212a4-927d-5a73-ad4e-5c4fc642beaa'::uuid,'581acb08-c5dd-5066-a023-40eaa3b5aca8'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **แยก adjective/adverb และขยายประโยคโดยไม่เปลี่ยนความหมายผิด**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![คุณลักษณะกับวิธีทำ: a careful driver; drives carefully; big enough / enough space](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/48b653e09fe9853c-module-16-map.png)\n\n*very = มาก  •  too = มากเกินเกณฑ์*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('35679b4a-5a91-5088-a90b-515d2cb44ffe'::uuid,'581acb08-c5dd-5066-a023-40eaa3b5aca8'::uuid,'multiple_choice',1,'{"question":"The child sings …","choices":[{"id":"choice_1","text":"well"},{"id":"choice_2","text":"good ในอังกฤษมาตรฐานบทนี้"},{"id":"choice_3","text":"friendly"}],"correctChoiceId":"choice_1","explanation":"well ขยาย sings ย้อน 16.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('aec3ed22-f80e-5732-a7d4-947dd3bb5208'::uuid,'581acb08-c5dd-5066-a023-40eaa3b5aca8'::uuid,'multiple_choice',1,'{"question":"The chair is … for me.","choices":[{"id":"choice_1","text":"high enough"},{"id":"choice_2","text":"enough high"},{"id":"choice_3","text":"enough highs"}],"correctChoiceId":"choice_1","explanation":"adjective + enough ย้อน 16.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2482acfe-39e9-5d87-abfa-73d608423efc'::uuid,'581acb08-c5dd-5066-a023-40eaa3b5aca8'::uuid,'multiple_choice',1,'{"question":"I don’t eat meat. Mai doesn’t …","choices":[{"id":"choice_1","text":"either"},{"id":"choice_2","text":"too"},{"id":"choice_3","text":"alsoly"}],"correctChoiceId":"choice_1","explanation":"either ท้ายปฏิเสธ ย้อน 16.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d3d997cf-8f97-51d3-a82a-a12ad0678dd5'::uuid,'581acb08-c5dd-5066-a023-40eaa3b5aca8'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nบรรยายวิธีทำสองกิจกรรม เปรียบเทียบ very/too และเพิ่มข้อมูลด้วย also/either\n\n### ตัวอย่างผลงาน\n\nI read slowly. Ben writes carefully. The tea is very hot, but it is not too hot to drink. I also study English. I don’t study French either.\n\n### ตรวจผลงาน\n\n- adjective/adverb ตามหน้าที่\n- very/too สื่อความหมายถูก\n- ตำแหน่ง enough และคำเพิ่มข้อมูลถูก\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4897ae70-0f89-5b2f-a50c-fb06f445b344'::uuid,'78ccd15f-544b-5dcb-aca8-38b27d8c41a6'::uuid,'reading',1,'{"title":"am/is/are + ing","body":"## am/is/are + ing\n\nPresent Continuous ใช้ am/is/are + verb-ing กับสิ่งกำลังเกิดตอนนี้หรือสถานการณ์ชั่วคราวในช่วงที่พูด เช่น I am reading now. / She is staying with a friend this week. ต้องมีทั้ง be และ ing ประธานกำหนดรูป be ไม่ใช่เติม s ที่ main verb\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I am reading a book. | กำลังอ่าน |\n| She is working this week. | ช่วงชั่วคราว |\n| They are playing now. | หลายคนใช้ are |\n\n### จุดที่มักสับสน\n\nShe working และ She is work ไม่เป็นรูป continuous ที่ถูก\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ผู้หญิงเสื้อฟ้าอ่านหนังสือ ผู้ชายเสื้อแดงวิ่ง คนสองคนเดินและสุนัขนอนใต้ต้นไม้](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/dd683d7c6dc8b68a-park-activities.png)\n\n*Four people are in the park. A woman is reading, a man is running, and two people are walking.*\n\nชี้คนที่หมายถึงก่อนบรรยาย แยกสิ่งที่เห็นตอนนี้จากกิจวัตรที่คุณต้องการสมมติ แล้วใช้รูปประโยคตามบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present continuous](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/present-continuous) · [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6338c370-e406-5949-a1e6-7c2123e69aed'::uuid,'78ccd15f-544b-5dcb-aca8-38b27d8c41a6'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/ac538888787896e2-lesson-17-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I am reading a book.. She is working this week.. They are playing now."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b436bedb-1112-5246-a6fa-3c9e6b50aaa7'::uuid,'78ccd15f-544b-5dcb-aca8-38b27d8c41a6'::uuid,'multiple_choice',1,'{"question":"They … football now.","choices":[{"id":"choice_1","text":"are playing"},{"id":"choice_2","text":"is play"},{"id":"choice_3","text":"playing"}],"correctChoiceId":"choice_1","explanation":"they ใช้ are + playing"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a638d287-f48c-5f90-a929-f7f48f82b34f'::uuid,'78ccd15f-544b-5dcb-aca8-38b27d8c41a6'::uuid,'multiple_choice',1,'{"question":"เลือกโครงสร้างที่ครบ","choices":[{"id":"choice_1","text":"I am studying."},{"id":"choice_2","text":"I studying."},{"id":"choice_3","text":"I am study."}],"correctChoiceId":"choice_1","explanation":"am + ing ครบสองส่วน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('48dffc2a-e8ae-5f40-a1f4-bf1ac250f66b'::uuid,'78ccd15f-544b-5dcb-aca8-38b27d8c41a6'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสิ่งที่คุณและคนสองคนกำลังทำตอนนี้\n\n### ตัวอย่างคำตอบ\n\nI am studying English. Mai is reading a book. Ben is drinking water.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **am/is/are + ing** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('67af567e-2e64-583e-adb6-9e193df83aa8'::uuid,'04bf0854-f793-551e-a93d-73c5717afd3e'::uuid,'reading',1,'{"title":"กฎเติม ing","body":"## กฎเติม ing\n\nปกติเติม ing: work→working; e ท้ายเงียบมักตัด: make→making; ie เปลี่ยนเป็น y: lie→lying; คำพยางค์เดียวสระสั้นตามด้วยพยัญชนะหนึ่งตัวมักซ้ำพยัญชนะ: run→running แต่ไม่ซ้ำ w/x/y และคำสองพยางค์ต้องดู stress เช่น begin→beginning ขณะที่ open→opening ฝึกคำที่ใช้จริงและตรวจรูปเมื่อไม่แน่ใจ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| make → making | ตัด e |\n| lie → lying | ie → y |\n| run → running | ซ้ำ n |\n| open → opening | ไม่เน้นพยางค์ท้าย ไม่ซ้ำ n |\n\n### จุดที่มักสับสน\n\nไม่ซ้ำตัวท้ายทุกคำ เช่น play→playing ไม่ใช่ playying; see→seeing ไม่ตัด e ทั้งชุด\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present continuous](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/present-continuous) · [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('79b01423-ff10-5f4f-a3b1-e7681b554f36'::uuid,'04bf0854-f793-551e-a93d-73c5717afd3e'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/b3235f9bc0d32f53-lesson-17-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"make ,  making. lie ,  lying. run ,  running. open ,  opening"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('dbb63db7-190c-5d7b-a9ec-3a88eeb636f2'::uuid,'04bf0854-f793-551e-a93d-73c5717afd3e'::uuid,'multiple_choice',1,'{"question":"ing ของ write คืออะไร?","choices":[{"id":"choice_1","text":"writeing"},{"id":"choice_2","text":"writing"},{"id":"choice_3","text":"writting"}],"correctChoiceId":"choice_2","explanation":"ตัด e แล้วเติม ing"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7889bc84-7950-524b-aaf6-fc95219b5427'::uuid,'04bf0854-f793-551e-a93d-73c5717afd3e'::uuid,'multiple_choice',1,'{"question":"ing ของ swim คืออะไร?","choices":[{"id":"choice_1","text":"swiming"},{"id":"choice_2","text":"swimming"},{"id":"choice_3","text":"swimying"}],"correctChoiceId":"choice_2","explanation":"สระสั้นตามด้วยพยัญชนะเดียวในพยางค์เดียว ซ้ำ m"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8cf8b0c1-2b6b-5202-a406-3274c1fa1ce5'::uuid,'04bf0854-f793-551e-a93d-73c5717afd3e'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียน ing ของ go, make, sit, lie, play แล้วใช้สองคำในประโยค\n\n### ตัวอย่างคำตอบ\n\ngoing; making; sitting; lying; playing. She is making tea. We are sitting here.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **กฎเติม ing** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('14ed37ce-4972-553a-a4be-ee51083def14'::uuid,'e595cde3-56e1-596f-a324-8537e5589228'::uuid,'reading',1,'{"title":"ปฏิเสธและคำถาม","body":"## ปฏิเสธและคำถาม\n\nปฏิเสธ continuous เติม not หลัง be: She isn’t working. คำถามย้าย be หน้าประธาน: Are they studying? Wh-question วางคำถามก่อน be: What are you doing? คำตอบสั้นใช้ be ไม่ใช่ do: Yes, I am./No, he isn’t. main verb คง ing ทุกประธาน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Are you reading? — Yes, I am. | be ในคำถามและคำตอบ |\n| What is Ben doing? — He is cooking. | Wh + be |\n| They aren’t working. | not หลัง be |\n\n### จุดที่มักสับสน\n\nDoes she working? และ Is she works? ผิดเพราะสลับระบบกับ Present Simple\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present continuous](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/present-continuous) · [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cbfc9eac-ac06-5aa4-a85c-73f084be1d07'::uuid,'e595cde3-56e1-596f-a324-8537e5589228'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/17c15a3feacc8df6-lesson-17-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Are you reading?. Yes, I am.. What is Ben doing?. He is cooking.. They aren’t working."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f6350c59-20ad-5756-a685-9aa5e8ab554f'::uuid,'e595cde3-56e1-596f-a324-8537e5589228'::uuid,'multiple_choice',1,'{"question":"เลือกคำถาม continuous ที่ถูก","choices":[{"id":"choice_1","text":"Does he studying?"},{"id":"choice_2","text":"Is he studying?"},{"id":"choice_3","text":"Is he studies?"}],"correctChoiceId":"choice_2","explanation":"Is + he + studying"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('32a6533e-3f24-5774-a9bf-9a3c4de67be8'::uuid,'e595cde3-56e1-596f-a324-8537e5589228'::uuid,'multiple_choice',1,'{"question":"Are they walking? — No, …","choices":[{"id":"choice_1","text":"they don’t"},{"id":"choice_2","text":"they aren’t"},{"id":"choice_3","text":"they isn’t"}],"correctChoiceId":"choice_2","explanation":"คำถาม are ตอบ aren’t"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8dc64e7b-0a65-5e79-a811-09b077230411'::uuid,'e595cde3-56e1-596f-a324-8537e5589228'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nถามและตอบสิ่งกำลังทำสองข้อ แล้วเขียนปฏิเสธหนึ่งประโยค\n\n### ตัวอย่างคำตอบ\n\nWhat are you doing? I am reading. Is Ben cooking? No, he isn’t. He isn’t cooking; he is eating.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ปฏิเสธและคำถาม** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('607233c0-c698-5cd3-a0c0-1dc719056795'::uuid,'2b5c11c6-ef4c-579d-a39c-e544bbf491ed'::uuid,'reading',1,'{"title":"Present Simple เทียบ Continuous","body":"## Present Simple เทียบ Continuous\n\nPresent Simple ใช้กิจวัตรหรือสภาพทั่วไป ส่วน Continuous ใช้กิจกรรมกำลังเกิดหรือชั่วคราว เปรียบเทียบ She usually walks, but today she is taking a bus. today ไม่ได้บังคับ continuous ทุกประโยค และ now กับ stative verb อาจยังใช้ simple จึงอ่านความหมายทั้งข้อความ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I work in Bangkok. | งานหรือสภาพปกติ |\n| I am working at home this week. | ชั่วคราว |\n| She usually walks, but she is taking a bus today. | กิจวัตรเทียบวันนี้ |\n\n### จุดที่มักสับสน\n\nคำบอกเวลาเป็นข้อมูลช่วย ไม่ใช่สูตรเลือก tense โดยไม่ดู verb และความหมาย\n\n\n\n### ดูภาพแล้วลองใช้\n\n![กิจวัตรกับกำลังทำ: She reads.; She is reading.; am / is / are + ing](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/aabc783af6dab850-module-17-map.png)\n\n*ดูความหมายทั้งประโยค  •  know/want มัก simple ในความหมายพื้นฐาน*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present continuous](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/present-continuous) · [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4bba6d41-5081-5623-ac87-1ef3c89f018e'::uuid,'2b5c11c6-ef4c-579d-a39c-e544bbf491ed'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/de33a26a147bedd1-lesson-17-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I work in Bangkok.. I am working at home this week.. She usually walks, but she is taking a bus today."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2886cad9-1285-5aea-acb5-23f75557a506'::uuid,'2b5c11c6-ef4c-579d-a39c-e544bbf491ed'::uuid,'multiple_choice',1,'{"question":"กิจวัตรทุกวัน: He … to school every day.","choices":[{"id":"choice_1","text":"walks"},{"id":"choice_2","text":"is walk"},{"id":"choice_3","text":"walking"}],"correctChoiceId":"choice_1","explanation":"ใช้ Present Simple กับกิจวัตร"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('897b663d-6dd4-51d6-ac15-d6dbf34840ca'::uuid,'2b5c11c6-ef4c-579d-a39c-e544bbf491ed'::uuid,'multiple_choice',1,'{"question":"กำลังอ่าน ณ ตอนนี้: She … a book at the moment.","choices":[{"id":"choice_1","text":"reads โดยบอกกำลังนี้"},{"id":"choice_2","text":"is reading"},{"id":"choice_3","text":"is read"}],"correctChoiceId":"choice_2","explanation":"กิจกรรมกำลังเกิดใช้ is + ing"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1b485c4e-0cc5-5832-ae6e-f677cca5a4bb'::uuid,'2b5c11c6-ef4c-579d-a39c-e544bbf491ed'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนกิจวัตรหนึ่งอย่างแล้วเปรียบเทียบสิ่งต่างไปที่กำลังทำวันนี้\n\n### ตัวอย่างคำตอบ\n\nI usually study at home, but today I am studying at the library.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Present Simple เทียบ Continuous** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('98b218b9-3ad4-5788-a45c-bcf523841e6c'::uuid,'7c260b9f-d5e9-5d4c-ac07-f1d08731e1f7'::uuid,'reading',1,'{"title":"กริยาสภาพที่พบบ่อย","body":"## กริยาสภาพที่พบบ่อย\n\nกริยาสภาพเช่น know/want/like/believe มักใช้ simple ในความหมายพื้นฐานแม้เป็นจริงขณะพูด I know the answer now. ไม่ใช่ I am knowing. แต่กริยาบางคำมีทั้งความหมายสภาพกับกิจกรรม เช่น I think it is good. แสดงความคิดเห็น เทียบ I am thinking about the problem. กำลังพิจารณา จึงไม่ห้าม ing ทุกความหมายของคำ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I want some water. | ความต้องการ |\n| I know her. | รู้จัก |\n| I think it is good. / I am thinking about it. | ความเห็น / กำลังคิดพิจารณา |\n\n### จุดที่มักสับสน\n\nไม่ใช้ I am wanting some water เป็นรูปเริ่มต้นทั่วไปในบทนี้ แต่ไม่เหมารวมว่ารูป ing เป็นไปไม่ได้ทุกบริบท\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present continuous](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/present-continuous) · [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('88fcfe2d-c9d0-5062-aefe-6d14c4052e37'::uuid,'7c260b9f-d5e9-5d4c-ac07-f1d08731e1f7'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9d224272f16fd9b4-lesson-17-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I want some water.. I know her.. I think it is good.. I am thinking about it."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8d06e38b-5570-57b9-a8a2-147abda37496'::uuid,'7c260b9f-d5e9-5d4c-ac07-f1d08731e1f7'::uuid,'multiple_choice',1,'{"question":"บอกว่ารู้คำตอบตอนนี้ เลือก","choices":[{"id":"choice_1","text":"I know the answer."},{"id":"choice_2","text":"I am knowing the answer."},{"id":"choice_3","text":"I knowing the answer."}],"correctChoiceId":"choice_1","explanation":"know ในความหมายรู้ข้อมูลเป็น stative"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bff43a56-15f5-58b6-a086-1d269d865f36'::uuid,'7c260b9f-d5e9-5d4c-ac07-f1d08731e1f7'::uuid,'multiple_choice',1,'{"question":"think ใน I am thinking about the plan สื่ออะไร?","choices":[{"id":"choice_1","text":"กำลังพิจารณาแผน"},{"id":"choice_2","text":"รู้จักคน"},{"id":"choice_3","text":"เป็นคำห้าม"}],"correctChoiceId":"choice_1","explanation":"think ใช้ continuous ได้เมื่อหมายถึงกิจกรรมคิดพิจารณา"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8af0a5b1-2ed6-539f-a94f-d69f79821319'::uuid,'7c260b9f-d5e9-5d4c-ac07-f1d08731e1f7'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสิ่งที่รู้ ต้องการและชอบสามประโยค แล้วเปรียบเทียบ think สองความหมาย\n\n### ตัวอย่างคำตอบ\n\nI know this word. I want tea. I like music. I think the plan is good. I am thinking about the plan.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **กริยาสภาพที่พบบ่อย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('422a262b-7c5c-53a5-a870-833be516c72e'::uuid,'591e3fbc-0dee-576f-a37d-d6b107bc5ac5'::uuid,'reading',1,'{"title":"อธิบายภาพและเหตุการณ์","body":"## อธิบายภาพและเหตุการณ์\n\nบรรยายภาพด้วย continuous สำหรับกิจกรรมที่เห็น เช่น The woman is reading. แล้วใช้ be/adjective หรือ wearing สำหรับเสื้อผ้า: She is wearing a blue shirt. สลับ pronouns เมื่ออ้างคนเดิมได้ชัด เพิ่มตำแหน่งเพื่อแยกคนหลายคน อย่าเดาความคิด อาชีพหรือเรื่องก่อนภาพจากสิ่งที่เห็นโดยไม่มีหลักฐาน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The man is sitting on a chair. | กิจกรรม |\n| He is wearing a red shirt. | การแต่งกาย |\n| Two people are walking behind him. | ตำแหน่งช่วยระบุกลุ่ม |\n\n### จุดที่มักสับสน\n\nShe is blue shirt ผิด ต้องใช้ She is wearing a blue shirt.; การนัดหมายอนาคตของ continuous จะเรียน M22\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ผู้หญิงเสื้อฟ้าอ่านหนังสือ ผู้ชายเสื้อแดงวิ่ง คนสองคนเดินและสุนัขนอนใต้ต้นไม้](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/dd683d7c6dc8b68a-park-activities.png)\n\n*Four people are in the park. A woman is reading, a man is running, and two people are walking.*\n\nชี้คนที่หมายถึงก่อนบรรยาย แยกสิ่งที่เห็นตอนนี้จากกิจวัตรที่คุณต้องการสมมติ แล้วใช้รูปประโยคตามบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present continuous](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/present-continuous) · [British Council — Present simple](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8747c6ff-382d-5ae1-a131-0d92ffe5f93f'::uuid,'591e3fbc-0dee-576f-a37d-d6b107bc5ac5'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/808333e6da45de24-lesson-17-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The man is sitting on a chair.. He is wearing a red shirt.. Two people are walking behind him."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a690b62a-7b1a-5fb3-a75a-2fed6cf31191'::uuid,'591e3fbc-0dee-576f-a37d-d6b107bc5ac5'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคบรรยายเสื้อผ้าถูก","choices":[{"id":"choice_1","text":"He is wearing a green shirt."},{"id":"choice_2","text":"He is green shirt."},{"id":"choice_3","text":"He wearing green shirt."}],"correctChoiceId":"choice_1","explanation":"be + wearing + noun phrase"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0801f21e-e6a2-54b5-a2dc-a96e3c5f432c'::uuid,'591e3fbc-0dee-576f-a37d-d6b107bc5ac5'::uuid,'multiple_choice',1,'{"question":"เมื่อเห็นคนถือหนังสือ ข้อมูลใดไม่ควรยืนยันโดยไม่มีหลักฐาน?","choices":[{"id":"choice_1","text":"เขาเป็นหมอ"},{"id":"choice_2","text":"เขากำลังถือหนังสือ"},{"id":"choice_3","text":"เสื้อของเขาสีที่เห็น"}],"correctChoiceId":"choice_1","explanation":"อาชีพไม่ปรากฏจากการถือหนังสือเพียงอย่างเดียว"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c128704e-d523-5ca0-a63b-76cee95a57f0'::uuid,'591e3fbc-0dee-576f-a37d-d6b107bc5ac5'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเลือกภาพคนอย่างน้อยสองคน บรรยายกิจกรรม ตำแหน่งและเสื้อผ้ารวมสี่ประโยค\n\n### ตัวอย่างคำตอบ\n\nA woman is reading on a bench. She is wearing a blue shirt. Two people are walking near her. A man is drinking water.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **อธิบายภาพและเหตุการณ์** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0e7d7158-0abc-53d2-a420-af21d0872122'::uuid,'641573f3-5a6e-5950-a5d4-5b965bb23ce3'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **แยกสิ่งที่ทำเป็นปกติจากสิ่งที่กำลังเกิดหรือเป็นชั่วคราว**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![กิจวัตรกับกำลังทำ: She reads.; She is reading.; am / is / are + ing](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/aabc783af6dab850-module-17-map.png)\n\n*ดูความหมายทั้งประโยค  •  know/want มัก simple ในความหมายพื้นฐาน*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ac47b413-9ee9-513a-aaa7-ef9c8f50a7f6'::uuid,'641573f3-5a6e-5950-a5d4-5b965bb23ce3'::uuid,'multiple_choice',1,'{"question":"At the moment, Tom … dinner.","choices":[{"id":"choice_1","text":"is making"},{"id":"choice_2","text":"makes โดยบอกกำลังทำ"},{"id":"choice_3","text":"is make"}],"correctChoiceId":"choice_1","explanation":"กำลังทำใช้ is + making ย้อน 17.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('244aafbe-4506-5f32-a624-9e9f1646a838'::uuid,'641573f3-5a6e-5950-a5d4-5b965bb23ce3'::uuid,'multiple_choice',1,'{"question":"Which ing form is correct?","choices":[{"id":"choice_1","text":"sitting"},{"id":"choice_2","text":"siting"},{"id":"choice_3","text":"siteing"}],"correctChoiceId":"choice_1","explanation":"sit ซ้ำ t ย้อน 17.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('26f35972-0faf-579b-a309-818633ac93bd'::uuid,'641573f3-5a6e-5950-a5d4-5b965bb23ce3'::uuid,'multiple_choice',1,'{"question":"บอกความชอบพื้นฐานตอนนี้ ใช้รูปใด?","choices":[{"id":"choice_1","text":"I like this song."},{"id":"choice_2","text":"I am liking this song. เป็นรูปเริ่มต้นทั่วไป"},{"id":"choice_3","text":"I liking this song."}],"correctChoiceId":"choice_1","explanation":"like ความหมายสภาพใช้ simple ย้อน 17.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('54e3cd6d-1651-5924-aab2-bdee6d389965'::uuid,'641573f3-5a6e-5950-a5d4-5b965bb23ce3'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nบรรยายภาพคนสองคนห้าประโยค แล้วเปรียบเทียบกิจวัตรของคุณกับวันนี้\n\n### ตัวอย่างผลงาน\n\nMai is reading. Ben is running. Mai is wearing a blue shirt. The dog is sleeping. I usually walk, but today I am taking a bus.\n\n### ตรวจผลงาน\n\n- be + ing ครบ\n- คำถามและปฏิเสธใช้ be\n- simple/continuous ตรงความหมายและไม่เดาข้อมูลจากภาพ\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('07f66d7f-4f84-5d7e-ac0a-fc6ca677d3c4'::uuid,'fb25b102-5690-57b5-a66c-361de0b6a356'::uuid,'reading',1,'{"title":"คำสั่งบอกเล่า–ปฏิเสธ","body":"## คำสั่งบอกเล่า–ปฏิเสธ\n\nคำสั่งใช้ base verb โดยปกติละ subject you: Open the door. ปฏิเสธใช้ Don’t + base: Don’t run. please ช่วยให้สุภาพแต่ยังต้องดูน้ำเสียงและความสัมพันธ์ คำสั่งสำหรับขั้นตอนใช้ First/Then ช่วยลำดับได้ ใช้กริยาชัดเพื่อให้ผู้ฟังทำตาม\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Sit down, please. | ขอให้นั่ง |\n| Don’t touch the screen. | ห้ามแตะ |\n| First, open the book. Then read. | ลำดับขั้น |\n\n### จุดที่มักสับสน\n\nDon’t to run และ Don’t running ไม่ใช่ imperative ที่ถูก\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cb923e28-ee8c-5c1e-a9b4-b9058c1ba1c1'::uuid,'fb25b102-5690-57b5-a66c-361de0b6a356'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/17d721a3a6d67809-lesson-18-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Sit down, please.. Don’t touch the screen.. First, open the book. Then read."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fce1686f-7a02-574c-a679-a7b76d835088'::uuid,'fb25b102-5690-57b5-a66c-361de0b6a356'::uuid,'multiple_choice',1,'{"question":"เลือกคำสั่งปฏิเสธถูก","choices":[{"id":"choice_1","text":"Don’t run."},{"id":"choice_2","text":"Don’t to run."},{"id":"choice_3","text":"Don’t running."}],"correctChoiceId":"choice_1","explanation":"Don’t + base verb"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('01af3a17-8c78-5e03-a7c9-e920f72f6031'::uuid,'fb25b102-5690-57b5-a66c-361de0b6a356'::uuid,'multiple_choice',1,'{"question":"คำสั่งบอกเล่าเริ่มด้วยรูปใด?","choices":[{"id":"choice_1","text":"base verb"},{"id":"choice_2","text":"verb s-form เสมอ"},{"id":"choice_3","text":"past form"}],"correctChoiceId":"choice_1","explanation":"Open/Read/Sit เป็น base form"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('160dbd53-9993-5dc2-ae6e-b8f778a7c9e4'::uuid,'fb25b102-5690-57b5-a66c-361de0b6a356'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนคำสั่งสามขั้นตอนและคำห้ามหนึ่งข้อสำหรับทำกิจกรรมง่าย\n\n### ตัวอย่างคำตอบ\n\nOpen the book. Read the question. Write the answer. Don’t close the book yet.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **คำสั่งบอกเล่า–ปฏิเสธ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ce34dbe1-a506-5351-a286-7a60e1049ff6'::uuid,'b9f97680-65a2-5add-a4aa-18ad0c1f6ebf'::uuid,'reading',1,'{"title":"can/can''t บอกความสามารถ","body":"## can/can''t บอกความสามารถ\n\ncan/can’t + base verb บอกความสามารถ ทุกประธานใช้ can รูปเดียว ไม่เติม s หรือ to หลัง can เช่น She can swim. และ They can swim. can’t ย่อ cannot ต่างจาก can ที่ต้องฟังเสียงทั้งประโยค ไม่ดูเพียงตัวสะกด\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I can cook. | ทำได้ |\n| She can swim. | can ไม่เติม s |\n| We can’t drive. | ทำไม่ได้ |\n\n### จุดที่มักสับสน\n\nShe cans swim, can to swim และ can swims ผิดในรูปนี้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6e34dbaf-9f2d-5cb0-adf4-202c13eb983a'::uuid,'b9f97680-65a2-5add-a4aa-18ad0c1f6ebf'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/0be8fcbf37079f31-lesson-18-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I can cook.. She can swim.. We can’t drive."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2e30936f-c23d-58ae-a2cc-db6b9b70f47b'::uuid,'b9f97680-65a2-5add-a4aa-18ad0c1f6ebf'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคความสามารถถูก","choices":[{"id":"choice_1","text":"He can plays football."},{"id":"choice_2","text":"He can play football."},{"id":"choice_3","text":"He cans play football."}],"correctChoiceId":"choice_2","explanation":"can + base play ทุกประธาน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5acc5014-2755-52ad-a5aa-d0257dba5179'::uuid,'b9f97680-65a2-5add-a4aa-18ad0c1f6ebf'::uuid,'multiple_choice',1,'{"question":"cannot หมายถึงอะไร?","choices":[{"id":"choice_1","text":"ไม่สามารถ"},{"id":"choice_2","text":"ทำเป็นปกติ"},{"id":"choice_3","text":"กำลังทำ"}],"correctChoiceId":"choice_1","explanation":"รูปปฏิเสธของ can"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('733e1bda-caca-595a-a3fc-b8f9a1cf7176'::uuid,'b9f97680-65a2-5add-a4aa-18ad0c1f6ebf'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกสามสิ่งที่คุณทำได้และสองสิ่งที่ยังทำไม่ได้\n\n### ตัวอย่างคำตอบ\n\nI can cook. I can swim. I can speak Thai. I can’t drive. I can’t play the piano.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **can/can''t บอกความสามารถ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('80130900-fe12-57e0-a218-a8267c055a2e'::uuid,'45ba1345-7ae7-557b-a4f0-5abd955ac703'::uuid,'reading',1,'{"title":"คำถามและคำตอบด้วย can","body":"## คำถามและคำตอบด้วย can\n\nคำถามใช้ Can + subject + base verb? เช่น Can you swim? คำตอบสั้น Yes, I can./No, I can’t. Wh-question เช่น What can Ben do? ไม่ใช้ do/does อีกตัวนำหน้าคำถาม modal ฟัง can/can’t จากเสียงท้าย จังหวะและบริบท เพราะ can รูปไม่เน้นมักออกเสียงอ่อน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Can she drive? — Yes, she can. | คำถามและคำตอบ |\n| What can you do? — I can cook. | Wh + can |\n| Can they swim? — No, they can’t. | ปฏิเสธ |\n\n### จุดที่มักสับสน\n\nDo you can swim? ผิด เพราะ can สลับขึ้นหน้าเอง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a5e1757e-ba27-52f0-adc2-ff558e321685'::uuid,'45ba1345-7ae7-557b-a4f0-5abd955ac703'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/e8e64e52a3ee9067-lesson-18-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Can she drive?. Yes, she can.. What can you do?. I can cook.. Can they swim?. No, they can’t."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cdfdd5c6-bb2e-55d9-a8e0-34f0658de0b3'::uuid,'45ba1345-7ae7-557b-a4f0-5abd955ac703'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามถูก","choices":[{"id":"choice_1","text":"Do you can cook?"},{"id":"choice_2","text":"Can you cook?"},{"id":"choice_3","text":"Can you cooks?"}],"correctChoiceId":"choice_2","explanation":"Can + you + base cook"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6611d8b0-ffc4-57b0-ae78-4439d4d9fa02'::uuid,'45ba1345-7ae7-557b-a4f0-5abd955ac703'::uuid,'multiple_choice',1,'{"question":"Can he swim? — No, …","choices":[{"id":"choice_1","text":"he doesn’t"},{"id":"choice_2","text":"he can’t"},{"id":"choice_3","text":"he isn’t"}],"correctChoiceId":"choice_2","explanation":"คำตอบตาม modal can"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('03b74300-58b9-562a-a63d-a97688f25b21'::uuid,'45ba1345-7ae7-557b-a4f0-5abd955ac703'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nถามเพื่อนเรื่องความสามารถสามอย่างแล้วสรุปสองประโยค\n\n### ตัวอย่างคำตอบ\n\nCan you swim? Yes, I can. Can you drive? No, I can’t. Ben can swim, but he can’t drive.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **คำถามและคำตอบด้วย can** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2ce1c54c-0f21-56d7-afd6-ec1f22adc35f'::uuid,'08f7b9bf-3680-51bd-aa2d-a2664860595b'::uuid,'reading',1,'{"title":"ขอและอนุญาต","body":"## ขอและอนุญาต\n\nCan I…? ขออนุญาตให้ผู้พูดทำ ส่วน Can you…? ขอให้ผู้ฟังช่วย Could you…? เป็นวลีขอร้องสุภาพที่ใช้ได้ตอนนี้แม้ความหมายอดีตของ could จะเรียนต่อ ตอบ Sure./Of course./Sorry, I can’t. ตามบริบท ระบุการกระทำชัดเจนและใช้ please ได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Can I sit here? | ขออนุญาต |\n| Can you help me? | ขอให้ช่วย |\n| Could you open the window, please? | ขอร้องสุภาพ |\n\n### จุดที่มักสับสน\n\nCould you…? ในคำขอนี้ไม่ได้ถามว่าเคยทำได้ในอดีตเสมอ\n\n\n\n### ดูภาพแล้วลองใช้\n\n![คำสั่ง ความสามารถและคำขอ: Open it. / Don’t run.; She can swim.; Can you help? / Can I sit?](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/767fed3b1561c832-module-18-map.png)\n\n*base verb หลัง can, Don’t และ Let’s*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9c301724-9201-5583-a5a7-16ffb70532a0'::uuid,'08f7b9bf-3680-51bd-aa2d-a2664860595b'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/c04a3ed0bef6e80f-lesson-18-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Can I sit here?. Can you help me?. Could you open the window, please?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('edce4c20-5d45-55cf-acce-09c0f1f50d3a'::uuid,'08f7b9bf-3680-51bd-aa2d-a2664860595b'::uuid,'multiple_choice',1,'{"question":"ขออนุญาตเปิดหน้าต่าง ใช้รูปใด?","choices":[{"id":"choice_1","text":"Can I open the window?"},{"id":"choice_2","text":"Can you open the window? เพื่อฉันทำเอง"},{"id":"choice_3","text":"I can window?"}],"correctChoiceId":"choice_1","explanation":"Can I ถามอนุญาตผู้พูดทำ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8da8aeb1-4782-5174-abd9-293d922a5007'::uuid,'08f7b9bf-3680-51bd-aa2d-a2664860595b'::uuid,'multiple_choice',1,'{"question":"ขอให้เพื่อนช่วยถือกระเป๋า ใช้รูปใด?","choices":[{"id":"choice_1","text":"Could you carry this bag, please?"},{"id":"choice_2","text":"Could I carry this bag? เพื่อเพื่อนทำ"},{"id":"choice_3","text":"You can to carry?"}],"correctChoiceId":"choice_1","explanation":"Could you + base เป็นคำขอสุภาพ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4cafe911-a896-5428-af2e-b331890a3a6e'::uuid,'08f7b9bf-3680-51bd-aa2d-a2664860595b'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนขออนุญาตหนึ่งข้อ ขอความช่วยเหลือหนึ่งข้อ พร้อมคำตอบรับและปฏิเสธสุภาพ\n\n### ตัวอย่างคำตอบ\n\nCan I use your pen? Of course. Could you help me, please? Sorry, I can’t right now.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ขอและอนุญาต** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5635b812-6adb-54ae-a6fc-ac7d58b6245f'::uuid,'ae55dcaa-ee55-5326-a716-811ca34af794'::uuid,'reading',1,'{"title":"ชวนและเสนอทางเลือก","body":"## ชวนและเสนอทางเลือก\n\nชวนทำร่วมกันใช้ Let’s + base verb; ปฏิเสธ Let’s not + base Why don’t we…? เป็นข้อเสนอ ไม่ใช่ปฏิเสธความจริงแบบธรรมดา ตอบ That’s a good idea./Sure. หรือ Sorry, I can’t. พร้อมเหตุผลสั้นตามเหมาะสม อย่าใช้ Let’s to go\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Let’s study together. | ชวนร่วมกัน |\n| Let’s not drive today. | เสนอไม่ทำ |\n| Why don’t we walk? | เสนอเดิน |\n\n### จุดที่มักสับสน\n\nLet’s = let us; ไม่เปลี่ยนเป็น Let’s goes ตามประธาน\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1ef4d5b1-55e0-54bc-a404-a1000caceec7'::uuid,'ae55dcaa-ee55-5326-a716-811ca34af794'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/e3d7ff3b87965712-lesson-18-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Let’s study together.. Let’s not drive today.. Why don’t we walk?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d5ac1dc7-fefa-5be3-ab5b-2c2c9299bd35'::uuid,'ae55dcaa-ee55-5326-a716-811ca34af794'::uuid,'multiple_choice',1,'{"question":"เลือกคำชวนถูก","choices":[{"id":"choice_1","text":"Let’s to eat."},{"id":"choice_2","text":"Let’s eat."},{"id":"choice_3","text":"Let’s eats."}],"correctChoiceId":"choice_2","explanation":"Let’s + base eat"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8c37eb66-5bbc-5f91-a82b-33fc4ff9d56b'::uuid,'ae55dcaa-ee55-5326-a716-811ca34af794'::uuid,'multiple_choice',1,'{"question":"Why don’t we meet at six? สื่ออะไรในบริบทนี้?","choices":[{"id":"choice_1","text":"เสนอเวลานัด"},{"id":"choice_2","text":"ยืนยันว่าไม่เคยพบกัน"},{"id":"choice_3","text":"ถามเจ้าของเวลา"}],"correctChoiceId":"choice_1","explanation":"Why don’t we…? ใช้เสนอทำร่วมกัน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4a20f4b1-3987-5058-adc0-8ca17ec546f0'::uuid,'ae55dcaa-ee55-5326-a716-811ca34af794'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nสร้างบทชวนสี่บรรทัดที่มีข้อเสนอ ตอบรับหรือปฏิเสธ และปรับทางเลือก\n\n### ตัวอย่างคำตอบ\n\nLet’s play tennis. Sorry, I can’t today. Why don’t we walk tomorrow? That’s a good idea.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ชวนและเสนอทางเลือก** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7fa0522d-a43f-595c-aac6-8db8f4aab115'::uuid,'32f72368-ef36-540e-a408-7d02dc8ee0ab'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **ให้คำสั่ง ขอความช่วยเหลือ และบอกความสามารถด้วยรูปที่ถูกต้อง**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![คำสั่ง ความสามารถและคำขอ: Open it. / Don’t run.; She can swim.; Can you help? / Can I sit?](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/767fed3b1561c832-module-18-map.png)\n\n*base verb หลัง can, Don’t และ Let’s*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('08429a74-8a28-5c52-a729-19cf7eccac0f'::uuid,'32f72368-ef36-540e-a408-7d02dc8ee0ab'::uuid,'multiple_choice',1,'{"question":"เลือกคำสั่งปฏิเสธ","choices":[{"id":"choice_1","text":"Don’t touch it."},{"id":"choice_2","text":"Don’t to touch it."},{"id":"choice_3","text":"Don’t touching it."}],"correctChoiceId":"choice_1","explanation":"Don’t + base ย้อน 18.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b8e5be5d-61df-5a4b-ab7d-ac2f19a248df'::uuid,'32f72368-ef36-540e-a408-7d02dc8ee0ab'::uuid,'multiple_choice',1,'{"question":"Sara … cook well.","choices":[{"id":"choice_1","text":"can"},{"id":"choice_2","text":"cans"},{"id":"choice_3","text":"can to"}],"correctChoiceId":"choice_1","explanation":"can รูปเดียวทุกประธาน ย้อน 18.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b3dad9a7-a1ad-5c35-a24c-386a6f2ac0f8'::uuid,'32f72368-ef36-540e-a408-7d02dc8ee0ab'::uuid,'multiple_choice',1,'{"question":"ขอให้ผู้อื่นช่วยเปิดประตูใช้รูปใด?","choices":[{"id":"choice_1","text":"Could you open the door, please?"},{"id":"choice_2","text":"Could I open the door? เพื่อขอให้เพื่อนทำ"},{"id":"choice_3","text":"You open can?"}],"correctChoiceId":"choice_1","explanation":"Could you…? เป็นคำขอสุภาพ ย้อน 18.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0170dbbe-7a16-501e-aae5-b03125a3f2e6'::uuid,'32f72368-ef36-540e-a408-7d02dc8ee0ab'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nแสดงบทสนทนาที่มีคำขออนุญาต ขอช่วย บอกความสามารถและชวน พร้อมคำตอบสุภาพ\n\n### ตัวอย่างผลงาน\n\nCan I sit here? Of course. Could you help me? Sure. I can cook. Let’s make lunch. That’s a good idea.\n\n### ตรวจผลงาน\n\n- base verb หลัง can/let’s/คำสั่ง\n- แยก Can I กับ Can you\n- ตอบรับหรือปฏิเสธตรงคำขอ\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5fc62878-aac5-54c4-aa8b-d6b2d0e3af60'::uuid,'3a411c03-83c2-5474-aa55-446bd7b2d7b3'::uuid,'reading',1,'{"title":"แสดงสิ่งที่ทำได้","body":"## งานปิดคอร์ส 2\n\n**บอกเวลา ความถี่ สถานที่ ปริมาณ และสิ่งที่กำลังเกิดขึ้นได้**\n\nทำข้อทดสอบใหม่ต่อไปนี้ แล้วทำงานอ่าน/พูด/เขียนตามโจทย์ ใช้ feedback เพื่อเลือกทบทวน ไม่ใช้จำนวน block ที่อ่านเป็นหลักฐานว่าคุณใช้ภาษาได้แล้ว","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9b5a8437-5936-5439-acd3-02daea2049ea'::uuid,'3a411c03-83c2-5474-aa55-446bd7b2d7b3'::uuid,'multiple_choice',1,'{"question":"We meet … 7:15 … Friday.","choices":[{"id":"choice_1","text":"at / on"},{"id":"choice_2","text":"on / at"},{"id":"choice_3","text":"in / on"}],"correctChoiceId":"choice_1","explanation":"at เวลา; on วัน: M11"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7c2d12ec-47e4-590c-a3b0-6568a79d7980'::uuid,'3a411c03-83c2-5474-aa55-446bd7b2d7b3'::uuid,'multiple_choice',1,'{"question":"How long do you read each day?","choices":[{"id":"choice_1","text":"For thirty minutes."},{"id":"choice_2","text":"Twice a week."},{"id":"choice_3","text":"At the library."}],"correctChoiceId":"choice_1","explanation":"ถามระยะเวลา: M12"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6f5f7ef6-1269-5b16-a73d-e7924ba33c82'::uuid,'3a411c03-83c2-5474-aa55-446bd7b2d7b3'::uuid,'multiple_choice',1,'{"question":"… four apples in the bag.","choices":[{"id":"choice_1","text":"There are"},{"id":"choice_2","text":"There is"},{"id":"choice_3","text":"It is"}],"correctChoiceId":"choice_1","explanation":"plural ใช้ There are: M13"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f269dfec-f788-5c6f-a49e-1f4b4e64f342'::uuid,'3a411c03-83c2-5474-aa55-446bd7b2d7b3'::uuid,'multiple_choice',1,'{"question":"We need … bottles of water.","choices":[{"id":"choice_1","text":"a few"},{"id":"choice_2","text":"a little"},{"id":"choice_3","text":"much"}],"correctChoiceId":"choice_1","explanation":"bottles countable plural: M14"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4fbd40fc-ad1d-59d8-a660-51b6df2987eb'::uuid,'3a411c03-83c2-5474-aa55-446bd7b2d7b3'::uuid,'multiple_choice',1,'{"question":"Look! The students … pictures.","choices":[{"id":"choice_1","text":"are drawing"},{"id":"choice_2","text":"draws"},{"id":"choice_3","text":"are draw"}],"correctChoiceId":"choice_1","explanation":"กิจกรรมที่กำลังเห็น: M17"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,6) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('53e434a0-d136-5089-a2b3-528b861a4028'::uuid,'3a411c03-83c2-5474-aa55-446bd7b2d7b3'::uuid,'multiple_choice',1,'{"question":"Can you help me? คำตอบสุภาพที่ปฏิเสธคืออะไร?","choices":[{"id":"choice_1","text":"Sorry, I can’t right now."},{"id":"choice_2","text":"No, you don’t."},{"id":"choice_3","text":"I can to."}],"correctChoiceId":"choice_1","explanation":"ตอบคำขอด้วย can’t และเหตุผลเวลา: M18"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,7) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('32c5bc37-fa0a-58a5-ad92-e9a348a1dc45'::uuid,'3a411c03-83c2-5474-aa55-446bd7b2d7b3'::uuid,'reading',1,'{"title":"ผลงานปิดคอร์ส","body":"วางแผนกิจกรรมกับเพื่อน: เขียนวันเวลา สถานที่ สิ่งของและจำนวนที่ต้องใช้ พร้อมบอกความถี่และความสามารถ แล้วสร้างบทขอความช่วยเหลือ 4 บรรทัด\n\n### ตัวอย่างผลงาน\n\nWe meet at nine on Saturday at the park. There are three people. We need three bottles of water and some apples. I walk every day for twenty minutes. Ben can cook.\n\nMai: Can you bring some cups?\nBen: Sure.\nMai: Could you help me carry the bag?\nBen: Of course.\n\n### เกณฑ์ตรวจ\n\n- วันเวลาและสถานที่ครบ\n- ความถี่ต่างจากระยะเวลา\n- จำนวน หน่วยและ quantifiers ถูก\n- บรรยายสิ่งกำลังทำด้วย be+ing ได้\n- คำขอและคำตอบเหมาะกับผู้ฟัง\n\nให้ตนเองหรือครูตรวจงาน ระบบตรวจอัตโนมัติเฉพาะข้อเลือกตอบ แล้วทบทวนจุดที่ยังไม่มั่นใจเป็นระยะ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,8) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3cb41d81-a3a6-5c56-a76c-629c6d3619f4'::uuid,'c005e929-fc90-56c0-a2ba-853de088e6b1'::uuid,'reading',1,'{"title":"was/were กับประธาน","body":"## was/were กับประธาน\n\nอดีตของ be คือ was กับ I/he/she/it และคำนามเอกพจน์ ส่วน were กับ you/we/they และคำนามพหูพจน์ ใช้บอกอายุ ตำแหน่งหรือสภาพในช่วงอดีตที่จบแล้ว เช่น yesterday/last year รูปนี้บอกสภาพ ไม่ใช่การกระทำทุกชนิด จึงไม่เติม was หน้ากริยา V2 โดยอัตโนมัติ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I was tired yesterday. | สภาพอดีต |\n| They were at school. | หลายคนอยู่ที่โรงเรียน |\n| She was eighteen last year. | อายุในอดีต |\n\n### จุดที่มักสับสน\n\nyou ใช้ were แม้หมายถึงคนเดียว; She was went ผิด ถ้าการไปใช้ She went.\n\n\n\n### ดูภาพแล้วลองใช้\n\n![เล่าสภาพและสถานที่อดีต: was / wasn’t; were / weren’t; Where were you?](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/1fb3862f1bbf0826-module-19-map.png)\n\n*be อดีตไม่ใช้ didn’t be  •  There was / There were*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n![ภาพสามช่อง Mai เดินในสวน จากนั้นฝนตก Ben ใช้ร่มช่วยและทั้งคู่ถึงร้านกาแฟ](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4253d113ce35a709-rain-story.png)\n\n*Mai was walking when it began to rain. Ben opened his umbrella. Then they reached a cafe.*\n\nใช้ภาพเป็นเรื่องใหม่สำหรับฝึก ไม่เปลี่ยนข้อเท็จจริงของตัวอย่างเดิม เล่าลำดับที่เห็น หรือเสนอแผนเมื่อมีฝนตามหัวข้อบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Past simple: regular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-regular-verbs) · [British Council — Present simple: to be](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple-be)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5c66e81d-3176-5bc4-a31f-f3b26d52a8cc'::uuid,'c005e929-fc90-56c0-a2ba-853de088e6b1'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d7ac10f5a18e5f09-lesson-19-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I was tired yesterday.. They were at school.. She was eighteen last year."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('154ff9c2-dd69-5422-ab29-cd18219ecde1'::uuid,'c005e929-fc90-56c0-a2ba-853de088e6b1'::uuid,'multiple_choice',1,'{"question":"You … at home yesterday.","choices":[{"id":"choice_1","text":"was"},{"id":"choice_2","text":"were"},{"id":"choice_3","text":"are ที่หมายถึงอดีต"}],"correctChoiceId":"choice_2","explanation":"you ใช้ were ในอดีต"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('569d3b10-00f6-55fa-ae35-cd432d949729'::uuid,'c005e929-fc90-56c0-a2ba-853de088e6b1'::uuid,'multiple_choice',1,'{"question":"The shop … closed last night.","choices":[{"id":"choice_1","text":"was"},{"id":"choice_2","text":"were"},{"id":"choice_3","text":"am"}],"correctChoiceId":"choice_1","explanation":"shop หนึ่งร้านใช้ was"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7970f519-4e2e-5abf-ac0c-f82897ec2144'::uuid,'c005e929-fc90-56c0-a2ba-853de088e6b1'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกสถานที่กับสภาพของคุณและอีกสองคนเมื่อวาน\n\n### ตัวอย่างคำตอบ\n\nI was at home yesterday. I was tired. Mai was at school. My friends were happy.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **was/were กับประธาน** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e0b92525-6680-5d6c-aa13-9a57d4c7bff9'::uuid,'88c87946-c7af-5cc6-a91c-47cc14443429'::uuid,'reading',1,'{"title":"wasn''t/weren''t","body":"## wasn''t/weren''t\n\nปฏิเสธ be อดีตเติม not หลัง was/were และย่อเป็น wasn’t/weren’t ไม่ใช้ didn’t be ในรูป Past Simple ของ be เลือก was/were ตามประธานก่อนเติม not เปรียบเทียบบอกเล่าและปฏิเสธเพื่อเห็นว่าข้อมูลใดเปลี่ยน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I wasn’t at work. | ไม่ได้อยู่ที่ทำงาน |\n| We weren’t tired. | ไม่ได้เหนื่อย |\n| The room wasn’t clean. | ห้องไม่สะอาด |\n\n### จุดที่มักสับสน\n\ndidn’t เป็นเครื่องมือของกริยาทั่วไปที่เรียน M20 ไม่ใช่คำที่เติมหน้ากริยาทุกประเภท\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Past simple: regular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-regular-verbs) · [British Council — Present simple: to be](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple-be)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('03a87e1e-566b-5a99-a28c-f972373692b9'::uuid,'88c87946-c7af-5cc6-a91c-47cc14443429'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9dbc20fa71d32468-lesson-19-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I wasn’t at work.. We weren’t tired.. The room wasn’t clean."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('accc78e9-1f26-5cdb-a0b4-8924ea6604ee'::uuid,'88c87946-c7af-5cc6-a91c-47cc14443429'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคอดีตปฏิเสธถูก","choices":[{"id":"choice_1","text":"She didn’t be late."},{"id":"choice_2","text":"She wasn’t late."},{"id":"choice_3","text":"She weren’t late."}],"correctChoiceId":"choice_2","explanation":"she ใช้ was not/wasn’t"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0ee1621b-a995-5509-ac68-298f43489d98'::uuid,'88c87946-c7af-5cc6-a91c-47cc14443429'::uuid,'multiple_choice',1,'{"question":"Our friends … at the park yesterday.","choices":[{"id":"choice_1","text":"wasn’t"},{"id":"choice_2","text":"weren’t"},{"id":"choice_3","text":"isn’t"}],"correctChoiceId":"choice_2","explanation":"friends plural ใช้ weren’t"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b66d592e-cd6b-58af-abbb-33fc8d3fe8c5'::uuid,'88c87946-c7af-5cc6-a91c-47cc14443429'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนเรื่องเมื่อวานด้วย was/were สองข้อแล้วเปลี่ยนเป็นปฏิเสธ\n\n### ตัวอย่างคำตอบ\n\nI was busy → I wasn’t busy. We were at school → We weren’t at school.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **wasn''t/weren''t** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b7515226-d498-5637-aa55-67ca08e56301'::uuid,'6bfb18b6-0cc2-5a36-aaf5-b8870c946a9f'::uuid,'reading',1,'{"title":"คำถามในอดีตด้วย be","body":"## คำถามในอดีตด้วย be\n\nถาม be อดีตย้าย Was/Were หน้าประธาน: Was she here? Wh-question วางคำถามก่อน เช่น Where were you? คำตอบสั้น Yes, I was./No, they weren’t. คง was/were ตามประธานผู้ตอบ ไม่ใช้ did ร่วมกับ be ในคำถามรูปนี้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Were you tired? — Yes, I was. | you ในคำถามเปลี่ยน I ผู้ตอบ |\n| Where was Ben? — At home. | ถามที่ |\n| Was Mai late? — No, she wasn’t. | คำตอบสั้น |\n\n### จุดที่มักสับสน\n\nDid you were…? และ Where you was? ไม่เป็นรูปคำถามที่ถูก\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Past simple: regular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-regular-verbs) · [British Council — Present simple: to be](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple-be)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ac91b239-e2f7-55c1-a8b7-cde5bfd50ee8'::uuid,'6bfb18b6-0cc2-5a36-aaf5-b8870c946a9f'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f349ad110d18d101-lesson-19-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Were you tired?. Yes, I was.. Where was Ben?. At home.. Was Mai late?. No, she wasn’t."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c48334f5-90ca-5dda-a684-9c6944278073'::uuid,'6bfb18b6-0cc2-5a36-aaf5-b8870c946a9f'::uuid,'multiple_choice',1,'{"question":"ถามว่าพวกเขาอยู่ไหนเมื่อวาน เลือก","choices":[{"id":"choice_1","text":"Where were they yesterday?"},{"id":"choice_2","text":"Where was they yesterday?"},{"id":"choice_3","text":"Where did they were yesterday?"}],"correctChoiceId":"choice_1","explanation":"they ใช้ were สลับหน้าประธาน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('95135e7d-8353-5b7d-a1d0-de7e50be82b8'::uuid,'6bfb18b6-0cc2-5a36-aaf5-b8870c946a9f'::uuid,'multiple_choice',1,'{"question":"Was your sister here? — Yes, …","choices":[{"id":"choice_1","text":"she was"},{"id":"choice_2","text":"she did"},{"id":"choice_3","text":"she were"}],"correctChoiceId":"choice_1","explanation":"คำถาม was ตอบ she was"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4d4a0edd-6979-57e2-a354-2f0f510fb9a8'::uuid,'6bfb18b6-0cc2-5a36-aaf5-b8870c946a9f'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nสัมภาษณ์สั้นสองคำถาม yes/no และสอง Wh เกี่ยวกับเมื่อวาน\n\n### ตัวอย่างคำตอบ\n\nWere you at home? Yes, I was. Was Mai tired? No, she wasn’t. Where were you? At school. How was your day? It was good.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **คำถามในอดีตด้วย be** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2ca903c5-684a-5842-ae6a-0eab7c29f65d'::uuid,'2de78988-4e83-526f-aff0-a8f734efdc6d'::uuid,'reading',1,'{"title":"There was / There were","body":"## There was / There were\n\nThere was + singular/uncountable และ There were + plural บอกว่ามีสิ่งใดในอดีต ใช้ wasn’t/weren’t และ Was there…?/Were there…? เช่นเดียวกับรูปปัจจุบัน คำ yesterday/last week/two days ago ช่วยระบุอดีตที่จบแล้ว ago อยู่หลังช่วงเวลานับถอยจากปัจจุบัน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| There was a cafe here last year. | มีหนึ่งร้านในอดีต |\n| There were three trees here. | มีหลายต้น |\n| There wasn’t any water. | ไม่มีน้ำ |\n\n### จุดที่มักสับสน\n\nไม่ใช้ There was two chairs และไม่วาง ago หน้าจำนวนในรูป two days ago\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Past simple: regular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-regular-verbs) · [British Council — Present simple: to be](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/present-simple-be)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d4abe28f-c450-5b2a-a24e-dd819008821d'::uuid,'2de78988-4e83-526f-aff0-a8f734efdc6d'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/5881de333723e2fc-lesson-19-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"There was a cafe here last year.. There were three trees here.. There wasn’t any water."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('23a1bd0e-3695-58de-a440-d8e22d75821e'::uuid,'2de78988-4e83-526f-aff0-a8f734efdc6d'::uuid,'multiple_choice',1,'{"question":"… two buses here an hour ago.","choices":[{"id":"choice_1","text":"There was"},{"id":"choice_2","text":"There were"},{"id":"choice_3","text":"There is"}],"correctChoiceId":"choice_2","explanation":"two buses plural ใช้ were"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b6f6044b-10bc-5145-a8ab-4648a9de68c2'::uuid,'2de78988-4e83-526f-aff0-a8f734efdc6d'::uuid,'multiple_choice',1,'{"question":"เลือกวลีเวลาอดีตถูก","choices":[{"id":"choice_1","text":"ago two days"},{"id":"choice_2","text":"two days ago"},{"id":"choice_3","text":"two ago days"}],"correctChoiceId":"choice_2","explanation":"ระยะเวลา + ago"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f5d1ba6f-47b4-5a4c-a8e2-ea90546403cb'::uuid,'2de78988-4e83-526f-aff0-a8f734efdc6d'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเปรียบเทียบสถานที่เดิมในอดีตกับปัจจุบันสามคู่\n\n### ตัวอย่างคำตอบ\n\nThere was one cafe last year. There are two cafes now. There were three trees. There is one tree now.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **There was / There were** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6fc44d39-af4e-5d14-af92-932c02bf0e99'::uuid,'5113395f-2612-500c-aab0-ef08a73e963b'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **บอกสภาพ ตำแหน่ง และการมีอยู่ในอดีตได้**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![เล่าสภาพและสถานที่อดีต: was / wasn’t; were / weren’t; Where were you?](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/1fb3862f1bbf0826-module-19-map.png)\n\n*be อดีตไม่ใช้ didn’t be  •  There was / There were*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a6b49b56-e2bc-5b2b-ab5d-3c5b723d1dd0'::uuid,'5113395f-2612-500c-aab0-ef08a73e963b'::uuid,'multiple_choice',1,'{"question":"My parents … in Chiang Mai last week.","choices":[{"id":"choice_1","text":"was"},{"id":"choice_2","text":"were"},{"id":"choice_3","text":"is"}],"correctChoiceId":"choice_2","explanation":"parents plural ใช้ were ย้อน 19.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('76bd3db2-3ef8-55bd-a3c1-a6b6d3ab5290'::uuid,'5113395f-2612-500c-aab0-ef08a73e963b'::uuid,'multiple_choice',1,'{"question":"เลือกปฏิเสธ be อดีตถูก","choices":[{"id":"choice_1","text":"I wasn’t late."},{"id":"choice_2","text":"I didn’t be late."},{"id":"choice_3","text":"I weren’t late."}],"correctChoiceId":"choice_1","explanation":"I + was not ย้อน 19.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2d69e630-4184-5bfa-aff9-84c3524be8ad'::uuid,'5113395f-2612-500c-aab0-ef08a73e963b'::uuid,'multiple_choice',1,'{"question":"… any milk yesterday?","choices":[{"id":"choice_1","text":"Was there"},{"id":"choice_2","text":"Were there"},{"id":"choice_3","text":"Did there"}],"correctChoiceId":"choice_1","explanation":"milk uncountable ใช้ was ย้อน 19.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('95977106-e353-5f6d-a306-bfa9917f9e4b'::uuid,'5113395f-2612-500c-aab0-ef08a73e963b'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเล่าสภาพและสถานที่เมื่อวาน พร้อมสิ่งที่มี/ไม่มี แล้วถามเพื่อนสองข้อ\n\n### ตัวอย่างผลงาน\n\nI was at the park. It was hot. There were three people. There wasn’t any rain. Where were you? Were you tired?\n\n### ตรวจผลงาน\n\n- was/were ตรงประธาน\n- คำถามกับปฏิเสธไม่ใช้ did be\n- there was/were ตรงจำนวน\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('036f04a3-1bdf-52bf-a977-d14961f914bd'::uuid,'f35ec82f-c78a-555a-a834-657a71fd9766'::uuid,'reading',1,'{"title":"Past Simple และเวลาอดีต","body":"## Past Simple และเวลาอดีต\n\nPast Simple เล่าเหตุการณ์หรือสภาพที่จบในอดีต ประโยคบอกเล่ากริยาทั่วไปใช้ V2 ทุกประธาน: I worked./She worked. ระบุหรือเข้าใจเวลาจากบริบท เช่น yesterday/last week เหตุการณ์หลายข้อเล่าตามลำดับได้ ต่างจาก Present Simple กิจวัตรปัจจุบัน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I visited Mai yesterday. | ไปพบจบแล้ว |\n| She worked last night. | ทำงานในอดีต |\n| I work here now. / I worked there last year. | ปัจจุบัน / อดีต |\n\n### จุดที่มักสับสน\n\nไม่เติม s ให้ V2 ตาม he/she/it และไม่เติม was หน้ากริยา V2 ปกติ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Past simple: regular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-regular-verbs) · [British Council — Past simple: irregular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-irregular-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('07664f1f-6c16-5db8-a9e0-35f102e9d871'::uuid,'f35ec82f-c78a-555a-a834-657a71fd9766'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/e4660ff38007a185-lesson-20-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I visited Mai yesterday.. She worked last night.. I work here now.. I worked there last year."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('50ac76ea-f1ae-5d5b-a3fd-4c106a1b49b2'::uuid,'f35ec82f-c78a-555a-a834-657a71fd9766'::uuid,'multiple_choice',1,'{"question":"เล่าไปเยี่ยมเมื่อวาน ใช้รูปใด?","choices":[{"id":"choice_1","text":"I visited my friend yesterday."},{"id":"choice_2","text":"I visit my friend yesterday. ในอดีตที่จบ"},{"id":"choice_3","text":"I was visited my friend."}],"correctChoiceId":"choice_1","explanation":"Past Simple บอกเล่าใช้ V2 visited"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('562d22bf-6645-527c-a6b6-fd8cd35e8548'::uuid,'f35ec82f-c78a-555a-a834-657a71fd9766'::uuid,'multiple_choice',1,'{"question":"She … here last year.","choices":[{"id":"choice_1","text":"worked"},{"id":"choice_2","text":"works"},{"id":"choice_3","text":"was work"}],"correctChoiceId":"choice_1","explanation":"last year จบแล้วและ work เป็น action verb ใช้ worked"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ddcb3d70-d9a5-5976-ae9a-009883304ec3'::uuid,'f35ec82f-c78a-555a-a834-657a71fd9766'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนเหตุการณ์เมื่อวานสามประโยคตามลำดับ\n\n### ตัวอย่างคำตอบ\n\nI walked to the shop. I bought some food. I cooked dinner.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Past Simple และเวลาอดีต** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('af12dd1b-042c-5bde-ab52-fbe2148b8b14'::uuid,'e9e6790e-7884-56ee-a41d-ec99871cce8f'::uuid,'reading',1,'{"title":"กริยาปกติเติม ed","body":"## กริยาปกติเติม ed\n\nregular verbs ทำ V2/V3 ด้วย ed: work→worked; ลง e เติม d: live→lived; พยัญชนะ+y เปลี่ยนเป็น ied: study→studied; บางคำสระสั้นซ้ำพยัญชนะ: stop→stopped เสียง ed คือ /t/ หลังเสียงไม่ก้องเช่น walked, /d/ หลังเสียงก้องเช่น played, /ɪd/ หลัง /t,d/ เช่น wanted/needed ตรวจเสียงท้ายของ verb ไม่ใช่ดูตัวอักษรอย่างเดียว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| walked | ed ออก /t/ |\n| played | ed ออก /d/ |\n| wanted / needed | ed เพิ่มพยางค์ /ɪd/ |\n| studied / stopped | รูปสะกดเปลี่ยน |\n\n### จุดที่มักสับสน\n\nไม่อ่าน ed ทุกคำเป็นพยางค์เอ็ด; played ไม่เพิ่มหนึ่งพยางค์แบบ wanted\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Past simple: regular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-regular-verbs) · [British Council — Past simple: irregular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-irregular-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('60d67745-ab80-5a03-a74a-1483cc8554a9'::uuid,'e9e6790e-7884-56ee-a41d-ec99871cce8f'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/829334896b7712b2-lesson-20-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Walked. Played. Wanted. Needed. I walked home. I played tennis. I wanted tea."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('86ac3309-0efa-51f9-aeb5-e67eb4d66fd4'::uuid,'e9e6790e-7884-56ee-a41d-ec99871cce8f'::uuid,'multiple_choice',1,'{"question":"V2 ของ study คือรูปใด?","choices":[{"id":"choice_1","text":"studyed"},{"id":"choice_2","text":"studied"},{"id":"choice_3","text":"studyd"}],"correctChoiceId":"choice_2","explanation":"พยัญชนะ + y เปลี่ยนเป็น ied"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1b1c7a81-1f0d-5a42-a9d5-6b56da2ecabf'::uuid,'e9e6790e-7884-56ee-a41d-ec99871cce8f'::uuid,'multiple_choice',1,'{"question":"ed คำใดเพิ่มพยางค์ /ɪd/?","choices":[{"id":"choice_1","text":"walked"},{"id":"choice_2","text":"played"},{"id":"choice_3","text":"wanted"}],"correctChoiceId":"choice_3","explanation":"want ลงเสียง /t/ จึง wanted เพิ่ม /ɪd/"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('83aaf4b2-2617-543e-a69e-137ea2febcde'::uuid,'e9e6790e-7884-56ee-a41d-ec99871cce8f'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียน V2 ของ work/live/study/stop และอ่าน walked/played/wanted ให้ต่างเสียงท้าย\n\n### ตัวอย่างคำตอบ\n\nworked; lived; studied; stopped. I walked home. I played tennis. I wanted tea.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **กริยาปกติเติม ed** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5d0b5256-08ff-5f49-a048-94fd3896fcc1'::uuid,'7bb39175-b2fd-557c-abab-44bc189525e5'::uuid,'reading',1,'{"title":"กริยาไม่ปกติที่ใช้บ่อย","body":"## กริยาไม่ปกติที่ใช้บ่อย\n\nirregular verbs มี V2 ที่ต้องเรียนเป็นรูป เช่น go→went, eat→ate, see→saw, have→had, do→did เรียนเป็นกลุ่มเหตุการณ์พร้อมความหมาย เช่น went to a shop แล้ว ate lunch ไม่เติม ed อีกเมื่อเป็น V2 แล้ว ประธานทุกตัวใช้รูปอดีตเดียวกันของกริยานั้น\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I went to a cafe. | go → went |\n| She ate rice. | eat → ate |\n| We saw a film. | see → saw |\n| He had lunch. | have → had |\n\n### จุดที่มักสับสน\n\ngoed, eated และ wented ไม่ใช่รูปอดีตมาตรฐาน\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ภาพสามช่อง Mai เดินในสวน จากนั้นฝนตก Ben ใช้ร่มช่วยและทั้งคู่ถึงร้านกาแฟ](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4253d113ce35a709-rain-story.png)\n\n*Mai was walking when it began to rain. Ben opened his umbrella. Then they reached a cafe.*\n\nใช้ภาพเป็นเรื่องใหม่สำหรับฝึก ไม่เปลี่ยนข้อเท็จจริงของตัวอย่างเดิม เล่าลำดับที่เห็น หรือเสนอแผนเมื่อมีฝนตามหัวข้อบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Past simple: regular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-regular-verbs) · [British Council — Past simple: irregular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-irregular-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d75ebdc1-2ec7-5f9d-ace1-e3ce43ca3f36'::uuid,'7bb39175-b2fd-557c-abab-44bc189525e5'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9dea003b6e5c4df5-lesson-20-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I went to a cafe.. She ate rice.. We saw a film.. He had lunch."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('dfd606c0-2cc4-5dc3-a0e7-69e773b8a279'::uuid,'7bb39175-b2fd-557c-abab-44bc189525e5'::uuid,'multiple_choice',1,'{"question":"V2 ของ go คืออะไร?","choices":[{"id":"choice_1","text":"goed"},{"id":"choice_2","text":"went"},{"id":"choice_3","text":"gone"}],"correctChoiceId":"choice_2","explanation":"went คือ V2 ส่วน gone คือ V3"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1fa27987-49d2-5e52-a3cc-795e046f1c34'::uuid,'7bb39175-b2fd-557c-abab-44bc189525e5'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคอดีตถูก","choices":[{"id":"choice_1","text":"She had breakfast."},{"id":"choice_2","text":"She hased breakfast."},{"id":"choice_3","text":"She hadded breakfast."}],"correctChoiceId":"choice_1","explanation":"have → had ไม่เติม ed อีก"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a5dabd54-bc3e-5e58-a48e-095c5f1deb3c'::uuid,'7bb39175-b2fd-557c-abab-44bc189525e5'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเล่าเรื่องสั้นด้วย went/ate/saw/had/did อย่างน้อยสามคำ\n\n### ตัวอย่างคำตอบ\n\nI went to a cafe. I had lunch and ate rice. Then I saw my friend. I did my homework at home.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **กริยาไม่ปกติที่ใช้บ่อย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('69552db1-3159-5d18-ac36-450ad10a9671'::uuid,'cd371d1f-ec19-50df-aed0-d1601b251d5b'::uuid,'reading',1,'{"title":"didn''t + V1","body":"## didn''t + V1\n\nPast Simple ปฏิเสธกริยาทั่วไปใช้ didn’t + base verb ทุกประธาน did รับความเป็นอดีตแล้วกริยาหลักกลับ V1: didn’t go ไม่ใช่ didn’t went ส่วน be ใช้ wasn’t/weren’t แยกระบบกัน อาจใช้ did not ในรูปเต็มที่เป็นทางการกว่า\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I didn’t go out. | didn’t + go |\n| She didn’t eat lunch. | didn’t + eat |\n| She wasn’t hungry. | be ปฏิเสธต่างระบบ |\n\n### จุดที่มักสับสน\n\nอย่าใส่อดีตสองจุดใน didn’t went/ didn’t ate\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Past simple: regular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-regular-verbs) · [British Council — Past simple: irregular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-irregular-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0c8ec038-dfe7-5e62-abe4-778478788c12'::uuid,'cd371d1f-ec19-50df-aed0-d1601b251d5b'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2ef553d6da4c7abf-lesson-20-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I didn’t go out.. She didn’t eat lunch.. She wasn’t hungry."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6cb280d2-74ac-5995-a8c3-f111f7a10749'::uuid,'cd371d1f-ec19-50df-aed0-d1601b251d5b'::uuid,'multiple_choice',1,'{"question":"เลือกอดีตปฏิเสธถูก","choices":[{"id":"choice_1","text":"He didn’t saw it."},{"id":"choice_2","text":"He didn’t see it."},{"id":"choice_3","text":"He doesn’t saw it."}],"correctChoiceId":"choice_2","explanation":"didn’t + base see"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e33d4eeb-0bdc-581b-a974-bc5cb4eb11e5'::uuid,'cd371d1f-ec19-50df-aed0-d1601b251d5b'::uuid,'multiple_choice',1,'{"question":"ทุกประธานใช้ didn’t รูปเดียวกันหรือไม่?","choices":[{"id":"choice_1","text":"ใช่ใน Past Simple กริยาทั่วไป"},{"id":"choice_2","text":"ไม่ ต้อง she didn’ts"},{"id":"choice_3","text":"ไม่ ต้อง I doesn’t"}],"correctChoiceId":"choice_1","explanation":"didn’t ไม่เปลี่ยนตาม he/she/it"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('34fada7f-5a0b-5051-afc1-766d0114a5b8'::uuid,'cd371d1f-ec19-50df-aed0-d1601b251d5b'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสามสิ่งที่คุณไม่ได้ทำเมื่อวาน และหนึ่งสภาพที่ไม่เป็นด้วย wasn’t\n\n### ตัวอย่างคำตอบ\n\nI didn’t drive. I didn’t cook. I didn’t watch TV. I wasn’t tired.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **didn''t + V1** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('532f353a-ed24-55f6-a658-bde3782a05a1'::uuid,'196d4e81-37e4-549e-a4af-3836dab0110c'::uuid,'reading',1,'{"title":"Did…? และ Wh-questions อดีต","body":"## Did…? และ Wh-questions อดีต\n\nถามอดีตกริยาทั่วไปใช้ Did + subject + base? และ Wh + did + subject + base? ตอบ Yes, I did./No, she didn’t. ถ้าถามผู้ทำใช้ Who + V2 เช่น Who came? ไม่เติม did ในรูปพื้นฐาน แต่ Who did you meet? ถามกรรมและมี subject you อยู่\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Did you go out? — No, I didn’t. | yes/no |\n| Where did she go? | Wh + did + V1 |\n| Who came? / Who did you meet? | ถามประธาน / กรรม |\n\n### จุดที่มักสับสน\n\nDid she went? ผิดเพราะ did ตามด้วย base; Who did came? ผิดในคำถามประธานพื้นฐาน\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Past simple: regular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-regular-verbs) · [British Council — Past simple: irregular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-irregular-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5c6194f9-7756-50c8-a256-09b29036d690'::uuid,'196d4e81-37e4-549e-a4af-3836dab0110c'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/69adae24ee738655-lesson-20-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Did you go out?. No, I didn’t.. Where did she go?. Who came?. Who did you meet?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f634628e-b6cb-5eb1-af45-442875e0b5fc'::uuid,'196d4e81-37e4-549e-a4af-3836dab0110c'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามอดีตถูก","choices":[{"id":"choice_1","text":"Did Ben eat lunch?"},{"id":"choice_2","text":"Did Ben ate lunch?"},{"id":"choice_3","text":"Does Ben ate lunch?"}],"correctChoiceId":"choice_1","explanation":"Did + subject + base eat"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('41e30c21-c4cc-56f5-a773-1a511469e572'::uuid,'196d4e81-37e4-549e-a4af-3836dab0110c'::uuid,'multiple_choice',1,'{"question":"Who came to the party? เป็นคำถามแบบใด?","choices":[{"id":"choice_1","text":"ถามผู้ทำ"},{"id":"choice_2","text":"ถามสถานที่"},{"id":"choice_3","text":"ถามกรรมโดยมี you"}],"correctChoiceId":"choice_1","explanation":"Who เป็นประธานของ came"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bffb2439-2298-595b-a54c-7b32b96f9d10'::uuid,'196d4e81-37e4-549e-a4af-3836dab0110c'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nถามอดีต yes/no และ Wh รวมสี่ข้อแล้วตอบ\n\n### ตัวอย่างคำตอบ\n\nDid you cook? Yes, I did. Where did you go? I went home. Who came? Mai came. Who did you meet? I met Ben.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Did…? และ Wh-questions อดีต** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8978f059-e722-52dd-a664-ce16ceb670e9'::uuid,'5270fed0-3e3f-5d7b-af19-350dad83b47e'::uuid,'reading',1,'{"title":"กริยา 3 ช่องมีหน้าที่อะไร","body":"## กริยา 3 ช่องมีหน้าที่อะไร\n\nV1 คือ base form; V2 ใช้บอกเล่า Past Simple; V3 คือ past participle ใช้ร่วม auxiliary เช่น have + V3 และ be + V3 ภายหลัง V3 ไม่ใช่อดีตที่ใส่แทน V2 ได้ทุกครั้ง regular forms มัก V2/V3 เหมือนกัน แต่ irregular เช่น go/went/gone, see/saw/seen ต้องแยกหน้าที่ก่อนจำ be มี V1 be; V2 was/were; V3 been\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| go / went / gone | V1 / V2 / V3 |\n| eat / ate / eaten | สามรูปต่าง |\n| work / worked / worked | V2/V3 เหมือน |\n| be / was, were / been | รูป be |\n\n### จุดที่มักสับสน\n\nI gone yesterday ผิดสำหรับ Past Simple ต้อง I went yesterday.; have gone เป็นโครงสร้างอีกแบบ\n\n\n\n### ดูภาพแล้วลองใช้\n\n![รูปเดียวกันไม่ได้แปลว่าหน้าที่เดียวกัน: go · eat · see; went · ate · saw; gone · eaten · seen](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/275ac1b1e0c966ab-module-20-map.png)\n\n*I went yesterday.  •  I didn’t go.  •  I have seen it.*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Past simple: regular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-regular-verbs) · [British Council — Past simple: irregular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-irregular-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4695a5d6-1560-5f84-a0a7-b10a9060bf0d'::uuid,'5270fed0-3e3f-5d7b-af19-350dad83b47e'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/e0ca250f5239fb2e-lesson-20-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"go. went. gone. eat. ate. eaten. work. worked. worked. be. was, were. been"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('35fbf600-fc65-55d1-a693-8c026ac42248'::uuid,'5270fed0-3e3f-5d7b-af19-350dad83b47e'::uuid,'multiple_choice',1,'{"question":"รูปใดเป็น V3 ของ see?","choices":[{"id":"choice_1","text":"see"},{"id":"choice_2","text":"saw"},{"id":"choice_3","text":"seen"}],"correctChoiceId":"choice_3","explanation":"seen คือ past participle; saw คือ V2"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('50a69a9d-e075-5a14-a366-58f873b6d32f'::uuid,'5270fed0-3e3f-5d7b-af19-350dad83b47e'::uuid,'multiple_choice',1,'{"question":"เล่าไปเมื่อวานแบบ Past Simple ใช้รูปใด?","choices":[{"id":"choice_1","text":"I went yesterday."},{"id":"choice_2","text":"I gone yesterday."},{"id":"choice_3","text":"I going yesterday."}],"correctChoiceId":"choice_1","explanation":"บอกเล่า Past Simple ใช้ V2 went"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('129ea979-8c7b-5d87-ac38-1dbb0d42cd51'::uuid,'5270fed0-3e3f-5d7b-af19-350dad83b47e'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nทำตารางสามช่องของ go/eat/see/do/have/work/be และแต่ง Past Simple สามประโยค\n\n### ตัวอย่างคำตอบ\n\ngo/went/gone; eat/ate/eaten; see/saw/seen; do/did/done; have/had/had; work/worked/worked; be/was,were/been. I went home. I ate rice. I saw Mai.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **กริยา 3 ช่องมีหน้าที่อะไร** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d218bbb4-11ea-5247-ae13-b5d83d9d8f27'::uuid,'22119376-e857-547d-a0ef-161acd37b8b8'::uuid,'reading',1,'{"title":"เล่าและถามเหตุการณ์ของตนเอง","body":"## เล่าและถามเหตุการณ์ของตนเอง\n\nเล่าเรื่องของคุณด้วยเวลาที่ชัดและลำดับเหตุการณ์ ใช้ V2 สำหรับการกระทำและ was/were สำหรับสภาพหรือที่อยู่ เพิ่ม first/then/finally ได้แล้วตรวจว่าผู้ฟังรู้ว่าใครทำอะไร คำถามรายละเอียดใช้ did + V1 ไม่ต้องเปลี่ยนทุกคำในเรื่องเป็น past ถ้าบางส่วนเป็นข้อเท็จจริงที่ยังจริง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Yesterday, I was tired. I went home early. | สภาพ + การกระทำ |\n| Then I cooked dinner. Finally, I went to bed. | ลำดับ |\n| Where did you go? | ถามต่อด้วย V1 |\n\n### จุดที่มักสับสน\n\nคง pronouns ให้ชัดและไม่สลับ tense โดยไม่มีความหมายรองรับ\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ภาพสามช่อง Mai เดินในสวน จากนั้นฝนตก Ben ใช้ร่มช่วยและทั้งคู่ถึงร้านกาแฟ](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4253d113ce35a709-rain-story.png)\n\n*Mai was walking when it began to rain. Ben opened his umbrella. Then they reached a cafe.*\n\nใช้ภาพเป็นเรื่องใหม่สำหรับฝึก ไม่เปลี่ยนข้อเท็จจริงของตัวอย่างเดิม เล่าลำดับที่เห็น หรือเสนอแผนเมื่อมีฝนตามหัวข้อบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Past simple: regular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-regular-verbs) · [British Council — Past simple: irregular verbs](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/past-simple-irregular-verbs)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4f2eafea-cc0b-56d6-a9a2-de9225621a0d'::uuid,'22119376-e857-547d-a0ef-161acd37b8b8'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/86fad457cfd215d6-lesson-20-07.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Yesterday, I was tired. I went home early.. Then I cooked dinner. Finally, I went to bed.. Where did you go?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6171d07c-3780-5359-a14a-6322d79addfe'::uuid,'22119376-e857-547d-a0ef-161acd37b8b8'::uuid,'multiple_choice',1,'{"question":"เลือกเรื่องอดีตที่ถูก","choices":[{"id":"choice_1","text":"I was hungry, so I ate rice."},{"id":"choice_2","text":"I did hungry, so I eaten rice."},{"id":"choice_3","text":"I was eat rice."}],"correctChoiceId":"choice_1","explanation":"was + adjective; ate คือ V2"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4ccb0b91-676a-5180-a3ee-14310feb2099'::uuid,'22119376-e857-547d-a0ef-161acd37b8b8'::uuid,'multiple_choice',1,'{"question":"คำถามรายละเอียดหลัง I visited Ben คือรูปใด?","choices":[{"id":"choice_1","text":"When did you visit him?"},{"id":"choice_2","text":"When did you visited him?"},{"id":"choice_3","text":"When were you visit him?"}],"correctChoiceId":"choice_1","explanation":"did + base visit"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('92eecee2-3b07-5479-aed1-050eea6f4a97'::uuid,'22119376-e857-547d-a0ef-161acd37b8b8'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนเมื่อวาน 5 ประโยค มีสภาพหนึ่งข้อและการกระทำสามข้อ จากนั้นตั้งคำถามสองข้อ\n\n### ตัวอย่างคำตอบ\n\nYesterday, I was at home. I was hungry. I cooked rice. I ate lunch. Then I called Mai. What did you cook? Who did you call?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เล่าและถามเหตุการณ์ของตนเอง** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0db3f21c-f208-5923-aa13-4e5b813516d6'::uuid,'ae9730e8-650e-5e93-acfa-e33661a5c04f'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เล่าเหตุการณ์ที่จบแล้ว ถามอดีต และอธิบายได้ว่าทำไม did ตามด้วย V1**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![รูปเดียวกันไม่ได้แปลว่าหน้าที่เดียวกัน: go · eat · see; went · ate · saw; gone · eaten · seen](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/275ac1b1e0c966ab-module-20-map.png)\n\n*I went yesterday.  •  I didn’t go.  •  I have seen it.*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('56f99b20-5aa1-5420-abd2-0562d99db0b6'::uuid,'ae9730e8-650e-5e93-acfa-e33661a5c04f'::uuid,'multiple_choice',1,'{"question":"Yesterday, my sister … a new book.","choices":[{"id":"choice_1","text":"bought"},{"id":"choice_2","text":"buy"},{"id":"choice_3","text":"buyed"}],"correctChoiceId":"choice_1","explanation":"buy→bought V2 ย้อน 20.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('133ac2cf-3535-5c04-a3d5-20044c58e747'::uuid,'ae9730e8-650e-5e93-acfa-e33661a5c04f'::uuid,'multiple_choice',1,'{"question":"He didn’t … breakfast.","choices":[{"id":"choice_1","text":"ate"},{"id":"choice_2","text":"eat"},{"id":"choice_3","text":"eaten"}],"correctChoiceId":"choice_2","explanation":"didn’t + base eat ย้อน 20.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bd09c679-94ba-5adc-abcd-5bcd201e95b3'::uuid,'ae9730e8-650e-5e93-acfa-e33661a5c04f'::uuid,'multiple_choice',1,'{"question":"Did you … home early?","choices":[{"id":"choice_1","text":"go"},{"id":"choice_2","text":"went"},{"id":"choice_3","text":"gone"}],"correctChoiceId":"choice_1","explanation":"did + base go ย้อน 20.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a2389f7b-ffa9-518d-a93e-30b921baadef'::uuid,'ae9730e8-650e-5e93-acfa-e33661a5c04f'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเล่าเมื่อวาน 6 ประโยค มี regular/irregular, ปฏิเสธและสภาพ จากนั้นถามรายละเอียดสองข้อ\n\n### ตัวอย่างผลงาน\n\nI was at home. I worked in the morning. I bought food. I cooked lunch. I didn’t drive. I went to bed early. What did you buy? When did you work?\n\n### ตรวจผลงาน\n\n- V2 ไม่เติม s หรือ ed ซ้ำ\n- did/didn’t ตามด้วย V1\n- อ่าน ed ตามเสียงท้ายและรู้ V3 ต่างหน้าที่\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d0ef3c3b-71cd-5f0e-a1fe-3594aca849d2'::uuid,'441cb0c2-cb15-5e19-a460-2f006c942811'::uuid,'reading',1,'{"title":"was/were + ing","body":"## was/were + ing\n\nPast Continuous ใช้ was/were + ing บอกกิจกรรมกำลังดำเนินในเวลาอดีต ไม่ยืนยันว่าทำจบในจุดนั้น ปฏิเสธ wasn’t/weren’t + ing คำถาม Was/Were + subject + ing? ใช้ be อดีตตามประธานเหมือน M19 และคง -ing ที่กริยาหลัก\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| At eight, I was studying. | กำลังทำในเวลาอดีต |\n| They weren’t sleeping. | ปฏิเสธ |\n| Was she cooking? | คำถาม |\n\n### จุดที่มักสับสน\n\nI was studied ไม่ใช่ continuous; อย่าละ was/were\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f787760c-6fae-5cad-a63b-7b495fb3c696'::uuid,'441cb0c2-cb15-5e19-a460-2f006c942811'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/8c6b10591b8619e8-lesson-21-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"At eight, I was studying.. They weren’t sleeping.. Was she cooking?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d885737b-ed6d-5b15-ad69-195ca9983a33'::uuid,'441cb0c2-cb15-5e19-a460-2f006c942811'::uuid,'multiple_choice',1,'{"question":"At nine last night, we … TV.","choices":[{"id":"choice_1","text":"were watching"},{"id":"choice_2","text":"was watched"},{"id":"choice_3","text":"watching"}],"correctChoiceId":"choice_1","explanation":"we + were + ing"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7d51b742-b684-5d10-a8d7-b78147e9c722'::uuid,'441cb0c2-cb15-5e19-a460-2f006c942811'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามถูก","choices":[{"id":"choice_1","text":"Did she was cooking?"},{"id":"choice_2","text":"Was she cooking?"},{"id":"choice_3","text":"Was she cooked?"}],"correctChoiceId":"choice_2","explanation":"Was สลับหน้าประธานและ cooking คง ing"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('76e1401e-4d62-5f19-a319-425affac4eb7'::uuid,'441cb0c2-cb15-5e19-a460-2f006c942811'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกสิ่งกำลังทำเมื่อวานสามช่วงเวลา แล้วถามหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nAt seven, I was eating. At eight, I was reading. At nine, I was sleeping. Were you studying at eight?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **was/were + ing** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a91a2fb7-4827-5fe4-a093-abd5a990ed90'::uuid,'4a24abb1-db14-5a83-a544-b4dcf2ee8dc3'::uuid,'reading',1,'{"title":"ฉากหลังกับเหตุการณ์หลัก","body":"## ฉากหลังกับเหตุการณ์หลัก\n\nPast Continuous ให้ฉากหลังหรือภาพกิจกรรมที่กำลังดำเนิน ส่วน Past Simple เล่าเหตุการณ์หลักหรือสิ่งที่มองเป็นหน่วยจบ เช่น I was walking when it started to rain. continuous ไม่จำเป็นต้องถูกขัดจังหวะเสมอ At eight, I was reading. ก็สมบูรณ์ได้โดยไม่มีเหตุการณ์แทรก\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I was walking when it started to rain. | ฉากหลัง + เหตุการณ์เกิด |\n| I walked home and cooked dinner. | เหตุการณ์ตามลำดับ |\n| At eight, I was reading. | กำลังทำ ไม่จำเป็นต้องมีอะไรแทรก |\n\n### จุดที่มักสับสน\n\nอย่ากำหนดกฎว่า continuous ต้องมี when ทุกประโยค\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ฉากหลังกับเหตุการณ์หลัก: I was reading.; The phone rang.; while + ongoing activity](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/3de7dcd93a4bca83-module-21-map.png)\n\n*I was reading when the phone rang.  •  continuous ไม่ต้องมีเหตุการณ์แทรกเสมอ*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n![ภาพสามช่อง Mai เดินในสวน จากนั้นฝนตก Ben ใช้ร่มช่วยและทั้งคู่ถึงร้านกาแฟ](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4253d113ce35a709-rain-story.png)\n\n*Mai was walking when it began to rain. Ben opened his umbrella. Then they reached a cafe.*\n\nใช้ภาพเป็นเรื่องใหม่สำหรับฝึก ไม่เปลี่ยนข้อเท็จจริงของตัวอย่างเดิม เล่าลำดับที่เห็น หรือเสนอแผนเมื่อมีฝนตามหัวข้อบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('857cf481-69b2-5e4e-a6aa-21b7ec37e927'::uuid,'4a24abb1-db14-5a83-a544-b4dcf2ee8dc3'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2c76ab657d8307e8-lesson-21-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I was walking when it started to rain.. I walked home and cooked dinner.. At eight, I was reading."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c9f1c7cf-1262-5e06-ac73-eeaef871632d'::uuid,'4a24abb1-db14-5a83-a544-b4dcf2ee8dc3'::uuid,'multiple_choice',1,'{"question":"ฉากหลังกำลังอ่านตอนโทรศัพท์ดัง ใช้รูปใด?","choices":[{"id":"choice_1","text":"I was reading when the phone rang."},{"id":"choice_2","text":"I reading when the phone rang."},{"id":"choice_3","text":"I was read when the phone rang."}],"correctChoiceId":"choice_1","explanation":"was reading กิจกรรมดำเนิน; rang เหตุการณ์"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8cc2139a-fd22-5aff-ad29-a27599e3e617'::uuid,'4a24abb1-db14-5a83-a544-b4dcf2ee8dc3'::uuid,'multiple_choice',1,'{"question":"At ten, he was sleeping จำเป็นต้องมีเหตุการณ์แทรกหรือไม่?","choices":[{"id":"choice_1","text":"ไม่จำเป็น"},{"id":"choice_2","text":"จำเป็นเสมอ"},{"id":"choice_3","text":"ต้องมี did ตาม"}],"correctChoiceId":"choice_1","explanation":"continuous บอกภาพกิจกรรมในเวลาอดีตได้เอง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a25c34e1-2a7a-594e-a008-1027c3754dcb'::uuid,'4a24abb1-db14-5a83-a544-b4dcf2ee8dc3'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนฉากหลังสองประโยคและเหตุการณ์หลักสองประโยค\n\n### ตัวอย่างคำตอบ\n\nI was sitting in the park. Mai was reading. A dog ran past us. We smiled.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ฉากหลังกับเหตุการณ์หลัก** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2558a569-9571-5aa6-a2c3-8c0d56e7b6e2'::uuid,'85ed89f5-4d9f-5e2c-aacf-a7b8db3e4be0'::uuid,'reading',1,'{"title":"when/while","body":"## when/while\n\nwhen เชื่อมเหตุการณ์กับช่วงเวลาที่อีกเหตุการณ์เกิด ส่วน while มักเน้นระหว่างกิจกรรมที่ดำเนิน เช่น While I was cooking, Ben was reading. ถ้าเหตุการณ์สั้นแทรกใช้ I was cooking when Ben called. เลือก tense จากสิ่งที่ต้องการเล่า ไม่ใช่ท่องว่า when ต้องตามด้วย V2 หรือ while ต้อง continuous ทุกความหมาย\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I was studying when Mai called. | เหตุการณ์หนึ่งเกิดระหว่างอีกกิจกรรม |\n| While I was studying, Mai was reading. | สองกิจกรรมพร้อมกัน |\n\n### จุดที่มักสับสน\n\nwhen/while เป็นคำเชื่อม แต่ tense ตามความหมายและบริบท ไม่ใช่สูตรบังคับหนึ่งแบบ\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ภาพสามช่อง Mai เดินในสวน จากนั้นฝนตก Ben ใช้ร่มช่วยและทั้งคู่ถึงร้านกาแฟ](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4253d113ce35a709-rain-story.png)\n\n*Mai was walking when it began to rain. Ben opened his umbrella. Then they reached a cafe.*\n\nใช้ภาพเป็นเรื่องใหม่สำหรับฝึก ไม่เปลี่ยนข้อเท็จจริงของตัวอย่างเดิม เล่าลำดับที่เห็น หรือเสนอแผนเมื่อมีฝนตามหัวข้อบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0e0a8b99-6d15-5c79-a689-004160d6a5cc'::uuid,'85ed89f5-4d9f-5e2c-aacf-a7b8db3e4be0'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/1e255a69494ff1c3-lesson-21-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I was studying when Mai called.. While I was studying, Mai was reading."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('66d7dd29-1673-5940-a530-3f7cd244c7ff'::uuid,'85ed89f5-4d9f-5e2c-aacf-a7b8db3e4be0'::uuid,'multiple_choice',1,'{"question":"สองกิจกรรมกำลังเกิดพร้อมกันในอดีต เลือก","choices":[{"id":"choice_1","text":"While I was cooking, Ben was reading."},{"id":"choice_2","text":"While I cooking, Ben reading."},{"id":"choice_3","text":"While I cook, Ben readed."}],"correctChoiceId":"choice_1","explanation":"ทั้งสองมี was + ing"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('791649ef-7571-52fa-ad34-f6746043e72e'::uuid,'85ed89f5-4d9f-5e2c-aacf-a7b8db3e4be0'::uuid,'multiple_choice',1,'{"question":"ใน I was walking when it began to rain เหตุการณ์ที่เกิดขึ้นคืออะไร?","choices":[{"id":"choice_1","text":"ฝนเริ่มตก"},{"id":"choice_2","text":"การเดินเป็นจุดเดียวเท่านั้น"},{"id":"choice_3","text":"ไม่มีเหตุการณ์"}],"correctChoiceId":"choice_1","explanation":"began เป็น Past Simple บอกจุดเริ่มฝน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cf4394b5-1777-5f1a-ac21-b532feecf2ff'::uuid,'85ed89f5-4d9f-5e2c-aacf-a7b8db3e4be0'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนหนึ่งเรื่องเหตุการณ์แทรกและหนึ่งเรื่องกิจกรรมพร้อมกัน\n\n### ตัวอย่างคำตอบ\n\nI was reading when my friend called. While I was reading, my sister was cooking.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **when/while** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c854b158-c439-504f-aaec-fce0659c2171'::uuid,'360a2091-8525-55bc-a4c5-2f3b86092779'::uuid,'reading',1,'{"title":"เรียงเรื่องให้คนฟังตามทัน","body":"## เรียงเรื่องให้คนฟังตามทัน\n\nfirst/then/after that/finally ช่วยให้ผู้อ่านตามลำดับเรื่องได้ เริ่มจากเหตุการณ์สำคัญและเชื่อมข้อมูลแต่ละประโยคให้ผู้ทำชัด ใช้ Past Simple กับเหตุการณ์ที่เกิดต่อกัน และ Past Continuous เมื่อต้องการฉากหลัง ไม่ใส่ทุกคำเชื่อมซ้ำจนข้อความหนัก\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| First, I bought food. Then I cooked. | ลำดับ |\n| After that, I ate. Finally, I washed the dishes. | ช่วงถัดไปจนจบ |\n\n### จุดที่มักสับสน\n\nthen หมายถึงจากนั้น; than ใช้เปรียบเทียบและสะกดต่างกัน\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ภาพสามช่อง Mai เดินในสวน จากนั้นฝนตก Ben ใช้ร่มช่วยและทั้งคู่ถึงร้านกาแฟ](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4253d113ce35a709-rain-story.png)\n\n*Mai was walking when it began to rain. Ben opened his umbrella. Then they reached a cafe.*\n\nใช้ภาพเป็นเรื่องใหม่สำหรับฝึก ไม่เปลี่ยนข้อเท็จจริงของตัวอย่างเดิม เล่าลำดับที่เห็น หรือเสนอแผนเมื่อมีฝนตามหัวข้อบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4ca362a8-6f88-5096-a95c-8d5612c7d4ef'::uuid,'360a2091-8525-55bc-a4c5-2f3b86092779'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/dac318bd565a54c8-lesson-21-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"First, I bought food. Then I cooked.. After that, I ate. Finally, I washed the dishes."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8b8b48e9-b2f0-570d-a7b6-67587eeb5ad2'::uuid,'360a2091-8525-55bc-a4c5-2f3b86092779'::uuid,'multiple_choice',1,'{"question":"คำใดบอกเหตุการณ์สุดท้าย?","choices":[{"id":"choice_1","text":"finally"},{"id":"choice_2","text":"before"},{"id":"choice_3","text":"while"}],"correctChoiceId":"choice_1","explanation":"finally ชี้ช่วงสุดท้ายของเรื่อง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f6acd5bb-c14d-5083-abb9-64a952f7c2ee'::uuid,'360a2091-8525-55bc-a4c5-2f3b86092779'::uuid,'multiple_choice',1,'{"question":"เลือกเรื่องเรียงตรรกะกิจกรรม","choices":[{"id":"choice_1","text":"I cooked, then I ate."},{"id":"choice_2","text":"I ate the meal, then I cooked that same meal. โดยไม่มีคำอธิบาย"},{"id":"choice_3","text":"I cooked than I ate."}],"correctChoiceId":"choice_1","explanation":"cooked ก่อน ate ในบริบทอาหารมื้อนี้ และใช้ then"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cf464fa7-dd76-5d6c-a409-9c3c16497115'::uuid,'360a2091-8525-55bc-a4c5-2f3b86092779'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเรียงกิจกรรมเช้า 4 ขั้นด้วย first/then/after that/finally\n\n### ตัวอย่างคำตอบ\n\nFirst, I got up. Then I had breakfast. After that, I took a bus. Finally, I arrived at school.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เรียงเรื่องให้คนฟังตามทัน** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7425675f-5439-5000-af3c-7daeaeab9c9e'::uuid,'fc25080e-568a-54e2-af94-88eb70f88c2a'::uuid,'reading',1,'{"title":"ฟังและเล่าเรื่องสั้น","body":"## ฟังและเล่าเรื่องสั้น\n\nฟังเรื่องสั้นรอบแรกจับว่าใครทำอะไร รอบสองจดช่วงเวลาและเหตุการณ์แทรก แล้วเล่าใหม่โดยรักษาข้อเท็จจริงกับ pronouns อย่าเปลี่ยนผู้ทำเพราะจำแต่คำกริยา ใช้ past continuous สำหรับฉากหลังและ simple สำหรับเหตุการณ์หลัก ยืนยันข้อมูลที่ไม่แน่ใจด้วยคำถาม\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| At six, Mai was walking home. It began to rain. | Mai เดินก่อนฝนเริ่ม |\n| Ben saw her and gave her an umbrella. | Ben ให้ร่มแก่ Mai |\n\n### จุดที่มักสับสน\n\nการเล่าใหม่ไม่ต้องเหมือนคำเดิม แต่ห้ามเติมข้อมูลที่ต้นเรื่องไม่มี\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ภาพสามช่อง Mai เดินในสวน จากนั้นฝนตก Ben ใช้ร่มช่วยและทั้งคู่ถึงร้านกาแฟ](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4253d113ce35a709-rain-story.png)\n\n*Mai was walking when it began to rain. Ben opened his umbrella. Then they reached a cafe.*\n\nใช้ภาพเป็นเรื่องใหม่สำหรับฝึก ไม่เปลี่ยนข้อเท็จจริงของตัวอย่างเดิม เล่าลำดับที่เห็น หรือเสนอแผนเมื่อมีฝนตามหัวข้อบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — A1–A2 grammar](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2b05197e-c378-5abd-a442-f7fb84f08447'::uuid,'fc25080e-568a-54e2-af94-88eb70f88c2a'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/dfa257070615a8a9-lesson-21-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"At six, Mai was walking home. It began to rain. Ben saw her and gave her an umbrella. Then Mai went home."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3ff5330f-fc31-5406-a651-633a9fd63c39'::uuid,'fc25080e-568a-54e2-af94-88eb70f88c2a'::uuid,'multiple_choice',1,'{"question":"Mai was walking. Ben gave her an umbrella. ใครให้ร่ม?","choices":[{"id":"choice_1","text":"Mai"},{"id":"choice_2","text":"Ben"},{"id":"choice_3","text":"ไม่ระบุผู้ทำ"}],"correctChoiceId":"choice_2","explanation":"Ben เป็น subject ของ gave"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('510feae0-abd2-5358-a828-306320acb0fb'::uuid,'fc25080e-568a-54e2-af94-88eb70f88c2a'::uuid,'multiple_choice',1,'{"question":"her ใน Ben gave her an umbrella อ้างใครตามเรื่อง?","choices":[{"id":"choice_1","text":"Mai"},{"id":"choice_2","text":"Ben"},{"id":"choice_3","text":"ร่ม"}],"correctChoiceId":"choice_1","explanation":"Mai เป็นคนที่อ้างก่อนและได้รับร่ม"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5be32a6c-0fb6-54fb-a189-595162e75b55'::uuid,'fc25080e-568a-54e2-af94-88eb70f88c2a'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nฟังเรื่อง Mai กับ Ben แล้วเล่าใหม่ 3–4 ประโยค จากนั้นตั้งคำถามเช็กข้อมูลหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nMai was walking home at six. It began to rain. Ben saw Mai and gave her an umbrella. Did Ben give her an umbrella? Yes, he did.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ฟังและเล่าเรื่องสั้น** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f1cc1311-284a-57e1-a759-b2a20f879661'::uuid,'0799871e-d3e1-560c-ab46-e627f04216de'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เล่าฉากหลัง เหตุการณ์ต่อเนื่อง และเหตุการณ์ที่เข้ามาระหว่างนั้น**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ฉากหลังกับเหตุการณ์หลัก: I was reading.; The phone rang.; while + ongoing activity](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/3de7dcd93a4bca83-module-21-map.png)\n\n*I was reading when the phone rang.  •  continuous ไม่ต้องมีเหตุการณ์แทรกเสมอ*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6123c38f-76a5-5ee8-aec1-8d34edadd71f'::uuid,'0799871e-d3e1-560c-ab46-e627f04216de'::uuid,'multiple_choice',1,'{"question":"We … lunch when Mai arrived.","choices":[{"id":"choice_1","text":"were eating"},{"id":"choice_2","text":"was eating"},{"id":"choice_3","text":"were ate"}],"correctChoiceId":"choice_1","explanation":"we + were + ing ฉากหลัง ย้อน 21.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bb15fc2a-075b-532c-a4c1-37c0cbe629f6'::uuid,'0799871e-d3e1-560c-ab46-e627f04216de'::uuid,'multiple_choice',1,'{"question":"While Ben was reading, I was cooking สื่ออะไร?","choices":[{"id":"choice_1","text":"สองกิจกรรมดำเนินพร้อมกัน"},{"id":"choice_2","text":"ทุกกิจกรรมจบก่อนกัน"},{"id":"choice_3","text":"เป็นคำสั่ง"}],"correctChoiceId":"choice_1","explanation":"while เชื่อมภาพกิจกรรมพร้อมกัน ย้อน 21.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bb4abf9f-66e5-5f89-a7f8-3edb1be30218'::uuid,'0799871e-d3e1-560c-ab46-e627f04216de'::uuid,'multiple_choice',1,'{"question":"คำใดเหมาะชี้ขั้นสุดท้ายของเรื่อง?","choices":[{"id":"choice_1","text":"Finally"},{"id":"choice_2","text":"Than"},{"id":"choice_3","text":"Whose"}],"correctChoiceId":"choice_1","explanation":"Finally ลำดับสุดท้าย ย้อน 21.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6b2fdf79-8d4d-522c-a4aa-2ce0e53c2ef8'::uuid,'0799871e-d3e1-560c-ab46-e627f04216de'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเล่าเรื่องสั้นที่มีฉากหลัง เหตุการณ์แทรกและตอนจบ แล้วสรุปว่าใครทำอะไร\n\n### ตัวอย่างผลงาน\n\nI was walking home when it began to rain. Ben was driving nearby. He stopped and helped me. Finally, we went home together.\n\n### ตรวจผลงาน\n\n- แยกฉากหลังจากเหตุการณ์หลัก\n- when/while ตามความสัมพันธ์\n- pronouns กับลำดับไม่เปลี่ยนข้อเท็จจริง\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('64026b39-1546-5c9f-ac9e-33e1f57f91c3'::uuid,'ed6f4ea8-d2bc-5c3b-a75c-6974166df7df'::uuid,'reading',1,'{"title":"be going to","body":"## be going to\n\nbe going to + base verb ใช้แผนหรือความตั้งใจและการคาดการณ์จากหลักฐาน เช่น I am going to study tonight. / Look at the clouds. It is going to rain. ปฏิเสธเติม not หลัง be และคำถามสลับ be ไปหน้า subject รูป going to ไม่ใช่การเดินทางทุกครั้ง แต่ go to the shop เป็นอีกโครง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I am going to cook tonight. | ความตั้งใจ |\n| She isn’t going to drive. | ปฏิเสธ |\n| Are you going to study? | ถามแผน |\n\n### จุดที่มักสับสน\n\nI going to study ขาด am; I am going study ขาด to\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ภาพสามช่อง Mai เดินในสวน จากนั้นฝนตก Ben ใช้ร่มช่วยและทั้งคู่ถึงร้านกาแฟ](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4253d113ce35a709-rain-story.png)\n\n*Mai was walking when it began to rain. Ben opened his umbrella. Then they reached a cafe.*\n\nใช้ภาพเป็นเรื่องใหม่สำหรับฝึก ไม่เปลี่ยนข้อเท็จจริงของตัวอย่างเดิม เล่าลำดับที่เห็น หรือเสนอแผนเมื่อมีฝนตามหัวข้อบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('70c140ae-fd9b-5fd6-a0e5-7533df129de1'::uuid,'ed6f4ea8-d2bc-5c3b-a75c-6974166df7df'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/766f107f4527a55e-lesson-22-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I am going to cook tonight.. She isn’t going to drive.. Are you going to study?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('92376ab2-24f1-5fc1-a8e2-9a8747e716d7'::uuid,'ed6f4ea8-d2bc-5c3b-a75c-6974166df7df'::uuid,'multiple_choice',1,'{"question":"เลือกแผนที่ถูก","choices":[{"id":"choice_1","text":"She is going to visit Mai."},{"id":"choice_2","text":"She going to visit Mai."},{"id":"choice_3","text":"She is going visit Mai."}],"correctChoiceId":"choice_1","explanation":"be + going to + base visit"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f6f102c8-eff2-53ce-aba2-b16e56f214f2'::uuid,'ed6f4ea8-d2bc-5c3b-a75c-6974166df7df'::uuid,'multiple_choice',1,'{"question":"Look at the dark clouds. It … rain.","choices":[{"id":"choice_1","text":"is going to"},{"id":"choice_2","text":"going to"},{"id":"choice_3","text":"is going"}],"correctChoiceId":"choice_1","explanation":"is going to rain คาดการณ์จากหลักฐาน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('af750c96-1034-59b8-a8d2-bd6b66e755f9'::uuid,'ed6f4ea8-d2bc-5c3b-a75c-6974166df7df'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนแผนสองข้อ คำถามหนึ่งข้อและปฏิเสธหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nI am going to study tonight. I am going to cook. Are you going to work? I am not going to drive.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **be going to** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('207b65fa-6f3b-578e-ad37-84051a296a01'::uuid,'e9cfb76f-f362-51fd-a175-849dadaaa3a3'::uuid,'reading',1,'{"title":"will/won''t","body":"## will/won''t\n\nwill + base verb ใช้การตัดสินใจขณะพูด ข้อเสนอ คำสัญญาหรือคาดการณ์ เช่น I’ll help you. won’t คือ will not ทุกประธานใช้รูปเดียว คำถาม Will + subject + base? ตอบ Yes, I will./No, I won’t. will ไม่ได้ใช้แทนทุกประโยคที่มีเวลาอนาคต\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I’ll carry your bag. | เสนอช่วย |\n| I won’t be late. | คำสัญญาปฏิเสธ |\n| Will she come? | ถามอนาคต |\n\n### จุดที่มักสับสน\n\nShe will comes และ will to come ผิด; will + be เมื่อตามด้วย adjective\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('db8e373f-8312-5026-a11b-b12ab900257b'::uuid,'e9cfb76f-f362-51fd-a175-849dadaaa3a3'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/a72c21f625db3dff-lesson-22-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I’ll carry your bag.. I won’t be late.. Will she come?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c6da33f1-2410-583c-adcf-9d38bba624b9'::uuid,'e9cfb76f-f362-51fd-a175-849dadaaa3a3'::uuid,'multiple_choice',1,'{"question":"เลือกคำเสนอช่วยถูก","choices":[{"id":"choice_1","text":"I’ll help you."},{"id":"choice_2","text":"I’ll to help you."},{"id":"choice_3","text":"I’ll helps you."}],"correctChoiceId":"choice_1","explanation":"will + base help"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('09e4e958-a6cb-5cd8-a2ca-645e840ccb91'::uuid,'e9cfb76f-f362-51fd-a175-849dadaaa3a3'::uuid,'multiple_choice',1,'{"question":"won’t ย่อจากอะไร?","choices":[{"id":"choice_1","text":"will not"},{"id":"choice_2","text":"want not"},{"id":"choice_3","text":"would not"}],"correctChoiceId":"choice_1","explanation":"won’t = will not"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('05446575-db12-5f0e-af4b-2b66f8f6fb0c'::uuid,'e9cfb76f-f362-51fd-a175-849dadaaa3a3'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนข้อเสนอ คำสัญญาและคำถามด้วย will\n\n### ตัวอย่างคำตอบ\n\nI’ll open the door. I won’t be late. Will you call me?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **will/won''t** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c21dde4d-40f2-5455-aa2e-6b08b5e64e7a'::uuid,'cf976fe0-5ee6-50e3-ad12-ef341cde991e'::uuid,'reading',1,'{"title":"going to เทียบ will","body":"## going to เทียบ will\n\ngoing to มักชี้ความตั้งใจที่มีมาก่อนหรือหลักฐานปัจจุบัน ส่วน will มักใช้ตัดสินใจขณะพูด ข้อเสนอและคาดการณ์ทั่วไป แต่ทั้งสองมีบริบททับซ้อน จึงไม่กำหนดว่าคำอนาคตประโยคหนึ่งมีได้รูปเดียวเสมอ เลือกรูปตามสิ่งที่ผู้พูดต้องการเน้น\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I bought food. I’m going to cook tonight. | แผนมีมาก่อน |\n| The phone is ringing. I’ll answer it. | ตัดสินใจตอนนี้ |\n| I think it will rain tomorrow. | คาดการณ์ |\n\n### จุดที่มักสับสน\n\nถ้าโจทย์ไม่ให้บริบทเพียงพอ will/going to อาจใช้ได้ทั้งคู่ ต้องไม่สร้างข้อสอบที่บังคับคำตอบเดียวโดยไม่มีเหตุผล\n\n\n\n### ดูภาพแล้วลองใช้\n\n![เลือกจากแผน นัดและบริบท: I’m going to study.; I’ll help you.; I’m meeting Mai. / It leaves.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/b47cc93e4761ebd8-module-22-map.png)\n\n*รูปต่าง ๆ ทับซ้อนกันได้บางบริบท ไม่ใช่สูตรแยกเด็ดขาด*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('94a6db06-5b3c-5a79-a448-a989411c27e9'::uuid,'cf976fe0-5ee6-50e3-ad12-ef341cde991e'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4ebb31d3c27a34e5-lesson-22-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I bought food. I’m going to cook tonight.. The phone is ringing. I’ll answer it.. I think it will rain tomorrow."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4d41a6cd-8356-5cc5-aa06-071dd3655a6a'::uuid,'cf976fe0-5ee6-50e3-ad12-ef341cde991e'::uuid,'multiple_choice',1,'{"question":"โทรศัพท์ดังและคุณตัดสินใจรับทันที รูปที่บทนี้เน้นคืออะไร?","choices":[{"id":"choice_1","text":"I’ll answer it."},{"id":"choice_2","text":"I answered it."},{"id":"choice_3","text":"I answer it yesterday."}],"correctChoiceId":"choice_1","explanation":"will ใช้ตอบสนองตัดสินใจตอนพูด"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('42ff45c1-99a7-5b88-a447-d681af9b0a43'::uuid,'cf976fe0-5ee6-50e3-ad12-ef341cde991e'::uuid,'multiple_choice',1,'{"question":"สองรูป will/going to ทับซ้อนในบางบริบทหรือไม่?","choices":[{"id":"choice_1","text":"ได้ ต้องดูความหมายที่เน้น"},{"id":"choice_2","text":"ไม่ได้เลยทุกประโยค"},{"id":"choice_3","text":"ไม่มีรูป going to จริง"}],"correctChoiceId":"choice_1","explanation":"แนวโน้มการใช้ไม่ใช่กฎห้ามทับซ้อน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a765040b-f8cd-557e-ab60-deadf10dae63'::uuid,'cf976fe0-5ee6-50e3-ad12-ef341cde991e'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนแผนที่มีมาก่อนหนึ่งข้อและการตัดสินใจตอนนี้หนึ่งข้อ พร้อมบอกบริบท\n\n### ตัวอย่างคำตอบ\n\nI have bought vegetables. I’m going to make dinner. Someone is at the door. I’ll open it.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **going to เทียบ will** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('600c017b-a448-5cc0-adac-a1cdf8d5c019'::uuid,'f683a0cf-dd1d-5f03-a50f-45f9685202b6'::uuid,'reading',1,'{"title":"Present Continuous สำหรับนัดหมาย","body":"## Present Continuous สำหรับนัดหมาย\n\nPresent Continuous ใช้กับนัดหมายอนาคตที่จัดการแล้วได้เมื่อมีบริบทเวลา เช่น I’m meeting Mai at six tomorrow. ไม่ได้หมายถึงกำลังพบขณะนี้เสมอ เปรียบเทียบ I’m meeting Mai now. ดูเวลาและสถานการณ์ be + ing เหมือนเดิมและคำถามใช้ be\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I’m seeing the doctor tomorrow. | นัดที่จัดไว้ |\n| We’re meeting at six tonight. | นัดร่วม |\n| Are you working tomorrow? | ถามตารางส่วนตัว |\n\n### จุดที่มักสับสน\n\nรูป ing ไม่รับรองว่าเป็นปัจจุบันในความหมาย ต้องอ่านเวลาและบริบท\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bc3454ad-614b-5d60-a220-bda4bbaf9afe'::uuid,'f683a0cf-dd1d-5f03-a50f-45f9685202b6'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/263ea91623e3bffa-lesson-22-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I’m seeing the doctor tomorrow.. We’re meeting at six tonight.. Are you working tomorrow?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cce67488-2109-55f2-a884-ea7025218b06'::uuid,'f683a0cf-dd1d-5f03-a50f-45f9685202b6'::uuid,'multiple_choice',1,'{"question":"I’m meeting Ben tomorrow หมายถึงอะไร?","choices":[{"id":"choice_1","text":"นัดพบอนาคต"},{"id":"choice_2","text":"พบแล้วเมื่อวาน"},{"id":"choice_3","text":"คำสั่งให้ Ben มา"}],"correctChoiceId":"choice_1","explanation":"tomorrow ทำให้ continuous ใช้กับ arrangement"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('940dee49-42ad-58bf-a6c5-c3120ddc10a7'::uuid,'f683a0cf-dd1d-5f03-a50f-45f9685202b6'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามนัดหมายที่ถูก","choices":[{"id":"choice_1","text":"Are you meeting her tonight?"},{"id":"choice_2","text":"Do you meeting her tonight?"},{"id":"choice_3","text":"Are you meet her tonight?"}],"correctChoiceId":"choice_1","explanation":"Are + subject + ing"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('25056387-a1f5-5caa-a34b-83f36550fad0'::uuid,'f683a0cf-dd1d-5f03-a50f-45f9685202b6'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนนัดสองข้อที่มีเวลาและสถานที่ แล้วถามเพื่อนหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nI’m meeting Mai at the cafe at six tomorrow. We’re playing tennis on Sunday. Are you joining us?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Present Continuous สำหรับนัดหมาย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a47fdfdf-2735-580e-a402-b7988c823dfa'::uuid,'682f8a70-fba3-548a-af93-b81e8b11f339'::uuid,'reading',1,'{"title":"Present Simple สำหรับตาราง","body":"## Present Simple สำหรับตาราง\n\nPresent Simple ใช้กำหนดการหรือตารางอนาคต เช่น The train leaves at seven tomorrow. คำ tomorrow ไม่บังคับ will กริยายังตรงประธาน leaves สำหรับ train หนึ่งขบวน ตารางใช้ do/does ถามกริยาทั่วไป เช่น What time does the shop open? ส่วน be ใช้ Is/Are ตามเดิม\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The train leaves at seven tomorrow. | ตาราง |\n| The shop opens at nine. | เวลาเปิด |\n| What time does the class start? | does + base |\n\n### จุดที่มักสับสน\n\nไม่ใช้ The train leave กับประธานหนึ่งเพียงเพราะพูดถึงอนาคต\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('32004224-8627-59dd-ad3f-a7f149959f3b'::uuid,'682f8a70-fba3-548a-af93-b81e8b11f339'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/0e0e919c86d151c8-lesson-22-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The train leaves at seven tomorrow.. The shop opens at nine.. What time does the class start?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('76c597b8-8033-58de-a6fd-a6b9c70a6f06'::uuid,'682f8a70-fba3-548a-af93-b81e8b11f339'::uuid,'multiple_choice',1,'{"question":"ตารางรถไฟหนึ่งขบวน: The train … at eight.","choices":[{"id":"choice_1","text":"leaves"},{"id":"choice_2","text":"leave"},{"id":"choice_3","text":"is leave"}],"correctChoiceId":"choice_1","explanation":"Present Simple timetable และ train singular"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('eaa004e4-1c7f-59a0-a3cd-0ab6bafd8411'::uuid,'682f8a70-fba3-548a-af93-b81e8b11f339'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามเวลาเริ่มถูก","choices":[{"id":"choice_1","text":"What time does the film start?"},{"id":"choice_2","text":"What time does the film starts?"},{"id":"choice_3","text":"What time the film start?"}],"correctChoiceId":"choice_1","explanation":"does + base start"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8d691dc1-d8aa-5752-aa77-1e22676de528'::uuid,'682f8a70-fba3-548a-af93-b81e8b11f339'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nทำตารางกิจกรรมสามรายการแล้วถาม–ตอบเวลาเริ่ม\n\n### ตัวอย่างคำตอบ\n\nThe train leaves at eight. The class starts at nine. The cafe opens at ten. What time does the cafe open? At ten.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Present Simple สำหรับตาราง** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ce65ed55-7412-51c2-a0af-f7f2af7be094'::uuid,'a9e2be93-0941-5933-ace6-e401c02c8371'::uuid,'reading',1,'{"title":"ชวนและเสนอด้วย shall/would like","body":"## ชวนและเสนอด้วย shall/would like\n\nShall I…? เสนอให้ผู้พูดช่วย; Shall we…? เสนอทำร่วมกันในภาษาอังกฤษที่ใช้รูปนี้ Would you like + noun? เสนอสิ่งของ และ Would you like to + verb? ชวนทำ ตอบ Yes, please./No, thank you. สำหรับสิ่งของหรือ I’d love to./Sorry, I can’t. สำหรับคำชวน ใช้รูปให้เหมาะข้อมูล\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Shall I carry your bag? | เสนอช่วย |\n| Shall we meet at six? | เสนอร่วมกัน |\n| Would you like some tea? | เสนอของ |\n| Would you like to come? | ชวนทำ |\n\n### จุดที่มักสับสน\n\nWould you like come? ขาด to เมื่อมี verb ตาม แต่ Would you like tea? ไม่ต้อง to\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('38ab41c0-c8d4-5bed-ab7b-f01732d32d15'::uuid,'a9e2be93-0941-5933-ace6-e401c02c8371'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d343ad51083569ad-lesson-22-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Shall I carry your bag?. Shall we meet at six?. Would you like some tea?. Would you like to come?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('85871f06-52c6-5ab8-a477-0f7571bea523'::uuid,'a9e2be93-0941-5933-ace6-e401c02c8371'::uuid,'multiple_choice',1,'{"question":"ชวนมาร่วมด้วย เลือกรูปใด?","choices":[{"id":"choice_1","text":"Would you like to join us?"},{"id":"choice_2","text":"Would you like join us?"},{"id":"choice_3","text":"Would you like to tea?"}],"correctChoiceId":"choice_1","explanation":"would like to + verb join"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('132e6de7-9fd3-5c75-a6bf-f81045c9a50e'::uuid,'a9e2be93-0941-5933-ace6-e401c02c8371'::uuid,'multiple_choice',1,'{"question":"Shall I open the door? สื่ออะไร?","choices":[{"id":"choice_1","text":"เสนอให้ฉันเปิด"},{"id":"choice_2","text":"ถามว่าคุณเปิดเมื่อวานไหม"},{"id":"choice_3","text":"บอกความถี่"}],"correctChoiceId":"choice_1","explanation":"Shall I เป็นข้อเสนอให้ผู้พูดช่วย"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6cba125f-e496-5285-a272-c16e8d6412f7'::uuid,'a9e2be93-0941-5933-ace6-e401c02c8371'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nสร้างบทนัดสี่บรรทัดที่เสนอเวลา ชวนและตอบสุภาพ\n\n### ตัวอย่างคำตอบ\n\nShall we meet at six? That’s a good idea. Would you like to have dinner? I’d love to.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ชวนและเสนอด้วย shall/would like** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b2137c0a-7d9c-5fbc-ad0d-e3f97a85fee5'::uuid,'317723c2-3ec0-50f9-a4ea-60d70d0af848'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เลือกโครงสร้างอนาคตให้ตรงแผน นัดหมาย การตัดสินใจ และตาราง**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![เลือกจากแผน นัดและบริบท: I’m going to study.; I’ll help you.; I’m meeting Mai. / It leaves.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/b47cc93e4761ebd8-module-22-map.png)\n\n*รูปต่าง ๆ ทับซ้อนกันได้บางบริบท ไม่ใช่สูตรแยกเด็ดขาด*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9ec3e685-d047-5ae9-a121-647058731e5f'::uuid,'317723c2-3ec0-50f9-a4ea-60d70d0af848'::uuid,'multiple_choice',1,'{"question":"We have tickets. We … to Chiang Mai tomorrow.","choices":[{"id":"choice_1","text":"are travelling"},{"id":"choice_2","text":"are travel"},{"id":"choice_3","text":"travelling"}],"correctChoiceId":"choice_1","explanation":"arrangement ใช้ continuous กับเวลาอนาคต ย้อน 22.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e1c918c7-ca89-51c5-aca0-6e1a8790315e'::uuid,'317723c2-3ec0-50f9-a4ea-60d70d0af848'::uuid,'multiple_choice',1,'{"question":"The bus … at six tomorrow ตามตาราง.","choices":[{"id":"choice_1","text":"leaves"},{"id":"choice_2","text":"leave"},{"id":"choice_3","text":"is leave"}],"correctChoiceId":"choice_1","explanation":"timetable present simple singular ย้อน 22.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('82bb3cbd-ea86-5c31-adb3-dddba5a0df7d'::uuid,'317723c2-3ec0-50f9-a4ea-60d70d0af848'::uuid,'multiple_choice',1,'{"question":"เสนอช่วยถือกล่องทันที ใช้รูปใด?","choices":[{"id":"choice_1","text":"I’ll carry it."},{"id":"choice_2","text":"I carried it yesterday."},{"id":"choice_3","text":"I carry it yesterday."}],"correctChoiceId":"choice_1","explanation":"will เป็นข้อเสนอตอนพูด ย้อน 22.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2c79de03-13ea-5988-a15d-12aa9dfe68fa'::uuid,'317723c2-3ec0-50f9-a4ea-60d70d0af848'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเขียนแผนมีมาก่อน นัดที่จัดแล้ว ตาราง และข้อเสนอช่วยอย่างละหนึ่ง จากนั้นชวนเพื่อน\n\n### ตัวอย่างผลงาน\n\nI’m going to pack tonight. I’m meeting Mai at five tomorrow. The bus leaves at six. I’ll carry your bag. Would you like to join us?\n\n### ตรวจผลงาน\n\n- รูปอนาคตตรงความหมายที่ต้องการเน้น\n- be+going to/ing และ will+base ครบ\n- ใช้ข้อเสนอและคำชวนสุภาพ\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('abaae00d-265f-5e7e-a239-038a82a866a6'::uuid,'fc0edf6b-0fcc-50a9-a7f6-eda9c52a0b89'::uuid,'reading',1,'{"title":"ขั้นกว่า -er/more + than","body":"## ขั้นกว่า -er/more + than\n\ncomparative เปรียบเทียบสองสิ่งหรือกลุ่ม ใช้ adjective สั้น + er เช่น small→smaller; e ท้ายเติม r: nice→nicer; สระสั้นบางคำซ้ำท้าย: big→bigger; y เปลี่ยน ier: happy→happier คำยาวมัก more + adjective: more expensive ตามด้วย than เมื่อระบุสิ่งที่เทียบ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| This bag is smaller than that one. | smaller + than |\n| This room is more expensive. | more กับคำยาว |\n| Today is hotter than yesterday. | hot → hotter |\n\n### จุดที่มักสับสน\n\nไม่ใช้ more smaller หรือ more better ซ้ำสองเครื่องมือเปรียบเทียบ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Comparative and superlative adjectives](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/comparative-superlative-adjectives)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('33be1b40-5dff-5d02-a9e3-e212ec0a7f58'::uuid,'fc0edf6b-0fcc-50a9-a7f6-eda9c52a0b89'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/a5b44a381ada927b-lesson-23-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"This bag is smaller than that one.. This room is more expensive.. Today is hotter than yesterday."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bb6bea07-2e2d-5177-a73f-52d5138fee12'::uuid,'fc0edf6b-0fcc-50a9-a7f6-eda9c52a0b89'::uuid,'multiple_choice',1,'{"question":"comparative ของ big คืออะไร?","choices":[{"id":"choice_1","text":"biger"},{"id":"choice_2","text":"bigger"},{"id":"choice_3","text":"more big ในรูปที่ฝึก"}],"correctChoiceId":"choice_2","explanation":"ซ้ำ g แล้ว er"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('34185048-5987-59ae-af73-94f65ea23496'::uuid,'fc0edf6b-0fcc-50a9-a7f6-eda9c52a0b89'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคถูก","choices":[{"id":"choice_1","text":"This phone is more cheaper."},{"id":"choice_2","text":"This phone is cheaper than that one."},{"id":"choice_3","text":"This phone cheaper that one."}],"correctChoiceId":"choice_2","explanation":"cheaper + than ไม่เติม more อีก"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6b4856ac-1b7a-5bf1-a048-87b9d7e24a87'::uuid,'fc0edf6b-0fcc-50a9-a7f6-eda9c52a0b89'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเทียบสิ่งของสองคู่ด้วย -er และ more\n\n### ตัวอย่างคำตอบ\n\nMy bag is smaller than Ben’s bag. This phone is more expensive than that one.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ขั้นกว่า -er/more + than** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f277269e-3b85-569e-a61b-89087cf75926'::uuid,'d05bbf58-42da-552e-acf5-14776f3151ed'::uuid,'reading',1,'{"title":"รูปไม่ปกติ","body":"## รูปไม่ปกติ\n\nรูปพิเศษ good→better→best; bad→worse→worst; much/many→more→most ใช้ตามสิ่งที่เทียบ good บรรยายคุณภาพ ส่วน well ที่ขยายการทำก็ใช้ better/best ได้ จำนวนใช้ more เช่น more books/more water ไม่ต้อง more good หรือ gooder\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| This book is better than that one. | good → better |\n| I have more books than Ben. | many → more |\n| She sings better than me. | well → better |\n\n### จุดที่มักสับสน\n\nmore better ผิดเพราะ better เป็นขั้นกว่าอยู่แล้ว\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Comparative and superlative adjectives](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/comparative-superlative-adjectives)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cff74703-8e39-5162-a5ae-788c0ba42ab3'::uuid,'d05bbf58-42da-552e-acf5-14776f3151ed'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/edfabaef3e721d33-lesson-23-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"This book is better than that one.. I have more books than Ben.. She sings better than me."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6102f772-250a-5325-a468-7daad19c5679'::uuid,'d05bbf58-42da-552e-acf5-14776f3151ed'::uuid,'multiple_choice',1,'{"question":"ขั้นกว่าของ bad คืออะไร?","choices":[{"id":"choice_1","text":"badder"},{"id":"choice_2","text":"worse"},{"id":"choice_3","text":"worst"}],"correctChoiceId":"choice_2","explanation":"worse ขั้นกว่า; worst ขั้นสูงสุด"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5b783bfe-a14d-5157-a45c-efcd6fc6fc72'::uuid,'d05bbf58-42da-552e-acf5-14776f3151ed'::uuid,'multiple_choice',1,'{"question":"เลือกวลีเทียบคุณภาพถูก","choices":[{"id":"choice_1","text":"more better"},{"id":"choice_2","text":"better"},{"id":"choice_3","text":"gooder"}],"correctChoiceId":"choice_2","explanation":"ใช้ better ไม่ซ้อน more"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('be445f44-2dbc-5d92-a94f-fc2186d3aecd'::uuid,'d05bbf58-42da-552e-acf5-14776f3151ed'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเทียบคุณภาพหนึ่งคู่ จำนวนหนึ่งคู่และการทำหนึ่งคู่\n\n### ตัวอย่างคำตอบ\n\nThis bag is better than that one. I have more books than Mai. Mai sings better than Ben.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **รูปไม่ปกติ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('be788487-fe58-5e9f-a8c5-cb968f3f2c41'::uuid,'a42308e0-f6bc-577b-ad50-19d50460cb4d'::uuid,'reading',1,'{"title":"ขั้นสูงสุด -est/most","body":"## ขั้นสูงสุด -est/most\n\nsuperlative ระบุสิ่งเด่นที่สุดในกลุ่ม ใช้ the + est หรือ the most + adjective เช่น the smallest/the most useful ระบุกลุ่มด้วย in/of เช่น the tallest student in the class หลัง possessive ใช้ my best friend โดยไม่เติม the ซ้อน เพราะ determiner มีแล้ว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Ben is the tallest student in the class. | กลุ่มชัด |\n| This is the most useful book here. | most + คำยาว |\n| Mai is my best friend. | my แทน the ในกลุ่มนี้ |\n\n### จุดที่มักสับสน\n\nไม่ใช้ most tallest และไม่เติม the หลัง my ใน my the best friend\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Comparative and superlative adjectives](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/comparative-superlative-adjectives)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4c2f2ba7-912b-5507-a23f-2b11b7ace9e6'::uuid,'a42308e0-f6bc-577b-ad50-19d50460cb4d'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/07875f13d7d36634-lesson-23-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Ben is the tallest student in the class.. This is the most useful book here.. Mai is my best friend."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('380d26a9-2e38-5631-a5a4-b49ee907b6c7'::uuid,'a42308e0-f6bc-577b-ad50-19d50460cb4d'::uuid,'multiple_choice',1,'{"question":"ขั้นสูงสุดของ small ในรูปนี้คืออะไร?","choices":[{"id":"choice_1","text":"the smallest"},{"id":"choice_2","text":"the more small"},{"id":"choice_3","text":"the smallerest"}],"correctChoiceId":"choice_1","explanation":"small + est และ the"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('dd259339-60aa-5e10-afd7-ea66dcc117f8'::uuid,'a42308e0-f6bc-577b-ad50-19d50460cb4d'::uuid,'multiple_choice',1,'{"question":"เลือกวลีถูก","choices":[{"id":"choice_1","text":"my the best friend"},{"id":"choice_2","text":"my best friend"},{"id":"choice_3","text":"my most best friend"}],"correctChoiceId":"choice_2","explanation":"my ทำหน้าที่ determiner และ best เป็น superlative อยู่แล้ว"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0f9793f6-e482-5476-a9e2-24edc9da6062'::uuid,'a42308e0-f6bc-577b-ad50-19d50460cb4d'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเลือกของสามชิ้นแล้วบอกชิ้นเล็กที่สุด ราคาแพงที่สุดและชิ้นที่ดีที่สุดสำหรับคุณ\n\n### ตัวอย่างคำตอบ\n\nThe blue bag is the smallest. The black bag is the most expensive. The red bag is the best for me.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ขั้นสูงสุด -est/most** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7340da88-5ca6-5ebe-a56b-5b9713a1ce78'::uuid,'4b48e880-d934-5c6d-a034-814809305788'::uuid,'reading',1,'{"title":"as…as / not as…as","body":"## as…as / not as…as\n\nas + adjective/adverb + as บอกเท่ากัน เช่น as tall as; not as…as บอกไม่เท่าในมิตินั้น less + uncountable หรือ adjective ยาวและ fewer + countable plural ใช้บอกน้อยกว่าในรูปที่ฝึก เช่น less water/fewer books ระบุว่าเทียบคุณลักษณะหรือจำนวนไม่ปนกัน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Mai is as tall as Ben. | สูงเท่ากัน |\n| My bag is not as big as yours. | ไม่ใหญ่เท่า |\n| fewer books / less water | นับได้ / นับไม่ได้ |\n\n### จุดที่มักสับสน\n\nas tall than ผิด; ต้อง as…as สองข้าง\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ขั้นกว่า เท่ากันและที่สุด: smaller than; as big as; the smallest](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d21dee22c5970c4a-module-23-map.png)\n\n*good → better → best  •  well → better  •  ไม่ใช้ more better*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Comparative and superlative adjectives](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/comparative-superlative-adjectives)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7163e3d2-4bb5-552e-a180-fc844bc3f5e7'::uuid,'4b48e880-d934-5c6d-a034-814809305788'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/8d6959587be737dc-lesson-23-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Mai is as tall as Ben.. My bag is not as big as yours.. fewer books. less water"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9808da45-0d07-5b55-a6e6-dcdd2c2c35f6'::uuid,'4b48e880-d934-5c6d-a034-814809305788'::uuid,'multiple_choice',1,'{"question":"เลือกรูปเท่ากันถูก","choices":[{"id":"choice_1","text":"as big as"},{"id":"choice_2","text":"as big than"},{"id":"choice_3","text":"as bigger as"}],"correctChoiceId":"choice_1","explanation":"as + adjective รูปปกติ + as"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e3bed8f2-6221-502e-a885-f78e4cf97c6d'::uuid,'4b48e880-d934-5c6d-a034-814809305788'::uuid,'multiple_choice',1,'{"question":"หนังสือน้อยเล่มกว่าใช้คำใดในรูปที่ฝึก?","choices":[{"id":"choice_1","text":"fewer books"},{"id":"choice_2","text":"less waters"},{"id":"choice_3","text":"fewest water"}],"correctChoiceId":"choice_1","explanation":"books countable plural ใช้ fewer"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('70f5fba6-978f-5009-a74f-33b9b62d205e'::uuid,'4b48e880-d934-5c6d-a034-814809305788'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสิ่งเท่ากัน สิ่งไม่เท่าและจำนวนที่น้อยกว่าอย่างละหนึ่ง\n\n### ตัวอย่างคำตอบ\n\nMai is as tall as Ben. My room is not as big as hers. I have fewer books than Ben.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **as…as / not as…as** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c179b208-4d3f-5151-a873-4fffb85d1b25'::uuid,'859237da-a910-5fdb-a8f8-b2aa33f3f325'::uuid,'reading',1,'{"title":"เปรียบเทียบ adverbs","body":"## เปรียบเทียบ adverbs\n\nเทียบวิธีทำใช้ comparative adverbs เช่น fast→faster, slowly→more slowly, well→better เลือกจากการกระทำที่ต้องการบอก ไม่ใช้ adjective แทน adverb ในอังกฤษมาตรฐานรูปที่ฝึก เมื่อเลือกทางเลือกให้บอกเหตุผลที่ตรวจได้จากข้อมูล\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Mai runs faster than Ben. | เทียบวิ่ง |\n| Ben speaks more slowly than Mai. | เทียบวิธีพูด |\n| She cooks better than me. | well → better |\n\n### จุดที่มักสับสน\n\nHe speaks more slow ไม่ใช่รูปที่ฝึก; ใช้ more slowly\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Comparative and superlative adjectives](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/comparative-superlative-adjectives)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0ccc7a65-9fcd-5272-a2c3-6674e5f34bbd'::uuid,'859237da-a910-5fdb-a8f8-b2aa33f3f325'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d64ad07189e93c7f-lesson-23-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Mai runs faster than Ben.. Ben speaks more slowly than Mai.. She cooks better than me."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('98d2674f-0df1-54f8-aee1-372d7b80d53e'::uuid,'859237da-a910-5fdb-a8f8-b2aa33f3f325'::uuid,'multiple_choice',1,'{"question":"เลือกวลีเทียบการพูดถูก","choices":[{"id":"choice_1","text":"speaks more slowly"},{"id":"choice_2","text":"speaks more slow"},{"id":"choice_3","text":"speaks slowlier"}],"correctChoiceId":"choice_1","explanation":"slowly เป็น adverb คำยาวใช้ more"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('91009320-a570-5c59-a2c8-7450163776cd'::uuid,'859237da-a910-5fdb-a8f8-b2aa33f3f325'::uuid,'multiple_choice',1,'{"question":"well ขั้นกว่าคืออะไร?","choices":[{"id":"choice_1","text":"weller"},{"id":"choice_2","text":"more well"},{"id":"choice_3","text":"better"}],"correctChoiceId":"choice_3","explanation":"well → better"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9c73ada5-958b-5325-a0b3-f80e2f1064ad'::uuid,'859237da-a910-5fdb-a8f8-b2aa33f3f325'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเปรียบเทียบการทำสองอย่าง แล้วเลือกคู่ฝึกภาษาพร้อมเหตุผล\n\n### ตัวอย่างคำตอบ\n\nMai speaks more slowly than Ben. Ben reads faster than Mai. I want to practise with Mai because she speaks more slowly.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เปรียบเทียบ adverbs** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5d1dc67a-6eb4-51dd-ac45-cdb899167eac'::uuid,'f3ee05a6-ebcb-5d06-a59c-ee7614dd4532'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เปรียบเทียบคุณลักษณะ ปริมาณ และวิธีทำอย่างง่ายได้**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ขั้นกว่า เท่ากันและที่สุด: smaller than; as big as; the smallest](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d21dee22c5970c4a-module-23-map.png)\n\n*good → better → best  •  well → better  •  ไม่ใช้ more better*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('26386fce-2968-53f0-aac8-7faced30d67a'::uuid,'f3ee05a6-ebcb-5d06-a59c-ee7614dd4532'::uuid,'multiple_choice',1,'{"question":"This room is … than that one.","choices":[{"id":"choice_1","text":"bigger"},{"id":"choice_2","text":"more bigger"},{"id":"choice_3","text":"biggest"}],"correctChoiceId":"choice_1","explanation":"comparative bigger + than ย้อน 23.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fed61d76-2961-5ae5-afc8-b0d5b20afafd'::uuid,'f3ee05a6-ebcb-5d06-a59c-ee7614dd4532'::uuid,'multiple_choice',1,'{"question":"Which is the … option in this group?","choices":[{"id":"choice_1","text":"best"},{"id":"choice_2","text":"better"},{"id":"choice_3","text":"gooder"}],"correctChoiceId":"choice_1","explanation":"superlative best ย้อน 23.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4f91e929-a89b-549f-aae9-0fe3e960acf5'::uuid,'f3ee05a6-ebcb-5d06-a59c-ee7614dd4532'::uuid,'multiple_choice',1,'{"question":"She speaks … than Ben.","choices":[{"id":"choice_1","text":"more carefully"},{"id":"choice_2","text":"more careful"},{"id":"choice_3","text":"carefuller"}],"correctChoiceId":"choice_1","explanation":"เทียบวิธีพูดใช้ adverb ย้อน 23.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bc731e32-da02-5cd6-a7ec-5a37ee0f35d9'::uuid,'f3ee05a6-ebcb-5d06-a59c-ee7614dd4532'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเทียบสิ่งของสามชิ้นจากราคาและขนาด แล้วเลือกหนึ่งชิ้นพร้อมเหตุผล\n\n### ตัวอย่างผลงาน\n\nThe red bag is bigger than the blue bag. The green bag is the cheapest. The blue bag is not as big as the red one. I choose the green bag because it is cheaper.\n\n### ตรวจผลงาน\n\n- ใช้ comparative/superlative ตามกลุ่ม\n- ไม่ซ้อน more กับ -er หรือ better\n- เทียบ adverb กับการกระทำได้\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('899e4e0f-6511-5702-a425-511193dd9768'::uuid,'8665dd05-0e3b-50b0-a346-17396f6f90d4'::uuid,'reading',1,'{"title":"can/could กับความสามารถ","body":"## can/could กับความสามารถ\n\ncan บอกความสามารถปัจจุบัน could/couldn’t บอกความสามารถทั่วไปในอดีต ทุกประธาน + modal + base เช่น When I was six, I could swim. เหตุการณ์สำเร็จเฉพาะครั้งมักใช้ was able to/managed to ตามบริบท ไม่เอา could แทนทุกความสำเร็จในอดีต ส่วนคำขอ Could you…? เป็นอีกความหมายที่รู้แล้ว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I can swim now. | ปัจจุบัน |\n| I could swim when I was six. | ความสามารถทั่วไปอดีต |\n| I couldn’t drive at eighteen. | อดีตทำไม่ได้ |\n\n### จุดที่มักสับสน\n\ncould ไม่มี s/to และไม่ผูกกับอดีตเสมอเพราะใช้คำขอสุภาพได้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [Cambridge English — A2 Key Handbook, edition for exams from 2020, pp. 49–51](https://www.cambridgeenglish.org/images/504505-a2-key-handbook-2020.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e1357159-98a6-5f62-a6c7-18aa40616309'::uuid,'8665dd05-0e3b-50b0-a346-17396f6f90d4'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/e24f34ddf3c94844-lesson-24-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I can swim now.. I could swim when I was six.. I couldn’t drive at eighteen."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5b8ca298-2cba-5380-a930-609b0ceb3714'::uuid,'8665dd05-0e3b-50b0-a346-17396f6f90d4'::uuid,'multiple_choice',1,'{"question":"บอกความสามารถทั่วไปเมื่อเด็กใช้รูปใด?","choices":[{"id":"choice_1","text":"I could read when I was five."},{"id":"choice_2","text":"I could to read when I was five."},{"id":"choice_3","text":"I could reads when I was five."}],"correctChoiceId":"choice_1","explanation":"could + base read"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('164c8374-ffde-5ab2-aff2-f4cf6ae6808e'::uuid,'8665dd05-0e3b-50b0-a346-17396f6f90d4'::uuid,'multiple_choice',1,'{"question":"Could you help me? จำเป็นต้องถามความสามารถอดีตหรือไม่?","choices":[{"id":"choice_1","text":"ไม่ เป็นคำขอสุภาพได้"},{"id":"choice_2","text":"ใช่เสมอ"},{"id":"choice_3","text":"เป็นคำห้าม"}],"correctChoiceId":"choice_1","explanation":"could มีหลายหน้าที่ ต้องดูบริบท"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f23cb51e-1bf1-50a8-aa60-6b66bc907378'::uuid,'8665dd05-0e3b-50b0-a346-17396f6f90d4'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเปรียบเทียบสิ่งที่ทำได้ตอนเด็กกับตอนนี้ และสิ่งที่ยังไม่ได้\n\n### ตัวอย่างคำตอบ\n\nI could swim when I was seven. I couldn’t drive then. Now I can drive.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **can/could กับความสามารถ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8b7fc689-d2e3-5912-a905-7cb5d5e26487'::uuid,'b00e2609-e00f-5c3d-a3fe-6fa6d5a13f0c'::uuid,'reading',1,'{"title":"should/shouldn''t","body":"## should/shouldn''t\n\nshould/shouldn’t + base verb ให้คำแนะนำไม่ใช่หน้าที่บังคับ เช่น You should rest. ถาม Should I…? และตอบ Yes, you should./No, you shouldn’t. แนะนำให้เหมาะปัญหาและบอกเหตุผลง่าย ๆ ไม่เติม s/to ให้ main verb\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| You should take a break. | แนะนำ |\n| You shouldn’t be late. | แนะนำไม่ทำ |\n| Should I call her? | ขอคำแนะนำ |\n\n### จุดที่มักสับสน\n\nshould to go และ should goes ผิด; should เป็นกริยาช่วยไม่ใช้ do ในคำถามนี้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [Cambridge English — A2 Key Handbook, edition for exams from 2020, pp. 49–51](https://www.cambridgeenglish.org/images/504505-a2-key-handbook-2020.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('521a2da4-bd8c-57c2-ab33-456ded93ab5f'::uuid,'b00e2609-e00f-5c3d-a3fe-6fa6d5a13f0c'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d5c9c65f4f96bb1f-lesson-24-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"You should take a break.. You shouldn’t be late.. Should I call her?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('99def5c9-c2f6-5bb2-a39d-94bba99e5594'::uuid,'b00e2609-e00f-5c3d-a3fe-6fa6d5a13f0c'::uuid,'multiple_choice',1,'{"question":"เลือกคำแนะนำถูก","choices":[{"id":"choice_1","text":"You should to rest."},{"id":"choice_2","text":"You should rest."},{"id":"choice_3","text":"You should rests."}],"correctChoiceId":"choice_2","explanation":"should + base rest"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ab998242-aa11-51f0-a142-9f4973703b14'::uuid,'b00e2609-e00f-5c3d-a3fe-6fa6d5a13f0c'::uuid,'multiple_choice',1,'{"question":"Should I leave now? คำตอบสั้นตรงคืออะไร?","choices":[{"id":"choice_1","text":"Yes, you should."},{"id":"choice_2","text":"Yes, you do."},{"id":"choice_3","text":"Yes, you are."}],"correctChoiceId":"choice_1","explanation":"ตอบด้วย modal should"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('64a551d4-e889-5592-a66c-518368a42d8d'::uuid,'b00e2609-e00f-5c3d-a3fe-6fa6d5a13f0c'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนคำแนะนำสองข้อเกี่ยวกับการเรียนและหนึ่งข้อที่ไม่ควรทำ พร้อมเหตุผล\n\n### ตัวอย่างคำตอบ\n\nYou should practise every day. You should read short texts. You shouldn’t study all night because you need rest.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **should/shouldn''t** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('55e6ccd2-ad09-520f-a2e5-1351dd5e7af7'::uuid,'fc0b8ace-92b5-5fee-a8e6-92fb7e01649a'::uuid,'reading',1,'{"title":"must/have to/need to","body":"## must/have to/need to\n\nmust + base, have/has to + base และ need/needs to + base บอกความจำเป็นหรือหน้าที่ must มักแสดงสิ่งที่ผู้พูดย้ำ ส่วน have to มักสัมพันธ์ข้อกำหนดภายนอก แต่ความหมายทับซ้อน ใช้ had to สำหรับหน้าที่ในอดีต คำถาม have to ใช้ do/does และปฏิเสธ don’t/doesn’t have to บอกไม่จำเป็น\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I must finish this. | ผู้พูดย้ำจำเป็น |\n| She has to work today. | หน้าที่ |\n| Did you have to wait? | อดีตถามด้วย did |\n| We had to leave early. | อดีตหน้าที่ |\n\n### จุดที่มักสับสน\n\nหลัง does/did ใช้ have ไม่ใช่ has/had; must ไม่มี s\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [Cambridge English — A2 Key Handbook, edition for exams from 2020, pp. 49–51](https://www.cambridgeenglish.org/images/504505-a2-key-handbook-2020.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3b9f1f8b-33ea-5b10-ade2-25fb357d6d84'::uuid,'fc0b8ace-92b5-5fee-a8e6-92fb7e01649a'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/810526a60f172cd1-lesson-24-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I must finish this.. She has to work today.. Did you have to wait?. We had to leave early."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ce5be0ca-e9a3-54e5-a7b6-f1317f84aa50'::uuid,'fc0b8ace-92b5-5fee-a8e6-92fb7e01649a'::uuid,'multiple_choice',1,'{"question":"He … wear a uniform at work.","choices":[{"id":"choice_1","text":"has to"},{"id":"choice_2","text":"have to"},{"id":"choice_3","text":"musts"}],"correctChoiceId":"choice_1","explanation":"he ใช้ has to"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c3bfa554-becd-574a-a32e-987be56fedf7'::uuid,'fc0b8ace-92b5-5fee-a8e6-92fb7e01649a'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามหน้าที่ถูก","choices":[{"id":"choice_1","text":"Does she have to work?"},{"id":"choice_2","text":"Does she has to work?"},{"id":"choice_3","text":"Must she to work?"}],"correctChoiceId":"choice_1","explanation":"does + base have"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b7dc2330-9448-5e20-a7bc-cce5ed8f98fa'::uuid,'fc0b8ace-92b5-5fee-a8e6-92fb7e01649a'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกหน้าที่วันนี้สองข้อและหน้าที่เมื่อวานหนึ่งข้อ แล้วถามหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nI have to study today. Mai needs to work. I had to help my family yesterday. Do you have to work tomorrow?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **must/have to/need to** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ccfff6ab-d5f7-5c7e-a90b-482808d9bb15'::uuid,'d938c4e5-8b13-5919-a8ab-a9df1b1c03ef'::uuid,'reading',1,'{"title":"mustn''t กับ don''t have to","body":"## mustn''t กับ don''t have to\n\nmustn’t หมายถึงห้ามทำ ส่วน don’t have to หมายถึงไม่จำเป็น ต้องไม่สับสนเพราะผลต่างกัน เช่น You mustn’t park here. ห้ามจอด กับ You don’t have to pay. ไม่จำเป็นจ่าย อาจทำก็ได้ตามบริบท can’t อาจหมายถึงไม่อนุญาตหรือไม่สามารถ ต้องอ่านสถานการณ์\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| You mustn’t touch this. | ห้าม |\n| You don’t have to come early. | ไม่จำเป็น |\n| You can’t park here. | ไม่อนุญาตในบริบทป้าย |\n\n### จุดที่มักสับสน\n\nmust not ไม่เท่ากับ not necessary จึงอย่าแปลทั้งหมดว่าไม่ต้อง\n\n\n\n### ดูภาพแล้วลองใช้\n\n![หน้าที่ ห้ามและไม่จำเป็น: You have to go.; You mustn’t go.; You don’t have to go.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9528a209b0f22c00-module-24-map.png)\n\n*ห้ามทำ ≠ ไม่จำเป็น  •  should: คำแนะนำ  •  might: อาจเป็นไปได้*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [Cambridge English — A2 Key Handbook, edition for exams from 2020, pp. 49–51](https://www.cambridgeenglish.org/images/504505-a2-key-handbook-2020.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('799699bd-5f5e-5a62-aab2-6ca9b62f7694'::uuid,'d938c4e5-8b13-5919-a8ab-a9df1b1c03ef'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/604e18ff8f7cf167-lesson-24-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"You mustn’t touch this.. You don’t have to come early.. You can’t park here."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e33d129e-5980-5e7f-afdd-7724b703207f'::uuid,'d938c4e5-8b13-5919-a8ab-a9df1b1c03ef'::uuid,'multiple_choice',1,'{"question":"ป้ายห้ามเข้า ควรใช้รูปใด?","choices":[{"id":"choice_1","text":"You mustn’t enter."},{"id":"choice_2","text":"You don’t have to enter."},{"id":"choice_3","text":"You should enter."}],"correctChoiceId":"choice_1","explanation":"mustn’t เป็น prohibition"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7de0b016-0c92-5412-a032-47818f6a2ca0'::uuid,'d938c4e5-8b13-5919-a8ab-a9df1b1c03ef'::uuid,'multiple_choice',1,'{"question":"ไม่จำเป็นต้องนำอาหาร แต่จะนำก็ได้ ใช้รูปใด?","choices":[{"id":"choice_1","text":"You don’t have to bring food."},{"id":"choice_2","text":"You mustn’t bring food."},{"id":"choice_3","text":"You can’t bring food."}],"correctChoiceId":"choice_1","explanation":"don’t have to = not necessary"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('24430528-df9d-5ee2-a7e9-19a586f35340'::uuid,'d938c4e5-8b13-5919-a8ab-a9df1b1c03ef'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนกฎสองข้อที่ห้าม และสองข้อที่ไม่จำเป็นสำหรับกิจกรรมสมมติ\n\n### ตัวอย่างคำตอบ\n\nYou mustn’t smoke here. You mustn’t touch the screen. You don’t have to bring a book. You don’t have to pay.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **mustn''t กับ don''t have to** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('160e0375-b527-5d55-abe8-3fda0f7f5778'::uuid,'e38ee5e0-9caa-503d-a697-689ba63d14ff'::uuid,'reading',1,'{"title":"don''t need to/needn''t","body":"## don''t need to/needn''t\n\ndon’t/doesn’t need to + base และ needn’t + base บอกไม่จำเป็น need แบบกริยาทั่วไปใช้ do/does ในคำถามและปฏิเสธ ส่วน needn’t เป็น modal ไม่เติม to: You needn’t wait. เนื้อหานี้ไม่ขยาย needn’t have + V3 ที่ใช้ประเมินเหตุการณ์อดีต\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| You don’t need to wait. | need กริยาทั่วไป |\n| You needn’t wait. | modal ไม่มี to |\n| Does she need to go? | คำถาม do/does |\n\n### จุดที่มักสับสน\n\nneedn’t to go ผิด และ doesn’t needs to ผิด\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [Cambridge English — A2 Key Handbook, edition for exams from 2020, pp. 49–51](https://www.cambridgeenglish.org/images/504505-a2-key-handbook-2020.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('eb25dd01-94a5-5dbc-a7d8-c930c468b958'::uuid,'e38ee5e0-9caa-503d-a697-689ba63d14ff'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2985feca0518478d-lesson-24-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"You don’t need to wait.. You needn’t wait.. Does she need to go?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d0706892-70d0-5aad-a7bd-005ec3fa20ff'::uuid,'e38ee5e0-9caa-503d-a697-689ba63d14ff'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคที่ถูก","choices":[{"id":"choice_1","text":"You needn’t to hurry."},{"id":"choice_2","text":"You needn’t hurry."},{"id":"choice_3","text":"You needn’t hurries."}],"correctChoiceId":"choice_2","explanation":"needn’t + base ไม่มี to"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('03eca2f4-91bf-52c3-a372-7c72fa7c9b3e'::uuid,'e38ee5e0-9caa-503d-a697-689ba63d14ff'::uuid,'multiple_choice',1,'{"question":"She … need to pay.","choices":[{"id":"choice_1","text":"doesn’t"},{"id":"choice_2","text":"don’t"},{"id":"choice_3","text":"isn’t"}],"correctChoiceId":"choice_1","explanation":"need เป็น verb ทั่วไปกับ she ใช้ doesn’t"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e42cbf17-0d0c-5856-ad2c-140fb5765350'::uuid,'e38ee5e0-9caa-503d-a697-689ba63d14ff'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนความจำเป็นหนึ่งข้อและไม่จำเป็นสองรูป แล้วตั้งคำถาม\n\n### ตัวอย่างคำตอบ\n\nI need to study. You don’t need to wait. You needn’t wait. Do you need to leave?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **don''t need to/needn''t** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5127bbf5-ffb1-5714-afbd-d6b43719df20'::uuid,'1e7164d3-b558-5679-a587-33c8f02fec21'::uuid,'reading',1,'{"title":"may/might/could บอกความเป็นไปได้","body":"## may/might/could บอกความเป็นไปได้\n\nmay/might/could + base บอกเป็นไปได้ เช่น It might rain. ไม่ยืนยันว่าจะเกิด probably/perhaps บอกความน่าจะเป็นแบบภาษาธรรมชาติ definitely ชี้มั่นใจมากกว่า แต่ไม่แปลงเป็นเปอร์เซ็นต์ตายตัว may ยังใช้อนุญาตได้ ต้องดูบริบท แยกความเป็นไปได้ could จากความสามารถอดีต\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| It may rain tomorrow. | อาจเกิด |\n| She might come later. | ยังไม่แน่ |\n| He could be at home. | เป็นไปได้ตามข้อมูล |\n\n### จุดที่มักสับสน\n\nIt might rains ผิด และ may/might ไม่รับรองความน่าจะเป็นเป็นตัวเลขคงที่\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [Cambridge English — A2 Key Handbook, edition for exams from 2020, pp. 49–51](https://www.cambridgeenglish.org/images/504505-a2-key-handbook-2020.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('72920887-4a62-5862-a50b-0d9824837351'::uuid,'1e7164d3-b558-5679-a587-33c8f02fec21'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/bb32e26b5443a80a-lesson-24-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"It may rain tomorrow.. She might come later.. He could be at home."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5c19199d-210f-543b-ac8c-b9b9e8252e10'::uuid,'1e7164d3-b558-5679-a587-33c8f02fec21'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคเป็นไปได้ถูก","choices":[{"id":"choice_1","text":"She might comes."},{"id":"choice_2","text":"She might come."},{"id":"choice_3","text":"She might to come."}],"correctChoiceId":"choice_2","explanation":"might + base come"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6c73d147-3051-5ea2-a111-488ef4d185ab'::uuid,'1e7164d3-b558-5679-a587-33c8f02fec21'::uuid,'multiple_choice',1,'{"question":"It may rain สื่ออะไร?","choices":[{"id":"choice_1","text":"ฝนอาจตก"},{"id":"choice_2","text":"ฝนต้องตกแน่นอน"},{"id":"choice_3","text":"ฝนไม่มีทางตก"}],"correctChoiceId":"choice_1","explanation":"may แสดง possibility"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5da5b426-d59f-5d35-a500-3b3d9d2a747f'::uuid,'1e7164d3-b558-5679-a587-33c8f02fec21'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนการคาดการณ์สามข้อที่ไม่แน่ใจ แล้วใส่ definitely ในข้อมูลที่คุณมั่นใจ\n\n### ตัวอย่างคำตอบ\n\nIt might rain. Ben may come late. Mai could be at home. I will definitely call you tonight.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **may/might/could บอกความเป็นไปได้** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('be602038-f572-5dae-ae60-ec5dccf4a074'::uuid,'496f918d-f732-58c4-ac12-1197dfe80bdc'::uuid,'reading',1,'{"title":"ขอ เสนอ อนุญาต และตอบ","body":"## ขอ เสนอ อนุญาต และตอบ\n\nเลือกคำขอ เสนอและอนุญาตตามผู้รับและความหมาย Can/Could/Would you + base? ขอให้ช่วย; Can/May I + base? ขออนุญาต; Would you like + noun/to verb? เสนอหรือชวน Could/Would มักนุ่มนวลกว่าแต่ความสุภาพยังขึ้นกับน้ำเสียง ตอบรับหรือปฏิเสธด้วยวลีชัดและไม่ฝืนใช้ short answer modal ทุกบริบท\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| May I come in? | ขออนุญาต |\n| Would you help me, please? | ขอช่วย |\n| Would you like some tea? — Yes, please. | เสนอ |\n\n### จุดที่มักสับสน\n\nMay I…? ต่างจาก May you…? สำหรับการขออนุญาตให้ตนเอง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [Cambridge English — A2 Key Handbook, edition for exams from 2020, pp. 49–51](https://www.cambridgeenglish.org/images/504505-a2-key-handbook-2020.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0028dcb4-ee91-588e-a8fb-9820dce3c9df'::uuid,'496f918d-f732-58c4-ac12-1197dfe80bdc'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/7dbd0c0dc772a07e-lesson-24-07.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"May I come in?. Would you help me, please?. Would you like some tea?. Yes, please."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('92d177da-25eb-5f7d-ab34-b136c1792208'::uuid,'496f918d-f732-58c4-ac12-1197dfe80bdc'::uuid,'multiple_choice',1,'{"question":"ขออนุญาตเข้าอย่างสุภาพ ใช้รูปใด?","choices":[{"id":"choice_1","text":"May I come in?"},{"id":"choice_2","text":"May I to come in?"},{"id":"choice_3","text":"May I comes in?"}],"correctChoiceId":"choice_1","explanation":"May I + base"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('706400ac-6366-58e8-aae7-548ca9a6acf7'::uuid,'496f918d-f732-58c4-ac12-1197dfe80bdc'::uuid,'multiple_choice',1,'{"question":"Would you like some coffee? คำตอบรับธรรมชาติคืออะไร?","choices":[{"id":"choice_1","text":"Yes, please."},{"id":"choice_2","text":"Yes, I must."},{"id":"choice_3","text":"Yes, I am coffee."}],"correctChoiceId":"choice_1","explanation":"เสนอของตอบ Yes, please ได้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e146177d-ecc6-5194-a426-fc5a384854d0'::uuid,'496f918d-f732-58c4-ac12-1197dfe80bdc'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nสร้างบทสนทนามีขออนุญาต ขอความช่วยเหลือและเสนอเครื่องดื่ม รวมหกบรรทัด\n\n### ตัวอย่างคำตอบ\n\nMay I sit here? Of course. Could you help me? Sure. Would you like some water? Yes, please.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ขอ เสนอ อนุญาต และตอบ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('39ad1669-c1c8-59e9-ac25-e73389fcbcc6'::uuid,'909e0fb1-4a0f-5976-aa9b-57f32370f8ac'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **แยกห้าม ไม่จำเป็น ควรทำ และอาจเกิดขึ้น พร้อมสร้างคำถามได้**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![หน้าที่ ห้ามและไม่จำเป็น: You have to go.; You mustn’t go.; You don’t have to go.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9528a209b0f22c00-module-24-map.png)\n\n*ห้ามทำ ≠ ไม่จำเป็น  •  should: คำแนะนำ  •  might: อาจเป็นไปได้*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a8f29c8c-0b2c-5ca4-af38-ae5b6f3a4db2'::uuid,'909e0fb1-4a0f-5976-aa9b-57f32370f8ac'::uuid,'multiple_choice',1,'{"question":"ห้ามสูบบุหรี่ใช้รูปใด?","choices":[{"id":"choice_1","text":"You mustn’t smoke."},{"id":"choice_2","text":"You don’t have to smoke."},{"id":"choice_3","text":"You should smoke."}],"correctChoiceId":"choice_1","explanation":"mustn’t เป็น prohibition ย้อน 24.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d9fc21a8-25dd-586f-abe7-8a272bf2cc73'::uuid,'909e0fb1-4a0f-5976-aa9b-57f32370f8ac'::uuid,'multiple_choice',1,'{"question":"ไม่จำเป็นต้องรอ ใช้รูปใด?","choices":[{"id":"choice_1","text":"You needn’t wait."},{"id":"choice_2","text":"You needn’t to wait."},{"id":"choice_3","text":"You needn’t waits."}],"correctChoiceId":"choice_1","explanation":"needn’t + base ย้อน 24.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('015d5e02-7063-5dca-a0d3-4117df625659'::uuid,'909e0fb1-4a0f-5976-aa9b-57f32370f8ac'::uuid,'multiple_choice',1,'{"question":"ความเป็นไปได้: He … be at home.","choices":[{"id":"choice_1","text":"might"},{"id":"choice_2","text":"mights"},{"id":"choice_3","text":"might to"}],"correctChoiceId":"choice_1","explanation":"might + base be ย้อน 24.06"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e2dc1759-2017-512d-a176-7a4c34c9a1ba'::uuid,'909e0fb1-4a0f-5976-aa9b-57f32370f8ac'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nจัดกฎกิจกรรม: หน้าที่หนึ่ง คำห้ามหนึ่ง สิ่งไม่จำเป็นหนึ่ง คำแนะนำหนึ่ง พร้อมขอและเสนอความช่วยเหลือ\n\n### ตัวอย่างผลงาน\n\nYou have to bring water. You mustn’t smoke. You don’t have to pay. You should wear comfortable shoes. Could you help me? Shall I carry your bag?\n\n### ตรวจผลงาน\n\n- ห้ามต่างจากไม่จำเป็น\n- modal+base และ have/need to ถูก\n- คำขอ ความสามารถและ possibility ดูบริบท\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8e0deb95-5cd6-5985-a3a6-3890c934e249'::uuid,'12288143-d1f9-5175-a683-e9bba1a7e777'::uuid,'reading',1,'{"title":"have/has + V3","body":"## have/has + V3\n\nPresent Perfect ใช้ have/has + V3 บอกสิ่งอดีตที่เชื่อมกับปัจจุบัน I/you/we/they ใช้ have; he/she/it ใช้ has ปฏิเสธ haven’t/hasn’t + V3 และคำถาม Have/Has + subject + V3? have ในรูปนี้เป็น auxiliary ต่างจาก have a car ที่บอกการมี รูปย่อ I’ve/she’s ต้องอ่านสิ่งที่ตาม\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I have finished my work. | have + V3 |\n| She hasn’t eaten. | has not + V3 |\n| Have you seen it? | คำถาม |\n\n### จุดที่มักสับสน\n\nI have saw ผิดต้อง seen; She’s finished = she has finished ตามโครงนี้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present perfect, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/present-perfect)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9356e108-3426-5db2-a812-3a7d478533b2'::uuid,'12288143-d1f9-5175-a683-e9bba1a7e777'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/821350c4b67d32f2-lesson-25-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I have finished my work.. She hasn’t eaten.. Have you seen it?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d8a860ab-fa8e-542e-aeef-519e10cb9a9b'::uuid,'12288143-d1f9-5175-a683-e9bba1a7e777'::uuid,'multiple_choice',1,'{"question":"He … finished his homework.","choices":[{"id":"choice_1","text":"have"},{"id":"choice_2","text":"has"},{"id":"choice_3","text":"is ในความหมายเขาทำเสร็จแล้ว"}],"correctChoiceId":"choice_2","explanation":"he ใช้ has + V3 finished"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e7998bf7-45db-5765-a96d-d9d0bc498c39'::uuid,'12288143-d1f9-5175-a683-e9bba1a7e777'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามถูก","choices":[{"id":"choice_1","text":"Have you seen Mai?"},{"id":"choice_2","text":"Have you saw Mai?"},{"id":"choice_3","text":"Do you have seen Mai?"}],"correctChoiceId":"choice_1","explanation":"Have + subject + V3 seen"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('eaeb5453-1c99-5f4f-a5f5-73ece28fa15f'::uuid,'12288143-d1f9-5175-a683-e9bba1a7e777'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสิ่งที่ทำแล้ว สิ่งที่ยังไม่ทำและคำถามเกี่ยวข้องปัจจุบัน\n\n### ตัวอย่างคำตอบ\n\nI have finished my work. I haven’t eaten lunch. Have you finished your work?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **have/has + V3** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('23212485-bd13-5c0e-a47d-6bac482fb0ed'::uuid,'3cc99b47-cf60-5065-ada8-5fb3d8cb5947'::uuid,'reading',1,'{"title":"V3 ที่ใช้จริง","body":"## V3 ที่ใช้จริง\n\nV3 ที่ใช้จริงมี regular เช่น worked/visited และ irregular เช่น seen/gone/done/eaten/written บางคำ V2/V3 เหมือนกัน เช่น had/bought แต่ see→saw→seen ต่างกัน เลือก V3 หลัง have/has ไม่ใช่หยิบรูปอดีตที่จำได้มาใส่โดยไม่ตรวจ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I have seen this film. | see/saw/seen |\n| She has done her work. | do/did/done |\n| We have bought food. | buy/bought/bought |\n\n### จุดที่มักสับสน\n\nwent เป็น V2 ของ go ส่วน gone เป็น V3; gone และ been มีความหมายต่างที่จะเรียน 25.07\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present perfect, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/present-perfect)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fbb8761f-8227-5954-aa09-b029887794fc'::uuid,'3cc99b47-cf60-5065-ada8-5fb3d8cb5947'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/44a1721f7646bd4d-lesson-25-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I have seen this film.. She has done her work.. We have bought food."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fcae295c-936d-5f39-a9b4-b63815044f8e'::uuid,'3cc99b47-cf60-5065-ada8-5fb3d8cb5947'::uuid,'multiple_choice',1,'{"question":"She has … a letter.","choices":[{"id":"choice_1","text":"write"},{"id":"choice_2","text":"wrote"},{"id":"choice_3","text":"written"}],"correctChoiceId":"choice_3","explanation":"have/has + V3 written"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('eba147a5-bf93-583e-ae1b-ee99adff7709'::uuid,'3cc99b47-cf60-5065-ada8-5fb3d8cb5947'::uuid,'multiple_choice',1,'{"question":"คำใด V2/V3 เหมือนกัน?","choices":[{"id":"choice_1","text":"buy/bought/bought"},{"id":"choice_2","text":"see/saw/seen"},{"id":"choice_3","text":"go/went/gone"}],"correctChoiceId":"choice_1","explanation":"bought ใช้ทั้งสองหน้าที่ แต่โครงสร้างต่างกัน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bd06c00f-4035-50a4-a76c-7582b94a7295'::uuid,'3cc99b47-cf60-5065-ada8-5fb3d8cb5947'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเติมตาราง V3 แล้วแต่งสามประโยคด้วย seen/done/eaten\n\n### ตัวอย่างคำตอบ\n\nsee/seen; do/done; eat/eaten. I have seen Mai. I have done my work. I have eaten rice.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **V3 ที่ใช้จริง** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('06972150-0300-5ac2-a391-c202ef96fdc8'::uuid,'9bf41a51-cd33-5a45-a199-4e974b9d28c6'::uuid,'reading',1,'{"title":"ประสบการณ์ ever/never","body":"## ประสบการณ์ ever/never\n\nถามประสบการณ์ในชีวิตถึงตอนนี้ใช้ Have you ever + V3? ever หมายถึงเคยในช่วงที่พิจารณา never คือไม่เคยและมีปฏิเสธในตัว ตอบ Yes, I have./No, I haven’t. หากเล่ารายละเอียดว่าเมื่อไรในอดีตที่จบแล้ว ใช้ Past Simple เช่น I went there last year. ไม่ใช้ Present Perfect คู่ yesterday\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Have you ever visited Japan? | ถามประสบการณ์ |\n| I have never flown. | ไม่เคย |\n| Yes, I have. I went there in 2024. | ประสบการณ์แล้วรายละเอียดอดีต |\n\n### จุดที่มักสับสน\n\nI haven’t never… ปฏิเสธซ้อน และ Have you ever went? ต้อง gone/been ตามความหมาย\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present perfect, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/present-perfect)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6cf5f6a8-d653-5c80-a7c6-426293bab7ff'::uuid,'9bf41a51-cd33-5a45-a199-4e974b9d28c6'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/30b71b5b6739dd6c-lesson-25-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Have you ever visited Japan?. I have never flown.. Yes, I have. I went there in 2024."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('033a454e-b204-5251-a43a-74d68708c939'::uuid,'9bf41a51-cd33-5a45-a199-4e974b9d28c6'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามประสบการณ์ถูก","choices":[{"id":"choice_1","text":"Have you ever eaten sushi?"},{"id":"choice_2","text":"Have you ever ate sushi?"},{"id":"choice_3","text":"Did you ever eaten sushi?"}],"correctChoiceId":"choice_1","explanation":"Have + ever + V3 eaten"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('50192645-82cf-51f1-a5d6-f9286813e43d'::uuid,'9bf41a51-cd33-5a45-a199-4e974b9d28c6'::uuid,'multiple_choice',1,'{"question":"หลัง Yes, I have จะบอกปี 2023 ใช้รูปใด?","choices":[{"id":"choice_1","text":"I visited Japan in 2023."},{"id":"choice_2","text":"I have visited Japan in 2023. เมื่อปีจบแล้ว"},{"id":"choice_3","text":"I visiting Japan in 2023."}],"correctChoiceId":"choice_1","explanation":"เวลาอดีตที่จบแล้วใช้ Past Simple"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a197d87b-0b8f-516f-af4d-85530a683877'::uuid,'9bf41a51-cd33-5a45-a199-4e974b9d28c6'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nถามเพื่อนประสบการณ์สองข้อแล้วถามรายละเอียดหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nHave you ever cooked Thai food? Yes, I have. When did you cook it? I cooked it last week. Have you ever flown? No, I haven’t.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ประสบการณ์ ever/never** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0815914d-549e-5bf6-a8b0-cae363015ae0'::uuid,'ed876a46-ef7c-5fa8-af77-1d0bbfddfa42'::uuid,'reading',1,'{"title":"just/already/yet","body":"## just/already/yet\n\njust บอกเพิ่งเกิด already ทำแล้วเร็วกว่าที่คิดหรือเรียบร้อยแล้ว มักอยู่ระหว่าง have/has กับ V3 ส่วน yet ใช้คำถามหรือปฏิเสธมักท้าย: Have you finished yet? / I haven’t finished yet. ใช้เมื่อเกี่ยวข้องกับสิ่งที่รออยู่ในปัจจุบัน การใช้ Past Simple กับ just/already บางสำเนียงมีได้ แต่บทนี้ฝึก Present Perfect ให้ครบรูป\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I have just arrived. | เพิ่งมาถึง |\n| She has already eaten. | กินแล้ว |\n| Have you finished yet? — Not yet. | เสร็จหรือยัง |\n\n### จุดที่มักสับสน\n\nalready/yet ไม่ใช่คำแปลรูป tense โดยตรง ต้องมีโครง have/has + V3 เมื่อเลือก perfect\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present perfect, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/present-perfect)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8640d812-e719-5d55-a0b7-7466359938cf'::uuid,'ed876a46-ef7c-5fa8-af77-1d0bbfddfa42'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/238e383c80b43b5b-lesson-25-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I have just arrived.. She has already eaten.. Have you finished yet?. Not yet."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('618551ce-4b08-5c0a-a1e3-e149368726b1'::uuid,'ed876a46-ef7c-5fa8-af77-1d0bbfddfa42'::uuid,'multiple_choice',1,'{"question":"เลือกตำแหน่ง just ที่เป็นรูปพื้นฐาน","choices":[{"id":"choice_1","text":"I have just finished."},{"id":"choice_2","text":"I just have finishedly."},{"id":"choice_3","text":"I have finished justly."}],"correctChoiceId":"choice_1","explanation":"just ระหว่าง have กับ V3"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('495aa85b-a7f0-500f-a502-b0c34ccd1ffe'::uuid,'ed876a46-ef7c-5fa8-af77-1d0bbfddfa42'::uuid,'multiple_choice',1,'{"question":"ยังไม่เสร็จ ใช้รูปใด?","choices":[{"id":"choice_1","text":"I haven’t finished yet."},{"id":"choice_2","text":"I have yet finished not."},{"id":"choice_3","text":"I haven’t finish already."}],"correctChoiceId":"choice_1","explanation":"haven’t + V3 และ yet ท้าย"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bfe781f9-9060-5a91-a148-b4564de73b42'::uuid,'ed876a46-ef7c-5fa8-af77-1d0bbfddfa42'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนสถานะงานสามข้อด้วย just/already/yet แล้วถามเพื่อน\n\n### ตัวอย่างคำตอบ\n\nI have just started. Mai has already finished. Ben hasn’t finished yet. Have you finished yet?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **just/already/yet** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3e3d07fe-59cf-52d8-a0d9-633f3388ca68'::uuid,'f5a6d337-00fd-5106-a950-3a206b303e03'::uuid,'reading',1,'{"title":"for/since และ How long…?","body":"## for/since และ How long…?\n\nfor + ระยะเวลา เช่น for two years; since + จุดเริ่ม เช่น since 2024 ใช้ perfect กับสภาพที่เริ่มอดีตและยังต่อถึงปัจจุบัน: I have lived here for two years. ถาม How long have you lived here? ไม่สรุปว่า for ต้องใช้ perfect เสมอ เพราะ I lived there for two years. บอกช่วงที่จบแล้วได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I have known Mai for three years. | ระยะเวลา |\n| I have known Mai since 2023. | จุดเริ่ม |\n| How long have you lived here? | ถามระยะที่ต่อถึงตอนนี้ |\n\n### จุดที่มักสับสน\n\nsince three years ผิดในความหมายนี้ และ for 2023 ผิดถ้าปีเป็นจุดเริ่ม\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present perfect, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/present-perfect)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4b281d3d-81de-5c7a-a29c-9bb9407ada1e'::uuid,'f5a6d337-00fd-5106-a950-3a206b303e03'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/28be7191e73c2399-lesson-25-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I have known Mai for three years.. I have known Mai since 2023.. How long have you lived here?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('43fd9cc9-e98a-502a-a14e-1ad63889e6c4'::uuid,'f5a6d337-00fd-5106-a950-3a206b303e03'::uuid,'multiple_choice',1,'{"question":"I have worked here … Monday.","choices":[{"id":"choice_1","text":"for"},{"id":"choice_2","text":"since"},{"id":"choice_3","text":"during"}],"correctChoiceId":"choice_2","explanation":"Monday เป็นจุดเริ่มใช้ since"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c9225e1a-253d-511e-abc4-b5abc982fc6b'::uuid,'f5a6d337-00fd-5106-a950-3a206b303e03'::uuid,'multiple_choice',1,'{"question":"I have lived here … six months.","choices":[{"id":"choice_1","text":"since"},{"id":"choice_2","text":"for"},{"id":"choice_3","text":"at"}],"correctChoiceId":"choice_2","explanation":"six months ระยะเวลาใช้ for"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ead473a5-fafe-5d10-a33f-618d7655227c'::uuid,'f5a6d337-00fd-5106-a950-3a206b303e03'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกสภาพสองข้อที่ยังต่อถึงตอนนี้ โดยใช้ for และ since แล้วถาม How long\n\n### ตัวอย่างคำตอบ\n\nI have lived here for two years. I have studied English since January. How long have you lived here?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **for/since และ How long…?** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d373cc21-d171-5a69-a0cc-ba32f16f237b'::uuid,'93729cc3-518f-5be7-aafc-740646782640'::uuid,'reading',1,'{"title":"Present Perfect เทียบ Past Simple","body":"## Present Perfect เทียบ Past Simple\n\nPresent Perfect เชื่อมอดีตถึงตอนนี้โดยไม่ระบุช่วงอดีตที่จบแล้วในโครงเดียวกัน เช่น I have lost my key. กุญแจยังหาย ส่วน I lost my key yesterday. เล่าเหตุการณ์เวลาจบแล้ว yesterday/last week/in 2020 ใช้ Past Simple สำหรับเหตุการณ์นั้น this week อาจเป็นช่วงยังไม่จบ ต้องดูว่าผู้พูดมองช่วงอย่างไร\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I have lost my key. | ผลยังเกี่ยวกับตอนนี้ |\n| I lost my key yesterday. | ระบุเมื่อวาน |\n| Have you seen Mai? / When did you see her? | ถามทั่วไป / ถามเวลาอดีต |\n\n### จุดที่มักสับสน\n\nไม่ใช้ I have seen her yesterday ในอังกฤษมาตรฐานรูปที่กำลังฝึก\n\n\n\n### ดูภาพแล้วลองใช้\n\n![Present Perfect และ V3: have / has + V3; for two years / since 2024; I saw her yesterday.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/aefc1b906f07923c-module-25-map.png)\n\n*I have seen it.  •  Have you ever…?  •  รายละเอียดอดีตจบใช้ Past Simple*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present perfect, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/present-perfect)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('33b416b3-1828-5e93-a0d7-b701989067d9'::uuid,'93729cc3-518f-5be7-aafc-740646782640'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/e16cd27921f625d0-lesson-25-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I have lost my key.. I lost my key yesterday.. Have you seen Mai?. When did you see her?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7b76cd6e-e203-525d-aac6-76d28a614103'::uuid,'93729cc3-518f-5be7-aafc-740646782640'::uuid,'multiple_choice',1,'{"question":"เล่าเจอ Mai เมื่อวาน เลือก","choices":[{"id":"choice_1","text":"I saw Mai yesterday."},{"id":"choice_2","text":"I have seen Mai yesterday."},{"id":"choice_3","text":"I seen Mai yesterday."}],"correctChoiceId":"choice_1","explanation":"yesterday จบแล้วใช้ V2 saw"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('94c560b4-cf15-5dbe-a918-a9e8041952ca'::uuid,'93729cc3-518f-5be7-aafc-740646782640'::uuid,'multiple_choice',1,'{"question":"ถามประสบการณ์ไม่ระบุเวลา ใช้รูปใด?","choices":[{"id":"choice_1","text":"Have you visited London?"},{"id":"choice_2","text":"Have you visited London yesterday?"},{"id":"choice_3","text":"Do you visited London?"}],"correctChoiceId":"choice_1","explanation":"perfect สำหรับประสบการณ์ถึงตอนนี้โดยไม่ผูกอดีตจบ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c6dda770-d67f-559b-af85-4857d5198bb1'::uuid,'93729cc3-518f-5be7-aafc-740646782640'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนประสบการณ์หนึ่งข้อแล้วตามด้วยรายละเอียดเวลาอดีต พร้อมเหตุผลการเลือก tense\n\n### ตัวอย่างคำตอบ\n\nI have visited Chiang Mai. I went there last year. I have lost my pen, so I can’t write now.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Present Perfect เทียบ Past Simple** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('18152246-02d8-5f0a-a3c6-5ea82f01ef9a'::uuid,'f6e3e1d1-f676-5fe5-a518-a4875b010e96'::uuid,'reading',1,'{"title":"been/gone และการเล่ารวม","body":"## been/gone และการเล่ารวม\n\nhas been to สื่อไปแล้วกลับหรือประสบการณ์ ส่วน has gone to สื่อไปแล้วและยังไม่กลับในบริบทที่พูด เช่น Mai has gone to the shop จึงไม่ได้อยู่ที่นี่ ตอนเล่ารวมให้ใช้ perfect สรุปประสบการณ์หรือผลปัจจุบัน แล้ว simple สำหรับรายละเอียดเวลา และไม่สลับ pronoun จนไม่ชัดว่าใครไป\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Ben has been to Japan. | เคยไปและกลับแล้วในบริบทนี้ |\n| Mai has gone to the shop. | ไปแล้วยังไม่กลับ |\n| I have been there. I went last year. | สอง tense ตามข้อมูล |\n\n### จุดที่มักสับสน\n\nbe + been เป็น V3 ของ be; have been to กับ have gone to ต้องดูความหมาย ไม่ใช้แทนกันทุกเรื่อง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Present perfect, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/present-perfect)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2fc556f0-6758-58d5-aac7-58aa93a84f59'::uuid,'f6e3e1d1-f676-5fe5-a518-a4875b010e96'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/a327851130cbd6a7-lesson-25-07.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Ben has been to Japan.. Mai has gone to the shop.. I have been there. I went last year."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d0e39980-84bc-54dc-a8b4-618804a996a9'::uuid,'f6e3e1d1-f676-5fe5-a518-a4875b010e96'::uuid,'multiple_choice',1,'{"question":"Mai ไม่อยู่เพราะไปธนาคารและยังไม่กลับ ใช้รูปใด?","choices":[{"id":"choice_1","text":"Mai has gone to the bank."},{"id":"choice_2","text":"Mai has been to the bank. เพื่อยืนยันยังอยู่"},{"id":"choice_3","text":"Mai has went to the bank."}],"correctChoiceId":"choice_1","explanation":"has gone ชี้ไปแล้วและยังไม่กลับ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('72672bf0-71ff-585b-a9fa-09f7e75e20f5'::uuid,'f6e3e1d1-f676-5fe5-a518-a4875b010e96'::uuid,'multiple_choice',1,'{"question":"เล่าประสบการณ์ที่ไปแล้วกลับ เลือกรูปใด?","choices":[{"id":"choice_1","text":"I have been to Japan."},{"id":"choice_2","text":"I have went to Japan."},{"id":"choice_3","text":"I am been to Japan."}],"correctChoiceId":"choice_1","explanation":"have been to ใช้ประสบการณ์"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('17e4f4be-a6c3-5323-a7f5-057158cfa640'::uuid,'f6e3e1d1-f676-5fe5-a518-a4875b010e96'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนบทถามว่าคนอยู่ไหนหนึ่งบท และเล่าประสบการณ์หนึ่งบทให้แยก been/gone\n\n### ตัวอย่างคำตอบ\n\nWhere is Mai? She has gone to the shop. Have you been to Japan? Yes, I have. I went there in 2024.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **been/gone และการเล่ารวม** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e095d3b1-259b-5c30-a91d-9cea2b4f64e9'::uuid,'8efe249a-ad49-5cd6-ac40-530a9f99f835'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เล่าประสบการณ์และสิ่งที่เชื่อมกับปัจจุบัน พร้อมแยกจากอดีตที่ระบุเวลาจบแล้ว**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![Present Perfect และ V3: have / has + V3; for two years / since 2024; I saw her yesterday.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/aefc1b906f07923c-module-25-map.png)\n\n*I have seen it.  •  Have you ever…?  •  รายละเอียดอดีตจบใช้ Past Simple*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4940da33-cfe3-53cf-a0de-5a84355556ce'::uuid,'8efe249a-ad49-5cd6-ac40-530a9f99f835'::uuid,'multiple_choice',1,'{"question":"Anna has … her work.","choices":[{"id":"choice_1","text":"done"},{"id":"choice_2","text":"did"},{"id":"choice_3","text":"do"}],"correctChoiceId":"choice_1","explanation":"has + V3 done ย้อน 25.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('18f2b042-8767-5d39-a74d-be695c53db8d'::uuid,'8efe249a-ad49-5cd6-ac40-530a9f99f835'::uuid,'multiple_choice',1,'{"question":"I have known her … 2021.","choices":[{"id":"choice_1","text":"for"},{"id":"choice_2","text":"since"},{"id":"choice_3","text":"during"}],"correctChoiceId":"choice_2","explanation":"2021 จุดเริ่ม ใช้ since ย้อน 25.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('662a12ed-0e34-58e7-a94b-f3f715e335af'::uuid,'8efe249a-ad49-5cd6-ac40-530a9f99f835'::uuid,'multiple_choice',1,'{"question":"เวลา last night ที่จบแล้ว ใช้รูปใด?","choices":[{"id":"choice_1","text":"I saw Ben last night."},{"id":"choice_2","text":"I have seen Ben last night."},{"id":"choice_3","text":"I seen Ben last night."}],"correctChoiceId":"choice_1","explanation":"finished past time ใช้ Past Simple ย้อน 25.06"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2b29837f-8833-5d46-a2e2-020decb4ae29'::uuid,'8efe249a-ad49-5cd6-ac40-530a9f99f835'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเล่าประสบการณ์พร้อมรายละเอียดอดีต บอกสถานะงานและสภาพต่อเนื่องถึงปัจจุบัน แล้วถามเพื่อนหนึ่งข้อ\n\n### ตัวอย่างผลงาน\n\nI have been to Chiang Mai. I went there last year. I have just finished my work. I haven’t eaten yet. I have lived here for two years. Have you ever visited Chiang Mai?\n\n### ตรวจผลงาน\n\n- have/has + V3 ครบ\n- ประสบการณ์แยกจากรายละเอียดเวลาจบ\n- for/since/just/already/yet ใช้ความหมายถูก\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ef39ea0f-5318-5a45-aec3-e40eb868679d'::uuid,'3f6d137a-c29e-5904-ac07-06161791730d'::uuid,'reading',1,'{"title":"want/need/plan/would like + to","body":"## want/need/plan/would like + to\n\nwant/need/plan/would like ตามด้วย to + base verb เมื่อพูดถึงกิจกรรม เช่น I want to learn. แยกจาก want + noun เช่น I want a book. to ใน infinitive ไม่ได้แปลว่าไปสถานที่เสมอ และกริยาหลักยังเปลี่ยนตาม subject/time เช่น She wants to learn./She wanted to learn.\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I want to study. | want + to verb |\n| She plans to travel. | plans ตาม subject |\n| We would like to join. | would like to verb |\n\n### จุดที่มักสับสน\n\nwant study และ wants to studies ผิด; หลัง to ใช้ base\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Verbs followed by -ing or infinitive](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/verbs-followed-ing-or-infinitive) · [British Council — Adjectives and prepositions](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-prepositions)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c835b941-f1e3-5fd3-a325-d11fc9f24214'::uuid,'3f6d137a-c29e-5904-ac07-06161791730d'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/329b32a8c0e33d06-lesson-26-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I want to study.. She plans to travel.. We would like to join."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f95df58d-81a3-5aac-a910-2a70ef306584'::uuid,'3f6d137a-c29e-5904-ac07-06161791730d'::uuid,'multiple_choice',1,'{"question":"She wants … English.","choices":[{"id":"choice_1","text":"to learn"},{"id":"choice_2","text":"learning ในรูป want นี้"},{"id":"choice_3","text":"learns"}],"correctChoiceId":"choice_1","explanation":"want + to-infinitive"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3a0b1ef3-81eb-55ae-a4c6-2ab7f6504a4b'::uuid,'3f6d137a-c29e-5904-ac07-06161791730d'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคถูก","choices":[{"id":"choice_1","text":"I would like to come."},{"id":"choice_2","text":"I would like coming ในคำชวนรูปนี้"},{"id":"choice_3","text":"I would like comes."}],"correctChoiceId":"choice_1","explanation":"would like + to + base"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b4b307ca-ce00-5382-a4ab-ece16aeecec8'::uuid,'3f6d137a-c29e-5904-ac07-06161791730d'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนความต้องการ ความจำเป็นและแผนอย่างละหนึ่งประโยค\n\n### ตัวอย่างคำตอบ\n\nI want to learn English. I need to practise. I plan to study tonight.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **want/need/plan/would like + to** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('423f313d-2b53-5bad-a5e8-f845de57407d'::uuid,'220c9b8f-124a-542c-adec-e23632337a33'::uuid,'reading',1,'{"title":"enjoy/like/love/hate + ing","body":"## enjoy/like/love/hate + ing\n\nenjoy ตามด้วย ing: enjoy reading ไม่ใช่ enjoy to read ส่วน like/love/hate ตามด้วย ing ได้เมื่อกล่าวถึงกิจกรรม และตามด้วย to ได้ในบางบริบท เช่น I like to read before bed. ไม่ตีความ ing ทุกคำเป็น continuous เพราะ enjoy swimming ไม่มี be + ing และ swimming เป็นกิจกรรมที่ชอบ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I enjoy cooking. | enjoy + ing |\n| She likes reading. | like + ing |\n| I love to walk in the morning. | love + to ได้ตามบริบท |\n\n### จุดที่มักสับสน\n\nI am enjoy reading ผิดสำหรับ Present Simple; enjoy เป็น main verb เอง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Verbs followed by -ing or infinitive](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/verbs-followed-ing-or-infinitive) · [British Council — Adjectives and prepositions](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-prepositions)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7e56672a-3727-54c4-a162-e7073a8074b4'::uuid,'220c9b8f-124a-542c-adec-e23632337a33'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/8be7687d9e3866b6-lesson-26-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I enjoy cooking.. She likes reading.. I love to walk in the morning."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ac1b26e3-7ae9-5532-ae14-9de77a7ad91e'::uuid,'220c9b8f-124a-542c-adec-e23632337a33'::uuid,'multiple_choice',1,'{"question":"เลือกวลีหลัง enjoy ที่ถูก","choices":[{"id":"choice_1","text":"enjoy to swim"},{"id":"choice_2","text":"enjoy swimming"},{"id":"choice_3","text":"enjoy swims"}],"correctChoiceId":"choice_2","explanation":"enjoy ตามด้วย -ing"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('52f68a17-4bd9-50b9-a543-ed791428c363'::uuid,'220c9b8f-124a-542c-adec-e23632337a33'::uuid,'multiple_choice',1,'{"question":"ing ใน I like cooking ทำหน้าที่ใด?","choices":[{"id":"choice_1","text":"กิจกรรมที่ชอบ"},{"id":"choice_2","text":"continuous ที่ขาด be"},{"id":"choice_3","text":"อดีตเสมอ"}],"correctChoiceId":"choice_1","explanation":"cooking เป็นกิจกรรมที่เป็นกรรมของ like"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fc816941-6025-518c-a23f-adec7952f702'::uuid,'220c9b8f-124a-542c-adec-e23632337a33'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกกิจกรรมที่ชอบสามอย่าง ใช้ enjoy/like/love แล้วเขียนไม่ชอบหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nI enjoy cooking. I like reading. I love swimming. I hate waiting.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **enjoy/like/love/hate + ing** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8863d123-1d7c-58d0-a721-6972ef8ad6dd'::uuid,'a2c9ec2f-dfba-58ba-a0f3-75cd725afdc5'::uuid,'reading',1,'{"title":"หลัง modal และคำสั่งใช้ base verb","body":"## หลัง modal และคำสั่งใช้ base verb\n\nหลัง modal can/should/must/will ใช้ base verb ไม่เติม to แต่หลัง want/need ใช้ to-infinitive เปรียบเทียบ can go กับ want to go คำสั่งก็เริ่ม base: Go now. help ใช้ help me do หรือ help me to do ได้ในรูปที่ใช้ทั่วไป โดยไม่เอากฎ help ไปใช้กับทุก verb\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I can go. / I want to go. | modal / verb pattern |\n| You should study. | should + base |\n| Help me carry this. / Help me to carry this. | สองรูปของ help |\n\n### จุดที่มักสับสน\n\ncan to go ผิด; modal ไม่ตามด้วย to ในโครงนี้\n\n\n\n### ดูภาพแล้วลองใช้\n\n![กริยาต่อกริยา: want to go; enjoy going; can go](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f0cf0f0de8bb6b76-module-26-map.png)\n\n*after eating  •  good at swimming  •  ing ไม่ใช่ continuous ทุกคำ*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Verbs followed by -ing or infinitive](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/verbs-followed-ing-or-infinitive) · [British Council — Adjectives and prepositions](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-prepositions)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('101df713-8910-5f81-ac24-d726c8b489bf'::uuid,'a2c9ec2f-dfba-58ba-a0f3-75cd725afdc5'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/fcf3f95f9d7ccf73-lesson-26-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I can go.. I want to go.. You should study.. Help me carry this.. Help me to carry this."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('81df26d8-aec5-59b7-af6c-e0193d1b6d03'::uuid,'a2c9ec2f-dfba-58ba-a0f3-75cd725afdc5'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคถูก","choices":[{"id":"choice_1","text":"We must leave."},{"id":"choice_2","text":"We must to leave."},{"id":"choice_3","text":"We must leaves."}],"correctChoiceId":"choice_1","explanation":"must + base"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4bd9bb46-b2c9-53f9-ad07-d15280344f9f'::uuid,'a2c9ec2f-dfba-58ba-a0f3-75cd725afdc5'::uuid,'multiple_choice',1,'{"question":"รูปใดของ help ใช้ได้ตามบท?","choices":[{"id":"choice_1","text":"help me carry / help me to carry"},{"id":"choice_2","text":"help me carries เท่านั้น"},{"id":"choice_3","text":"help me carrying เท่านั้น"}],"correctChoiceId":"choice_1","explanation":"help ใช้ infinitive แบบมีหรือไม่มี to ได้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5167cdf4-6dbd-5aa5-afee-1f11b409ea8a'::uuid,'a2c9ec2f-dfba-58ba-a0f3-75cd725afdc5'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนกิจกรรมเดียวกันด้วย can/want/should และ help\n\n### ตัวอย่างคำตอบ\n\nI can cook. I want to cook. I should cook. Could you help me cook?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **หลัง modal และคำสั่งใช้ base verb** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cb86966e-cc2f-5ba9-a6fc-c741e1b9b3d8'::uuid,'8a3ffc9b-e809-5182-a68b-91fedff5c162'::uuid,'reading',1,'{"title":"preposition + ing","body":"## preposition + ing\n\nหลัง preposition โดยทั่วไปใช้ noun หรือ ing สำหรับกิจกรรม เช่น after eating/before leaving/without paying บาง to เป็น preposition เช่น look forward to meeting ไม่ใช่ to-infinitive เริ่มเรียนเป็นกลุ่มคำพร้อมความหมาย ส่วน want to meet ใช้ to + base เพราะเป็น infinitive\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Wash your hands before eating. | before + ing |\n| He left without saying goodbye. | without + ing |\n| I look forward to meeting you. | to เป็น preposition ในกลุ่มนี้ |\n\n### จุดที่มักสับสน\n\nไม่ใช้ after to eat ในรูปที่ฝึก; การเห็น to ไม่รับรองว่ากริยาถัดไปต้อง base ทุกกลุ่ม\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Verbs followed by -ing or infinitive](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/verbs-followed-ing-or-infinitive) · [British Council — Adjectives and prepositions](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-prepositions)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('09fd5ed3-e27a-53b2-a576-519bd1542524'::uuid,'8a3ffc9b-e809-5182-a68b-91fedff5c162'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/bd1486c177ddad54-lesson-26-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Wash your hands before eating.. He left without saying goodbye.. I look forward to meeting you."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4b7dbf7c-cd81-590a-a4aa-d706ab733c22'::uuid,'8a3ffc9b-e809-5182-a68b-91fedff5c162'::uuid,'multiple_choice',1,'{"question":"เลือกวลีถูก","choices":[{"id":"choice_1","text":"after eating"},{"id":"choice_2","text":"after to eat"},{"id":"choice_3","text":"after eats"}],"correctChoiceId":"choice_1","explanation":"after เป็น preposition ตามด้วย ing เมื่อกิจกรรม"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8268e5e8-bb27-53c1-a9ab-6673443dd6da'::uuid,'8a3ffc9b-e809-5182-a68b-91fedff5c162'::uuid,'multiple_choice',1,'{"question":"without … ใช้รูปใด?","choices":[{"id":"choice_1","text":"pay"},{"id":"choice_2","text":"paying"},{"id":"choice_3","text":"to pay"}],"correctChoiceId":"choice_2","explanation":"without + ing"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6dee2187-7c2e-51b7-a21b-e8e3de363a94'::uuid,'8a3ffc9b-e809-5182-a68b-91fedff5c162'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนข้อปฏิบัติสามอย่างด้วย before/after/without + ing\n\n### ตัวอย่างคำตอบ\n\nWash your hands before eating. Rest after working. Don’t leave without saying goodbye.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **preposition + ing** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b2f28aba-53dc-56c4-a570-a60fe4be7746'::uuid,'d2edd500-1959-5aa8-a685-f4ba621d8342'::uuid,'reading',1,'{"title":"ing เป็นชื่อกิจกรรม","body":"## ing เป็นชื่อกิจกรรม\n\ning ใช้เป็นชื่อกิจกรรมและเป็น subject/object ได้ เช่น Swimming is fun. ใช้ singular verb เมื่อกิจกรรมหนึ่งเป็นประธาน ต่างจาก She is swimming. ที่เป็น continuous ส่วน adjective + to-infinitive เช่น easy to use/ happy to help มีรูปตามกลุ่มคำที่ใช้จริง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Reading is useful. | กิจกรรมเป็น subject |\n| I like swimming. | กิจกรรมเป็น object |\n| This app is easy to use. | adjective + to verb |\n\n### จุดที่มักสับสน\n\nSwimming are fun ผิดเมื่อพูดถึงกิจกรรมหนึ่ง และ ing ไม่ได้บอกกำลังทำทุกครั้ง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Verbs followed by -ing or infinitive](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/verbs-followed-ing-or-infinitive) · [British Council — Adjectives and prepositions](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-prepositions)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fad9a314-1e5c-5682-ac5c-ec8a2f212f58'::uuid,'d2edd500-1959-5aa8-a685-f4ba621d8342'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9de9330a232b2114-lesson-26-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Reading is useful.. I like swimming.. This app is easy to use."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c62407f7-a002-570c-aa28-7e7242ea2614'::uuid,'d2edd500-1959-5aa8-a685-f4ba621d8342'::uuid,'multiple_choice',1,'{"question":"… English is useful.","choices":[{"id":"choice_1","text":"Learning"},{"id":"choice_2","text":"Learned"},{"id":"choice_3","text":"Learns"}],"correctChoiceId":"choice_1","explanation":"Learning เป็นกิจกรรมที่ทำหน้าที่ประธาน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('90ec8290-98c9-593c-a4c6-db8129b56365'::uuid,'d2edd500-1959-5aa8-a685-f4ba621d8342'::uuid,'multiple_choice',1,'{"question":"เลือกวลี adjective + infinitive","choices":[{"id":"choice_1","text":"easy to use"},{"id":"choice_2","text":"easy usingly"},{"id":"choice_3","text":"easy uses"}],"correctChoiceId":"choice_1","explanation":"easy + to + base"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b636d72e-7122-54e5-ad92-f2b9e7289fa7'::uuid,'d2edd500-1959-5aa8-a685-f4ba621d8342'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนกิจกรรมเป็นประธานสองข้อ และ adjective + to สองข้อ\n\n### ตัวอย่างคำตอบ\n\nReading is fun. Cooking is useful. This book is easy to read. I am happy to help.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ing เป็นชื่อกิจกรรม** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ada7224a-7f8e-5d03-a27d-7311b976acb5'::uuid,'b23b7460-fa9e-5e65-a19e-62269ac29cc5'::uuid,'reading',1,'{"title":"adjective/verb + preposition","body":"## adjective/verb + preposition\n\nจำ adjective/verb พร้อม preposition และกรรม: good at/interested in/afraid of; listen to/wait for/look at; prefer A to B อย่าแปลคำเดี่ยวแล้วเลือก preposition จากไทย หลัง preposition ใช้ object pronoun หรือ ing ตามสิ่งที่พูด เช่น good at swimming/listen to her\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| She is good at drawing. | adjective + preposition + ing |\n| I listen to music. | verb + to + noun |\n| We wait for him. | for + object pronoun |\n| I prefer tea to coffee. | A เทียบ B |\n\n### จุดที่มักสับสน\n\nlisten music และ wait him ขาด preposition; prefer A than B ไม่ใช่ pattern ที่ฝึก\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Verbs followed by -ing or infinitive](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/verbs-followed-ing-or-infinitive) · [British Council — Adjectives and prepositions](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-prepositions)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('08969374-2d3a-5d4e-aca2-6129a8b9cdb3'::uuid,'b23b7460-fa9e-5e65-a19e-62269ac29cc5'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/27852e054d95eb16-lesson-26-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"She is good at drawing.. I listen to music.. We wait for him.. I prefer tea to coffee."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4bdd8fce-d63e-5751-a4cd-2bbe5740b5ab'::uuid,'b23b7460-fa9e-5e65-a19e-62269ac29cc5'::uuid,'multiple_choice',1,'{"question":"I am interested … art.","choices":[{"id":"choice_1","text":"in"},{"id":"choice_2","text":"at"},{"id":"choice_3","text":"for"}],"correctChoiceId":"choice_1","explanation":"interested in เป็นกลุ่มคำ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f892264e-3f0d-54ea-a986-98e91377a788'::uuid,'b23b7460-fa9e-5e65-a19e-62269ac29cc5'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มคำถูก","choices":[{"id":"choice_1","text":"listen to her"},{"id":"choice_2","text":"listen she"},{"id":"choice_3","text":"listen for music ในความหมายฟังเพลงทั่วไป"}],"correctChoiceId":"choice_1","explanation":"listen to + object pronoun"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5aa507df-d146-5f8e-af57-946753cd6c41'::uuid,'b23b7460-fa9e-5e65-a19e-62269ac29cc5'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนห้าประโยคพร้อมกลุ่ม good at/interested in/listen to/wait for/prefer…to…\n\n### ตัวอย่างคำตอบ\n\nI am good at cooking. I am interested in music. I listen to songs. I wait for Mai. I prefer tea to coffee.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **adjective/verb + preposition** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6e07446b-aba9-5c6b-a1b5-eb54e2c32403'::uuid,'d6bf9c9d-f8f0-5b15-a5f1-9005393d109d'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เลือก to/ing/base verb ตามโครงสร้างที่เรียน โดยไม่เอา ing ทุกคำไปตีความเป็น continuous**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![กริยาต่อกริยา: want to go; enjoy going; can go](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f0cf0f0de8bb6b76-module-26-map.png)\n\n*after eating  •  good at swimming  •  ing ไม่ใช่ continuous ทุกคำ*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('12169db0-01d0-5b92-a8d4-f7ad408960f1'::uuid,'d6bf9c9d-f8f0-5b15-a5f1-9005393d109d'::uuid,'multiple_choice',1,'{"question":"I enjoy …","choices":[{"id":"choice_1","text":"swimming"},{"id":"choice_2","text":"to swim"},{"id":"choice_3","text":"swims"}],"correctChoiceId":"choice_1","explanation":"enjoy + ing ย้อน 26.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ca33629a-6aed-536a-ad36-c22ee80b8645'::uuid,'d6bf9c9d-f8f0-5b15-a5f1-9005393d109d'::uuid,'multiple_choice',1,'{"question":"She is good … drawing.","choices":[{"id":"choice_1","text":"at"},{"id":"choice_2","text":"in"},{"id":"choice_3","text":"for"}],"correctChoiceId":"choice_1","explanation":"good at เป็นกลุ่มคำ ย้อน 26.06"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('818fee44-570c-59c5-a1cb-9a5e1af4ae5a'::uuid,'d6bf9c9d-f8f0-5b15-a5f1-9005393d109d'::uuid,'multiple_choice',1,'{"question":"Wash your hands before …","choices":[{"id":"choice_1","text":"eating"},{"id":"choice_2","text":"to eat"},{"id":"choice_3","text":"eats"}],"correctChoiceId":"choice_1","explanation":"preposition + ing ย้อน 26.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('98c311c7-5e65-5692-aab0-4dcb9633058d'::uuid,'d6bf9c9d-f8f0-5b15-a5f1-9005393d109d'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเขียนความต้องการ ความชอบ ความสามารถ จุดแข็งและข้อปฏิบัติโดยใช้รูปกริยาต่อกริยาห้าประโยค\n\n### ตัวอย่างผลงาน\n\nI want to learn. I enjoy reading. I can cook. I am good at drawing. I rest after studying.\n\n### ตรวจผลงาน\n\n- verb pattern to/ing/base ตรงกลุ่ม\n- แยก ing กิจกรรมจาก continuous\n- preposition และกรรมไม่ตก\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('32a56300-f5c3-5af1-a5d8-42424fde59c8'::uuid,'36957d04-79f9-5273-a6a6-b0217b6be4d4'::uuid,'reading',1,'{"title":"and/but/or","body":"## and/but/or\n\nand เพิ่มข้อมูล but บอกความต่างหรือขัดความคาดหมาย or เสนอทางเลือก เชื่อมคำ วลีหรือประโยคที่มีหน้าที่เข้ากัน ถ้าเชื่อมประโยคหลักสองส่วนให้ชัดว่าประธานแต่ละส่วนคือใคร เช่น I like tea, but Ben likes coffee. comma ช่วยแบ่งส่วนเมื่อจำเป็น\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I read and write. | สองการกระทำ |\n| I like tea, but Mai likes coffee. | ความต่าง |\n| Do you want tea or water? | ทางเลือก |\n\n### จุดที่มักสับสน\n\nไม่ใช้ and เพื่อบอกผลทุกครั้ง; เลือกคำจากความสัมพันธ์ของความคิด\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory, 2011](https://www.eaquals.org/wp-content/uploads/EAQUALS_British_Council_Core_Curriculum_April2011.pdf) · [British Council — Verbs in time clauses and if clauses, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/verbs-time-clauses-if-clauses?page=18)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7fdd7597-64da-59e8-af71-b4f755bbf53a'::uuid,'36957d04-79f9-5273-a6a6-b0217b6be4d4'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d7787560ea485fc2-lesson-27-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I read and write.. I like tea, but Mai likes coffee.. Do you want tea or water?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('34b9526c-ff80-5deb-a156-82032db999e1'::uuid,'36957d04-79f9-5273-a6a6-b0217b6be4d4'::uuid,'multiple_choice',1,'{"question":"เลือกคำเชื่อมทางเลือก: Tea … coffee?","choices":[{"id":"choice_1","text":"and เท่านั้น"},{"id":"choice_2","text":"or"},{"id":"choice_3","text":"because"}],"correctChoiceId":"choice_2","explanation":"or เสนอให้เลือก"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ecb9d52d-99dd-5dd9-a8e4-4305781a235f'::uuid,'36957d04-79f9-5273-a6a6-b0217b6be4d4'::uuid,'multiple_choice',1,'{"question":"สองข้อมูลต่างกัน: I like music, … Ben doesn’t.","choices":[{"id":"choice_1","text":"but"},{"id":"choice_2","text":"so"},{"id":"choice_3","text":"until"}],"correctChoiceId":"choice_1","explanation":"but แสดงความต่าง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8cb26e5c-7d24-56fa-a4c3-2fa63086a8d1'::uuid,'36957d04-79f9-5273-a6a6-b0217b6be4d4'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนประโยคเพิ่มข้อมูล ความต่างและทางเลือกอย่างละหนึ่ง\n\n### ตัวอย่างคำตอบ\n\nI read and write. I like tea, but Ben likes coffee. Do you want rice or noodles?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **and/but/or** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fb9a4896-7158-5b55-a0d8-136c6da14d1b'::uuid,'169e9dfb-e4af-5d8b-afb3-31798ee01b8b'::uuid,'reading',1,'{"title":"because/so/although","body":"## because/so/although\n\nbecause แนะนำเหตุผล so แนะนำผล although แสดงความต่างแม้เงื่อนไขหนึ่งเป็นจริง เลือกโครง I stayed home because it rained. หรือ It rained, so I stayed home. ไม่ซ้อน because…so… แบบไทยในรูปที่ฝึก although… ไม่จำเป็นต้องมี but ซ้ำ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I stayed home because I was tired. | เหตุผล |\n| I was tired, so I rested. | ผล |\n| Although it rained, we went out. | ความต่างจากคาด |\n\n### จุดที่มักสับสน\n\nbecause it rained เพียงส่วนเดียวเป็น subordinate clause หากตั้งใจประโยคเต็มให้มี main clause ด้วย\n\n\n\n### ดูภาพแล้วลองใช้\n\n![เหตุผล ผลและจุดประสงค์: I stayed because it rained.; It rained, so I stayed.; I read to learn.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/c322643548958391-module-27-map.png)\n\n*I’ll call when I arrive.  •  present ใน time clause อนาคต*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory, 2011](https://www.eaquals.org/wp-content/uploads/EAQUALS_British_Council_Core_Curriculum_April2011.pdf) · [British Council — Verbs in time clauses and if clauses, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/verbs-time-clauses-if-clauses?page=18)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('73e58f13-05be-55e0-a9c7-a4efe259ab58'::uuid,'169e9dfb-e4af-5d8b-afb3-31798ee01b8b'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/5b6fcd1421e15d7f-lesson-27-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I stayed home because I was tired.. I was tired, so I rested.. Although it rained, we went out."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('093b7655-9f57-5f83-a606-d68473b59b74'::uuid,'169e9dfb-e4af-5d8b-afb3-31798ee01b8b'::uuid,'multiple_choice',1,'{"question":"It was cold, … I wore a coat.","choices":[{"id":"choice_1","text":"so"},{"id":"choice_2","text":"because ในความหมายเป็นผลนี้"},{"id":"choice_3","text":"although"}],"correctChoiceId":"choice_1","explanation":"ใส่เสื้อเป็นผลของอากาศหนาว"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6ce1a90a-4522-51bc-ab0e-6fe2ad5d81bb'::uuid,'169e9dfb-e4af-5d8b-afb3-31798ee01b8b'::uuid,'multiple_choice',1,'{"question":"เลือกรูปเหตุผลถูก","choices":[{"id":"choice_1","text":"Because I was tired, so I slept."},{"id":"choice_2","text":"I slept because I was tired."},{"id":"choice_3","text":"Because tired."}],"correctChoiceId":"choice_2","explanation":"main clause + because + clause ไม่ซ้อน so"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c898a4b5-0ba9-56ea-a2d3-7cbadac6873b'::uuid,'169e9dfb-e4af-5d8b-afb3-31798ee01b8b'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนเหตุผลหนึ่งเรื่องสองรูป because/so และความต่างด้วย although อีกหนึ่ง\n\n### ตัวอย่างคำตอบ\n\nI stayed home because I was tired. I was tired, so I stayed home. Although I was tired, I finished my work.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **because/so/although** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e279c71d-7883-5343-adf1-a96a263c694b'::uuid,'ab94396e-59ff-559c-a85d-5438aebf17ab'::uuid,'reading',1,'{"title":"to บอกจุดประสงค์","body":"## to บอกจุดประสงค์\n\nto + base verb บอกจุดประสงค์ของการทำ เช่น I study to learn. หรือ I went to the shop to buy food. to แรกใน to the shop เป็น preposition + place ส่วน to buy เป็น infinitive + verb ใช้ตอบ Why…? เมื่อบอกจุดประสงค์ ไม่ใช้ for + base verb แทนตรง ๆ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I read to learn new words. | จุดประสงค์ |\n| She went to the bank to get money. | place / purpose |\n| We meet to practise English. | กิจกรรมเพื่อเป้าหมาย |\n\n### จุดที่มักสับสน\n\nto learning ไม่ใช่ purpose infinitive ในรูปนี้; for ใช้กับ noun/ing ในโครงอื่นได้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory, 2011](https://www.eaquals.org/wp-content/uploads/EAQUALS_British_Council_Core_Curriculum_April2011.pdf) · [British Council — Verbs in time clauses and if clauses, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/verbs-time-clauses-if-clauses?page=18)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8775be7d-6953-520c-a4e2-a2ba9dd5abab'::uuid,'ab94396e-59ff-559c-a85d-5438aebf17ab'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/cb3811ddb091a1d3-lesson-27-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I read to learn new words.. She went to the bank to get money.. We meet to practise English."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8cef75a8-6b05-5add-a965-f0cd56d51989'::uuid,'ab94396e-59ff-559c-a85d-5438aebf17ab'::uuid,'multiple_choice',1,'{"question":"I went to the shop … food.","choices":[{"id":"choice_1","text":"to buy"},{"id":"choice_2","text":"to buying"},{"id":"choice_3","text":"for buy"}],"correctChoiceId":"choice_1","explanation":"purpose ใช้ to + base buy"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5b0e8037-f06a-56e9-abff-51f3174b6df6'::uuid,'ab94396e-59ff-559c-a85d-5438aebf17ab'::uuid,'multiple_choice',1,'{"question":"to ใน to school ต่างจาก to learn อย่างไร?","choices":[{"id":"choice_1","text":"place preposition / infinitive purpose"},{"id":"choice_2","text":"ทั้งสองต้องตามด้วย noun"},{"id":"choice_3","text":"ทั้งสองเป็นอดีต"}],"correctChoiceId":"choice_1","explanation":"ชนิดคำที่ตามและหน้าที่ต่างกัน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('83d3e59b-86c0-56bb-a95a-699f5d41a90d'::uuid,'ab94396e-59ff-559c-a85d-5438aebf17ab'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนเหตุผลการทำสามกิจกรรมด้วย to + verb\n\n### ตัวอย่างคำตอบ\n\nI study to learn English. I work to earn money. I go to the cafe to meet Mai.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **to บอกจุดประสงค์** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f469c54f-409a-5422-a006-38488cadba25'::uuid,'b655076d-8b05-56de-a257-7dd18c2c5f93'::uuid,'reading',1,'{"title":"when/before/after/until","body":"## when/before/after/until\n\ntime clauses ด้วย when/before/after/until มี subject + verb ของตนเอง หากพูดอนาคตใช้ present form ใน clause เวลา: I’ll call when I arrive. ไม่เติม will ซ้ำโดยอัตโนมัติ where เชื่อมข้อมูลสถานที่ได้ เช่น I’ll wait where you are. ดูความหมายและความสัมพันธ์ของสองส่วน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I’ll call you when I arrive. | อนาคต main, present time clause |\n| We’ll eat after Ben comes. | after + clause |\n| I’ll wait where you are. | clause สถานที่ |\n\n### จุดที่มักสับสน\n\nI’ll call when I will arrive ไม่ใช่รูปทั่วไปที่ฝึกใน time clause นี้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory, 2011](https://www.eaquals.org/wp-content/uploads/EAQUALS_British_Council_Core_Curriculum_April2011.pdf) · [British Council — Verbs in time clauses and if clauses, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/verbs-time-clauses-if-clauses?page=18)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('17068875-2182-505e-a863-8df5377da87f'::uuid,'b655076d-8b05-56de-a257-7dd18c2c5f93'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/5eab093874a1216d-lesson-27-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I’ll call you when I arrive.. We’ll eat after Ben comes.. I’ll wait where you are."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b554d56e-fece-5fd1-aa96-9aefd2b27b4a'::uuid,'b655076d-8b05-56de-a257-7dd18c2c5f93'::uuid,'multiple_choice',1,'{"question":"I’ll send a message when I … home.","choices":[{"id":"choice_1","text":"get"},{"id":"choice_2","text":"will get"},{"id":"choice_3","text":"getting"}],"correctChoiceId":"choice_1","explanation":"time clause อนาคตใช้ present get"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('af93868c-4f92-5677-ad7f-669d51d385d0'::uuid,'b655076d-8b05-56de-a257-7dd18c2c5f93'::uuid,'multiple_choice',1,'{"question":"ส่วนใดมี subject+verb?","choices":[{"id":"choice_1","text":"after she arrives"},{"id":"choice_2","text":"after arrives เท่านั้น"},{"id":"choice_3","text":"after arrival เป็น clause"}],"correctChoiceId":"choice_1","explanation":"she subject และ arrives verb ทำให้เป็น clause"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3814f1a0-6171-5502-aee7-476240548959'::uuid,'b655076d-8b05-56de-a257-7dd18c2c5f93'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนแผนที่เชื่อม when/before/after/until อย่างละหนึ่ง\n\n### ตัวอย่างคำตอบ\n\nI’ll call when I arrive. I’ll eat before I leave. I’ll study after I get home. I’ll wait until Mai comes.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **when/before/after/until** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bae3bba6-0212-5aba-a803-9c24b195b44b'::uuid,'bea9ba97-8860-5482-aa76-b0e62d014f08'::uuid,'reading',1,'{"title":"จัดย่อหน้าสั้น","body":"## จัดย่อหน้าสั้น\n\nย่อหน้าสั้นควรมีหัวเรื่องหรือใจความหนึ่งแล้วเรียงข้อมูล เพิ่มเหตุผลและเวลาให้คนอ่านตามได้ first/next/then/finally ช่วยลำดับ ใช้ pronouns เมื่ออ้างกลับชัด และรักษา tense ตามข้อมูลแต่ละช่วง เช่น past เหตุการณ์เมื่อวานกับ future แผนพรุ่งนี้ ตรวจจุดท้ายและตัวใหญ่เมื่อเชื่อมหลายประโยค\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Yesterday, I visited Mai. We cooked lunch together. | อ้าง we ชัด |\n| Then we studied because we had a test. | ลำดับ + เหตุผล |\n| Tomorrow, I’m going to study again. | แผนต่างช่วง |\n\n### จุดที่มักสับสน\n\nไม่ต่อประโยคทั้งหมดด้วย and โดยไม่มีจุดแบ่ง และไม่เปลี่ยนผู้ทำหรือเวลาโดยไร้บริบท\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ภาพสามช่อง Mai เดินในสวน จากนั้นฝนตก Ben ใช้ร่มช่วยและทั้งคู่ถึงร้านกาแฟ](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4253d113ce35a709-rain-story.png)\n\n*Mai was walking when it began to rain. Ben opened his umbrella. Then they reached a cafe.*\n\nใช้ภาพเป็นเรื่องใหม่สำหรับฝึก ไม่เปลี่ยนข้อเท็จจริงของตัวอย่างเดิม เล่าลำดับที่เห็น หรือเสนอแผนเมื่อมีฝนตามหัวข้อบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory, 2011](https://www.eaquals.org/wp-content/uploads/EAQUALS_British_Council_Core_Curriculum_April2011.pdf) · [British Council — Verbs in time clauses and if clauses, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/verbs-time-clauses-if-clauses?page=18)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cb552014-46e1-57f0-a0d3-d29a9123a12f'::uuid,'bea9ba97-8860-5482-aa76-b0e62d014f08'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/87afd13ed298d431-lesson-27-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Yesterday, I visited Mai. We cooked lunch together.. Then we studied because we had a test.. Tomorrow, I’m going to study again."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('807d9c54-15eb-57bd-ab58-8d9c996f802e'::uuid,'bea9ba97-8860-5482-aa76-b0e62d014f08'::uuid,'multiple_choice',1,'{"question":"คำใดทำให้ลำดับชัด?","choices":[{"id":"choice_1","text":"First… Then… Finally…"},{"id":"choice_2","text":"Every… Many… Much…"},{"id":"choice_3","text":"Whose… Which…"}],"correctChoiceId":"choice_1","explanation":"ชุดแรกเป็น markers ลำดับเรื่อง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('dbda95e5-0a96-5980-ab54-4a5abad2333f'::uuid,'bea9ba97-8860-5482-aa76-b0e62d014f08'::uuid,'multiple_choice',1,'{"question":"Mai visited Ben. He cooked lunch. He อ้างใครตามข้อมูลที่ชัด?","choices":[{"id":"choice_1","text":"Ben"},{"id":"choice_2","text":"Mai"},{"id":"choice_3","text":"อาหาร"}],"correctChoiceId":"choice_1","explanation":"Ben เป็นบุคคลที่อ้างกับ he ตามบริบทชื่อที่กำหนด"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6b68e01c-4bea-5bc3-a944-5bc7f7779b0f'::uuid,'bea9ba97-8860-5482-aa76-b0e62d014f08'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนย่อหน้า 5–6 ประโยคเล่าเมื่อวานและแผนพรุ่งนี้ มีคำเชื่อมอย่างน้อยสามคำ\n\n### ตัวอย่างคำตอบ\n\nYesterday, I visited Ben. First, we cooked lunch. Then we ate together. After that, we studied English because we had a test. Tomorrow, we’re going to read a new book.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **จัดย่อหน้าสั้น** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('71cb6465-52e5-5b3c-a48a-9e7311e213ac'::uuid,'b4c5358b-493a-53f5-a69e-5132425f4722'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เชื่อมความคิดโดยยังคงประธาน กริยา และลำดับเหตุผลชัดเจน**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![เหตุผล ผลและจุดประสงค์: I stayed because it rained.; It rained, so I stayed.; I read to learn.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/c322643548958391-module-27-map.png)\n\n*I’ll call when I arrive.  •  present ใน time clause อนาคต*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('caffc8e7-433c-5532-a5f2-9e9f595f17b8'::uuid,'b4c5358b-493a-53f5-a69e-5132425f4722'::uuid,'multiple_choice',1,'{"question":"I was hungry, … I ate lunch.","choices":[{"id":"choice_1","text":"so"},{"id":"choice_2","text":"because ในความหมายผลนี้"},{"id":"choice_3","text":"or"}],"correctChoiceId":"choice_1","explanation":"so เชื่อมผล ย้อน 27.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('66bb5778-5461-5543-a730-bc0d6c4843cd'::uuid,'b4c5358b-493a-53f5-a69e-5132425f4722'::uuid,'multiple_choice',1,'{"question":"I’ll call when I …","choices":[{"id":"choice_1","text":"arrive"},{"id":"choice_2","text":"will arrive ใน time clause รูปทั่วไป"},{"id":"choice_3","text":"arriving"}],"correctChoiceId":"choice_1","explanation":"present ใน time clause อนาคต ย้อน 27.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('39c8d691-07c3-5821-a247-0e24ed2f541a'::uuid,'b4c5358b-493a-53f5-a69e-5132425f4722'::uuid,'multiple_choice',1,'{"question":"I read … learn new words.","choices":[{"id":"choice_1","text":"to"},{"id":"choice_2","text":"for"},{"id":"choice_3","text":"because โดยไม่มี clause"}],"correctChoiceId":"choice_1","explanation":"to+base บอกจุดประสงค์ ย้อน 27.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fa9b574a-94cc-5de5-a36a-da9ab382a2ef'::uuid,'b4c5358b-493a-53f5-a69e-5132425f4722'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเขียนย่อหน้าอดีตห้าประโยคแล้วแผนอนาคตสองประโยค มีเหตุผล จุดประสงค์และลำดับเวลา\n\n### ตัวอย่างผลงาน\n\nYesterday, I went to the library to find a book. First, I looked for it. Then I asked the librarian because I couldn’t find it. She helped me, so I thanked her. Tomorrow, I’ll read it after I finish work.\n\n### ตรวจผลงาน\n\n- ความสัมพันธ์ and/but/or/because/so ชัด\n- แต่ละ clause มีประธานและกริยา\n- time clause อนาคตใช้ present และย่อหน้ารักษาเวลา\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1a2ecacb-6b6f-5acb-a300-db0c2e7d776b'::uuid,'14e1dcd0-a57a-5dd7-a9c3-81fadad11542'::uuid,'reading',1,'{"title":"แสดงสิ่งที่ทำได้","body":"## งานปิดคอร์ส 3\n\n**เล่าอดีต พูดถึงแผน ประสบการณ์ เปรียบเทียบ และอธิบายเหตุผลง่าย ๆ ได้**\n\nทำข้อทดสอบใหม่ต่อไปนี้ แล้วทำงานอ่าน/พูด/เขียนตามโจทย์ ใช้ feedback เพื่อเลือกทบทวน ไม่ใช้จำนวน block ที่อ่านเป็นหลักฐานว่าคุณใช้ภาษาได้แล้ว","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('aa5ba907-a41c-5556-a865-1ea1a5c02816'::uuid,'14e1dcd0-a57a-5dd7-a9c3-81fadad11542'::uuid,'multiple_choice',1,'{"question":"Last Sunday, Sara … a cake.","choices":[{"id":"choice_1","text":"made"},{"id":"choice_2","text":"make"},{"id":"choice_3","text":"has made ในอดีตจบที่ระบุ"}],"correctChoiceId":"choice_1","explanation":"Past Simple กับ Last Sunday: M20"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0d1ae59e-3d3b-59da-aea9-f344b5887ad2'::uuid,'14e1dcd0-a57a-5dd7-a9c3-81fadad11542'::uuid,'multiple_choice',1,'{"question":"He didn’t … the train.","choices":[{"id":"choice_1","text":"take"},{"id":"choice_2","text":"took"},{"id":"choice_3","text":"taken"}],"correctChoiceId":"choice_1","explanation":"didn’t+base: M20"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d2bdb4a6-8e32-599e-aca5-6248b092967f'::uuid,'14e1dcd0-a57a-5dd7-a9c3-81fadad11542'::uuid,'multiple_choice',1,'{"question":"I … when the phone rang.","choices":[{"id":"choice_1","text":"was sleeping"},{"id":"choice_2","text":"was slept"},{"id":"choice_3","text":"sleeping"}],"correctChoiceId":"choice_1","explanation":"ฉากหลัง past continuous: M21"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('495f7a5f-a856-586b-a9ad-6ff18588469e'::uuid,'14e1dcd0-a57a-5dd7-a9c3-81fadad11542'::uuid,'multiple_choice',1,'{"question":"This bag is … than mine.","choices":[{"id":"choice_1","text":"more expensive"},{"id":"choice_2","text":"most expensive"},{"id":"choice_3","text":"expensiver ในรูปที่ฝึก"}],"correctChoiceId":"choice_1","explanation":"คำยาว more…than: M23"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('06960a71-2d28-5e5b-a34e-7cf532f43773'::uuid,'14e1dcd0-a57a-5dd7-a9c3-81fadad11542'::uuid,'multiple_choice',1,'{"question":"We … park here. The sign says NO PARKING.","choices":[{"id":"choice_1","text":"mustn’t"},{"id":"choice_2","text":"don’t have to"},{"id":"choice_3","text":"needn’t"}],"correctChoiceId":"choice_1","explanation":"prohibition: M24"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,6) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d86c9b1c-fc95-5700-a6fa-4fe8ff00231d'::uuid,'14e1dcd0-a57a-5dd7-a9c3-81fadad11542'::uuid,'multiple_choice',1,'{"question":"I have lived here … three years.","choices":[{"id":"choice_1","text":"for"},{"id":"choice_2","text":"since"},{"id":"choice_3","text":"at"}],"correctChoiceId":"choice_1","explanation":"for+duration: M25"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,7) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('981d7bba-d508-5be6-ac97-c0b200e547ca'::uuid,'14e1dcd0-a57a-5dd7-a9c3-81fadad11542'::uuid,'reading',1,'{"title":"ผลงานปิดคอร์ส","body":"อ่านข้อมูลนี้: Mai visited a friend last Saturday. They were cooking when Ben called. Mai has known her friend for five years. Tomorrow she is meeting Ben at six. สรุปข้อมูลโดยไม่เติมเอง แล้วเขียนเรื่องของคุณ 80–100 คำ มีอดีต ประสบการณ์ แผนและเหตุผล พร้อมถามรายละเอียดเพื่อนสามข้อ\n\n### ตัวอย่างผลงาน\n\n**สรุปข้อมูลที่อ่าน:** Mai visited her friend last Saturday. They were cooking when Ben called. She has known her friend for five years. She is meeting Ben at six tomorrow.\n\n**เรื่องของฉัน (87 คำ):** Last Saturday, I visited my sister at her home. We were preparing lunch when our cousin called. He wanted to join us, so we cooked some more rice. I have helped my sister in the kitchen many times, but I have never made her favourite soup by myself. Tomorrow, I am going to visit her again because I want to learn the recipe. We are meeting at eleven. I will buy the vegetables before I go, and I will write down the steps while she explains them.\n\n**คำถามกลับ:**\n1. Who did you visit last weekend?\n2. What were you doing when your cousin called?\n3. What are you going to do tomorrow?\n\n### เกณฑ์ตรวจ\n\n- สรุปข้อเท็จจริงครบไม่เปลี่ยนผู้ทำ เวลา ระยะ\n- V1/V2/V3 ถูกตามโครงสร้าง\n- เลือก tense ตามความหมาย ไม่ตามคำใบ้ล้วน\n- คำแนะนำ ห้ามและไม่จำเป็นแยกกัน\n- เชื่อมเหตุผล จุดประสงค์และเวลาให้คนอ่านตามได้\n\nให้ตนเองหรือครูตรวจงาน ระบบตรวจอัตโนมัติเฉพาะข้อเลือกตอบ แล้วทบทวนจุดที่ยังไม่มั่นใจเป็นระยะ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,8) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f2b3785f-2ee0-5cb6-a99c-1c3dc478c526'::uuid,'d62dd42d-93c1-5600-a9c0-baa01ad32946'::uuid,'reading',1,'{"title":"ส่วนเงื่อนไขกับส่วนผล","body":"## ส่วนเงื่อนไขกับส่วนผล\n\nประโยคเงื่อนไขมี if-clause บอกเงื่อนไขและ main clause บอกผล ทั้งสองส่วนมีประธานกับกริยา สลับตำแหน่งได้: If it rains, I’ll stay home. / I’ll stay home if it rains. โดยทั่วไป if-clause ต้นใช้ comma แบ่งส่วน ส่วนอยู่ท้ายมักไม่ต้อง comma เงื่อนไขไม่ยืนยันว่าต้องเกิดแน่นอน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| If it rains, I’ll stay home. | เงื่อนไขต้น |\n| I’ll stay home if it rains. | เงื่อนไขท้าย |\n\n### จุดที่มักสับสน\n\nIf it rains. เพียงอย่างเดียวไม่เป็นประโยคเงื่อนไขเต็มในงานเขียนนี้ ต้องมีผล\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [British Council — Verbs in time clauses and if clauses, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/verbs-time-clauses-if-clauses?page=18)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('14a94365-a19e-55e0-a6a2-5cdc9116923d'::uuid,'d62dd42d-93c1-5600-a9c0-baa01ad32946'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/56c5e4c14e55fc48-lesson-28-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"If it rains, I’ll stay home.. I’ll stay home if it rains."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b27e3012-721e-556e-a3ae-3124fe3bb7e9'::uuid,'d62dd42d-93c1-5600-a9c0-baa01ad32946'::uuid,'multiple_choice',1,'{"question":"ส่วน if ใน If I have time, I’ll call หมายถึงอะไร?","choices":[{"id":"choice_1","text":"เงื่อนไข"},{"id":"choice_2","text":"ผล"},{"id":"choice_3","text":"คำสั่ง"}],"correctChoiceId":"choice_1","explanation":"มีเวลาก่อนจึงโทร"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('623d747d-0071-56cd-add1-4750d522a6d3'::uuid,'d62dd42d-93c1-5600-a9c0-baa01ad32946'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคเต็มตามรูปบทนี้","choices":[{"id":"choice_1","text":"If it rains, we’ll stay home."},{"id":"choice_2","text":"If it rains. เท่านั้น"},{"id":"choice_3","text":"If rains, we home."}],"correctChoiceId":"choice_1","explanation":"สองส่วนมี subject/verb และเงื่อนไขต้นมี comma"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('54e6843a-ce6a-552b-aa34-ac187a24fa1b'::uuid,'d62dd42d-93c1-5600-a9c0-baa01ad32946'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนเงื่อนไขง่ายสองข้อแล้วสลับตำแหน่งหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nIf I have time, I’ll read. I’ll read if I have time. If it rains, we’ll stay home.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ส่วนเงื่อนไขกับส่วนผล** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('57300504-2637-55f4-a2a5-9fe213403ba1'::uuid,'29fe70d3-1107-52a3-a005-d924b76a0d5b'::uuid,'reading',1,'{"title":"Zero Conditional","body":"## Zero Conditional\n\nZero Conditional ใช้ if + present, present สำหรับกฎ ข้อเท็จจริงหรือผลประจำ เช่น If I drink coffee at night, I don’t sleep well. ไม่ได้ทำนายเหตุการณ์หนึ่งครั้งเท่านั้น ประธานแต่ละส่วนกำหนดกริยาเอง และ when ใช้แทนได้บางบริบทที่หมายถึงทุกครั้ง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| If I’m tired, I go to bed early. | ผลประจำ |\n| If you press this button, the light comes on. | กฎอุปกรณ์ |\n\n### จุดที่มักสับสน\n\nอย่าเติม will ทุกเงื่อนไขเพราะคิดว่า if เป็นอนาคตเสมอ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [British Council — Verbs in time clauses and if clauses, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/verbs-time-clauses-if-clauses?page=18)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0ddd3aff-5450-5b1c-a362-ac7bec595972'::uuid,'29fe70d3-1107-52a3-a005-d924b76a0d5b'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/12b417bfac432eb0-lesson-28-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"If I’m tired, I go to bed early.. If you press this button, the light comes on."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('585f8704-51f9-5bce-adf3-469e3ad8865b'::uuid,'29fe70d3-1107-52a3-a005-d924b76a0d5b'::uuid,'multiple_choice',1,'{"question":"กฎประจำของอุปกรณ์ เลือกรูปใด?","choices":[{"id":"choice_1","text":"If you press this button, the door opens."},{"id":"choice_2","text":"If you pressing this button, door open."},{"id":"choice_3","text":"If you presses this button, it opening."}],"correctChoiceId":"choice_1","explanation":"present ทั้งสองส่วนและ door ใช้ opens"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3cbaa467-9df5-5061-a004-be382200076c'::uuid,'29fe70d3-1107-52a3-a005-d924b76a0d5b'::uuid,'multiple_choice',1,'{"question":"Zero Conditional ในบทนี้เน้นอะไร?","choices":[{"id":"choice_1","text":"ผลหรือกฎประจำ"},{"id":"choice_2","text":"อดีตที่ผิดความจริง"},{"id":"choice_3","text":"คำถามเจ้าของ"}],"correctChoiceId":"choice_1","explanation":"เงื่อนไขทั่วไปที่มีผลแบบเดิม"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a3d7d5fc-25f7-540d-a25d-418b543ce642'::uuid,'29fe70d3-1107-52a3-a005-d924b76a0d5b'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนกฎหรือพฤติกรรมประจำสามข้อด้วย if\n\n### ตัวอย่างคำตอบ\n\nIf I am hungry, I eat. If I drink coffee at night, I don’t sleep well. If it is hot, I open the window.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Zero Conditional** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2f017454-2bb6-5bf5-a4c9-2f5f7b73fd1d'::uuid,'9d3bda94-8371-5c59-a6b7-9f1044ca480c'::uuid,'reading',1,'{"title":"First Conditional","body":"## First Conditional\n\nFirst Conditional ใช้ if + present กับผลอนาคตที่เป็นไปได้ เช่น If it rains tomorrow, I’ll stay home. ผลใช้ will/can หรือ imperative ได้ตามความหมาย: If you’re tired, take a break. ไม่เติม will ใน if-clause ทั่วไปที่ฝึก แต่ไม่ห้ามทุกความหมายขั้นสูงของ will ซึ่งอยู่นอกคอร์สนี้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| If I finish early, I’ll call you. | ผลอนาคต |\n| If you have time, you can help me. | ผลเป็นสิทธิ/ความสามารถ |\n| If you’re cold, close the window. | ผลเป็นคำสั่ง |\n\n### จุดที่มักสับสน\n\nIf I will finish early… ไม่ใช่รูปทั่วไปในบทนี้\n\n\n\n### ดูภาพแล้วลองใช้\n\n![เงื่อนไขทั่วไปกับอนาคตที่เป็นไปได้: If I’m tired, I rest.; If it rains, I’ll stay.; uncertain / expected](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/5d82768fd6bd0575-module-28-map.png)\n\n*if + present ในรูปที่ฝึก  •  ส่วนผลใช้ will/can/คำสั่งตามความหมาย*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n![ภาพสามช่อง Mai เดินในสวน จากนั้นฝนตก Ben ใช้ร่มช่วยและทั้งคู่ถึงร้านกาแฟ](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4253d113ce35a709-rain-story.png)\n\n*Mai was walking when it began to rain. Ben opened his umbrella. Then they reached a cafe.*\n\nใช้ภาพเป็นเรื่องใหม่สำหรับฝึก ไม่เปลี่ยนข้อเท็จจริงของตัวอย่างเดิม เล่าลำดับที่เห็น หรือเสนอแผนเมื่อมีฝนตามหัวข้อบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [British Council — Verbs in time clauses and if clauses, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/verbs-time-clauses-if-clauses?page=18)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1ce85912-aac9-5e67-a9d0-abcee2420ccf'::uuid,'9d3bda94-8371-5c59-a6b7-9f1044ca480c'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/129f526d16cc6600-lesson-28-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"If I finish early, I’ll call you.. If you have time, you can help me.. If you’re cold, close the window."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2fd8c1e1-d884-5812-a581-e581d85207b6'::uuid,'9d3bda94-8371-5c59-a6b7-9f1044ca480c'::uuid,'multiple_choice',1,'{"question":"If she … early, we’ll have lunch.","choices":[{"id":"choice_1","text":"arrives"},{"id":"choice_2","text":"will arrive ในเงื่อนไขรูปทั่วไป"},{"id":"choice_3","text":"arriving"}],"correctChoiceId":"choice_1","explanation":"if-clause ใช้ present และ she ใช้ arrives"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5fd170d3-1b52-5b4a-ae6c-f7b512f59677'::uuid,'9d3bda94-8371-5c59-a6b7-9f1044ca480c'::uuid,'multiple_choice',1,'{"question":"ผลใน First Conditional ต้องเป็น will เท่านั้นหรือไม่?","choices":[{"id":"choice_1","text":"ไม่ ใช้ can หรือ imperative ตามความหมายได้"},{"id":"choice_2","text":"ใช่ทุกครั้ง"},{"id":"choice_3","text":"ต้องเป็น past เท่านั้น"}],"correctChoiceId":"choice_1","explanation":"ผลมีหลายรูปตามหน้าที่ที่ต้องการสื่อ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('098e2f13-5906-5653-af8a-a426ee074696'::uuid,'9d3bda94-8371-5c59-a6b7-9f1044ca480c'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nวางแผนสามเงื่อนไขด้วยผล will/can/imperative อย่างละหนึ่ง\n\n### ตัวอย่างคำตอบ\n\nIf it rains, I’ll stay home. If you finish early, you can leave. If you feel tired, take a break.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **First Conditional** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b59e7bfd-0573-5ceb-adfe-4329143f1da4'::uuid,'75bf8f49-60e5-5a4a-a13d-801ef326dee9'::uuid,'reading',1,'{"title":"if เทียบ when","body":"## if เทียบ when\n\nif ชี้เงื่อนไขที่ยังไม่แน่ว่าจะเกิด ส่วน when ชี้เวลาเหตุการณ์ที่ผู้พูดคาดว่าจะเกิด เช่น If Mai comes… เทียบ When Mai arrives… แต่ทั้งสองใช้กับผลทั่วไปได้บางบริบท อ่านความมั่นใจและความสัมพันธ์จากข้อความ ไม่คิดว่า when รับรองอนาคตแน่นอนในโลกจริง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| If I win, I’ll buy a bike. | ยังไม่แน่ชนะ |\n| When I get home, I’ll call. | คาดว่าจะถึงบ้าน |\n| If the shop is open, we can go in. | เช็กเงื่อนไข |\n\n### จุดที่มักสับสน\n\nwhen กับ if ไม่ใช่คำเดียวกันที่เปลี่ยนได้ทุกบริบท\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf) · [British Council — Verbs in time clauses and if clauses, beginner section](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/verbs-time-clauses-if-clauses?page=18)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d0ebeb13-0362-54b8-a2a5-d1d69c4608ed'::uuid,'75bf8f49-60e5-5a4a-a13d-801ef326dee9'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/e167026bc40a1e30-lesson-28-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"If I win, I’ll buy a bike.. When I get home, I’ll call.. If the shop is open, we can go in."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('906379c6-b185-57ad-a310-ddb783f484a4'::uuid,'75bf8f49-60e5-5a4a-a13d-801ef326dee9'::uuid,'multiple_choice',1,'{"question":"ไม่แน่ว่าจะชนะการแข่งขัน ใช้คำใดตามความหมายที่ต้องการ?","choices":[{"id":"choice_1","text":"If I win, I’ll celebrate."},{"id":"choice_2","text":"When I win, I’ll celebrate. เพื่อสื่อไม่แน่เท่ากันเสมอ"},{"id":"choice_3","text":"Where I win…"}],"correctChoiceId":"choice_1","explanation":"if สื่อเงื่อนไขยังไม่แน่"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d9b2db06-36aa-581b-a1ed-a02616157a66'::uuid,'75bf8f49-60e5-5a4a-a13d-801ef326dee9'::uuid,'multiple_choice',1,'{"question":"When I arrive, I’ll call ส่วนเวลาควรเป็นรูปใด?","choices":[{"id":"choice_1","text":"present arrive"},{"id":"choice_2","text":"will arrive ทุกครั้ง"},{"id":"choice_3","text":"arriving โดยไม่มี be"}],"correctChoiceId":"choice_1","explanation":"time clause อนาคตใช้ present ตามรูปที่ฝึก"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c0055a89-77a2-506b-afbc-02a89b1800e0'::uuid,'75bf8f49-60e5-5a4a-a13d-801ef326dee9'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนแผนที่คาดว่าจะเกิดหนึ่งข้อกับเงื่อนไขไม่แน่สองข้อ พร้อมอธิบายเลือก when/if\n\n### ตัวอย่างคำตอบ\n\nWhen I finish work, I’ll go home. If it rains, I’ll take a taxi. If Mai is free, we’ll have dinner.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **if เทียบ when** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4ba05bcc-a8a5-5c32-ac22-8df5d1c48825'::uuid,'28729d73-aed1-5a56-ab99-04e418c32d29'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **บอกเงื่อนไขที่จริงทั่วไปและเงื่อนไขอนาคตที่เป็นไปได้**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![เงื่อนไขทั่วไปกับอนาคตที่เป็นไปได้: If I’m tired, I rest.; If it rains, I’ll stay.; uncertain / expected](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/5d82768fd6bd0575-module-28-map.png)\n\n*if + present ในรูปที่ฝึก  •  ส่วนผลใช้ will/can/คำสั่งตามความหมาย*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b0f96bcc-00c2-51c9-a0e5-9340f9b3dde0'::uuid,'28729d73-aed1-5a56-ab99-04e418c32d29'::uuid,'multiple_choice',1,'{"question":"If Ben … early, we’ll eat together.","choices":[{"id":"choice_1","text":"comes"},{"id":"choice_2","text":"will come ในรูปเงื่อนไขนี้"},{"id":"choice_3","text":"coming"}],"correctChoiceId":"choice_1","explanation":"present ใน if-clause ย้อน 28.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ac23c9db-98d4-5750-a452-629a0000a06f'::uuid,'28729d73-aed1-5a56-ab99-04e418c32d29'::uuid,'multiple_choice',1,'{"question":"If I am tired, I go to bed early สื่ออะไร?","choices":[{"id":"choice_1","text":"ผลประจำ"},{"id":"choice_2","text":"อดีตครั้งเดียว"},{"id":"choice_3","text":"คำถามทางอ้อม"}],"correctChoiceId":"choice_1","explanation":"zero conditional ย้อน 28.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4c05e423-dfa9-5b28-a68d-fb906d627e81'::uuid,'28729d73-aed1-5a56-ab99-04e418c32d29'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคเงื่อนไขเต็ม","choices":[{"id":"choice_1","text":"If it rains, we’ll stay home."},{"id":"choice_2","text":"If rains home."},{"id":"choice_3","text":"If it rains. เท่านั้น"}],"correctChoiceId":"choice_1","explanation":"สอง clauses ครบ ย้อน 28.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('455290f8-54df-5b0c-a0fc-1013ad4cf046'::uuid,'28729d73-aed1-5a56-ab99-04e418c32d29'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nเขียนกฎประจำสองข้อ แผนมีเงื่อนไขสองข้อและนัดคาดว่าจะเกิดหนึ่งข้อ\n\n### ตัวอย่างผลงาน\n\nIf I’m hungry, I eat. If it’s hot, I open the window. If it rains tomorrow, I’ll stay home. If Ben is free, we can meet. When I arrive, I’ll call.\n\n### ตรวจผลงาน\n\n- แยกผลประจำกับอนาคตที่เป็นไปได้\n- if/time clauses ใช้ present ตามรูปที่ฝึก\n- if/when ตรงความหมายและ clauses ครบ\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4faf6f64-1d62-5ae5-a283-505b6771d89e'::uuid,'b1f3424b-e43b-5e32-a726-1b279b9a7c1f'::uuid,'reading',1,'{"title":"who/which/that","body":"## who/which/that\n\ndefining relative clause ขยายคำนามเพื่อระบุว่าคนหรือสิ่งไหน who ใช้กับคน which กับสิ่งของ/สัตว์ตามบริบท และ that ใช้แทนได้ใน defining clauses ที่ฝึก เช่น the person who works here/the book that I read คำนามหลักมาก่อนแล้วส่วนขยายตาม ไม่ใช้ comma แยกในรูปที่จำเป็นระบุ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The woman who teaches English is Mai. | ระบุผู้หญิงคนไหน |\n| The book which is on the desk is mine. | ระบุหนังสือ |\n| The bag that I bought is blue. | ระบุจากการซื้อ |\n\n### จุดที่มักสับสน\n\nnon-defining clauses และ whom ขั้นลึกอยู่นอกขอบเขตนี้ ไม่เอากฎ that ไปใช้ทุก clause\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Relative pronouns and relative clauses](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/relative-pronouns-relative-clauses)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('954f1e10-ce9a-5b93-a3f9-1ed25c235b0d'::uuid,'b1f3424b-e43b-5e32-a726-1b279b9a7c1f'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/741dd5d1cd90133f-lesson-29-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The woman who teaches English is Mai.. The book which is on the desk is mine.. The bag that I bought is blue."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('86a55ad5-4a7c-54c6-af17-a64b2f31dcac'::uuid,'b1f3424b-e43b-5e32-a726-1b279b9a7c1f'::uuid,'multiple_choice',1,'{"question":"ขยายคำนามคน เลือกคำที่บทนี้ใช้โดยตรง","choices":[{"id":"choice_1","text":"who"},{"id":"choice_2","text":"where"},{"id":"choice_3","text":"when"}],"correctChoiceId":"choice_1","explanation":"who สำหรับบุคคล"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('90654fc5-1525-5c88-a035-e1ddebf1d3ea'::uuid,'b1f3424b-e43b-5e32-a726-1b279b9a7c1f'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคขยายหนังสือที่ถูก","choices":[{"id":"choice_1","text":"The book that I bought is new."},{"id":"choice_2","text":"The book who I bought is new."},{"id":"choice_3","text":"The book that is new I bought it."}],"correctChoiceId":"choice_1","explanation":"that ขยาย book และลำดับ clause ชัด"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5ecfa699-a7b5-5f37-aa99-4c6b9ec0a81e'::uuid,'b1f3424b-e43b-5e32-a726-1b279b9a7c1f'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนคำนามคนหนึ่งกับสิ่งของหนึ่งที่มีส่วนขยาย\n\n### ตัวอย่างคำตอบ\n\nThe person who helps me is Ben. The book that I like is on the desk.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **who/which/that** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8768ee7e-ffd0-5c77-af40-c9474744db06'::uuid,'9c339e06-8e99-5975-a261-d560892dcbb3'::uuid,'reading',1,'{"title":"เมื่อคำเชื่อมเป็นประธาน","body":"## เมื่อคำเชื่อมเป็นประธาน\n\nถ้า who/which/that ทำหน้าที่ประธานของ relative clause ไม่ใส่ he/she/it ซ้ำ เช่น the man who works here ไม่ใช่ who he works here เลือก verb ตาม noun ที่ขยาย: the person who works / the people who work ส่วน main clause ยังมีกริยาของตัวเอง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The person who lives here is Ben. | who เป็น subject ของ lives |\n| The people who live here are friendly. | plural ใช้ live |\n\n### จุดที่มักสับสน\n\nไม่ละ relative pronoun แบบ subject ในรูป defining ที่ฝึก และไม่ซ้ำ subject\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Relative pronouns and relative clauses](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/relative-pronouns-relative-clauses)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9255bf38-119f-5526-a7db-4877b679cfcb'::uuid,'9c339e06-8e99-5975-a261-d560892dcbb3'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/bac2ddad3c039380-lesson-29-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The person who lives here is Ben.. The people who live here are friendly."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('abf8db4c-04ba-56b0-a91d-8576017d277a'::uuid,'9c339e06-8e99-5975-a261-d560892dcbb3'::uuid,'multiple_choice',1,'{"question":"เลือกส่วนขยายถูก","choices":[{"id":"choice_1","text":"the woman who teaches here"},{"id":"choice_2","text":"the woman who she teaches here"},{"id":"choice_3","text":"the woman teaches here ใน relative subject รูปนี้"}],"correctChoiceId":"choice_1","explanation":"who เป็น subject แล้วไม่เติม she อีก"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('49dcab99-562c-5a95-a2fb-be2a466fcb82'::uuid,'9c339e06-8e99-5975-a261-d560892dcbb3'::uuid,'multiple_choice',1,'{"question":"The students who … here are kind.","choices":[{"id":"choice_1","text":"study"},{"id":"choice_2","text":"studies"},{"id":"choice_3","text":"is study"}],"correctChoiceId":"choice_1","explanation":"students plural กำหนด study"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c1c663aa-0975-5b1b-a670-cea76997bd9e'::uuid,'9c339e06-8e99-5975-a261-d560892dcbb3'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nรวม She works here. She is Mai. แล้วทำอีกตัวอย่างกับคนหลายคน\n\n### ตัวอย่างคำตอบ\n\nThe woman who works here is Mai. The people who help me are my friends.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เมื่อคำเชื่อมเป็นประธาน** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4db263aa-ee2e-5cac-a786-3942bacb24f9'::uuid,'bfa74328-0998-58d5-ac05-908f26338ffd'::uuid,'reading',1,'{"title":"เมื่อคำเชื่อมเป็นกรรม","body":"## เมื่อคำเชื่อมเป็นกรรม\n\nถ้า relative pronoun เป็นกรรม ใน clause ยังมี subject เช่น the book that I read คำ that เป็นสิ่งที่ read อ่าน และ I เป็นผู้ทำ ไม่เติม it ซ้ำ กรณี defining relative แบบกรรมง่ายละ that/which/who ได้ เช่น the book I read ต่างจาก relative subject ที่ละไม่ได้ในรูปเดียวกัน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The book that I read is good. | that เป็น object |\n| The book I read is good. | ละ that ได้ |\n| The person who I met is kind. | who เป็นกรรม |\n\n### จุดที่มักสับสน\n\nthe book that I read it ผิดเพราะกรรมซ้ำ\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ใช้ clause ระบุคำนาม: the person who helps me; the book I read; the cafe where we meet](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/aeee4c1a81e9f024-module-29-map.png)\n\n*ไม่ซ้ำ he/it/there ในส่วนขยาย  •  กรรมละ relative pronoun ได้บางรูป*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Relative pronouns and relative clauses](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/relative-pronouns-relative-clauses)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('22ebead1-bdf8-5d01-a530-7209b6dd3ad1'::uuid,'bfa74328-0998-58d5-ac05-908f26338ffd'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/1e35d67babe94027-lesson-29-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The book that I read is good.. The book I read is good.. The person who I met is kind."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3f5b5b81-0bb8-5169-ada9-33d4ad2d0564'::uuid,'bfa74328-0998-58d5-ac05-908f26338ffd'::uuid,'multiple_choice',1,'{"question":"เลือกส่วนขยายกรรมที่ถูก","choices":[{"id":"choice_1","text":"the bag that I bought"},{"id":"choice_2","text":"the bag that I bought it"},{"id":"choice_3","text":"the bag that bought I"}],"correctChoiceId":"choice_1","explanation":"I subject, bought verb, that object ไม่เติม it"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('eb1a1da1-1607-53af-a04b-82a1dd851488'::uuid,'bfa74328-0998-58d5-ac05-908f26338ffd'::uuid,'multiple_choice',1,'{"question":"the book I read เป็นรูปใด?","choices":[{"id":"choice_1","text":"relative กรรมที่ละ pronoun ได้"},{"id":"choice_2","text":"ไม่มี verb"},{"id":"choice_3","text":"relative subject ที่ละได้เสมอ"}],"correctChoiceId":"choice_1","explanation":"I เป็น subject อยู่แล้วและ book เป็นกรรมของ read"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('653771e7-694b-5d95-af41-3ab8ded99b84'::uuid,'bfa74328-0998-58d5-ac05-908f26338ffd'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nรวมสองประโยคเกี่ยวกับสิ่งที่ซื้อหรืออ่าน แล้วเขียนทั้งแบบมีและละ that\n\n### ตัวอย่างคำตอบ\n\nI bought a bag. The bag is blue. → The bag that I bought is blue. The bag I bought is blue.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เมื่อคำเชื่อมเป็นกรรม** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('34c560ae-2878-599c-a70d-6084b0befd1f'::uuid,'8e95cd9c-52b8-5cb7-aa6f-ba6a63d4c0dd'::uuid,'reading',1,'{"title":"อ่านและประกอบคำอธิบาย","body":"## อ่านและประกอบคำอธิบาย\n\nรวมคำอธิบายโดยเลือกคำนามหลักแล้วใส่ clause ที่ช่วยระบุคนหรือสิ่ง ใช้ where ในรูปสถานที่ที่พบบ่อย เช่น the cafe where we meet = คาเฟ่ที่พวกเราพบกัน ไม่ใส่ there ซ้ำหลัง where ตรวจว่าคำเชื่อมทำหน้าที่ใด และ main clause มี subject/verb ครบ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The cafe where we meet is small. | ระบุสถานที่ |\n| The teacher who helped me is kind. | ระบุคน |\n| The phone I use is old. | ระบุสิ่งจากการใช้ |\n\n### จุดที่มักสับสน\n\nthe cafe where we meet there ผิดเพราะตำแหน่งซ้ำ; ไม่ขยาย non-defining/whom ทุกรูปตอนนี้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Relative pronouns and relative clauses](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/relative-pronouns-relative-clauses)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a7757b37-c67a-56a6-aa2e-dc3912950671'::uuid,'8e95cd9c-52b8-5cb7-aa6f-ba6a63d4c0dd'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/661fd24f2837a7ec-lesson-29-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The cafe where we meet is small.. The teacher who helped me is kind.. The phone I use is old."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('50e738a4-a60c-528d-a8db-958a4cd1c0c2'::uuid,'8e95cd9c-52b8-5cb7-aa6f-ba6a63d4c0dd'::uuid,'multiple_choice',1,'{"question":"เลือกคำอธิบายสถานที่ถูก","choices":[{"id":"choice_1","text":"the shop where I work"},{"id":"choice_2","text":"the shop where I work there"},{"id":"choice_3","text":"the shop who I work"}],"correctChoiceId":"choice_1","explanation":"where แทนความสัมพันธ์สถานที่ ไม่เติม there ซ้ำ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d943aafa-3af5-50f8-af90-f67e18769588'::uuid,'8e95cd9c-52b8-5cb7-aa6f-ba6a63d4c0dd'::uuid,'multiple_choice',1,'{"question":"The person who helped me is Ben กริยาของ main clause คืออะไร?","choices":[{"id":"choice_1","text":"is"},{"id":"choice_2","text":"helped"},{"id":"choice_3","text":"who"}],"correctChoiceId":"choice_1","explanation":"helped อยู่ relative clause; is บอกคนนั้นเป็น Ben"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a8bd2e94-5ef9-57b7-a1da-adc802919b2b'::uuid,'8e95cd9c-52b8-5cb7-aa6f-ba6a63d4c0dd'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนคำอธิบายคน ของและสถานที่ให้เพื่อนเลือกสิ่งที่หมายถึง\n\n### ตัวอย่างคำตอบ\n\nThe person who sits near me is Mai. The cup I use is blue. The cafe where we meet is near the station.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **อ่านและประกอบคำอธิบาย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('919d98d7-b494-5ac3-a5e2-c747a1ac73b0'::uuid,'a43dd5a0-6541-52f9-aa68-2074692f7ffa'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **ระบุว่าหมายถึงคนหรือสิ่งไหนด้วยประโยคขยายสั้น ๆ**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ใช้ clause ระบุคำนาม: the person who helps me; the book I read; the cafe where we meet](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/aeee4c1a81e9f024-module-29-map.png)\n\n*ไม่ซ้ำ he/it/there ในส่วนขยาย  •  กรรมละ relative pronoun ได้บางรูป*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('86c04a36-3b42-5ad5-a53c-1ad6c2c6c37d'::uuid,'a43dd5a0-6541-52f9-aa68-2074692f7ffa'::uuid,'multiple_choice',1,'{"question":"The person … lives next door is a nurse.","choices":[{"id":"choice_1","text":"who"},{"id":"choice_2","text":"where"},{"id":"choice_3","text":"when"}],"correctChoiceId":"choice_1","explanation":"who ขยายคนเป็น subject ย้อน 29.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('153bab89-abc0-53c9-a6e1-78e38051cb8e'::uuid,'a43dd5a0-6541-52f9-aa68-2074692f7ffa'::uuid,'multiple_choice',1,'{"question":"เลือกส่วนขยายถูก","choices":[{"id":"choice_1","text":"the phone that I use"},{"id":"choice_2","text":"the phone that I use it"},{"id":"choice_3","text":"the phone who I use"}],"correctChoiceId":"choice_1","explanation":"relative object ไม่ซ้ำ it ย้อน 29.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fae6d75b-7665-5860-ab38-f7da67a62ca9'::uuid,'a43dd5a0-6541-52f9-aa68-2074692f7ffa'::uuid,'multiple_choice',1,'{"question":"เลือกสถานที่ถูก","choices":[{"id":"choice_1","text":"the room where we study"},{"id":"choice_2","text":"the room where we study there"},{"id":"choice_3","text":"the room who we study"}],"correctChoiceId":"choice_1","explanation":"where ไม่ซ้ำ there ย้อน 29.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1c7f0b1e-4d69-5da4-a61b-f826b3cff3fb'::uuid,'a43dd5a0-6541-52f9-aa68-2074692f7ffa'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nอธิบายคนสองคน สิ่งของและสถานที่โดย relative clauses ให้คู่ฝึกระบุสิ่งที่หมายถึง\n\n### ตัวอย่างผลงาน\n\nThe woman who helps me is Mai. The person who works here is Ben. The book I read is new. The cafe where we meet is near the library.\n\n### ตรวจผลงาน\n\n- who/which/that/where ตรงสิ่งที่ขยาย\n- ไม่ซ้ำ subject/object/place\n- main clause และส่วนขยายมีรูปครบ\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('93bd4d51-4ec8-5b5f-a527-7bebb2a02e3e'::uuid,'d16d575f-3e83-5db0-a104-4ed0b645d95e'::uuid,'reading',1,'{"title":"I think/know/hope/believe…","body":"## I think/know/hope/believe…\n\nthink/know/hope/believe + (that) clause ใช้บอกความคิดหรือข้อมูล เช่น I think that the plan is good. clause ที่ตามมี subject/verb ครบและ that อาจละได้ในรูปนี้ I’m sure/certain + clause บอกความมั่นใจ เลือกคำตามระดับความเชื่อ ไม่ใช้เพียง noun เมื่อเจตนาเล่าข้อความเต็ม\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I think the book is useful. | ความเห็น |\n| I hope that Ben can come. | ความหวัง |\n| I’m sure she is at home. | มั่นใจ |\n\n### จุดที่มักสับสน\n\nI think good plan ยังขาดการประกอบข้อมูลตามรูปที่ฝึก ให้ I think the plan is good.\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Reporting verbs with that, wh- and if clauses](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/reporting-verbs-wh-if-clauses) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ab1aea7d-4763-516f-a183-5f322cecb78f'::uuid,'d16d575f-3e83-5db0-a104-4ed0b645d95e'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/58a16140df769672-lesson-30-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I think the book is useful.. I hope that Ben can come.. I’m sure she is at home."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2ab93b52-114a-5980-a092-6a648fcf11e9'::uuid,'d16d575f-3e83-5db0-a104-4ed0b645d95e'::uuid,'multiple_choice',1,'{"question":"เลือก that-clause ที่ครบ","choices":[{"id":"choice_1","text":"I think that she is ready."},{"id":"choice_2","text":"I think that ready."},{"id":"choice_3","text":"I think that is she ready."}],"correctChoiceId":"choice_1","explanation":"ส่วนย่อยเรียง she + is + ready"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('22ec41c3-2360-5849-a236-cae7b5a694bd'::uuid,'d16d575f-3e83-5db0-a104-4ed0b645d95e'::uuid,'multiple_choice',1,'{"question":"I hope Ben can come สื่ออะไร?","choices":[{"id":"choice_1","text":"ความหวัง"},{"id":"choice_2","text":"คำห้าม"},{"id":"choice_3","text":"จำนวน"}],"correctChoiceId":"choice_1","explanation":"hope บอกสิ่งที่อยากให้เกิด"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6297b725-c2b8-5afa-aa45-841ba63e1bde'::uuid,'d16d575f-3e83-5db0-a104-4ed0b645d95e'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนความเห็น ความรู้และความหวังอย่างละหนึ่ง\n\n### ตัวอย่างคำตอบ\n\nI think English is useful. I know that Mai is a teacher. I hope Ben can join us.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **I think/know/hope/believe…** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('73d391f9-94ed-5945-a1f3-a1548340b815'::uuid,'3a00383c-4381-5d83-ad1a-c9631c9157fd'::uuid,'reading',1,'{"title":"say กับ tell","body":"## say กับ tell\n\nsay ตามด้วยข้อความ ส่วน tell ตามด้วยผู้รับและข้อความ: She says that she is busy./She tells me that she is busy. ถ้า say มีผู้รับใช้ say to me ไม่ใช้ say me ปรับ pronouns ตามผู้พูดจริง เช่น Mai says “I am tired.” → Mai says that she is tired. บทนี้เริ่มด้วย reporting verb ปัจจุบัน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Ben says that he is ready. | say + message |\n| Ben tells me that he is ready. | tell + recipient + message |\n| Ben says to me, “I’m ready.” | say to ผู้รับ |\n\n### จุดที่มักสับสน\n\nShe tells that… ขาดผู้รับในรูปนี้ และ She says me… ขาด to\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Reporting verbs with that, wh- and if clauses](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/reporting-verbs-wh-if-clauses) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('df49376d-39af-5b64-a71c-8220c91fd5ba'::uuid,'3a00383c-4381-5d83-ad1a-c9631c9157fd'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/97f0fbe08bd13abd-lesson-30-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Ben says that he is ready.. Ben tells me that he is ready.. Ben says to me, “I’m ready.”"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1ccf3ddf-b44b-54aa-a3e2-2383cb335276'::uuid,'3a00383c-4381-5d83-ad1a-c9631c9157fd'::uuid,'multiple_choice',1,'{"question":"เลือกประโยคที่ถูก","choices":[{"id":"choice_1","text":"She tells me that she is busy."},{"id":"choice_2","text":"She says me that she is busy."},{"id":"choice_3","text":"She tells that she is busy. ในรูปบทนี้"}],"correctChoiceId":"choice_1","explanation":"tell someone something"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('09bd8f6d-5bd5-5e25-a802-219c8afc6395'::uuid,'3a00383c-4381-5d83-ad1a-c9631c9157fd'::uuid,'multiple_choice',1,'{"question":"Mai says “I like tea.” เล่าต่อรูปใด?","choices":[{"id":"choice_1","text":"Mai says that she likes tea."},{"id":"choice_2","text":"Mai says that I likes tea. เมื่อ I หมายถึง Mai"},{"id":"choice_3","text":"Mai tells tea."}],"correctChoiceId":"choice_1","explanation":"เปลี่ยน I ของ Mai เป็น she และ likes ตรงประธาน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a6de2f99-5fc6-5694-a047-220e372a7bcb'::uuid,'3a00383c-4381-5d83-ad1a-c9631c9157fd'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนหนึ่งคำพูดแล้วเล่าต่อทั้ง say กับ tell พร้อมผู้รับ\n\n### ตัวอย่างคำตอบ\n\nBen says, “I am ready.” Ben says that he is ready. Ben tells me that he is ready.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **say กับ tell** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e406699c-b14c-5285-acb0-1db8d4ecd9d3'::uuid,'c14a50ad-3c07-51c5-abcd-205cdae97cd6'::uuid,'reading',1,'{"title":"คำพูดตรงกับคำพูดที่เล่าต่อ","body":"## คำพูดตรงกับคำพูดที่เล่าต่อ\n\ndirect speech ยกคำพูดตรงและใช้เครื่องหมายคำพูด ส่วน reported speech เล่าเนื้อหาด้วยมุมของผู้เล่า โดยเปลี่ยน pronouns ให้ตรง บทนี้ฝึก present reporting: She says that she is tired. รู้จัก She said… ว่ารายงานอดีตแต่ยังไม่ฝึก backshift ทุก tense หรือการเปลี่ยนเวลาทั้งระบบ เน้นรักษาความหมายและผู้พูด\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Mai says, “I work here.” | คำพูดตรง |\n| Mai says that she works here. | เล่าต่อ |\n| Ben said that he was tired. | ตัวอย่างรายงานอดีตเพื่อรู้จัก |\n\n### จุดที่มักสับสน\n\nreported speech ไม่ต้องใส่เครื่องหมายคำพูดครอบทั้งข้อความเหมือน direct; ไม่เปลี่ยน I เป็น I ผู้เล่าโดยไร้เหตุผล\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Reporting verbs with that, wh- and if clauses](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/reporting-verbs-wh-if-clauses) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('684f57b2-d332-5b02-a259-ee050a322b4d'::uuid,'c14a50ad-3c07-51c5-abcd-205cdae97cd6'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/e65cdc50b99ead79-lesson-30-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Mai says, “I work here.”. Mai says that she works here.. Ben said that he was tired."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('dc0654a9-9de5-589f-a1e5-2d8e658e1407'::uuid,'c14a50ad-3c07-51c5-abcd-205cdae97cd6'::uuid,'multiple_choice',1,'{"question":"ประโยคใดเป็น direct speech?","choices":[{"id":"choice_1","text":"Ben says, “I am hungry.”"},{"id":"choice_2","text":"Ben says that he is hungry."},{"id":"choice_3","text":"I think Ben is hungry."}],"correctChoiceId":"choice_1","explanation":"มีคำพูดตรงใน quotation marks"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3e9e13d0-a668-5ce5-a6c3-ee120192457d'::uuid,'c14a50ad-3c07-51c5-abcd-205cdae97cd6'::uuid,'multiple_choice',1,'{"question":"Ben says “We are ready.” ถ้า we หมายถึง Ben กับเพื่อน เล่าต่อได้อย่างไร?","choices":[{"id":"choice_1","text":"Ben says that they are ready."},{"id":"choice_2","text":"Ben says that he are ready."},{"id":"choice_3","text":"Ben says that I is ready."}],"correctChoiceId":"choice_1","explanation":"they อ้าง Ben กับเพื่อนตามบริบทที่ระบุ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5009f200-603f-5d12-a6bf-ad588306295f'::uuid,'c14a50ad-3c07-51c5-abcd-205cdae97cd6'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนคำพูดตรงสองข้อความแล้วเล่าต่อโดยเปลี่ยน pronouns ชัด\n\n### ตัวอย่างคำตอบ\n\nMai says, “I study English.” → Mai says that she studies English. Ben says, “My bag is blue.” → Ben says that his bag is blue.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **คำพูดตรงกับคำพูดที่เล่าต่อ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6db8bb65-f64a-5da4-a2ef-09176a2e8937'::uuid,'583d1466-4581-5544-acf3-7a382700719d'::uuid,'reading',1,'{"title":"Do you know where…? / Can you tell me…?","body":"## Do you know where…? / Can you tell me…?\n\nคำถามทางอ้อมเริ่ม Do you know…?/Can you tell me…? ส่วนย่อยใช้ลำดับบอกเล่า: where the station is ไม่ใช่ where is the station ถ้า yes/no ใช้ if เช่น Do you know if the shop is open? ตัด do/does ของคำถามตรงในส่วนย่อยและคืนกริยาตามประธาน: where she lives\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Where is the bank? → Do you know where the bank is? | ส่วนย่อย statement order |\n| Where does Mai live? → Do you know where Mai lives? | ไม่มี does ในส่วนย่อย |\n| Is it open? → Do you know if it is open? | if สำหรับ yes/no |\n\n### จุดที่มักสับสน\n\nCan you tell me where is it? ผิดในรูปนี้; ใช้ where it is\n\n\n\n### ดูภาพแล้วลองใช้\n\n![คำพูดและคำถามทางอ้อม: She says she is ready.; She tells me she is ready.; Do you know where it is?](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/6127f522fe48f266-module-30-map.png)\n\n*ส่วนย่อยใช้ subject + verb  •  ไม่ใช้ where is it ซ้อนในคำถามทางอ้อม*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Reporting verbs with that, wh- and if clauses](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/reporting-verbs-wh-if-clauses) · [British Council — Question words](https://learnenglishteens.britishcouncil.org/grammar/a1-a2-grammar/question-words)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7651dc61-75c6-52bd-a2d5-447b0141a4ba'::uuid,'583d1466-4581-5544-acf3-7a382700719d'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/a61e3556b646154a-lesson-30-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Where is the bank? ,  Do you know where the bank is?. Where does Mai live? ,  Do you know where Mai lives?. Is it open? ,  Do you know if it is open?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f70cd787-daf9-5a83-abac-6bb5e920882a'::uuid,'583d1466-4581-5544-acf3-7a382700719d'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามทางอ้อมถูก","choices":[{"id":"choice_1","text":"Do you know where Ben lives?"},{"id":"choice_2","text":"Do you know where does Ben live?"},{"id":"choice_3","text":"Do you know where lives Ben?"}],"correctChoiceId":"choice_1","explanation":"embedded clause ใช้ subject + verb"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ce887544-d44e-5df7-a154-d6b2331bee0c'::uuid,'583d1466-4581-5544-acf3-7a382700719d'::uuid,'multiple_choice',1,'{"question":"ถามทางอ้อมจาก Is the cafe open? ใช้รูปใด?","choices":[{"id":"choice_1","text":"Do you know if the cafe is open?"},{"id":"choice_2","text":"Do you know is the cafe open?"},{"id":"choice_3","text":"Do you know if is the cafe open?"}],"correctChoiceId":"choice_1","explanation":"if + statement order"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0341ef14-64b4-5bac-a4b1-bff0417e252b'::uuid,'583d1466-4581-5544-acf3-7a382700719d'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเปลี่ยน Where is the station? / What time does the shop open? / Is Mai here? เป็นคำถามสุภาพ\n\n### ตัวอย่างคำตอบ\n\nCan you tell me where the station is? Do you know what time the shop opens? Do you know if Mai is here?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Do you know where…? / Can you tell me…?** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('52759de2-c18f-5cb6-a39e-59770ca40094'::uuid,'71e7d685-6a2a-56d0-afa4-3fd0eb78ccdc'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **เล่าความคิด/คำพูดปัจจุบันและใช้ indirect question แบบพื้นฐาน**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![คำพูดและคำถามทางอ้อม: She says she is ready.; She tells me she is ready.; Do you know where it is?](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/6127f522fe48f266-module-30-map.png)\n\n*ส่วนย่อยใช้ subject + verb  •  ไม่ใช้ where is it ซ้อนในคำถามทางอ้อม*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c8f92dce-e6ec-5758-a739-31662a972243'::uuid,'71e7d685-6a2a-56d0-afa4-3fd0eb78ccdc'::uuid,'multiple_choice',1,'{"question":"Ben … me that he is ready.","choices":[{"id":"choice_1","text":"tells"},{"id":"choice_2","text":"says"},{"id":"choice_3","text":"say"}],"correctChoiceId":"choice_1","explanation":"tell someone something ย้อน 30.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9dd8666c-c5b2-5a5e-a3e6-4ffe0c1d9c35'::uuid,'71e7d685-6a2a-56d0-afa4-3fd0eb78ccdc'::uuid,'multiple_choice',1,'{"question":"ถามทางอ้อมถูกคืออะไร?","choices":[{"id":"choice_1","text":"Can you tell me where the bank is?"},{"id":"choice_2","text":"Can you tell me where is the bank?"},{"id":"choice_3","text":"Can you tell me where the bank are?"}],"correctChoiceId":"choice_1","explanation":"statement order ส่วนย่อย ย้อน 30.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a5f7f8ba-0080-5862-a8c6-065b1f4de45c'::uuid,'71e7d685-6a2a-56d0-afa4-3fd0eb78ccdc'::uuid,'multiple_choice',1,'{"question":"Mai says “I am tired.” เล่าต่อรูปใด?","choices":[{"id":"choice_1","text":"Mai says that she is tired."},{"id":"choice_2","text":"Mai says that I are tired."},{"id":"choice_3","text":"Mai tells tired."}],"correctChoiceId":"choice_1","explanation":"pronoun เปลี่ยนตามผู้พูด ย้อน 30.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cf915001-7f27-5ef0-a2db-9a45047e11da'::uuid,'71e7d685-6a2a-56d0-afa4-3fd0eb78ccdc'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nบอกความคิดหนึ่งข้อ เล่าคำพูดคนหนึ่งด้วย say/tell และถามสุภาพสองข้อ\n\n### ตัวอย่างผลงาน\n\nI think the plan is good. Ben says that he is ready. He tells me that he can come. Do you know where Mai lives? Can you tell me if the cafe is open?\n\n### ตรวจผลงาน\n\n- clause มี subject/verb\n- say/tell มีผู้รับตามรูป\n- embedded question ไม่กลับลำดับซ้ำ\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('73023e98-e2ca-5912-a73b-359935a47937'::uuid,'def69d08-1f43-5856-ade6-e20b767790e9'::uuid,'reading',1,'{"title":"Active เทียบ Passive","body":"## Active เทียบ Passive\n\nactive เน้นผู้ทำ เช่น Mai makes this cake. passive เน้นสิ่งได้รับผล เช่น This cake is made by Mai. ใช้กับกริยาที่รับกรรมและเปลี่ยนกรรมเดิมเป็น subject ไม่จำเป็นแปลงทุกประโยค Birds fly ไม่มีกรรมจึงไม่ทำ passive แบบตรงนี้ เลือกตามว่าข้อมูลใดสำคัญและผู้ทำรู้หรือไม่\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| People clean the room. → The room is cleaned. | เปลี่ยนจุดเน้น |\n| Mai made the cake. → The cake was made by Mai. | เน้น cake |\n\n### จุดที่มักสับสน\n\npassive ไม่ได้แปลว่าประธานไม่ทำอะไรทุกกรณี ต้องดูโครง be+V3 และความสัมพันธ์\n\n\n\n### ดูภาพแล้วลองใช้\n\n![Active และ Passive: Mai makes the cake.; The cake is made here.; The cake was made by Mai.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/1454fd37b16498dd-module-31-map.png)\n\n*be + V3  •  by ระบุผู้ทำเมื่อมีประโยชน์  •  made of ระบุวัสดุ*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Active and passive voice](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/active-passive-voice)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6f8c2bef-903b-5a71-ac6c-a95ce49028d4'::uuid,'def69d08-1f43-5856-ade6-e20b767790e9'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/9207caed5f60b023-lesson-31-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"People clean the room. ,  The room is cleaned.. Mai made the cake. ,  The cake was made by Mai."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('08a1c25d-f0f8-5fed-a297-5714af73fad2'::uuid,'def69d08-1f43-5856-ade6-e20b767790e9'::uuid,'multiple_choice',1,'{"question":"ประโยคใดเหมาะเปลี่ยนเป็น passive จากกรรม?","choices":[{"id":"choice_1","text":"Mai writes a letter."},{"id":"choice_2","text":"Birds fly."},{"id":"choice_3","text":"Ben sleeps."}],"correctChoiceId":"choice_1","explanation":"writes รับกรรม a letter"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bb9f13e6-7060-5873-aa58-1b002b4ddca0'::uuid,'def69d08-1f43-5856-ade6-e20b767790e9'::uuid,'multiple_choice',1,'{"question":"ใน The window was broken สิ่งที่เน้นคืออะไร?","choices":[{"id":"choice_1","text":"window ที่ได้รับผล"},{"id":"choice_2","text":"คนทำที่ระบุแน่นอน"},{"id":"choice_3","text":"ความถี่"}],"correctChoiceId":"choice_1","explanation":"subject passive คือสิ่งที่ถูกกระทำ; ผู้ทำไม่ได้ระบุ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bbf5ce17-f664-56fa-a67a-77c0f8cdc690'::uuid,'def69d08-1f43-5856-ade6-e20b767790e9'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียน active สองข้อแล้วเลือกหนึ่งข้อเปลี่ยนเป็น passive พร้อมบอกเหตุผลจุดเน้น\n\n### ตัวอย่างคำตอบ\n\nPeople clean this room. This room is cleaned every day. I want to describe the room, so I focus on it.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Active เทียบ Passive** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e139bf42-8d76-53f7-a3ad-ceb25222db9d'::uuid,'5a02e9e4-9bb8-5eb3-a951-efea922a8ba5'::uuid,'reading',1,'{"title":"Present Simple Passive","body":"## Present Simple Passive\n\nPresent Simple Passive ใช้ am/is/are + V3: English is spoken here. ประธานหนึ่งใช้ is และหลายใช้ are ปฏิเสธเติม not หลัง be คำถาม Is/Are + subject + V3? ไม่ใช้ do/does ในโครง passive นี้ อ่านป้ายหรือข้อมูลว่ากิจกรรมทำกับสิ่งใดทั่วไป\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The room is cleaned every day. | is + V3 |\n| The books are sold here. | plural are |\n| Is this food made here? | คำถาม |\n\n### จุดที่มักสับสน\n\nThe books are sell ผิดเพราะต้อง sold V3; ไม่ใช้ is+V2 โดยเดารูป\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Active and passive voice](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/active-passive-voice)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('efe7c812-43cb-5c09-a5fa-682d73ac2c74'::uuid,'5a02e9e4-9bb8-5eb3-a951-efea922a8ba5'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/1e3416004ba81620-lesson-31-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The room is cleaned every day.. The books are sold here.. Is this food made here?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7b9e82cd-e612-5396-a7d5-a703dd4a8c3b'::uuid,'5a02e9e4-9bb8-5eb3-a951-efea922a8ba5'::uuid,'multiple_choice',1,'{"question":"These bags … here.","choices":[{"id":"choice_1","text":"are made"},{"id":"choice_2","text":"is made"},{"id":"choice_3","text":"are make"}],"correctChoiceId":"choice_1","explanation":"bags plural ใช้ are + V3 made"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ae538642-952c-536a-a662-a4f6125a683c'::uuid,'5a02e9e4-9bb8-5eb3-a951-efea922a8ba5'::uuid,'multiple_choice',1,'{"question":"เลือกปฏิเสธ passive ถูก","choices":[{"id":"choice_1","text":"The door isn’t locked."},{"id":"choice_2","text":"The door doesn’t locked."},{"id":"choice_3","text":"The door isn’t lock."}],"correctChoiceId":"choice_1","explanation":"be not + V3 locked"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('412a16f4-ebda-51e7-a3a8-f1d31b83be40'::uuid,'5a02e9e4-9bb8-5eb3-a951-efea922a8ba5'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบอกข้อมูลทั่วไปของร้านสมมติสองข้อพร้อมคำถามและปฏิเสธ\n\n### ตัวอย่างคำตอบ\n\nBread is made here. Books are sold here. Is coffee served here? Food isn’t sold here.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Present Simple Passive** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('286e38e7-e580-5321-a447-13af7687d535'::uuid,'8d7958d8-60d6-5ef8-a0b8-3812e564612b'::uuid,'reading',1,'{"title":"Past Simple Passive","body":"## Past Simple Passive\n\nPast Simple Passive ใช้ was/were + V3 บอกเหตุการณ์ที่เกิดกับสิ่งในอดีต: The window was broken yesterday. tense อยู่ที่ be ส่วนกริยาหลักใช้ V3 ไม่ใช่ V2: was written ไม่ใช่ was wrote ปฏิเสธ wasn’t/weren’t และคำถาม Was/Were + subject + V3?\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The letter was written yesterday. | was + written |\n| The bags were made last year. | plural were |\n| Was the door closed? | คำถาม |\n\n### จุดที่มักสับสน\n\nI was went ผิดทั้งไม่ได้มีกรรมเป็น subject และ went ไม่ใช่ V3 ของ go\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Active and passive voice](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/active-passive-voice)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7a21f4e4-dc06-5c40-ace6-1575c8597f80'::uuid,'8d7958d8-60d6-5ef8-a0b8-3812e564612b'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f58c229acd320a52-lesson-31-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The letter was written yesterday.. The bags were made last year.. Was the door closed?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3a27e4bf-6963-579c-a1df-64820ff6d288'::uuid,'8d7958d8-60d6-5ef8-a0b8-3812e564612b'::uuid,'multiple_choice',1,'{"question":"The book … in 2020.","choices":[{"id":"choice_1","text":"was written"},{"id":"choice_2","text":"was wrote"},{"id":"choice_3","text":"were written"}],"correctChoiceId":"choice_1","explanation":"book singular และ write V3 written"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('92a27890-35d8-5ff3-a0c5-837aa803bf1d'::uuid,'8d7958d8-60d6-5ef8-a0b8-3812e564612b'::uuid,'multiple_choice',1,'{"question":"เลือกคำถามอดีต passive ถูก","choices":[{"id":"choice_1","text":"Were the windows cleaned?"},{"id":"choice_2","text":"Did the windows cleaned?"},{"id":"choice_3","text":"Were the windows clean ในความหมายถูกทำความสะอาด"}],"correctChoiceId":"choice_1","explanation":"Were + plural subject + V3 cleaned"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('193db8cd-a762-57f3-a952-2e7fad9af9ce'::uuid,'8d7958d8-60d6-5ef8-a0b8-3812e564612b'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเล่าของสองชิ้นที่ถูกทำหรือส่งในอดีต แล้วถามหนึ่งข้อ\n\n### ตัวอย่างคำตอบ\n\nThe cake was made yesterday. The books were sent last week. Was the letter written today?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **Past Simple Passive** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ddb7ab2a-c317-5e6a-a62e-669ef79f26e8'::uuid,'542697b4-ae26-5f6a-a13e-d3c2ee5c75c7'::uuid,'reading',1,'{"title":"by และการไม่ระบุผู้ทำ","body":"## by และการไม่ระบุผู้ทำ\n\nby + ผู้ทำเพิ่มข้อมูลเมื่อจำเป็น เช่น The cake was made by Mai. ถ้าไม่รู้หรือผู้ทำไม่สำคัญละ by ได้ เช่น My phone was stolen. made of บอกวัสดุที่มองลักษณะเดิมได้ used for + noun/ing บอกการใช้ ระวัง of ไม่ใช่ by ที่ถามผู้ทำ คอร์สนี้ใช้ passive simple present/past ก่อน ไม่ขยายทุก tense\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The table is made of wood. | วัสดุ |\n| The table was made by Ben. | ผู้ทำ |\n| This tool is used for cutting paper. | การใช้ |\n\n### จุดที่มักสับสน\n\nไม่เติม by someone ทุกประโยคเพราะไม่เพิ่มข้อมูล และไม่สลับ made of wood เป็น made by wood ในความหมายวัสดุ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council — Active and passive voice](https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/active-passive-voice)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c5995851-3b22-5848-a373-566e75a8aaae'::uuid,'542697b4-ae26-5f6a-a13e-d3c2ee5c75c7'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/b7c8b8d06fc0c11c-lesson-31-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The table is made of wood.. The table was made by Ben.. This tool is used for cutting paper."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3517ee55-4e99-5d33-ae37-c40e6c6dcd80'::uuid,'542697b4-ae26-5f6a-a13e-d3c2ee5c75c7'::uuid,'multiple_choice',1,'{"question":"บอกวัสดุไม้ใช้วลีใด?","choices":[{"id":"choice_1","text":"made of wood"},{"id":"choice_2","text":"made by wood"},{"id":"choice_3","text":"made to wood"}],"correctChoiceId":"choice_1","explanation":"of สำหรับวัสดุในกลุ่มนี้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('00f921ec-8f97-5071-a172-9ca06d513e01'::uuid,'542697b4-ae26-5f6a-a13e-d3c2ee5c75c7'::uuid,'multiple_choice',1,'{"question":"จำเป็นต้องบอก by ผู้ทำทุก passive หรือไม่?","choices":[{"id":"choice_1","text":"ไม่ ถ้าไม่รู้หรือไม่สำคัญละได้"},{"id":"choice_2","text":"จำเป็นเสมอ"},{"id":"choice_3","text":"ห้ามใช้ by"}],"correctChoiceId":"choice_1","explanation":"passive เลือกเน้นผู้รับผลได้โดยไม่ระบุผู้ทำ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('001c810c-a024-54cf-a409-acf4c36139d7'::uuid,'542697b4-ae26-5f6a-a13e-d3c2ee5c75c7'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nบรรยายของหนึ่งชิ้นโดยบอกวัสดุ ผู้ทำถ้ารู้และการใช้\n\n### ตัวอย่างคำตอบ\n\nThis table is made of wood. It was made by Ben. It is used for studying.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **by และการไม่ระบุผู้ทำ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ae66e6fa-0f79-5b04-a6ab-6214ee4e97fc'::uuid,'5562eab8-646e-5dd2-ac14-29cae2adf91e'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **อ่านและใช้ passive ปัจจุบัน/อดีตแบบง่าย โดยแยก V3 จาก V2**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![Active และ Passive: Mai makes the cake.; The cake is made here.; The cake was made by Mai.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/1454fd37b16498dd-module-31-map.png)\n\n*be + V3  •  by ระบุผู้ทำเมื่อมีประโยชน์  •  made of ระบุวัสดุ*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('aa76b073-b227-5532-ac3f-0c5ade3a9ab9'::uuid,'5562eab8-646e-5dd2-ac14-29cae2adf91e'::uuid,'multiple_choice',1,'{"question":"The chairs … every morning.","choices":[{"id":"choice_1","text":"are cleaned"},{"id":"choice_2","text":"is cleaned"},{"id":"choice_3","text":"are clean ในความหมายถูกทำความสะอาด"}],"correctChoiceId":"choice_1","explanation":"plural+are+V3 ย้อน 31.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c3b08c6f-a309-561d-ae24-9f066d6354a6'::uuid,'5562eab8-646e-5dd2-ac14-29cae2adf91e'::uuid,'multiple_choice',1,'{"question":"The letter … last Friday.","choices":[{"id":"choice_1","text":"was sent"},{"id":"choice_2","text":"was sended"},{"id":"choice_3","text":"were sent"}],"correctChoiceId":"choice_1","explanation":"singular+was+V3 sent ย้อน 31.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('726e7106-8d19-5cf1-aa37-8d10a86d0762'::uuid,'5562eab8-646e-5dd2-ac14-29cae2adf91e'::uuid,'multiple_choice',1,'{"question":"บอกผู้ทำคือ Mai ใช้คำใด?","choices":[{"id":"choice_1","text":"by Mai"},{"id":"choice_2","text":"of Mai"},{"id":"choice_3","text":"for Mai เพื่อระบุผู้ทำโดยตรง"}],"correctChoiceId":"choice_1","explanation":"by ผู้ทำใน passive ย้อน 31.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0b56290e-8a94-5b28-a263-5806b90da950'::uuid,'5562eab8-646e-5dd2-ac14-29cae2adf91e'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nบรรยายของหนึ่งชิ้นด้วยวัสดุ ผู้ทำ การใช้และเหตุการณ์อดีต พร้อมถามหนึ่งข้อ\n\n### ตัวอย่างผลงาน\n\nThis table is made of wood. It was made by Ben last year. It is used for studying. Was it made here?\n\n### ตรวจผลงาน\n\n- present/past อยู่ที่ be\n- main verb ใช้ V3\n- แยกวัสดุ ผู้ทำและจุดประสงค์\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('09592741-8858-5162-afaa-8381a73a5555'::uuid,'a8b1f244-dd5d-526f-adca-0e3507e19277'::uuid,'reading',1,'{"title":"ใช้ learner''s dictionary","body":"## ใช้ learner''s dictionary\n\nlearner’s dictionary ช่วยตรวจเสียง ชนิดคำ countability รูปกริยาและความหมายตามประโยค เปิดคำแล้วเลือกความหมายที่ตรงบริบท ดู noun [C]/[U] หรือ verb patterns และฟัง UK/US ตามแหล่ง อย่าหยุดที่คำแปลแรกโดยไม่ดูตัวอย่าง เพราะ light อาจเป็นแสง เบาหรือเปิดไฟตามหน้าที่\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| light bag | light เป็น adjective เบา |\n| turn on the light | light เป็น noun แสงหรือไฟ |\n| information [U] | นับไม่ได้ในความหมายทั่วไป |\n\n### จุดที่มักสับสน\n\nการรู้คำแปลไม่รับรองว่าวางคำได้ถูก ต้องตรวจเสียงและ pattern ด้วย\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Oxford University Press — Learner''s Word Lists](https://www.oxfordlearnersdictionaries.com/us/about/wordlists/index.html) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf) · [British Council — Adjectives and prepositions](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-prepositions)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b4c72072-a00f-5473-aa56-20583cfd6c81'::uuid,'a8b1f244-dd5d-526f-adca-0e3507e19277'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/3a23138d180ec442-lesson-32-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"light bag. turn on the light. information [U]"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2c48e3d5-2722-5873-a234-92001d20101e'::uuid,'a8b1f244-dd5d-526f-adca-0e3507e19277'::uuid,'multiple_choice',1,'{"question":"เครื่องหมาย [U] หลัง noun บอกอะไร?","choices":[{"id":"choice_1","text":"uncountable"},{"id":"choice_2","text":"อดีต"},{"id":"choice_3","text":"เสียงเน้น"}],"correctChoiceId":"choice_1","explanation":"[U] หมายถึงนามนับไม่ได้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8111d056-3448-5b19-a9de-ce9e680fce1f'::uuid,'a8b1f244-dd5d-526f-adca-0e3507e19277'::uuid,'multiple_choice',1,'{"question":"light ใน a light bag ทำหน้าที่ใด?","choices":[{"id":"choice_1","text":"adjective"},{"id":"choice_2","text":"กริยาอดีต"},{"id":"choice_3","text":"pronoun"}],"correctChoiceId":"choice_1","explanation":"ขยาย bag ว่าเบา"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('cc26c200-02bd-5e15-a25e-93808946d5e2'::uuid,'a8b1f244-dd5d-526f-adca-0e3507e19277'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเปิดพจนานุกรมของ information, teach และ light จดเสียง ชนิดคำ ตัวอย่างและรูปสำคัญ\n\n### ตัวอย่างคำตอบ\n\ninformation: noun [U], some information. teach: verb, taught/taught, teach English. light: adjective ใน a light bag.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ใช้ learner''s dictionary** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8fdb3e33-94df-5b0a-ae89-86b92c4d7f1e'::uuid,'0b7c1b89-8fa9-5d3b-abec-9ef80071b253'::uuid,'reading',1,'{"title":"word families","body":"## word families\n\nword family ช่วยเชื่อมความหมายแต่รูปและหน้าที่อาจเปลี่ยน teach→teacher เปลี่ยนกริยาเป็นคนทำ happy→happiness เป็นคำนาม unhappy เติม un- ทำให้ความหมายตรงข้าม suffix เช่น -er/-ness/-ful และ prefix un-/re- เป็นแนวทาง ต้องตรวจว่ารูปมีใช้จริง ไม่สร้างคำทุกคำด้วยสูตรเดียว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| teach / teacher | verb / noun บุคคล |\n| happy / happiness / unhappy | adjective / noun / ตรงข้าม |\n| write / rewrite | เขียน / เขียนใหม่ |\n\n### จุดที่มักสับสน\n\nteacher ไม่ใช่ verb จึงไม่เขียน I teacher English.; prefix/suffix ไม่ได้ต่อได้อิสระทุกคำ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Oxford University Press — Learner''s Word Lists](https://www.oxfordlearnersdictionaries.com/us/about/wordlists/index.html) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf) · [British Council — Adjectives and prepositions](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-prepositions)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a9980b2b-3c1c-5892-a6ae-166b97ac9803'::uuid,'0b7c1b89-8fa9-5d3b-abec-9ef80071b253'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/0f489ff31a3c13dc-lesson-32-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"teach. teacher. happy. happiness. unhappy. write. rewrite"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('95febe6e-ca46-58e4-afb1-3d35e1cb6b35'::uuid,'0b7c1b89-8fa9-5d3b-abec-9ef80071b253'::uuid,'multiple_choice',1,'{"question":"teacher เป็นอะไรตาม family นี้?","choices":[{"id":"choice_1","text":"noun ผู้สอน"},{"id":"choice_2","text":"verb สอน"},{"id":"choice_3","text":"adverb"}],"correctChoiceId":"choice_1","explanation":"-er ใน teacher สร้างชื่อบุคคล"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('aea3e630-2c15-5022-a06d-ccb6fad3ff54'::uuid,'0b7c1b89-8fa9-5d3b-abec-9ef80071b253'::uuid,'multiple_choice',1,'{"question":"unhappy สื่ออะไร?","choices":[{"id":"choice_1","text":"ไม่สุข"},{"id":"choice_2","text":"สุขมากกว่า"},{"id":"choice_3","text":"ความสุขเป็นคำนาม"}],"correctChoiceId":"choice_1","explanation":"un- ทำให้ความหมายตรงข้ามในคำนี้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('52e5a47b-d7b4-567a-aed3-965c180498e9'::uuid,'0b7c1b89-8fa9-5d3b-abec-9ef80071b253'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nทำ family สองกลุ่มและแต่งประโยคด้วยคำต่างชนิด\n\n### ตัวอย่างคำตอบ\n\nteach/teacher: I teach English. I am a teacher. happy/happiness/unhappy: She is happy. Happiness is important.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **word families** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('38e41524-8cdf-573d-a41b-7790ab1a357a'::uuid,'a2d88cc8-b7c2-58b6-a3be-0f6047a182a8'::uuid,'reading',1,'{"title":"compound nouns และ collocations","body":"## compound nouns และ collocations\n\ncompound nouns รวมคำเป็นความหมายหนึ่ง เช่น bus stop/toothpaste เขียนเว้นหรือไม่เว้นตามคำและ stress มักช่วยฟังกลุ่ม collocations คือคำที่ใช้ร่วมธรรมชาติ เช่น make a mistake/do homework/have breakfast/take a photo ไม่เลือกกริยาจากคำแปลไทยเดียว จำกลุ่มพร้อมตัวอย่าง\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| bus stop / toothpaste | คำนามประกอบ |\n| make a mistake / do homework | collocations |\n| have breakfast / take a photo | กลุ่มกริยากับคำนาม |\n\n### จุดที่มักสับสน\n\ndo a mistake และ make homework ไม่ใช่กลุ่มมาตรฐานที่ฝึก\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ศัพท์พร้อมเสียง หน้าที่และกลุ่มคำ: teach → teacher; do homework; turn it off](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/aec5dd00cd6427f4-module-32-map.png)\n\n*ตรวจความหมายในบริบท  •  บันทึกตัวอย่าง  •  ทบทวนโดยปิดคำตอบ*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Oxford University Press — Learner''s Word Lists](https://www.oxfordlearnersdictionaries.com/us/about/wordlists/index.html) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf) · [British Council — Adjectives and prepositions](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-prepositions)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('49f8b020-fd65-5bd1-a50e-62c2a5b347e3'::uuid,'a2d88cc8-b7c2-58b6-a3be-0f6047a182a8'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/cda2c01688f37dea-lesson-32-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"bus stop. toothpaste. make a mistake. do homework. have breakfast. take a photo"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3a228829-9a2d-5237-a3f6-2031c80169c1'::uuid,'a2d88cc8-b7c2-58b6-a3be-0f6047a182a8'::uuid,'multiple_choice',1,'{"question":"เลือก collocation ถูก","choices":[{"id":"choice_1","text":"make a mistake"},{"id":"choice_2","text":"do a mistake"},{"id":"choice_3","text":"have a mistake ในความหมายทำผิดนี้"}],"correctChoiceId":"choice_1","explanation":"make a mistake เป็นกลุ่มคำ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('79c66e08-f70b-5d46-a148-437c1109ed0b'::uuid,'a2d88cc8-b7c2-58b6-a3be-0f6047a182a8'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มการบ้านถูก","choices":[{"id":"choice_1","text":"do homework"},{"id":"choice_2","text":"make homework"},{"id":"choice_3","text":"take homework ในความหมายทำการบ้าน"}],"correctChoiceId":"choice_1","explanation":"do homework ใช้ทำงานการบ้าน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('97d60e92-4b5c-5c79-a4d4-38a58828bc9f'::uuid,'a2d88cc8-b7c2-58b6-a3be-0f6047a182a8'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nจดคำนามประกอบสองคำและ collocations สี่กลุ่มแล้วใช้ในเรื่องสั้น\n\n### ตัวอย่างคำตอบ\n\nI wait at the bus stop. I have breakfast, do my homework and take a photo. Sometimes I make a mistake.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **compound nouns และ collocations** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5164c664-a71e-5597-a497-5d515ea9e363'::uuid,'b223d65f-0fde-55f4-abf3-c9a742e073c9'::uuid,'reading',1,'{"title":"phrasal verbs ที่พบบ่อย","body":"## phrasal verbs ที่พบบ่อย\n\nphrasal verbs มี verb กับ particle เช่น get up/sit down/turn on/off/look after ความหมายอาจตรงการเคลื่อนหรือเป็นกลุ่มใหม่ เช่น look after คือดูแล turn off ที่แยกได้ใช้ turn off the light หรือ turn the light off แต่ถ้า object pronoun ต้องกลาง: turn it off ไม่ใช้ turn off it ส่วน look after ไม่แยกในรูปนี้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I get up at six. | ตื่นนอน |\n| Please turn it off. | pronoun อยู่กลาง |\n| She looks after her brother. | ดูแล ไม่แยก |\n\n### จุดที่มักสับสน\n\nอย่าใช้กฎแยก object กับทุก phrasal verb ต้องตรวจคำเป็นรายกลุ่ม\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Oxford University Press — Learner''s Word Lists](https://www.oxfordlearnersdictionaries.com/us/about/wordlists/index.html) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf) · [British Council — Adjectives and prepositions](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-prepositions)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('642e40a8-2d63-5d03-af81-835199236452'::uuid,'b223d65f-0fde-55f4-abf3-c9a742e073c9'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/49c75b7042091eeb-lesson-32-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I get up at six.. Please turn it off.. She looks after her brother."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('df298d31-5a2e-5112-a2ec-c84d5750d4dc'::uuid,'b223d65f-0fde-55f4-abf3-c9a742e073c9'::uuid,'multiple_choice',1,'{"question":"เลือกวลีปิดไฟเมื่อแทน light ด้วย it","choices":[{"id":"choice_1","text":"turn it off"},{"id":"choice_2","text":"turn off it"},{"id":"choice_3","text":"turn it of"}],"correctChoiceId":"choice_1","explanation":"separable phrasal verb pronoun อยู่กลาง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bffdcff0-cfa4-5039-a57c-1cb1a546cb18'::uuid,'b223d65f-0fde-55f4-abf3-c9a742e073c9'::uuid,'multiple_choice',1,'{"question":"look after หมายถึงอะไรในบทนี้?","choices":[{"id":"choice_1","text":"ดูแล"},{"id":"choice_2","text":"ดูเวลาหลังจาก"},{"id":"choice_3","text":"ปิด"}],"correctChoiceId":"choice_1","explanation":"เป็นความหมายกลุ่มคำ ไม่แปล look/after ทีละคำ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3ffd0810-e4a5-5b47-a059-c993edc9bc1b'::uuid,'b223d65f-0fde-55f4-abf3-c9a742e073c9'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียน get up, turn on/off และ look after พร้อมหนึ่งประโยคที่ใช้ it\n\n### ตัวอย่างคำตอบ\n\nI get up at seven. I turn on the light. Then I turn it off. Mai looks after her sister.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **phrasal verbs ที่พบบ่อย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('80fec02a-07bb-50b0-ab5a-6727c64f977e'::uuid,'71a57687-6156-55f5-a297-b76ea6865946'::uuid,'reading',1,'{"title":"บันทึกและทบทวนคำ","body":"## บันทึกและทบทวนคำ\n\nบันทึกศัพท์ให้มีคำ เสียง ความหมายที่เลือก กลุ่มคำและประโยคของคุณ แยกคำที่เข้าใจเมื่ออ่าน/ฟังออกจากคำที่ใช้พูด/เขียนได้เอง เลือก A1/A2 ตามความหมายและคำที่จำเป็นกับชีวิต ทบทวนแบบเว้นระยะโดยปิดคำตอบแล้วนึก ไม่อ่านบัตรเดิมอย่างเดียว เป้าหมายคือใช้ข้อมูลใหม่ได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| wait for — I wait for Mai. | จำกลุ่มพร้อมตัวอย่าง |\n| information [U] — some information | ชนิด noun พร้อมการใช้ |\n\n### จุดที่มักสับสน\n\nรายการคำระดับหนึ่งไม่บังคับให้ท่องทุกความหมายของคำ และจำนวนคำที่เห็นไม่ใช่จำนวนคำที่ใช้ได้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Oxford University Press — Learner''s Word Lists](https://www.oxfordlearnersdictionaries.com/us/about/wordlists/index.html) · [Cambridge English — A2 Key Vocabulary List, August 2025](https://www.cambridgeenglish.org/Images/506886-a2-key-2020-vocabulary-list.pdf) · [British Council — Adjectives and prepositions](https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-prepositions)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4811f572-20c9-5f1e-af9a-0715fa58b2da'::uuid,'71a57687-6156-55f5-a297-b76ea6865946'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d7051f7e0a0fb20d-lesson-32-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"wait for. I wait for Mai.. information [U]. some information"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('dc240d83-29f4-5c31-a6d7-159d29c1506d'::uuid,'71a57687-6156-55f5-a297-b76ea6865946'::uuid,'multiple_choice',1,'{"question":"บัตรแบบใดช่วยใช้คำได้มากกว่า?","choices":[{"id":"choice_1","text":"wait = รอ อย่างเดียว"},{"id":"choice_2","text":"wait for + someone; I wait for Ben."},{"id":"choice_3","text":"wait เขียนซ้ำสิบครั้งโดยไม่ใช้"}],"correctChoiceId":"choice_2","explanation":"มี pattern และประโยคที่นำไปใช้ได้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('49b7d8f8-0650-5755-a4a7-f66853a2ae3f'::uuid,'71a57687-6156-55f5-a297-b76ea6865946'::uuid,'multiple_choice',1,'{"question":"productive vocabulary หมายถึงอะไร?","choices":[{"id":"choice_1","text":"คำที่ใช้พูดหรือเขียนได้เอง"},{"id":"choice_2","text":"คำที่เห็นผ่านตาเท่านั้น"},{"id":"choice_3","text":"คำยาวทุกคำ"}],"correctChoiceId":"choice_1","explanation":"ต่างจาก receptive ที่เข้าใจเมื่อรับข้อมูล"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3ab6ccf4-7b62-5822-ac3e-3f8358f901b8'::uuid,'71a57687-6156-55f5-a297-b76ea6865946'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nทำบัตรห้าคำที่ใช้จริง ตั้งรอบทบทวนวันถัดไปและสัปดาห์ถัดไป แล้วแต่งเรื่องไม่เปิดบัตร\n\n### ตัวอย่างคำตอบ\n\nwait for: I wait for the bus. interested in: I am interested in music. a bottle of: I buy a bottle of water. แผน: ทบทวนพรุ่งนี้และอีกหนึ่งสัปดาห์\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **บันทึกและทบทวนคำ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d1d930d2-a490-53e2-a498-380d9a64d3ab'::uuid,'f0e15504-9158-5f28-a0f2-f573f0dce034'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **ใช้คำพร้อมรูป เสียง ความหมาย และกลุ่มคำที่จำเป็น**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ศัพท์พร้อมเสียง หน้าที่และกลุ่มคำ: teach → teacher; do homework; turn it off](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/aec5dd00cd6427f4-module-32-map.png)\n\n*ตรวจความหมายในบริบท  •  บันทึกตัวอย่าง  •  ทบทวนโดยปิดคำตอบ*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6d7b3767-e2b0-523e-ae7e-6c73b8105c19'::uuid,'f0e15504-9158-5f28-a0f2-f573f0dce034'::uuid,'multiple_choice',1,'{"question":"เลือกกลุ่มคำมาตรฐาน","choices":[{"id":"choice_1","text":"take a photo"},{"id":"choice_2","text":"do a photo ในความหมายถ่ายภาพ"},{"id":"choice_3","text":"make homework"}],"correctChoiceId":"choice_1","explanation":"take a photo collocation ย้อน 32.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8e949fa8-4086-5191-a75e-4551ba283462'::uuid,'f0e15504-9158-5f28-a0f2-f573f0dce034'::uuid,'multiple_choice',1,'{"question":"ใช้ pronoun กับ turn off รูปใด?","choices":[{"id":"choice_1","text":"turn it off"},{"id":"choice_2","text":"turn off it"},{"id":"choice_3","text":"turn its off"}],"correctChoiceId":"choice_1","explanation":"pronoun กลาง separable phrasal verb ย้อน 32.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b6d42210-503f-5cb9-ac2a-a94d3fe992fb'::uuid,'f0e15504-9158-5f28-a0f2-f573f0dce034'::uuid,'multiple_choice',1,'{"question":"การใช้พจนานุกรมควรดูอะไรเพิ่มจากคำแปล?","choices":[{"id":"choice_1","text":"เสียง ชนิดคำและตัวอย่าง"},{"id":"choice_2","text":"แต่จำนวนตัวอักษร"},{"id":"choice_3","text":"แต่สีของหน้า"}],"correctChoiceId":"choice_1","explanation":"ข้อมูลช่วยผลิตภาษา ย้อน 32.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('64efab59-d37d-5ae7-a0b8-0d3af2b40ec7'::uuid,'f0e15504-9158-5f28-a0f2-f573f0dce034'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nทำบัตรห้าคำพร้อมเสียง ชนิด ความหมายกลุ่มและประโยค จากนั้นปิดบัตรพูดเรื่องใหม่\n\n### ตัวอย่างผลงาน\n\nteacher: noun, teach/teacher. wait for: I wait for Mai. turn it off: Please turn it off. do homework: I do homework at night. a piece of information: I need some information.\n\n### ตรวจผลงาน\n\n- เลือกความหมายตามบริบท\n- collocations/pattern ถูก\n- ทบทวนโดยเรียกใช้ ไม่เพียงอ่านบัตร\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8364ab52-7f4c-5ac0-a08d-d735a5d11b73'::uuid,'e2899568-8871-5ace-a4ba-34af908f45a5'::uuid,'reading',1,'{"title":"ทบทวนเสียงท้ายที่มีความหมาย","body":"## ทบทวนเสียงท้ายที่มีความหมาย\n\nทบทวนเสียง s/es ตามเสียงท้ายเดิม: /s/ หลังเสียงไม่ก้อง เช่น cups; /z/ หลังก้อง เช่น bags; /ɪz/ หลังเสียงกลุ่ม s/z/sh/ch เช่น buses ส่วน ed: /t/ เช่น walked; /d/ เช่น played; /ɪd/ หลัง /t,d/ เช่น wanted การคงเสียงท้ายช่วยให้ฟังจำนวน verb agreement และอดีตได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| cups / bags / buses | สามเสียงของ s/es |\n| walked / played / wanted | สามเสียงของ ed |\n\n### จุดที่มักสับสน\n\nตัดสินจากเสียงท้ายไม่ใช่ตัวอักษรเดี่ยว และไม่เพิ่มพยางค์ให้ s/ed ทุกคำ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council TeachingEnglish — Stress](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/q-s/stress) · [British Council TeachingEnglish — Connected speech](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/connected-speech)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('00b745f9-ff2c-581d-ad7e-590d63d37d7e'::uuid,'e2899568-8871-5ace-a4ba-34af908f45a5'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/940e23952f7df292-lesson-33-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Cups. Bags. Buses. Cups. Bags. Buses. Walked. Played. Wanted. Walked. Played. Wanted."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('de5bf566-c5aa-5685-a49c-cdb2bd968d75'::uuid,'e2899568-8871-5ace-a4ba-34af908f45a5'::uuid,'multiple_choice',1,'{"question":"s ของ buses โดยทั่วไปเป็นเสียงใด?","choices":[{"id":"choice_1","text":"/ɪz/"},{"id":"choice_2","text":"/s/ อย่างเดียว"},{"id":"choice_3","text":"ไม่มีเสียง"}],"correctChoiceId":"choice_1","explanation":"bus ลงเสียง /s/ จึงเพิ่ม /ɪz/"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9a968d33-49ca-5c61-afec-553995d93fbe'::uuid,'e2899568-8871-5ace-a4ba-34af908f45a5'::uuid,'multiple_choice',1,'{"question":"ed ของ played โดยทั่วไปเป็นเสียงใด?","choices":[{"id":"choice_1","text":"/d/"},{"id":"choice_2","text":"/ɪd/"},{"id":"choice_3","text":"/t/ เท่านั้น"}],"correctChoiceId":"choice_1","explanation":"play ลงเสียงก้อง จึง /d/"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('421fe453-a115-5ffa-a7c2-890fe76717c4'::uuid,'e2899568-8871-5ace-a4ba-34af908f45a5'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nฟังแล้วอ่าน cups/bags/buses และ walked/played/wanted บันทึกประโยคสามข้อให้ผู้ฟังระบุจำนวนหรืออดีต\n\n### ตัวอย่างคำตอบ\n\nShe likes cups. He plays with dogs. They visited us yesterday.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ทบทวนเสียงท้ายที่มีความหมาย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fdaa60a2-39b9-50ac-aecd-5a565c36b724'::uuid,'3f80dd77-d994-5257-a3c3-1a31f2e79796'::uuid,'reading',1,'{"title":"word stress และ schwa","body":"## word stress และ schwa\n\nword stress ทำให้คำหลายพยางค์ฟังเป็นคำที่รู้จัก เช่น TEAcher/baNAna พยางค์ไม่เน้นหลายคำลดเป็น schwa /ə/ เช่นเสียงแรก about /əˈbaʊt/ ตรวจ stress จากเครื่องหมาย ˈ และเสียงพจนานุกรม อย่าสรุปว่าทุกสระไม่เน้นต้องเป็น /ə/ และอย่าอ่านตามไทยแทนเสียงตลอด\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| a-BOUT | เสียงแรกมัก schwa |\n| TEA-cher | เน้นแรก |\n| ba-NA-na | เน้นกลาง |\n\n### จุดที่มักสับสน\n\nstress กับการลดเสียงขึ้นกับคำและสำเนียง ต้องตรวจคำจริง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council TeachingEnglish — Stress](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/q-s/stress) · [British Council TeachingEnglish — Connected speech](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/connected-speech)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b34d8aac-a1d2-5535-a7aa-29638b63b846'::uuid,'3f80dd77-d994-5257-a3c3-1a31f2e79796'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/c969695dcb313f1d-lesson-33-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"About. Teacher. Banana. About. Teacher. Banana. My teacher is kind."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0e37ae85-34ef-5ef6-a30a-0ee42d888f62'::uuid,'3f80dd77-d994-5257-a3c3-1a31f2e79796'::uuid,'multiple_choice',1,'{"question":"schwa ใช้สัญลักษณ์ใด?","choices":[{"id":"choice_1","text":"/ə/"},{"id":"choice_2","text":"/b/"},{"id":"choice_3","text":"/ʃ/"}],"correctChoiceId":"choice_1","explanation":"/ə/ เป็นเสียงสระที่พบบ่อยในพยางค์ไม่เน้น"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3864e105-e877-5b3a-a77a-e74b3ca4ad3a'::uuid,'3f80dd77-d994-5257-a3c3-1a31f2e79796'::uuid,'multiple_choice',1,'{"question":"about เน้นพยางค์ใดโดยทั่วไป?","choices":[{"id":"choice_1","text":"พยางค์ที่สอง"},{"id":"choice_2","text":"พยางค์แรก"},{"id":"choice_3","text":"ไม่มี stress"}],"correctChoiceId":"choice_1","explanation":"a-BOUT; ฟังเสียงเพื่อได้ทั้งคำ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0e5a8847-5123-501e-a11c-9c8e540e9626'::uuid,'3f80dd77-d994-5257-a3c3-1a31f2e79796'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเลือกคำใหม่สามคำ ฟัง ตรวจ stress แล้วใช้ในประโยค\n\n### ตัวอย่างคำตอบ\n\nabout: I know about it. teacher: My teacher is kind. banana: I eat a banana.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **word stress และ schwa** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a0311eae-51ed-5324-aad0-d0b6e7ac2cd3'::uuid,'47ddab55-2e39-5359-a3cf-1a59fc1a4aef'::uuid,'reading',1,'{"title":"sentence stress และการแบ่งวลี","body":"## sentence stress และการแบ่งวลี\n\nsentence stress เน้นข้อมูลสำคัญ และเปลี่ยนจุดเน้นแล้วเปลี่ยนสิ่งที่ผู้ฟังเข้าใจได้ I bought a BLUE bag เน้นสี ส่วน I bought a blue BAG เน้นประเภทสิ่ง แบ่ง thought groups เป็นวลีตามความหมาย พักสั้นระหว่างส่วนเพื่อช่วยผู้ฟัง ไม่หยุดกลางกลุ่มคำนามทุกคำ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I bought a BLUE bag. | แก้ข้อมูลสี |\n| I BOUGHT a blue bag. | เน้นว่าซื้อ ไม่ได้ยืม |\n| After work / I went home / and cooked dinner. | แบ่งวลี |\n\n### จุดที่มักสับสน\n\nไม่เน้นทุกคำเท่ากันหรือพักทุกคำ เพราะฟังจับข้อมูลยาก\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council TeachingEnglish — Stress](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/q-s/stress) · [British Council TeachingEnglish — Connected speech](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/connected-speech)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('32ce7240-7307-50d6-afaf-e92386947fce'::uuid,'47ddab55-2e39-5359-a3cf-1a59fc1a4aef'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/388abc8d27ce4080-lesson-33-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I bought a blue bag. After work, I went home and cooked dinner."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2a91c0a3-8de5-5bcb-a804-d0c50394a7b1'::uuid,'47ddab55-2e39-5359-a3cf-1a59fc1a4aef'::uuid,'multiple_choice',1,'{"question":"เน้น BLUE ใน I bought a BLUE bag ต้องการแก้ข้อมูลใดเป็นหลัก?","choices":[{"id":"choice_1","text":"สี"},{"id":"choice_2","text":"ราคา"},{"id":"choice_3","text":"เวลา"}],"correctChoiceId":"choice_1","explanation":"stress ตรง BLUE ทำให้สีเด่น"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('19fcc242-1a9c-5672-a373-133a3959a526'::uuid,'47ddab55-2e39-5359-a3cf-1a59fc1a4aef'::uuid,'multiple_choice',1,'{"question":"thought groups ควรแบ่งตามอะไร?","choices":[{"id":"choice_1","text":"ความหมายของวลี"},{"id":"choice_2","text":"ทุกตัวอักษร"},{"id":"choice_3","text":"ทุกสองคำเสมอ"}],"correctChoiceId":"choice_1","explanation":"แบ่งส่วนที่ฟังเข้าใจร่วมกัน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('38cd8f14-f5bf-52cf-a2af-a19ee344d1d6'::uuid,'47ddab55-2e39-5359-a3cf-1a59fc1a4aef'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nอ่าน I bought a blue bag สองรอบโดยเน้นสีแล้วเน้นการซื้อ จากนั้นเล่าเรื่องแบ่งวลี\n\n### ตัวอย่างคำตอบ\n\nI bought a BLUE bag. I BOUGHT a blue bag. Yesterday / I went to the shop / and bought a book.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **sentence stress และการแบ่งวลี** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a5a23212-2c75-59e1-a023-74686db8fd0d'::uuid,'d417d178-aa62-5dd5-a27f-b365ecaacce1'::uuid,'reading',1,'{"title":"รูปย่อและ weak forms","body":"## รูปย่อและ weak forms\n\nรูปย่อ I’m/doesn’t/I’ll/I’ve ลดจำนวนเสียงแต่ยังมีข้อมูล grammar คำ function words a/the/to/can มักออก weak forms เมื่อไม่เน้น เช่น a /ə/ และ to /tə/ ในบริบททั่วไป รูป ’s อาจเป็น is หรือ has: She’s tired = is; She’s finished her work = has ดูโครงและความหมาย ไม่เลือกจาก apostrophe เพียงอย่างเดียว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I’m ready. / I’ll call. / I’ve eaten. | am / will / have |\n| She’s tired. / She’s done it. | is / has |\n\n### จุดที่มักสับสน\n\nweak forms เปลี่ยนตามจังหวะและการเน้น; can’t อาจได้ stress ชัด อย่าละคำช่วยที่มีความหมาย\n\n\n\n### ดูภาพแล้วลองใช้\n\n![เสียงท้าย เสียงเน้นและวลี: cups · bags · buses; TEAcher · aBOUT; turn‿it‿off](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2d99e75a2c61254c-module-33-map.png)\n\n*จังหวะช่วยผู้ฟังรับข้อมูล  •  ความเข้าใจได้คือเป้าหมาย*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council TeachingEnglish — Stress](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/q-s/stress) · [British Council TeachingEnglish — Connected speech](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/connected-speech)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('2a353aa4-0541-5f4c-accc-a72640f00f56'::uuid,'d417d178-aa62-5dd5-a27f-b365ecaacce1'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/3ccd87b86642a293-lesson-33-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I''m ready. He doesn''t work here. I''ll help you. I''ve finished. She''s tired. She''s done it."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e821b9ed-d526-5951-ad03-42f8c0276cf4'::uuid,'d417d178-aa62-5dd5-a27f-b365ecaacce1'::uuid,'multiple_choice',1,'{"question":"She’s finished her homework รูป ’s ในประโยคนี้คืออะไร?","choices":[{"id":"choice_1","text":"has"},{"id":"choice_2","text":"is ในความหมายเธอทำเสร็จ"},{"id":"choice_3","text":"was"}],"correctChoiceId":"choice_1","explanation":"has + V3 finished + object"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a083ee3a-8bd5-536f-ab55-946a99221cf4'::uuid,'d417d178-aa62-5dd5-a27f-b365ecaacce1'::uuid,'multiple_choice',1,'{"question":"I’ll ย่อจากอะไร?","choices":[{"id":"choice_1","text":"I will"},{"id":"choice_2","text":"I have"},{"id":"choice_3","text":"I am"}],"correctChoiceId":"choice_1","explanation":"I’ll = I will"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fd91ffeb-f271-5536-a1ae-d21ca78ea0b4'::uuid,'d417d178-aa62-5dd5-a27f-b365ecaacce1'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nฟังและเขียนรูปเต็มของ I’m ready / I’ll help / I’ve finished / She’s done it แล้วอ่านรูปย่อ\n\n### ตัวอย่างคำตอบ\n\nI am ready. I will help. I have finished. She has done it.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **รูปย่อและ weak forms** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4f0f834c-2936-54b2-aba9-621a2533db0e'::uuid,'5f95143a-e10b-53de-a638-c1b59980e15f'::uuid,'reading',1,'{"title":"linking และ intonation","body":"## linking และ intonation\n\nconnected speech อาจเชื่อมพยัญชนะท้ายกับสระต้น เช่น turn it off ฟังเป็นกลุ่มต่อกัน ไม่ใช่สามคำที่พักเท่ากัน intonation ช่วยแสดงคำถาม ขอร้องหรือยืนยัน เช่น rising บาง yes/no และ falling บาง Wh แต่ไม่มีทำนองเดียวบังคับทุกบริบท ฟังหลายสำเนียงและปรับเพื่อให้คู่สนทนาเข้าใจ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| turn it off | เชื่อม n→i และ t→o |\n| Can you help me? | น้ำเสียงคำขอขึ้นกับบริบท |\n| Where are you? | ฟังเป็นวลี ไม่อ่านชื่ออักษร |\n\n### จุดที่มักสับสน\n\nการเชื่อมเสียงไม่ใช่การตัดเสียง grammar ทั้งหมด และ intonation ต้องดูสถานการณ์\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [British Council TeachingEnglish — Stress](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/q-s/stress) · [British Council TeachingEnglish — Connected speech](https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/c/connected-speech)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0a76eb6f-2544-5b59-aea4-afc40e3e6ec4'::uuid,'5f95143a-e10b-53de-a638-c1b59980e15f'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/bcfdba94d75d16a8-lesson-33-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Turn it off. Please turn it off. Can you help me? Where are you?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('062dec91-ac78-505c-a7f3-3ce0c57f2bb2'::uuid,'5f95143a-e10b-53de-a638-c1b59980e15f'::uuid,'multiple_choice',1,'{"question":"turn it off มีจุดเชื่อมชนิดใดที่บทนี้เน้น?","choices":[{"id":"choice_1","text":"พยัญชนะท้ายกับสระต้น"},{"id":"choice_2","text":"ทุกคำแยกพักยาว"},{"id":"choice_3","text":"ไม่มีพยัญชนะท้าย"}],"correctChoiceId":"choice_1","explanation":"turn→it และ it→off เชื่อม consonant-vowel"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7d949c43-bc54-5ead-a08c-bb3531b173f7'::uuid,'5f95143a-e10b-53de-a638-c1b59980e15f'::uuid,'multiple_choice',1,'{"question":"คำถามทุกชนิดต้องขึ้นเสียงท้ายแบบเดียวหรือไม่?","choices":[{"id":"choice_1","text":"ไม่ ขึ้นกับประเภทและบริบท"},{"id":"choice_2","text":"ใช่เสมอ"},{"id":"choice_3","text":"ห้ามใช้น้ำเสียง"}],"correctChoiceId":"choice_1","explanation":"intonation มีหลาย pattern ตามการสื่อสาร"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9926dc37-76bb-503c-a7df-3a7403b23488'::uuid,'5f95143a-e10b-53de-a638-c1b59980e15f'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nฟัง turn it off / Can you help me? / Where are you? แล้วพูดตามเป็นวลี พร้อมขอเพื่อนตรวจว่าเข้าใจไหม\n\n### ตัวอย่างคำตอบ\n\nPlease turn it off. Can you help me, please? Where are you?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **linking และ intonation** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('15ce1cd9-7c84-5728-a25c-b4caa6c07c92'::uuid,'e8197261-2fe4-52ff-aefb-ece804e9e0a4'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **พูดสื่อความหมายได้และฟังรูปย่อ/คำเชื่อมโดยไม่ต้องเลียนสำเนียงเจ้าของภาษา**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![เสียงท้าย เสียงเน้นและวลี: cups · bags · buses; TEAcher · aBOUT; turn‿it‿off](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/2d99e75a2c61254c-module-33-map.png)\n\n*จังหวะช่วยผู้ฟังรับข้อมูล  •  ความเข้าใจได้คือเป้าหมาย*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ce698215-7ae0-5bfc-aa0f-75a1ffc890c7'::uuid,'e8197261-2fe4-52ff-aefb-ece804e9e0a4'::uuid,'multiple_choice',1,'{"question":"เสียง ed ของ wanted โดยทั่วไปคืออะไร?","choices":[{"id":"choice_1","text":"/ɪd/"},{"id":"choice_2","text":"/s/"},{"id":"choice_3","text":"ไม่ออกเสียง"}],"correctChoiceId":"choice_1","explanation":"หลัง /t/ เพิ่ม /ɪd/ ย้อน 33.01"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('75d0f87e-6752-5f1e-a860-a2b3319fbcc3'::uuid,'e8197261-2fe4-52ff-aefb-ece804e9e0a4'::uuid,'multiple_choice',1,'{"question":"She’s eaten lunch รูป ’s คืออะไร?","choices":[{"id":"choice_1","text":"has"},{"id":"choice_2","text":"is ในความหมายเธอกินแล้ว"},{"id":"choice_3","text":"was"}],"correctChoiceId":"choice_1","explanation":"has+V3 eaten ย้อน 33.04"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f7d512f0-a503-5610-a4d5-bf0783546001'::uuid,'e8197261-2fe4-52ff-aefb-ece804e9e0a4'::uuid,'multiple_choice',1,'{"question":"เน้น BUS ใน I took the BUS แก้ข้อมูลอะไรเป็นหลัก?","choices":[{"id":"choice_1","text":"วิธีเดินทาง"},{"id":"choice_2","text":"วันที่"},{"id":"choice_3","text":"ราคา"}],"correctChoiceId":"choice_1","explanation":"sentence stress เน้นสิ่งที่เทียบ ย้อน 33.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b16f014d-f2b7-5428-a567-9dd84c337b54'::uuid,'e8197261-2fe4-52ff-aefb-ece804e9e0a4'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nฟังแล้วพูดคำและประโยค: cups/bags/buses, walked/played/wanted, I’ve finished, turn it off บันทึกเสียงและให้ผู้ฟังตรวจข้อมูลที่ได้ยิน\n\n### ตัวอย่างผลงาน\n\nShe likes books. I wanted to go. I’ve finished my work. Please turn it off.\n\n### ตรวจผลงาน\n\n- คงเสียงท้ายที่มีความหมาย\n- word/sentence stress ช่วยจับใจความ\n- weak forms/linking ยังสื่อข้อมูลครบ\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('dea0f5dc-1614-5d38-a874-888684f3f3e8'::uuid,'c08622e1-afa5-5bea-a840-5922704e2448'::uuid,'reading',1,'{"title":"ฟังใจความกับฟังรายละเอียด","body":"## ฟังใจความกับฟังรายละเอียด\n\nฟังรอบแรกจับใจความว่าใคร ทำอะไร จุดประสงค์อะไรโดยยังไม่หยุดทุกคำ รอบสองฟังรายละเอียดที่ต้องใช้ เช่นเวลา สถานที่หรือสิ่งที่ต้องนำ ตั้งคำถามเป้าหมายก่อนฟังและตรวจจากข้อความ ไม่เดาคำตอบเพราะตัวเลือกดูเข้ากับเรื่อง ตัวอย่างเรื่องนัด: Mai calls Ben to arrange a study session. They meet at the library at six.\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Who? Mai and Ben. | ผู้ร่วม |\n| Why? To study together. | จุดประสงค์ |\n| Where/When? At the library at six. | รายละเอียด |\n\n### จุดที่มักสับสน\n\nการฟัง gist ไม่ต้องจำทุกคำ แต่ต้องไม่สรุปเรื่องที่คลิปไม่ได้พูด\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('55c378a5-454c-5421-afa5-0ae79c73d5df'::uuid,'c08622e1-afa5-5bea-a840-5922704e2448'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/97ee49441fcfe28c-lesson-34-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Hi Ben, this is Mai. Would you like to study English together? We can meet at the library at six this evening. Please bring your book. See you there."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('74b50478-e86e-5b93-ab06-d6cbfa542402'::uuid,'c08622e1-afa5-5bea-a840-5922704e2448'::uuid,'multiple_choice',1,'{"question":"จากเรื่องนัดเรียนในบท จุดประสงค์คืออะไร?","choices":[{"id":"choice_1","text":"เรียนด้วยกัน"},{"id":"choice_2","text":"ซื้อจักรยาน"},{"id":"choice_3","text":"ไปหาหมอ"}],"correctChoiceId":"choice_1","explanation":"to arrange a study session"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d3b30793-0363-5463-a358-d83c638530ec'::uuid,'c08622e1-afa5-5bea-a840-5922704e2448'::uuid,'multiple_choice',1,'{"question":"รายละเอียดสถานที่ที่เรื่องให้คืออะไร?","choices":[{"id":"choice_1","text":"the library"},{"id":"choice_2","text":"the bank"},{"id":"choice_3","text":"the airport"}],"correctChoiceId":"choice_1","explanation":"meet at the library"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0d0b37fb-66f8-5ed2-ae0a-ab601e4e2d9f'::uuid,'c08622e1-afa5-5bea-a840-5922704e2448'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nฟังคลิปนัดเรียนก่อนอ่าน transcript จดใจความหนึ่งประโยค แล้วฟังอีกครั้งจดคน เวลาและสถานที่\n\n### ตัวอย่างคำตอบ\n\nMai and Ben are going to study together. They meet at the library at six.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ฟังใจความกับฟังรายละเอียด** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('62aab1e2-7c66-53d5-a072-33fe1d37fedf'::uuid,'63114d61-8bf9-5205-a2b7-a212099551b0'::uuid,'reading',1,'{"title":"ฟังจำนวน เวลา และการแก้ข้อมูล","body":"## ฟังจำนวน เวลา และการแก้ข้อมูล\n\nจำนวนและเวลามักฟังใกล้กัน เช่น thirteen/thirty, fifteen/fifty ให้ฟัง stress กับข้อมูลรอบ ๆ ระวังผู้พูดแก้ข้อมูล not…/sorry/I mean… จดค่าล่าสุดที่ยืนยัน เช่น Let’s meet at seven. Sorry, I mean seven thirty. ต้องตอบ 7:30 ไม่ใช่คำแรกที่ได้ยิน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| thirteen / thirty | เลขใกล้เสียงแต่ stress ต่าง |\n| seven — sorry, seven thirty | ข้อมูลแก้เป็น 7:30 |\n| fifteen, not fifty | ย้ำจำนวน 15 |\n\n### จุดที่มักสับสน\n\nไม่เลือกตัวเลขแรกโดยอัตโนมัติเมื่อมีการแก้ และอย่าเอาจำนวนกับราคา/หมายเลขปน\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ใจความ รายละเอียดและการแก้ข้อมูล: Who? Why?; When? Where? How many?; seven → sorry, seven thirty](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/035074e0769b312d-module-34-map.png)\n\n*ใช้ข้อมูลสุดท้ายที่ยืนยัน  •  สรุปโดยไม่เติมข้อเท็จจริงเอง*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('547f67bf-9327-5ec5-aec9-ff2a3ef95677'::uuid,'63114d61-8bf9-5205-a2b7-a212099551b0'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/3e623ad11cc4b522-lesson-34-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Let us meet at seven. Sorry, I mean seven thirty. The ticket is fifteen pounds, not fifty. We need thirteen tickets, not thirty."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a77980a3-c262-5d62-a68c-c9cfc2f778bc'::uuid,'63114d61-8bf9-5205-a2b7-a212099551b0'::uuid,'multiple_choice',1,'{"question":"Meet at seven. Sorry, I mean seven thirty. เวลาสุดท้ายคืออะไร?","choices":[{"id":"choice_1","text":"7:00"},{"id":"choice_2","text":"7:30"},{"id":"choice_3","text":"6:30"}],"correctChoiceId":"choice_2","explanation":"I mean แก้เวลาเป็น seven thirty"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e364155e-44f2-5c31-a9f1-31aeda905f7f'::uuid,'63114d61-8bf9-5205-a2b7-a212099551b0'::uuid,'multiple_choice',1,'{"question":"The ticket is fifteen, not fifty ราคาเท่าไรตามข้อความ?","choices":[{"id":"choice_1","text":"15"},{"id":"choice_2","text":"50"},{"id":"choice_3","text":"55"}],"correctChoiceId":"choice_1","explanation":"not fifty ปฏิเสธ 50 และยืนยัน fifteen"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6bd1bd87-f3a9-5849-a980-ea98c6602422'::uuid,'63114d61-8bf9-5205-a2b7-a212099551b0'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nฟังคลิปสองรอบแล้วจดเวลานัด ราคาและจำนวนที่แก้สุดท้าย ทวนให้คู่สนทนาตรวจ\n\n### ตัวอย่างคำตอบ\n\nWe meet at seven thirty. The ticket is fifteen pounds. We need thirteen tickets, not thirty.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ฟังจำนวน เวลา และการแก้ข้อมูล** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('0b68f60e-b457-5a76-ae32-976f50e074b9'::uuid,'5cd44514-e3a0-5fd7-a654-5172b64d44c4'::uuid,'reading',1,'{"title":"อ่านป้าย แบบฟอร์ม และตาราง","body":"## อ่านป้าย แบบฟอร์ม และตาราง\n\nอ่านป้าย แบบฟอร์มและตารางตามเป้าหมาย มองคำห้าม/คำสั่ง ช่องข้อมูลหรือหัวตารางก่อน ตัวอย่าง Library hours: Monday–Friday 9:00–18:00; Saturday 10:00–16:00; Sunday closed. ต้องดูวันประกอบเวลา ไม่ยกเวลาวันธรรมดาไปใช้วันเสาร์ ป้าย No food บอกห้ามนำหรือกินอาหารตามบริบท\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Sunday: closed | ปิดวันอาทิตย์ |\n| Saturday: 10:00–16:00 | ช่วงวันเสาร์ |\n| No food in the reading room. | ห้ามอาหารในห้องอ่าน |\n\n### จุดที่มักสับสน\n\nเวลา 18:00 คือหกโมงเย็น ไม่ใช่แปดโมง; ช่อง surname ถามนามสกุล ไม่ใช่ชื่อจริง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('84e74450-d51e-5f20-a217-699e1ad7f173'::uuid,'5cd44514-e3a0-5fd7-a654-5172b64d44c4'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/56a6570660acf310-lesson-34-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Sunday: closed. Saturday: 10:00–16:00. No food in the reading room."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('585c851e-7f38-518e-a981-2a68bc0264ab'::uuid,'5cd44514-e3a0-5fd7-a654-5172b64d44c4'::uuid,'multiple_choice',1,'{"question":"จากตารางห้องสมุดในบท วันเสาร์เปิดกี่โมง?","choices":[{"id":"choice_1","text":"9:00"},{"id":"choice_2","text":"10:00"},{"id":"choice_3","text":"18:00"}],"correctChoiceId":"choice_2","explanation":"Saturday 10:00–16:00"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('67370203-621f-5bd5-adb9-5792c32911c3'::uuid,'5cd44514-e3a0-5fd7-a654-5172b64d44c4'::uuid,'multiple_choice',1,'{"question":"แบบฟอร์มถาม surname ต้องใส่อะไร?","choices":[{"id":"choice_1","text":"นามสกุล"},{"id":"choice_2","text":"อายุ"},{"id":"choice_3","text":"ประเทศ"}],"correctChoiceId":"choice_1","explanation":"surname คือ family name"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ff5c7319-0a97-591b-ac34-6958d24a5dca'::uuid,'5cd44514-e3a0-5fd7-a654-5172b64d44c4'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nอ่านตารางแล้วเขียนเวลาเปิดวันพุธ วันเสาร์และสถานะวันอาทิตย์ พร้อมกรอกแบบฟอร์มสมมติ\n\n### ตัวอย่างคำตอบ\n\nWednesday: nine to six. Saturday: ten to four. Sunday: closed. First name: Mai. Surname: Srisuk.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **อ่านป้าย แบบฟอร์ม และตาราง** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('91ab00b4-ae21-5302-aa86-ed49560ac8f7'::uuid,'bd5ecc26-efcb-59ff-a2be-2d5d8984a264'::uuid,'reading',1,'{"title":"อ่านเรื่องสั้นและข้อความ","body":"## อ่านเรื่องสั้นและข้อความ\n\nอ่านเรื่องรอบแรกหาใจความแล้ว scan ข้อมูลเฉพาะตามคำถาม ติดตาม pronoun ว่าอ้างใครและคำเวลา/เหตุผล ตัวอย่าง: Ben missed the bus because he got up late. He called Mai. She drove him to school. He thanked her. He อ้าง Ben และ She/her อ้าง Mai ไม่สลับผู้ช่วยกับคนที่พลาดรถ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Why? He got up late. | เหตุผลพลาดรถ |\n| Who helped? Mai. | She drove him |\n| What happened last? Ben thanked Mai. | ลำดับท้าย |\n\n### จุดที่มักสับสน\n\nแยกข้อมูลที่เขียนจริงกับข้อเดา เช่นยังไม่รู้ว่า Ben มีสอบหรือไม่\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7c242510-f1fa-59a9-a3b5-8a3389304083'::uuid,'bd5ecc26-efcb-59ff-a2be-2d5d8984a264'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/d04c9b09f3f2d06f-lesson-34-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Why? He got up late.. Who helped? Mai.. What happened last? Ben thanked Mai."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b3337a28-8959-56c8-aa67-329c37e4cb22'::uuid,'bd5ecc26-efcb-59ff-a2be-2d5d8984a264'::uuid,'multiple_choice',1,'{"question":"Ben missed the bus because… เหตุผลในเรื่องคืออะไร?","choices":[{"id":"choice_1","text":"ตื่นสาย"},{"id":"choice_2","text":"รถเสีย"},{"id":"choice_3","text":"ไม่มีเงิน"}],"correctChoiceId":"choice_1","explanation":"because he got up late"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a3fba924-62c2-515d-a1fd-fb6fc1d1d2c3'::uuid,'bd5ecc26-efcb-59ff-a2be-2d5d8984a264'::uuid,'multiple_choice',1,'{"question":"She ใน She drove him to school อ้างใคร?","choices":[{"id":"choice_1","text":"Mai"},{"id":"choice_2","text":"Ben"},{"id":"choice_3","text":"รถบัส"}],"correctChoiceId":"choice_1","explanation":"Mai เป็นคนที่โทรหาและพาไป"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('41985c45-17de-5d79-aa82-b77a7e7065fe'::uuid,'bd5ecc26-efcb-59ff-a2be-2d5d8984a264'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nอ่านเรื่องแล้วสรุปสามประโยคพร้อมระบุ he/she/him/her\n\n### ตัวอย่างคำตอบ\n\nBen got up late and missed the bus. Mai drove him to school. Ben thanked her.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **อ่านเรื่องสั้นและข้อความ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9aa25535-74fe-50be-a70d-c9cb4aca8ce9'::uuid,'91048461-811b-5594-a5ae-df60bd6d8fe6'::uuid,'reading',1,'{"title":"เดาคำจากบริบท","body":"## เดาคำจากบริบท\n\nเดาคำจากบริบทโดยดูสิ่งรอบคำและหน้าที่ ตัวอย่าง The room was chilly, so Mai wore a coat. แม้ไม่รู้ chilly ก็เดาว่าเย็นได้จากใส่เสื้อโค้ต หากคำไม่สำคัญต่อเป้าหมายอาจข้าม แต่ถ้าเป็นข้อมูลสำคัญเช่นราคา เวลา คำห้าม หรือเดายังไม่พอให้เปิดพจนานุกรม การเดาคือข้อสันนิษฐานต้องตรวจ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| chilly … wore a coat | บริบทสภาพเย็น |\n| Please enter your surname. | คำสำคัญในแบบฟอร์ม ต้องตรวจถ้าไม่รู้ |\n\n### จุดที่มักสับสน\n\nอย่าถือว่าคำที่เดาต้องถูก หรือหยุดแปลทุกคำจนลืมใจความ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f0fa02f9-3a5b-56d3-aaee-f5faa35e68ef'::uuid,'91048461-811b-5594-a5ae-df60bd6d8fe6'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/a07fbdf77a9c5146-lesson-34-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"chilly … wore a coat. Please enter your surname."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('08b831e4-f309-573b-a364-6d8631fc3e65'::uuid,'91048461-811b-5594-a5ae-df60bd6d8fe6'::uuid,'multiple_choice',1,'{"question":"The room was chilly, so she wore a coat. chilly น่าจะหมายถึงอะไร?","choices":[{"id":"choice_1","text":"เย็น"},{"id":"choice_2","text":"ร้อนจัด"},{"id":"choice_3","text":"เสียงดัง"}],"correctChoiceId":"choice_1","explanation":"coat เป็นหลักฐานประกอบสภาพอากาศเย็น"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5c64e7f3-fd67-52ae-ab4a-1132c3e20287'::uuid,'91048461-811b-5594-a5ae-df60bd6d8fe6'::uuid,'multiple_choice',1,'{"question":"เมื่อไม่รู้คำห้ามสำคัญในป้าย ควรทำอย่างไร?","choices":[{"id":"choice_1","text":"ตรวจความหมายก่อนทำตาม"},{"id":"choice_2","text":"เดาแล้วทำโดยไม่ตรวจ"},{"id":"choice_3","text":"ข้ามเพราะทุกคำไม่สำคัญ"}],"correctChoiceId":"choice_1","explanation":"คำที่มีผลต่อการทำต้องเข้าใจถูก"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('94345c51-4bb2-52ab-aad7-d38ed2937ec1'::uuid,'91048461-811b-5594-a5ae-df60bd6d8fe6'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเลือกข้อความสั้นหนึ่งเรื่อง จดคำที่เดา ข้ามและต้องตรวจอย่างละหนึ่งพร้อมเหตุผล\n\n### ตัวอย่างคำตอบ\n\nchilly: เดาว่าเย็นจาก coat แล้วตรวจ. ชื่อคนไม่ต้องแปล. surname: ตรวจเพราะต้องกรอกข้อมูลให้ถูก.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เดาคำจากบริบท** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('de54532d-b349-580b-ab8d-189ea06c1808'::uuid,'60290252-8619-5ff8-a043-4da35a8aa30b'::uuid,'reading',1,'{"title":"ถ่ายทอดข้อมูลให้ผู้อื่น","body":"## ถ่ายทอดข้อมูลให้ผู้อื่น\n\nถ่ายทอดข้อมูลจากตารางหรือข้อความเป็นคำของคุณโดยคงผู้ทำ วันเวลา จำนวนและเงื่อนไข ใช้ประโยคง่ายแทนคัดทุกคำ ตัวอย่างข้อความ: Art class Saturday 10:00, room 2, bring a pencil; free for students. สรุปให้เพื่อนรู้วัน เวลา ห้อง สิ่งที่ต้องนำและเงื่อนไขฟรี ไม่เพิ่มว่าเปิดให้ทุกคนฟรี\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| The art class is on Saturday at ten. | วันเวลา |\n| It is in room two. | ที่ |\n| Students don’t have to pay. Bring a pencil. | เงื่อนไข / ของ |\n\n### จุดที่มักสับสน\n\nไม่เปลี่ยน free for students เป็น free for everyone เพราะขยายข้อเท็จจริงเกินข้อความ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b175263f-eeaf-5007-afcb-65a8a1b237d4'::uuid,'60290252-8619-5ff8-a043-4da35a8aa30b'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/59398f87b4ce1e08-lesson-34-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"The art class is on Saturday at ten.. It is in room two.. Students don’t have to pay. Bring a pencil."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('566d3b22-8b5d-526c-ad74-ffbf9fcaa970'::uuid,'60290252-8619-5ff8-a043-4da35a8aa30b'::uuid,'multiple_choice',1,'{"question":"จากประกาศ art class ใครไม่ต้องจ่าย?","choices":[{"id":"choice_1","text":"students"},{"id":"choice_2","text":"everyone โดยประกาศยืนยัน"},{"id":"choice_3","text":"teachers เท่านั้น"}],"correctChoiceId":"choice_1","explanation":"free for students ไม่ใช่ทุกคน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b30ac48a-2f28-5e31-afbe-4693c80c41f2'::uuid,'60290252-8619-5ff8-a043-4da35a8aa30b'::uuid,'multiple_choice',1,'{"question":"ต้องนำอะไรตามประกาศ?","choices":[{"id":"choice_1","text":"a pencil"},{"id":"choice_2","text":"a phone"},{"id":"choice_3","text":"food"}],"correctChoiceId":"choice_1","explanation":"bring a pencil"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('148ecd8e-43e2-5a6a-aaff-a522046237d7'::uuid,'60290252-8619-5ff8-a043-4da35a8aa30b'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nสรุปประกาศให้เพื่อนใน 3–4 ประโยค แล้วตรวจวันเวลา ห้องและเงื่อนไข\n\n### ตัวอย่างคำตอบ\n\nThe art class is on Saturday at ten in room two. Bring a pencil. It is free for students.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ถ่ายทอดข้อมูลให้ผู้อื่น** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('db908a0c-e61c-5847-ad44-c572ab0c0678'::uuid,'1a479c31-65dd-5edb-a6b0-b89eaa80531d'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **จับใจความและข้อมูลเฉพาะจากข้อความพื้นฐานได้ โดยไม่ต้องรู้ทุกคำ**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ใจความ รายละเอียดและการแก้ข้อมูล: Who? Why?; When? Where? How many?; seven → sorry, seven thirty](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/035074e0769b312d-module-34-map.png)\n\n*ใช้ข้อมูลสุดท้ายที่ยืนยัน  •  สรุปโดยไม่เติมข้อเท็จจริงเอง*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8c38db61-0416-5e2f-a2a7-51462f853d53'::uuid,'1a479c31-65dd-5edb-a6b0-b89eaa80531d'::uuid,'multiple_choice',1,'{"question":"The meeting is at eight. Sorry, at eight fifteen. เวลาสุดท้ายคืออะไร?","choices":[{"id":"choice_1","text":"8:15"},{"id":"choice_2","text":"8:00"},{"id":"choice_3","text":"8:50"}],"correctChoiceId":"choice_1","explanation":"การแก้ข้อมูลให้ใช้ค่าหลัง ย้อน 34.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6a3912ac-ebfc-5d82-a038-68debf391c09'::uuid,'1a479c31-65dd-5edb-a6b0-b89eaa80531d'::uuid,'multiple_choice',1,'{"question":"ข้อความ Free for children สรุปได้ว่าอะไร?","choices":[{"id":"choice_1","text":"เด็กไม่ต้องจ่าย"},{"id":"choice_2","text":"ทุกคนฟรีแน่นอน"},{"id":"choice_3","text":"ผู้ใหญ่ฟรีเท่านั้น"}],"correctChoiceId":"choice_1","explanation":"คงเงื่อนไขไม่ขยาย ย้อน 34.06"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('70924ac6-ea24-52f4-ac51-b49100c59329'::uuid,'1a479c31-65dd-5edb-a6b0-b89eaa80531d'::uuid,'multiple_choice',1,'{"question":"อ่านเพื่อหาราคาเฉพาะใช้แนวทางใด?","choices":[{"id":"choice_1","text":"scan จุดที่เกี่ยวกับราคา"},{"id":"choice_2","text":"แปลทุกคำก่อนเสมอ"},{"id":"choice_3","text":"เดาราคาโดยไม่ดู"}],"correctChoiceId":"choice_1","explanation":"อ่านตามเป้าหมาย ย้อน 34.03"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ff0f7e9e-57fe-57dd-a0fb-51177aa02e82'::uuid,'1a479c31-65dd-5edb-a6b0-b89eaa80531d'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nฟังคลิปแก้ข้อมูลแล้วทวน จากนั้นอ่านตารางห้องสมุดและสรุปให้เพื่อน โดยคงวันเวลาและเงื่อนไข\n\n### ตัวอย่างผลงาน\n\nWe meet at seven thirty, not seven. Saturday library hours are ten to four; it is closed on Sunday.\n\n### ตรวจผลงาน\n\n- ฟัง gist และข้อมูลแก้ได้\n- scan วัน/เวลา/เงื่อนไขตรง\n- สรุปโดยไม่เติมข้อมูล\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c94e900f-bb39-5255-a7ff-9bf337b47543'::uuid,'26f3d545-ad7c-5be8-ac03-859405736d15'::uuid,'reading',1,'{"title":"เริ่ม รักษา และจบบทสนทนา","body":"## เริ่ม รักษา และจบบทสนทนา\n\nบทสนทนามีเปิด รับช่วง ตอบแล้วถามกลับ และจบอย่างเหมาะสม เช่น Hi, how are you? → Fine, thanks. How about you? แสดงความสนใจด้วย Oh, really?/That sounds good. ขอแทรก Excuse me. และจบ I have to go. See you later. ใช้กับบริบทของคุณไม่ท่องบทเดียวและไม่ตอบยาวโดยไม่ฟังคู่สนทนา\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| How are you? — Good, thanks. How about you? | ตอบและถามกลับ |\n| Excuse me, can I ask something? | ขอแทรก |\n| I have to go. See you later. | จบสุภาพ |\n\n### จุดที่มักสับสน\n\nถามกลับเรื่องเดียวกันได้ แต่ไม่ต้องซักข้อมูลส่วนตัวที่ไม่เหมาะกับความสัมพันธ์\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d21002d2-f3bc-5ea9-a351-0e34e6cf3182'::uuid,'26f3d545-ad7c-5be8-ac03-859405736d15'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/265346e6a067b31e-lesson-35-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"How are you?. Good, thanks. How about you?. Excuse me, can I ask something?. I have to go. See you later."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e765eb1c-38f6-5b25-a12d-6666110720fa'::uuid,'26f3d545-ad7c-5be8-ac03-859405736d15'::uuid,'multiple_choice',1,'{"question":"คำตอบใดช่วยรับช่วงและถามกลับ?","choices":[{"id":"choice_1","text":"Good, thanks. How about you?"},{"id":"choice_2","text":"Blue bag."},{"id":"choice_3","text":"I yesterday."}],"correctChoiceId":"choice_1","explanation":"ตอบคำถามแล้วเชิญอีกฝ่ายพูด"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('75721fa7-c84a-5b0a-acc5-de3a7718407f'::uuid,'26f3d545-ad7c-5be8-ac03-859405736d15'::uuid,'multiple_choice',1,'{"question":"ต้องจบบทสนทนาอย่างสุภาพ เลือก","choices":[{"id":"choice_1","text":"I have to go. See you later."},{"id":"choice_2","text":"Stop talk now."},{"id":"choice_3","text":"No question."}],"correctChoiceId":"choice_1","explanation":"บอกเหตุผลสั้นและคำลา"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fa627c1e-2e79-5ef3-a7c7-afbe594eb3da'::uuid,'26f3d545-ad7c-5be8-ac03-859405736d15'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเล่นบทสนทนาหกบรรทัด มีทัก ตอบ ถามกลับ รับช่วงและจบ แล้วเปลี่ยนข้อมูลอีกครั้ง\n\n### ตัวอย่างคำตอบ\n\nHi, how are you? Good, thanks. How about you? I’m fine. I’m going to the library. Oh, really? I have to go now. See you later.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เริ่ม รักษา และจบบทสนทนา** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fcbf3e74-7136-5983-a839-fa2bd762bdd9'::uuid,'52ed22be-beb6-542b-aa48-9d987b270cb0'::uuid,'reading',1,'{"title":"ขอให้ทวนและตรวจความเข้าใจ","body":"## ขอให้ทวนและตรวจความเข้าใจ\n\nเมื่อไม่เข้าใจให้ขอทวน Could you say that again? ขอช้า Could you speak more slowly? ขอสะกด How do you spell that? ถามความหมาย What does … mean? และทวนข้อมูล So we meet at six, right? หากจำคำไม่ได้ใช้อธิบายรูป หน้าที่หรือที่ใช้แทน ไม่ต้องหยุดบทสนทนาทันที\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Could you repeat that, please? | ขอทวน |\n| How do you spell your name? | ขอสะกด |\n| Do you mean six thirty? | ตรวจข้อมูล |\n\n### จุดที่มักสับสน\n\nขอ clarification เป็นทักษะสื่อสาร ไม่ใช่ความล้มเหลว และต้องฟังคำตอบที่แก้แล้ว\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ตอบ ถามกลับและแก้ความไม่เข้าใจ: How about you?; Could you repeat that?; See you later.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/8f0355e94cb41e63-module-35-map.png)\n\n*พูดและเขียนเพื่อจุดประสงค์  •  ตรวจข้อความแล้วแก้หนึ่งรอบ*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b6b8a492-2851-5f07-a0c2-f15ab8d1819a'::uuid,'52ed22be-beb6-542b-aa48-9d987b270cb0'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/52dee207b78d2302-lesson-35-02.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Could you repeat that, please?. How do you spell your name?. Do you mean six thirty?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('00061f05-9f64-5142-a471-f0583278a677'::uuid,'52ed22be-beb6-542b-aa48-9d987b270cb0'::uuid,'multiple_choice',1,'{"question":"ฟังเวลาไม่ชัด คำใดช่วยตรวจข้อมูล?","choices":[{"id":"choice_1","text":"Do you mean seven thirty?"},{"id":"choice_2","text":"Where’s your bag?"},{"id":"choice_3","text":"I never late."}],"correctChoiceId":"choice_1","explanation":"ทวนเวลาที่คิดว่าได้ยินให้ยืนยัน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1ca98d5c-ea97-57f5-a422-01e2f723033f'::uuid,'52ed22be-beb6-542b-aa48-9d987b270cb0'::uuid,'multiple_choice',1,'{"question":"ต้องการรู้การสะกดชื่อ ใช้คำถามใด?","choices":[{"id":"choice_1","text":"How do you spell your name?"},{"id":"choice_2","text":"How often your name?"},{"id":"choice_3","text":"What name long?"}],"correctChoiceId":"choice_1","explanation":"How do you spell…? ถามตัวอักษร"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a85d456a-289b-5e15-a4e3-5d84882df83d'::uuid,'52ed22be-beb6-542b-aa48-9d987b270cb0'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nจำลองฟังข้อมูลไม่ชัด ใช้ขอทวน ขอสะกดและทวนเวลารวมสามครั้ง\n\n### ตัวอย่างคำตอบ\n\nCould you say that again? How do you spell Ben? B–E–N. So we meet at seven thirty, right? Yes.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ขอให้ทวนและตรวจความเข้าใจ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ee1596ba-8a41-5796-a9ee-9a0265724a6f'::uuid,'aeb3acd9-9074-50b4-abc0-621b99ed219e'::uuid,'reading',1,'{"title":"เสนอ ชวน ขอ และตอบ","body":"## เสนอ ชวน ขอ และตอบ\n\nคำเสนอ ชวน ขอและอนุญาตต้องตรงสิ่งที่อยากให้คู่สนทนาทำ Shall I help? เสนอช่วย; Would you like to join? ชวน; Could you lend me a pen? ขอ; May I use this? ขออนุญาต ตอบรับหรือปฏิเสธสุภาพพร้อมทางเลือกเมื่อมี เช่น Sorry, I can’t today. How about tomorrow?\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Would you like to join us? — I’d love to. | รับคำชวน |\n| Could you help me? — Sure. | รับคำขอ |\n| Can I sit here? — Of course. | อนุญาต |\n\n### จุดที่มักสับสน\n\nไม่ตอบ Yes, I do ทุกคำถามโดยไม่ดูหน้าที่และกริยาช่วย\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6eae2a99-d5e2-5ab5-a168-8a79b5f8b8c9'::uuid,'aeb3acd9-9074-50b4-abc0-621b99ed219e'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/ca643f891e6b436e-lesson-35-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Would you like to join us?. I’d love to.. Could you help me?. Sure.. Can I sit here?. Of course."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1dfedfc7-4961-5811-acc2-f7e844b196ab'::uuid,'aeb3acd9-9074-50b4-abc0-621b99ed219e'::uuid,'multiple_choice',1,'{"question":"คำถามใดเป็นการเสนอให้ผู้พูดช่วย?","choices":[{"id":"choice_1","text":"Shall I carry it?"},{"id":"choice_2","text":"Could you carry it?"},{"id":"choice_3","text":"Can I borrow it?"}],"correctChoiceId":"choice_1","explanation":"Shall I…? offer"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c0db5924-5004-5017-a9e8-09ca9a1549e8'::uuid,'aeb3acd9-9074-50b4-abc0-621b99ed219e'::uuid,'multiple_choice',1,'{"question":"ปฏิเสธคำชวนสุภาพพร้อมทางเลือกคืออะไร?","choices":[{"id":"choice_1","text":"Sorry, I can’t today. How about tomorrow?"},{"id":"choice_2","text":"No go."},{"id":"choice_3","text":"Yes, I don’t."}],"correctChoiceId":"choice_1","explanation":"ปฏิเสธชัดแล้วเสนอเวลาอื่น"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('415114c2-fe58-527d-abd5-36a47213e71f'::uuid,'aeb3acd9-9074-50b4-abc0-621b99ed219e'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nสร้างบทสองสถานการณ์: ขอสิ่งจำเป็นและชวนทำกิจกรรม มีตอบรับหรือทางเลือก\n\n### ตัวอย่างคำตอบ\n\nCould you lend me a pen? Sure. Would you like to play tennis today? Sorry, I can’t today. How about tomorrow? That sounds good.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เสนอ ชวน ขอ และตอบ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('71dbf20b-0ae6-5a12-a9bc-181e180ef775'::uuid,'ebf178d7-b777-5c37-a648-0a822b110953'::uuid,'reading',1,'{"title":"ตอบสนองทางสังคม","body":"## ตอบสนองทางสังคม\n\nใช้วลีสังคมให้ตรงสถานการณ์ Thank you. → You’re welcome. Sorry I’m late. → That’s okay. Your presentation was great. → Thank you. I’m sorry to hear that. แสดงความเห็นใจเมื่ออีกคนมีเรื่องไม่ดี น้ำเสียงกับความสัมพันธ์สำคัญ และคำตอบไม่ต้องแปลไทยตรงตัวทุกวลี\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Thanks for your help. — You’re welcome. | ขอบคุณ/รับ |\n| I’m sorry I’m late. — That’s okay. | ขอโทษ/รับ |\n| I lost my phone. — I’m sorry to hear that. | เห็นใจ |\n\n### จุดที่มักสับสน\n\nI’m sorry to hear that ไม่จำเป็นแปลว่าผู้พูดเป็นคนทำผิด แต่แสดงความเห็นใจ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b5d4d816-7ab4-5213-aa15-60c063cd766d'::uuid,'ebf178d7-b777-5c37-a648-0a822b110953'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4cb4dc6ca7804a57-lesson-35-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Thanks for your help.. You’re welcome.. I’m sorry I’m late.. That’s okay.. I lost my phone.. I’m sorry to hear that."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a0686d63-3417-5db7-a970-e276e38aac4e'::uuid,'ebf178d7-b777-5c37-a648-0a822b110953'::uuid,'multiple_choice',1,'{"question":"เพื่อนบอก My dog is sick คำตอบเห็นใจเหมาะคืออะไร?","choices":[{"id":"choice_1","text":"I’m sorry to hear that."},{"id":"choice_2","text":"Congratulations!"},{"id":"choice_3","text":"Happy birthday!"}],"correctChoiceId":"choice_1","explanation":"ตอบเรื่องไม่ดีด้วยความเห็นใจ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('129db843-2469-52c3-a3dc-815591493dd8'::uuid,'ebf178d7-b777-5c37-a648-0a822b110953'::uuid,'multiple_choice',1,'{"question":"Thanks for your help คำตอบรับธรรมชาติคืออะไร?","choices":[{"id":"choice_1","text":"You’re welcome."},{"id":"choice_2","text":"You’re thank."},{"id":"choice_3","text":"I’m welcome."}],"correctChoiceId":"choice_1","explanation":"You’re welcome รับคำขอบคุณ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('03b64327-7f55-5a59-a3c9-24a85689426b'::uuid,'ebf178d7-b777-5c37-a648-0a822b110953'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนบทขอบคุณ ขอโทษ ชมและเห็นใจอย่างละหนึ่งคู่\n\n### ตัวอย่างคำตอบ\n\nThank you. You’re welcome. Sorry I’m late. That’s okay. Your work is great. Thanks. I lost my book. I’m sorry to hear that.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ตอบสนองทางสังคม** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('8d076cde-6eb5-5cf8-a371-192add76c407'::uuid,'c896154f-62b6-5411-a730-66e49860da26'::uuid,'reading',1,'{"title":"ความเห็นและความชอบ","body":"## ความเห็นและความชอบ\n\nให้ความเห็น I think… และความชอบ I prefer… because… เห็นด้วย I agree./Me too. หรือไม่เห็นด้วยสุภาพ I see your point, but… ประโยคปฏิเสธรับด้วย Me neither. รูป so/neither + auxiliary + subject ใช้ตามกริยาช่วย เช่น I like tea. So do I. / I can’t swim. Neither can I. เริ่มจากชุดที่ใช้บ่อยไม่เหมารวม auxiliary เดียว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I like music. — So do I. | กริยาทั่วไป do |\n| I am tired. — So am I. | be |\n| I can’t drive. — Neither can I. | modal ปฏิเสธ |\n\n### จุดที่มักสับสน\n\nSo I do. ในอีกความหมายไม่ใช่รูปตอบเห็นด้วยที่ฝึก; I don’t like it. → Me neither.\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e2420bc0-00a0-5f94-aafb-bcb6f9b9c430'::uuid,'c896154f-62b6-5411-a730-66e49860da26'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/6a5cf412cbb86bd9-lesson-35-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I like music.. So do I.. I am tired.. So am I.. I can’t drive.. Neither can I."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('e5b49991-b899-546a-a383-f28247b4996d'::uuid,'c896154f-62b6-5411-a730-66e49860da26'::uuid,'multiple_choice',1,'{"question":"I can swim. ตอบว่าฉันก็ได้ ใช้รูปใด?","choices":[{"id":"choice_1","text":"So can I."},{"id":"choice_2","text":"So do I."},{"id":"choice_3","text":"Neither can I."}],"correctChoiceId":"choice_1","explanation":"auxiliary can ตามต้นประโยค"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fbf49298-0abe-526a-a45c-d222056d82b0'::uuid,'c896154f-62b6-5411-a730-66e49860da26'::uuid,'multiple_choice',1,'{"question":"I don’t like coffee. ตอบฉันก็ไม่ชอบ ใช้รูปใด?","choices":[{"id":"choice_1","text":"Me too."},{"id":"choice_2","text":"Me neither."},{"id":"choice_3","text":"So am I."}],"correctChoiceId":"choice_2","explanation":"รับประโยคปฏิเสธด้วย Me neither"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ea2206c0-0ef4-515e-a700-4b31af2d7c1a'::uuid,'c896154f-62b6-5411-a730-66e49860da26'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเลือกสองทางแล้วให้เหตุผลหนึ่งข้อ พร้อมตอบเห็นด้วยทั้งบอกเล่าและปฏิเสธ\n\n### ตัวอย่างคำตอบ\n\nI prefer tea because it is lighter. I like books. So do I. I don’t drive. Me neither.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ความเห็นและความชอบ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('074c516c-cc48-5c19-adac-6f190af818bf'::uuid,'b869b95e-8c2e-5a29-a45c-da11711f2875'::uuid,'reading',1,'{"title":"เขียนข้อความที่มีจุดประสงค์","body":"## เขียนข้อความที่มีจุดประสงค์\n\nเขียนข้อความตามจุดประสงค์และผู้รับ: แบบฟอร์มตอบข้อมูลตรงช่อง โน้ตสั้นให้คนทำสิ่งหนึ่ง อีเมล/แชตมีทัก เนื้อหาและจบ ระบุเวลา สถานที่หรือสิ่งที่ต้องการชัด การคุยเพื่อนใช้ Hi…/See you. ส่วนครูหรือคนไม่คุ้นใช้คำขอสุภาพและชื่อให้เหมาะ ไม่ต้องทำทุกข้อความเป็นภาษาทางการยาว\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Hi Ben, can we meet at six? Thanks, Mai. | ข้อความเพื่อน |\n| Dear Ms Lee, could you explain this word, please? Thank you, Mai. | คำขอครู |\n\n### จุดที่มักสับสน\n\nไม่ส่งข้อความที่ไม่มีข้อมูลหลัก เช่นเวลาในคำชวน หรือใช้ชื่อ/ข้อมูลจริงที่ไม่อยากเปิดเผยในแบบฝึก ใช้ข้อมูลสมมติได้\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f49a49a4-7300-5117-ab27-ca4299f62c89'::uuid,'b869b95e-8c2e-5a29-a45c-da11711f2875'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/f0db8974228a954c-lesson-35-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Hi Ben, can we meet at six? Thanks, Mai.. Dear Ms Lee, could you explain this word, please? Thank you, Mai."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4ccb6f5b-c8c4-5f35-a8a9-7fd2cb40200a'::uuid,'b869b95e-8c2e-5a29-a45c-da11711f2875'::uuid,'multiple_choice',1,'{"question":"คำชวนให้เพื่อนนัดได้ควรมีอะไร?","choices":[{"id":"choice_1","text":"วันเวลาและสถานที่ที่จำเป็น"},{"id":"choice_2","text":"คำศัพท์ยากที่สุด"},{"id":"choice_3","text":"แต่คำว่า Hello"}],"correctChoiceId":"choice_1","explanation":"ข้อมูลทำให้ผู้รับตอบหรือนัดได้"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f14c308c-26e4-5d36-ad21-bd02109047c8'::uuid,'b869b95e-8c2e-5a29-a45c-da11711f2875'::uuid,'multiple_choice',1,'{"question":"ถามครูสุภาพ เลือก","choices":[{"id":"choice_1","text":"Could you explain this word, please?"},{"id":"choice_2","text":"Explain now."},{"id":"choice_3","text":"You word explain."}],"correctChoiceId":"choice_1","explanation":"Could you + base และ please"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b940491f-045b-58ef-acdf-1735d1b67dc1'::uuid,'b869b95e-8c2e-5a29-a45c-da11711f2875'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนแชตถึงเพื่อน 40–50 คำและคำขอครูหนึ่งข้อความ มีจุดประสงค์และข้อมูลครบ\n\n### ตัวอย่างคำตอบ\n\nHi Ben, would you like to study with me on Saturday? We can meet at the library at ten. Please bring your English book and a pencil. Let me know if you can come. Thanks, Mai. Dear Ms Lee, could you explain this sentence, please? Thank you, Mai.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เขียนข้อความที่มีจุดประสงค์** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('39ea0459-364a-5228-a118-86d6a46c483b'::uuid,'ea1120bd-e1bf-532c-a760-9582ffc61fcf'::uuid,'reading',1,'{"title":"เล่าตนเองและเหตุการณ์","body":"## เล่าตนเองและเหตุการณ์\n\nเล่าตนเองเป็นเรื่องราวโดยเลือกช่วงเวลาชัด กิจวัตรใช้ simple พร้อมความถี่ เหตุการณ์จบใช้ past ประสบการณ์เชื่อมปัจจุบันใช้ perfect และแผนใช้รูปอนาคตที่ตรงความหมาย เชื่อมข้อมูลด้วย and/but/because/then แยกประโยคและย่อหน้าเมื่อหัวข้อเปลี่ยน ไม่พยายามใส่ทุก tense ในทุกเรื่องถ้าไม่จำเป็น\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I usually study at night. | กิจวัตร |\n| Last week, I read a new book. | อดีต |\n| I have learnt many words. | ประสบการณ์/ผล |\n| Tomorrow, I’m going to practise speaking. | แผน |\n\n### จุดที่มักสับสน\n\nจุดมุ่งหมายคือถ่ายทอดข้อมูลชัด ไม่ใช่แสดงรูป grammar มากที่สุด\n\n\n\n### ดูภาพแล้วลองใช้\n\n![ภาพสามช่อง Mai เดินในสวน จากนั้นฝนตก Ben ใช้ร่มช่วยและทั้งคู่ถึงร้านกาแฟ](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4253d113ce35a709-rain-story.png)\n\n*Mai was walking when it began to rain. Ben opened his umbrella. Then they reached a cafe.*\n\nใช้ภาพเป็นเรื่องใหม่สำหรับฝึก ไม่เปลี่ยนข้อเท็จจริงของตัวอย่างเดิม เล่าลำดับที่เห็น หรือเสนอแผนเมื่อมีฝนตามหัวข้อบท\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d2914557-3b34-5d98-a3cd-389dc94c854c'::uuid,'ea1120bd-e1bf-532c-a760-9582ffc61fcf'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4d91881eb0d80c41-lesson-35-07.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I usually study at night.. Last week, I read a new book.. I have learnt many words.. Tomorrow, I’m going to practise speaking."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('413fcaca-651b-5288-a2b8-b4c7a122a2ca'::uuid,'ea1120bd-e1bf-532c-a760-9582ffc61fcf'::uuid,'multiple_choice',1,'{"question":"เล่า yesterday ในเหตุการณ์จบใช้ประโยคใด?","choices":[{"id":"choice_1","text":"I met Mai yesterday."},{"id":"choice_2","text":"I have met Mai yesterday."},{"id":"choice_3","text":"I meeting Mai yesterday."}],"correctChoiceId":"choice_1","explanation":"Past Simple ระบุอดีตจบ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b76cd0cd-d69f-51d2-a959-b0713cc65704'::uuid,'ea1120bd-e1bf-532c-a760-9582ffc61fcf'::uuid,'multiple_choice',1,'{"question":"ข้อมูลกิจวัตรใช้รูปใด?","choices":[{"id":"choice_1","text":"I usually read at night."},{"id":"choice_2","text":"I usually was reading tomorrow."},{"id":"choice_3","text":"I reading every day."}],"correctChoiceId":"choice_1","explanation":"Present Simple + frequency"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('531389b2-2a52-5690-a366-7269ae39ed13'::uuid,'ea1120bd-e1bf-532c-a760-9582ffc61fcf'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nพูด 60–90 วินาทีหรือเขียน 80–100 คำเกี่ยวกับกิจวัตร เหตุการณ์หนึ่งและแผน พร้อมเหตุผล\n\n### ตัวอย่างคำตอบ\n\nI am Mai, and I live in Bangkok with my family. I usually study English in the evening for thirty minutes. Last Saturday, I visited my friend Ben at the library. We read a short story and talked about the people in it. I have learnt many useful words this month, but I still need to practise speaking. Tomorrow, I am going to record myself because I want to speak more clearly. Then I will listen to the recording and try again.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เล่าตนเองและเหตุการณ์** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f508b6ab-c9e8-5792-aa9c-6009158da227'::uuid,'4126dc6a-ce21-508d-a8f0-153776f722eb'::uuid,'reading',1,'{"title":"ตรวจและแก้ข้อความ","body":"## ตรวจและแก้ข้อความ\n\nตรวจงานเป็นรอบ: ความหมายและข้อมูลก่อน แล้ว subject/verb, tense, article, number, pronouns, spelling/punctuation ขีดเฉพาะจุดที่ผิดและอธิบายเหตุผล เช่น She go to school yesterday. → She went… เพราะเมื่อวานจบแล้ว ไม่แก้คำถูกเพียงเพราะมีหลายรูปที่ใช้ได้ อ่านออกเสียงเพื่อจับคำที่ตกและตรวจจากแหล่งเมื่อไม่แน่ใจ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| He don’t like tea. → He doesn’t like tea. | agreement |\n| I have saw it. → I have seen it. | have + V3 |\n| a apples → apples / an apple | จำนวนกับ determiner |\n\n### จุดที่มักสับสน\n\nตรวจ tense จากเจตนา ไม่ใช้คำว่า yesterday แล้วเปลี่ยนทุก clause โดยไม่อ่านความหมาย\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid) · [British Council–Eaquals — Core Inventory posters, 2018 update](https://www.eaquals.org/wp-content/uploads/Core-Inventory-Posters-2018-update.pdf)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5571d433-4bf2-5f0d-a6cc-f208982b99e3'::uuid,'4126dc6a-ce21-508d-a8f0-153776f722eb'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/04d105aa3bacb30f-lesson-35-08.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"He don’t like tea. ,  He doesn’t like tea.. I have saw it. ,  I have seen it.. a apples ,  apples. an apple"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('97d3f33e-bdff-5d9c-ac9e-9e5fc7708f84'::uuid,'4126dc6a-ce21-508d-a8f0-153776f722eb'::uuid,'multiple_choice',1,'{"question":"แก้ She doesn’t likes coffee เป็นอะไร?","choices":[{"id":"choice_1","text":"She doesn’t like coffee."},{"id":"choice_2","text":"She don’t likes coffee."},{"id":"choice_3","text":"She doesn’t liked coffee."}],"correctChoiceId":"choice_1","explanation":"doesn’t ตามด้วย base"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9dfe4bd3-80b3-5d6a-a0e3-3a941eef9903'::uuid,'4126dc6a-ce21-508d-a8f0-153776f722eb'::uuid,'multiple_choice',1,'{"question":"แก้ two childs เป็นอะไร?","choices":[{"id":"choice_1","text":"two children"},{"id":"choice_2","text":"two childrens"},{"id":"choice_3","text":"two child"}],"correctChoiceId":"choice_1","explanation":"child plural children"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f4d54fb2-98cb-581f-a7e0-805a1ce42d36'::uuid,'4126dc6a-ce21-508d-a8f0-153776f722eb'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nแก้ข้อความ: i am mai i studies english every day yesterday i have go to school แล้วอธิบายอย่างน้อยสามจุด\n\n### ตัวอย่างคำตอบ\n\nI am Mai. I study English every day. Yesterday, I went to school. แก้ตัวใหญ่และจุด; I ใช้ study; yesterday เหตุการณ์จบใช้ went ไม่ใช่ have go.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ตรวจและแก้ข้อความ** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3fa5bbb4-f81b-5ae4-aca5-6150a5952d5e'::uuid,'3704574b-ede2-5d01-ab4b-1fc275135e42'::uuid,'reading',1,'{"title":"ลองทำด้วยตัวเอง","body":"## ตรวจความเข้าใจ\n\nเป้าหมาย: **สื่อสารข้อความใหม่ ถามต่อ และแก้ความไม่เข้าใจด้วยภาษาที่เรียนมา**\n\nทำข้อทดสอบโดยไม่เปิดตัวอย่างก่อน จากนั้นอ่านเหตุผลทุกข้อ ข้อที่ยังตอบไม่มั่นใจให้ย้อนกลับไปบทที่ระบุใน feedback แล้วลองอธิบายใหม่ด้วยคำของตัวเอง\n\nข้อเลือกตอบต้องตอบถูกเพื่อผ่าน block สามารถลองใหม่ได้ คะแนนแต่ละข้อไม่ได้ใช้รับรองทักษะพูดหรือเขียน\n\n### ดูภาพแล้วลองใช้\n\n![ตอบ ถามกลับและแก้ความไม่เข้าใจ: How about you?; Could you repeat that?; See you later.](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/8f0355e94cb41e63-module-35-map.png)\n\n*พูดและเขียนเพื่อจุดประสงค์  •  ตรวจข้อความแล้วแก้หนึ่งรอบ*\n\nปิดตัวอย่างแล้วลองนึกโครงสร้าง จากนั้นใช้ภาพตรวจเหตุผลของคำตอบอีกครั้ง","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1b8b6648-238a-5e4b-a1d6-62fdedf3e620'::uuid,'3704574b-ede2-5d01-ab4b-1fc275135e42'::uuid,'multiple_choice',1,'{"question":"I don’t eat meat. คำตอบว่าฉันก็ไม่กินคืออะไร?","choices":[{"id":"choice_1","text":"Me neither."},{"id":"choice_2","text":"Me too."},{"id":"choice_3","text":"So am I."}],"correctChoiceId":"choice_1","explanation":"รับปฏิเสธ ย้อน 35.05"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7071500e-563b-5d22-afcc-4eeaea44f739'::uuid,'3704574b-ede2-5d01-ab4b-1fc275135e42'::uuid,'multiple_choice',1,'{"question":"คำขอให้พูดช้าลงคืออะไร?","choices":[{"id":"choice_1","text":"Could you speak more slowly, please?"},{"id":"choice_2","text":"Where do you speak?"},{"id":"choice_3","text":"Could speak you slow?"}],"correctChoiceId":"choice_1","explanation":"clarification phrase ย้อน 35.02"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('4eb038f8-f332-5758-a270-463f5c51c22a'::uuid,'3704574b-ede2-5d01-ab4b-1fc275135e42'::uuid,'multiple_choice',1,'{"question":"แก้ He has saw it เป็นอะไร?","choices":[{"id":"choice_1","text":"He has seen it."},{"id":"choice_2","text":"He have saw it."},{"id":"choice_3","text":"He has see it."}],"correctChoiceId":"choice_1","explanation":"has+V3 seen ย้อน 35.08"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('c4e8f902-35f4-5907-aa91-e8a8b809b2ff'::uuid,'3704574b-ede2-5d01-ab4b-1fc275135e42'::uuid,'reading',1,'{"title":"ภารกิจประจำ module","body":"## ใช้ภาษาเพื่อสื่อสาร\n\nสนทนา 2 นาทีและเขียนข้อความ 60–80 คำ มีทัก ตอบถามกลับ ขอทวน นัดและลา แล้วแก้หนึ่งรอบตาม checklist\n\n### ตัวอย่างผลงาน\n\nHi Ben, how are you? I enjoyed studying with you last week. Would you like to meet again on Saturday at ten? We can read a short story at the library and practise speaking after that. Please bring your notebook. Let me know if you can come, and tell me if another time is better. See you soon, and thanks, Mai.\n\n### ตรวจผลงาน\n\n- สื่อจุดประสงค์และข้อมูลครบ\n- ถามกลับและแก้ความไม่เข้าใจได้\n- ใช้ภาษาเหมาะผู้รับ\n- ตรวจ grammar/spelling/punctuation ที่กระทบความเข้าใจ\n\nลองทำก่อนดูตัวอย่าง แล้วแก้ผลงานของคุณอีกครั้ง งานนี้ใช้ตรวจตนเองหรือให้ครูตรวจ ระบบบันทึกการอ่าน block และไม่ได้ให้คะแนนงานพูด/เขียนโดยอัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('63ce2d59-361d-5f0e-a85a-6768b3ab3452'::uuid,'997b95a1-6b15-58c2-a0d8-aa53f3840dd0'::uuid,'reading',1,'{"title":"เลือกและอธิบายโครงสร้าง","body":"## เลือกและอธิบายโครงสร้าง\n\nประเมินโครงสร้างแบบผสมโดยอ่านความหมายก่อนเลือกรูป อธิบายว่าประธานใดกำหนด verb ทำไม noun ต้องมี determiner และกริยาตาม auxiliary เป็นรูปใด ข้อทดสอบนี้วัดความเข้าใจข้อเลือกตอบ แต่ต้องใช้ร่วมงานฟัง พูด อ่าน เขียนถัดไป ไม่ถือคะแนน grammar อย่างเดียวเป็นหลักฐานสื่อสารได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| My sister has a book. | subject singular/verb/article |\n| She doesn’t read it every day. | doesn’t + base/object |\n| She bought it yesterday. | past time/V2 |\n\n### จุดที่มักสับสน\n\nหลังตอบให้บอกเหตุผลจากโครงสร้างและความหมาย ไม่จำเฉลยตัวอักษร\n\n\n\n### ดูภาพแล้วลองใช้\n\n![หลักฐานก่อนเลือกทางต่อยอด: listen + read; speak + write; feedback → practise again](https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/41d6eb05bad6459b-module-36-map.png)\n\n*ข้อเลือกตอบตรวจอัตโนมัติ  •  งานพูด/เขียนใช้ตนเองหรือครูตรวจ*\n\nชี้ส่วนที่สัมพันธ์กับตัวอย่างในบท แล้วอธิบายด้วยคำของคุณก่อนดูข้อทดสอบ\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6f9e0317-6a2f-577d-a6b9-6a5e486a9b28'::uuid,'997b95a1-6b15-58c2-a0d8-aa53f3840dd0'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/49b05809337d7134-lesson-36-01.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"My sister has a book.. She doesn’t read it every day.. She bought it yesterday."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('57e8f25a-4ffd-5a1b-ad0f-214f35ea7569'::uuid,'997b95a1-6b15-58c2-a0d8-aa53f3840dd0'::uuid,'multiple_choice',1,'{"question":"Every student … a book.","choices":[{"id":"choice_1","text":"has"},{"id":"choice_2","text":"have"},{"id":"choice_3","text":"are"}],"correctChoiceId":"choice_1","explanation":"every + singular student ใช้ has"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5eec5f96-75df-5f5a-a95c-d161aec354d9'::uuid,'997b95a1-6b15-58c2-a0d8-aa53f3840dd0'::uuid,'multiple_choice',1,'{"question":"Choose the correct sentence.","choices":[{"id":"choice_1","text":"She has never seen snow."},{"id":"choice_2","text":"She has never saw snow."},{"id":"choice_3","text":"She have never seen snow."}],"correctChoiceId":"choice_1","explanation":"she has + V3 seen"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
