INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('41814697-ad04-5d99-a20e-aafaf47794c0'::uuid,'997b95a1-6b15-58c2-a0d8-aa53f3840dd0'::uuid,'multiple_choice',1,'{"question":"If it rains tomorrow, we … home.","choices":[{"id":"choice_1","text":"will stay"},{"id":"choice_2","text":"stayed"},{"id":"choice_3","text":"will staying"}],"correctChoiceId":"choice_1","explanation":"ผลอนาคตที่เป็นไปได้ใช้ will + base"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,7) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bbc34f76-1b4e-5cca-aadc-10f22699b747'::uuid,'997b95a1-6b15-58c2-a0d8-aa53f3840dd0'::uuid,'multiple_choice',1,'{"question":"Do you know where the station …?","choices":[{"id":"choice_1","text":"is"},{"id":"choice_2","text":"does"},{"id":"choice_3","text":"are"}],"correctChoiceId":"choice_1","explanation":"indirect question ส่วนย่อยใช้ statement order และ station singular"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,8) ON CONFLICT(id) DO NOTHING;
