INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('105aabbf-17cd-5fe6-ae4d-d4fba7b267cc'::uuid,'997b95a1-6b15-58c2-a0d8-aa53f3840dd0'::uuid,'multiple_choice',1,'{"question":"The person … works here is Mai.","choices":[{"id":"choice_1","text":"who"},{"id":"choice_2","text":"where"},{"id":"choice_3","text":"when"}],"correctChoiceId":"choice_1","explanation":"who เป็น subject ของ relative clause ที่ขยายคน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,10) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9a85b7d3-3f1d-507f-a3d9-e85f949b4f36'::uuid,'997b95a1-6b15-58c2-a0d8-aa53f3840dd0'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nทำข้อผสมแล้วจัดข้อที่ไม่มั่นใจเป็นหัวข้อ พร้อมอธิบายสองคำตอบด้วยคำของตน\n\n### ตัวอย่างคำตอบ\n\nEvery student has a book เพราะ student singular; She has never seen snow เพราะ has + V3 และ never บอกไม่เคย\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เลือกและอธิบายโครงสร้าง** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,11) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d3ef269f-ca5e-5717-a371-f11805b60e5f'::uuid,'fd84b685-2447-5a1b-a35f-e34e0d946901'::uuid,'reading',1,'{"title":"ฟังข้อมูลใหม่","body":"## ฟังข้อมูลใหม่\n\nประเมินฟังข้อมูลใหม่โดยฟังรอบแรกเพื่อจับจุดประสงค์และรอบสองเพื่อจำนวน วันเวลาและสิ่งต้องทำ ปิด transcript จนตอบเสร็จ ตัวอย่างภารกิจในคลิป: นัดกิจกรรมวันเสาร์ มีการแก้เวลาและจำนวน ให้ใช้ข้อมูลสุดท้ายที่ยืนยัน ถ้าไม่เข้าใจขอทวนหรือฟังอีกครั้ง แล้วบันทึกว่าจุดใดต้องเสริม\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| first listen: purpose | จับว่าข้อความชวนทำอะไร |\n| second listen: details | จดวันเวลา จำนวนและการแก้ |\n\n### จุดที่มักสับสน\n\nการอ่าน transcript ก่อนทำข้อทดสอบจะกลายเป็นอ่าน ไม่ใช่หลักฐานฟัง เป้าหมายวัดการรับข้อมูลด้วยเสียง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f29f1c03-b411-5676-a89f-612058d514a6'::uuid,'fd84b685-2447-5a1b-a35f-e34e0d946901'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/8874823a2d07ef9f-lesson-36-02.wav"},"title":"ฟังข้อความใหม่ แล้วตอบคำถาม","transcript":""}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d38fd276-a361-54dd-a654-449c28c40c1e'::uuid,'fd84b685-2447-5a1b-a35f-e34e0d946901'::uuid,'multiple_choice',1,'{"question":"จากคลิปประเมิน เวลาที่ตกลงหลังแก้คืออะไร?","choices":[{"id":"choice_1","text":"10:30"},{"id":"choice_2","text":"10:00"},{"id":"choice_3","text":"11:00"}],"correctChoiceId":"choice_1","explanation":"ผู้พูดแก้ ten เป็น ten thirty"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ff4c25c1-c7bf-5500-aa94-e0ddf78265b1'::uuid,'fd84b685-2447-5a1b-a35f-e34e0d946901'::uuid,'multiple_choice',1,'{"question":"จากคลิปประเมิน ต้องนำอะไร?","choices":[{"id":"choice_1","text":"a pencil and some water"},{"id":"choice_2","text":"a ticket and a coat"},{"id":"choice_3","text":"a phone only"}],"correctChoiceId":"choice_1","explanation":"คลิปบอก bring a pencil and some water"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('23b117fa-6468-581a-ae55-5e9f340dc2a5'::uuid,'fd84b685-2447-5a1b-a35f-e34e0d946901'::uuid,'multiple_choice',1,'{"question":"จำนวนคนสุดท้ายในคลิปคือเท่าไร?","choices":[{"id":"choice_1","text":"4"},{"id":"choice_2","text":"3"},{"id":"choice_3","text":"5"}],"correctChoiceId":"choice_1","explanation":"แก้ข้อมูลจาก three เป็น four"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('a3c5eea4-1246-5b52-a52c-ad9f39382ce7'::uuid,'fd84b685-2447-5a1b-a35f-e34e0d946901'::uuid,'multiple_choice',1,'{"question":"จุดประสงค์นัดคืออะไร?","choices":[{"id":"choice_1","text":"practise English"},{"id":"choice_2","text":"buy a car"},{"id":"choice_3","text":"watch a film"}],"correctChoiceId":"choice_1","explanation":"คลิปชวน practise English together"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,6) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bc402f93-3741-5472-a15a-c460458472a3'::uuid,'fd84b685-2447-5a1b-a35f-e34e0d946901'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nฟังคลิปนัดโดยไม่อ่าน transcript จดวันเวลา สถานที่ ของที่ต้องนำและจำนวนคน แล้วพูดทวนเหมือนยืนยันกับคู่สนทนา\n\n### ตัวอย่างคำตอบ\n\nWe meet on Saturday at ten thirty in room three. Bring a pencil and some water. Four people are coming.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **ฟังข้อมูลใหม่** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,7) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d07063cd-e4ca-5e3c-aa35-1626ce58caf6'::uuid,'328ebf2a-55cd-5c20-a28e-eb3808e278bf'::uuid,'reading',1,'{"title":"อ่านและถ่ายทอด","body":"## อ่านและถ่ายทอด\n\nอ่านข้อความและตารางใหม่แล้วตอบข้อมูลเฉพาะพร้อมสรุป ไม่แปลทุกคำก่อนหาเป้าหมาย ประกาศ: English club — Tuesday 17:00–18:00, room 4; Saturday 10:00–11:30, library. Bring a notebook. Students pay 20 baht; visitors pay 40 baht. ตรวจวัน สถานที่ ระยะเวลาและเงื่อนไขราคาไม่ปนกัน\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Tuesday: room 4, one hour | อังคารหนึ่งชั่วโมง |\n| Saturday: library, ninety minutes | เสาร์90นาที |\n| Students 20 / visitors 40 baht | ราคาตามกลุ่ม |\n\n### จุดที่มักสับสน\n\nไม่สรุปว่าเวลาและห้องทุกวันเหมือนกัน และไม่ขยายส่วนลดไปกลุ่มที่ไม่ได้ระบุ\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b3724198-e35d-5100-ab46-d46dff2d0b0c'::uuid,'328ebf2a-55cd-5c20-a28e-eb3808e278bf'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/fe25e63943309b5b-lesson-36-03.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Tuesday: room 4, one hour. Saturday: library, ninety minutes. Students 20. visitors 40 baht"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
