INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('bae3ac64-8753-5af9-a1f8-7994b569a5e6'::uuid,'328ebf2a-55cd-5c20-a28e-eb3808e278bf'::uuid,'multiple_choice',1,'{"question":"กิจกรรมวันเสาร์ใช้เวลานานเท่าไร?","choices":[{"id":"choice_1","text":"90 minutes"},{"id":"choice_2","text":"60 minutes"},{"id":"choice_3","text":"30 minutes"}],"correctChoiceId":"choice_1","explanation":"10:00–11:30 เท่ากับ 90 นาที"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('6e5e4e92-4de7-501f-a918-709c0b5a7bd1'::uuid,'328ebf2a-55cd-5c20-a28e-eb3808e278bf'::uuid,'multiple_choice',1,'{"question":"ต้องนำอะไรตามประกาศ?","choices":[{"id":"choice_1","text":"a notebook"},{"id":"choice_2","text":"a ticket"},{"id":"choice_3","text":"a lunch box"}],"correctChoiceId":"choice_1","explanation":"Bring a notebook เป็นข้อมูลที่ระบุ"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,6) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('662d6c9f-5ada-5cb0-a48c-184c2e0d36d6'::uuid,'328ebf2a-55cd-5c20-a28e-eb3808e278bf'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nสรุปประกาศให้เพื่อนสามประโยคและคำนวณระยะเวลาทั้งสองวันโดยไม่เติมข้อมูลเอง\n\n### ตัวอย่างคำตอบ\n\nThe English club meets on Tuesday from five to six in room four and on Saturday from ten to eleven thirty at the library. Bring a notebook. Students pay twenty baht, and visitors pay forty baht.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **อ่านและถ่ายทอด** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,7) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fb99bcb9-3ef4-58d6-a8d6-0812a755cff8'::uuid,'3102e675-0402-5da5-ac53-6d2d805da99d'::uuid,'reading',1,'{"title":"พูดโดยมีเป้าหมาย","body":"## พูดโดยมีเป้าหมาย\n\nงานพูดต้องสื่อสารข้อมูลใหม่ ตอบ ถามกลับและแก้ความไม่เข้าใจ ภารกิจ: นัดเพื่อนฝึกภาษา มีตัวเลือกวันเวลาและสถานที่ แล้วอธิบายแผน ใช้คำช่วยสื่อสาร Could you repeat that? เมื่อจำเป็น ประเมินความเข้าใจได้ ความครบ การโต้ตอบและความเหมาะสม มากกว่าความเหมือนสำเนียงเจ้าของภาษา งานนี้ครูหรือผู้ฟังช่วยตรวจ ไม่ได้ให้คะแนนพูดอัตโนมัติ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| Can we meet on Saturday? | เสนอวัน |\n| How about ten thirty? | ปรับเวลา |\n| Do you mean the library near the station? | ตรวจความเข้าใจ |\n\n### จุดที่มักสับสน\n\nอย่าอ่านบทตัวอย่างทั้งชุดแล้วถือว่าได้สื่อสารข้อมูลใหม่ ให้เปลี่ยนข้อมูลและตอบจริง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('1fe46c38-4337-5a0d-aaa9-7f534a753b4a'::uuid,'3102e675-0402-5da5-ac53-6d2d805da99d'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/6c6aedc33eb576b9-lesson-36-04.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"Can we meet on Saturday?. How about ten thirty?. Do you mean the library near the station?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('5665b6f6-8b9e-5126-a16e-508a6bbacbb0'::uuid,'3102e675-0402-5da5-ac53-6d2d805da99d'::uuid,'multiple_choice',1,'{"question":"เกณฑ์สำคัญของงานพูดนี้คืออะไร?","choices":[{"id":"choice_1","text":"ผู้ฟังเข้าใจและข้อมูลครบ"},{"id":"choice_2","text":"สำเนียงเหมือนคนชาติเดียวเท่านั้น"},{"id":"choice_3","text":"ใช้ศัพท์ยากที่สุด"}],"correctChoiceId":"choice_1","explanation":"เป้าหมายคือ intelligibility และการสื่อสารตามโจทย์"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9cc57eb5-4270-52d1-aab4-2ee24181b5e0'::uuid,'3102e675-0402-5da5-ac53-6d2d805da99d'::uuid,'multiple_choice',1,'{"question":"ถ้าฟังเวลานัดไม่ชัดควรทำอย่างไร?","choices":[{"id":"choice_1","text":"ขอทวนและยืนยันเวลา"},{"id":"choice_2","text":"ตอบ yes โดยไม่เข้าใจ"},{"id":"choice_3","text":"เปลี่ยนเรื่องทันที"}],"correctChoiceId":"choice_1","explanation":"clarification เป็นส่วนของทักษะสื่อสาร"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('ffa56920-372a-597b-a923-c7a63e1a405b'::uuid,'3102e675-0402-5da5-ac53-6d2d805da99d'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nพูดกับคู่ฝึก 2–3 นาที: แนะนำตัว บอกกิจวัตรหนึ่งข้อ เล่าอดีตหนึ่งเหตุการณ์ นัดครั้งถัดไปและถามกลับ ใช้ขอทวนหนึ่งครั้ง ให้คู่ฝึกตรวจ 4 ด้าน คะแนนด้านละ 0–2: เข้าใจได้/ข้อมูลครบ/ตอบและถามกลับ/ใช้ภาษาตรงความหมาย\n\n### ตัวอย่างคำตอบ\n\nHi, I’m Mai. I usually study at night. Last week, I read a story with Ben. Can we meet on Saturday? How about ten thirty at the library? Could you repeat the time, please? So we meet at ten thirty, right? What would you like to practise?\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **พูดโดยมีเป้าหมาย** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('82047e54-c952-510e-accb-89d9bd2cbaca'::uuid,'ca44ea52-61f0-54bd-abe9-0911f71aba7f'::uuid,'reading',1,'{"title":"เขียนและแก้ไข","body":"## เขียนและแก้ไข\n\nงานเขียนต้องมีผู้รับและจุดประสงค์ ภารกิจเขียนถึงเพื่อนเพื่อเล่าเหตุการณ์และชวนครั้งถัดไป ตรวจรอบแรกว่าข้อมูลครบและลำดับชัด รอบสองตรวจ subject/verb/tense/article/number/pronouns/spelling/punctuation จากนั้นแก้ฉบับใหม่พร้อมบอกเหตุผล งานนี้ใช้ rubric ตรวจตนเองหรือครู ระบบไม่ได้ตรวจงานเขียนอัตโนมัติ\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| I visited Mai yesterday. → เวลาอดีตชัด | เลือก Past Simple |\n| Would you like to meet on Sunday? → คำชวน | ข้อมูลผู้รับและนัด |\n\n### จุดที่มักสับสน\n\nอย่าแก้ทุกอย่างให้เป็นรูปยากขึ้น หากรูปง่ายสื่อความหมายถูกแล้ว\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('fb12dee7-6793-520b-af67-2156aa8bbfb2'::uuid,'ca44ea52-61f0-54bd-abe9-0911f71aba7f'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/4c1831fe15387208-lesson-36-05.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I visited Mai yesterday. Would you like to meet on Sunday? I enjoyed studying with you. Please bring a notebook and a pencil."}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('b0162e83-bebc-5c87-a19d-1a0fb6cb27c3'::uuid,'ca44ea52-61f0-54bd-abe9-0911f71aba7f'::uuid,'multiple_choice',1,'{"question":"He didn’t went home ควรแก้เป็นอะไร?","choices":[{"id":"choice_1","text":"He didn’t go home."},{"id":"choice_2","text":"He didn’t gone home."},{"id":"choice_3","text":"He doesn’t went home."}],"correctChoiceId":"choice_1","explanation":"didn’t + base go"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('d0f0bf93-ea86-585b-a128-03d351c6f074'::uuid,'ca44ea52-61f0-54bd-abe9-0911f71aba7f'::uuid,'multiple_choice',1,'{"question":"ข้อมูลใดจำเป็นสำหรับคำชวนที่ผู้รับตัดสินใจได้?","choices":[{"id":"choice_1","text":"กิจกรรมและวันเวลา/สถานที่ที่ตกลงได้"},{"id":"choice_2","text":"แต่คำลา"},{"id":"choice_3","text":"ศัพท์ยาวสิบคำ"}],"correctChoiceId":"choice_1","explanation":"ผู้รับต้องรู้ว่าจะทำอะไรเมื่อไรที่ไหน"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9e206ac7-aa9d-5d84-aea3-a5dcfd0e18d2'::uuid,'ca44ea52-61f0-54bd-abe9-0911f71aba7f'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nเขียนอีเมล 80–100 คำ เล่าเหตุการณ์ที่ทำแล้ว ชวนเพื่อนทำกิจกรรมอีกครั้งและให้เหตุผล จากนั้นแก้หนึ่งรอบ ให้คะแนนด้านละ 0–2: จุดประสงค์/ข้อมูลและลำดับ/รูปภาษาที่ทำให้เข้าใจ/สะกดและเครื่องหมาย\n\n### ตัวอย่างคำตอบ\n\nHi Ben, last Saturday I visited the library with Mai. We read a short story and talked about the people in it. I enjoyed the activity because I learnt some useful words. Would you like to join us next Sunday? We are meeting at the library near the station at ten in the morning. Please bring a notebook and a pencil. We can practise speaking after we finish reading. Let me know if you can come or if another time is better for you. See you soon, Mai.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **เขียนและแก้ไข** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('9ee8e0f5-a0f9-5473-a100-9e82053f7460'::uuid,'6eeae2b2-319f-5dda-af83-1c6b1be41845'::uuid,'reading',1,'{"title":"กลับไปเสริมเฉพาะจุด","body":"## กลับไปเสริมเฉพาะจุด\n\nเลือกเสริมจากหลักฐาน: ข้อเลือกตอบที่ผิดจัดตามหัวข้อ งานฟังตรวจว่าตกจำนวนหรือข้อมูลแก้ งานพูด/เขียนดู rubric จากตนเองหรือครู ไม่ใช้ block viewed เป็นหลักฐานเชี่ยวชาญ วางทบทวนวันถัดไปและสัปดาห์ถัดไป ใช้ Everyday English ฝึกสถานการณ์ควบคู่หรือเรียนต่อเมื่อสร้างข้อความใหม่ด้วยตนเองได้\n\n### ดูรูปและความหมายร่วมกัน\n\n| ภาษาอังกฤษ | ความหมาย / จุดสังเกต |\n|---|---|\n| ผิด didn’t went → กลับ M20 | auxiliary + base |\n| ผิด much books → กลับ M14 | countability |\n| ฟังแก้เวลาไม่ทัน → กลับ M34 | listening repair |\n\n### จุดที่มักสับสน\n\nการจบคอร์สไม่ใช่ใบรับรอง A2 และไม่มีระบบวินิจฉัยทักษะพูด/เขียนอัตโนมัติในเวอร์ชันนี้ ให้บันทึกหลักฐานเอง\n\n\n\n### ลองสังเกต\n\nอ่านตัวอย่างออกเสียง ชี้คำที่ทำหน้าที่สำคัญในบทนี้ แล้วอธิบายว่าถ้าเปลี่ยนคำนั้น ความหมายหรือรูปประโยคจะเปลี่ยนอย่างไร\n\nแหล่งอ่านต่อ: [Council of Europe — A1/A2 global scale](https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale) · [Council of Europe — Self-assessment grid](https://www.coe.int/en/web/common-european-framework-reference-languages/table-2-cefr-3.3-common-reference-levels-self-assessment-grid)","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('899e1075-3f36-5c1f-a306-a86444276af5'::uuid,'6eeae2b2-319f-5dda-af83-1c6b1be41845'::uuid,'audio',1,'{"media":{"source":"url","url":"https://paovbldfnyaudjmhnpoh.supabase.co/storage/v1/object/public/lesson-media/english-foundations/v1/ed28a8ff6826e6bb-lesson-36-06.wav"},"title":"ฟังตัวอย่างและลองพูดตาม","transcript":"I didn''t go home. I need some water. How much water do we need? How many books do you have? Could you repeat the time, please?"}'::jsonb,'{"autoplay":false,"controls":true}'::jsonb,'{"mode":"activity"}'::jsonb,'{"rule":"viewed"}'::jsonb,2) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('f2c7395d-41fb-534a-a270-a5459532e0bb'::uuid,'6eeae2b2-319f-5dda-af83-1c6b1be41845'::uuid,'multiple_choice',1,'{"question":"ผิดรูป didn’t ate ควรเสริมประเด็นใด?","choices":[{"id":"choice_1","text":"did/didn’t + base verb"},{"id":"choice_2","text":"สีของสิ่งของ"},{"id":"choice_3","text":"relative where"}],"correctChoiceId":"choice_1","explanation":"กลับ 20.04 เพื่อฝึก ate→eat หลัง didn’t"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,3) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('7cd44876-b941-5338-a9f5-fd61ab7437cc'::uuid,'6eeae2b2-319f-5dda-af83-1c6b1be41845'::uuid,'multiple_choice',1,'{"question":"อ่านทุก block แล้วแต่ยังแต่งประโยคใหม่ไม่ได้ ควรทำอย่างไร?","choices":[{"id":"choice_1","text":"ฝึกใช้และตรวจผลงานก่อนถือว่ามั่นคง"},{"id":"choice_2","text":"ถือว่าใช้ได้แล้วเพราะ viewed"},{"id":"choice_3","text":"ท่องชื่อ tense อย่างเดียว"}],"correctChoiceId":"choice_1","explanation":"การรับเนื้อหาต่างจากการผลิตภาษาเอง"}'::jsonb,'{"shuffleChoices":true,"showExplanation":true}'::jsonb,'{"mode":"answer"}'::jsonb,'{"rule":"correct"}'::jsonb,4) ON CONFLICT(id) DO NOTHING;
INSERT INTO lesson_blocks(id,lesson_id,type,version,content,settings,interaction,completion,sort_order) VALUES('3697fe49-994d-5d33-ac29-211770dcae7c'::uuid,'6eeae2b2-319f-5dda-af83-1c6b1be41845'::uuid,'reading',1,'{"title":"ตาคุณลองใช้","body":"## เปลี่ยนจากตัวอย่างเป็นข้อมูลของคุณ\n\nทำแผนส่วนตัว: จุดแข็งสองข้อ จุดเสริมสามข้อพร้อมบทอ้างอิง งานใหม่ที่จะแสดงความก้าวหน้าและวันทบทวน\n\n### ตัวอย่างคำตอบ\n\nจุดแข็ง: be และเวลา. เสริม: M14 many/much; M20 did+V1; M34 ฟังจำนวนแก้. พรุ่งนี้เขียนรายการซื้อของและเล่าเมื่อวาน อีกสัปดาห์ฟังนัดใหม่แล้วพูดทวน จากนั้นฝึก Everyday English ควบคู่.\n\n### ตรวจตนเอง\n\n- สื่อข้อมูลตามโจทย์ครบ และผู้อ่านหรือผู้ฟังเข้าใจว่าพูดถึงอะไร\n- ใช้รูปหรือกลุ่มคำ **กลับไปเสริมเฉพาะจุด** ตามความหมาย ไม่เติมหรือละคำสำคัญ\n- อ่านออกเสียงหนึ่งรอบ แล้วแก้การสะกด ตัวใหญ่และเครื่องหมายที่ทำให้ความหมายไม่ชัด\n\nตัวอย่างเป็นเพียงคำตอบหนึ่งแบบ ใช้ข้อมูลของคุณได้ งานพูด/เขียนใช้ตรวจตนเองหรือครูตรวจ ระบบไม่ได้ประเมินผลงานเหล่านี้อัตโนมัติ","format":"markdown"}'::jsonb,'{"textSize":"medium","alignment":"left"}'::jsonb,'{"mode":"none"}'::jsonb,'{"rule":"viewed"}'::jsonb,5) ON CONFLICT(id) DO NOTHING;
